/// Live compile-clean pipeline module paths for census exclusion silent-loss checks.
/// Shard entry paths plus their import closures — modules the compile-clean gate may touch.
pub fn compile_clean_live_pipeline_module_paths() -> Vec<String> {
    let pool_roots = default_source_roots();
    let facts = build_module_graph_facts_live(&pool_roots);
    let mut paths = BTreeSet::new();
    let roster = compile_clean_shard_entry_paths_fast().unwrap_or_else(|reason| {
        panic!("compile_clean_live_pipeline_module_paths: {reason}");
    });
    for entry in roster {
        for path in import_closure_live_paths_with_facts(&entry, &facts) {
            paths.insert(path);
        }
    }
    paths.into_iter().collect()
}

/// Host census for `fn_arrow_decl_substrate_is_whole_tree` — eligible module count vs
/// `loaded` modules in the current resolve context (same exclude set as `whole_tree_resolved_ctx`).
pub fn fn_arrow_decl_substrate_is_whole_tree_for_census(loaded: usize) -> bool {
    let roots = default_source_roots();
    let excludes = whole_tree_resolve_exclusion_substrings();
    let index = build_module_path_index(&roots);
    let expected = index
        .iter()
        .filter(|(module_path, rel_path)| {
            !excludes
                .iter()
                .any(|sub| rel_path.contains(sub) || module_path.contains(sub))
        })
        .count();
    loaded >= expected
}

pub fn census_corpus_roots_follow_layer_authority() -> bool {
    let synthetic = "module gunbc.ci_layer_roots\n\n\
         data witness_layer_roots: List<String> = [\"alpha_layer_root\", \"beta_layer_root\", \"gamma_layer_root\"]\n";
    let follows = witness_layer_roots_from_source(synthetic)
        == ["alpha_layer_root", "beta_layer_root", "gamma_layer_root"];
    let live_nonempty = !witness_layer_roots().is_empty();
    follows && live_nonempty
}

pub(crate) fn default_source_roots() -> Vec<String> {
    let ws = workspace_root();
    witness_layer_roots()
        .iter()
        .map(|r| ws.join(r).to_string_lossy().into_owned())
        .collect()
}

/// A source root the stage0 self-compile closure may be built from.
///
/// The seed boundary is the reason this is a closed two-member vocabulary rather than a string:
/// stage0 IS the v1 seed, so a root reaching into `src/v2` would make the seed depend on the
/// successor it bootstraps toward. There is no `src/v2` variant to write, so that root set has no
/// spelling — DESIGN §4b *structurally impossible*, replacing a validation that never existed.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum RegenSourceRoot {
    /// The v1 seed tree — every `.dag` under it seeds the closure.
    SeedV1,
    /// The shared `.dag` corpus — reached only through imports from the seed.
    DagCorpus,
}

impl RegenSourceRoot {
    pub fn repo_relative_path(self) -> &'static str {
        match self {
            RegenSourceRoot::SeedV1 => "src/v1",
            RegenSourceRoot::DagCorpus => "dag",
        }
    }
}

/// The stage0 self-compile root set: exactly two roots, in named roles.
///
/// Both invalid states the previous `Vec<String>` admitted are unwritable here. The empty set has
/// no constructor, so `regen_input_sources`' "root list must not be empty" refusal is deleted
/// rather than kept beside the proof (DESIGN §4b dissolution-on-climb); and the entry role is a
/// field rather than `.first()`, so it cannot be decided by list order. Fields are private and
/// `regen_source_roots` is the sole constructor, so a same-root or role-swapped pair is likewise
/// unconstructable outside this module.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct RegenSourceRoots {
    entry: RegenSourceRoot,
    imported: RegenSourceRoot,
}

impl RegenSourceRoots {
    /// The root whose `.dag` files seed the closure whole.
    pub fn entry(self) -> RegenSourceRoot {
        self.entry
    }

    /// Both roots, in the order the module-path index is built over them.
    pub fn all(self) -> [RegenSourceRoot; 2] {
        [self.entry, self.imported]
    }

    pub fn repo_relative_paths(self) -> Vec<String> {
        self.all()
            .iter()
            .map(|root| root.repo_relative_path().to_string())
            .collect()
    }
}

#[cfg(test)]
mod regen_source_root_tests {
    use super::{regen_source_roots, RegenSourceRoot};

    /// Positive control for the construction above. The discriminating RED is a compile error and
    /// so cannot be enrolled as a running test: adding a third root, emptying the set, or naming
    /// `src/v2` are all unwritable, which is the point. This asserts the surviving population and
    /// the entry role so a silent widening of either would fail here.
    #[test]
    fn root_set_is_the_two_seed_admissible_roots_with_the_seed_as_entry() {
        let roots = regen_source_roots();
        assert_eq!(roots.entry(), RegenSourceRoot::SeedV1);
        assert_eq!(
            roots.all(),
            [RegenSourceRoot::SeedV1, RegenSourceRoot::DagCorpus]
        );
        assert_eq!(roots.repo_relative_paths(), vec!["src/v1", "dag"]);
    }
}

/// Source roots whose transitive import closure feeds stage0 self-compile (`required_regen`).
pub fn regen_source_roots() -> RegenSourceRoots {
    RegenSourceRoots {
        entry: RegenSourceRoot::SeedV1,
        imported: RegenSourceRoot::DagCorpus,
    }
}

/// Every `(repo-relative path, source text)` in the stage0 compile closure.
///
/// Seeds every `.dag` under `src/v1`; walks imports through `build_module_path_index`
/// over `regen_source_roots()` so reachable `dag/` modules are included.
pub fn regen_input_sources(workspace: &Path) -> Result<Vec<(String, String)>, String> {
    let roots = regen_source_roots();
    let abs_roots: Vec<String> = roots
        .all()
        .iter()
        .map(|root| {
            workspace
                .join(root.repo_relative_path())
                .to_string_lossy()
                .into_owned()
        })
        .collect();
    let entry_root = workspace.join(roots.entry().repo_relative_path());
    regen_input_sources_over_roots(&entry_root, &abs_roots)
}

/// `regen_input_sources` with its roots supplied rather than derived from the
/// repository layout — the seam the regression test drives with a controlled
/// fixture. The production entry point above is the only caller that computes
/// the roots; everything below this line is root-agnostic, so the test exercises
/// THE SAME code path production does rather than a re-implementation of it.
fn regen_input_sources_over_roots(
    entry_root: &Path,
    abs_roots: &[String],
) -> Result<Vec<(String, String)>, String> {
    let mut entry_paths = Vec::new();
    collect_dag_files_result(entry_root, &mut entry_paths)?;

    // Seed: every `.dag` under the entry root that declares a module path.
    let mut seeds: Vec<Rc<v1_compiler_compile::SourceFile>> = Vec::new();
    for path in &entry_paths {
        let content =
            std::fs::read_to_string(path).map_err(|e| format!("read {}: {e}", path.display()))?;
        let rel = workspace_relative_repo_path(&path.to_string_lossy());
        if extract_module_path(&content).is_some() {
            seeds.push(Rc::new(v1_compiler_compile::SourceFile {
                path: rel,
                content,
            }));
        }
    }

    // Grow the closure through `extend_sources_to_both_closure_fixpoint` — import
    // edges PLUS dotted-reference PLUS bare-reference modules, to a joint fixpoint —
    // rather than the import-only walk this function used to run.
    //
    // WHY (§3 de-fork). An `import` line and a qualified or bare reference are the
    // SAME dependency edge. A walk that follows only imports is therefore not a
    // narrower closure — it is a closure that goes BLIND the moment a module spells
    // a dependency any other way. That function's own doc-comment calls itself "The
    // ONE closure-extension authority" and names the loaders that call it: "Both
    // source loaders — the per-entry witness loader and the affected-set
    // compile-clean gate loader". There are THREE. This one was the third, and it
    // is the one whose subject feeds regeneration of the seed itself.
    //
    // So the single-authority claim was true of its own enumeration and false of
    // the concept it named — the fork survived precisely because the prose asserting
    // its absence was load-bearing and never re-audited against the call graph.
    //
    // The same class was already repaired once, for the gate loader, which had run
    // only `extend_with_reference_closure` and dropped providers reached purely by
    // bare name (ARM1 ref-only = 3 unresolved-type diags; +bare = 0).
    //
    // LATENT HERE, FATAL NEXT DOOR. On this branch every seed dependency is still
    // spelled as an import, so the import-only walk happens to reach everything and
    // the defect cannot be observed from the corpus alone — which is why it has sat
    // here unnoticed. On `integration/namespace-cut`, where the `dag/` imports are
    // deleted, the identical code admits `src/v1` and NOTHING else: the queue drains
    // on its first pass and regen refuses with `unresolved type 'std.types.SourceSpan'`
    // while `std.types` sits present and correct in the authority. The regression
    // test below fixes the behaviour independently of either corpus.
    let mei = build_multi_entry_index(abs_roots);
    let closure = extend_sources_to_both_closure_fixpoint(seeds, &mei)?;

    let mut result: Vec<(String, String)> = closure
        .into_iter()
        .map(|s| (s.path.clone(), s.content.clone()))
        .collect();
    result.sort_by(|a, b| a.0.cmp(&b.0));
    result.dedup_by(|a, b| a.0 == b.0);
    Ok(result)
}

pub fn build_module_path_index_from_witness_roots() -> HashMap<String, String> {
    build_module_path_index(&default_source_roots())
}

pub fn source_path_for_module_path(module_path: String) -> String {
    let index = build_module_path_index_from_witness_roots();
    index
        .get(&module_path)
        .cloned()
        .unwrap_or_else(|| panic!("module_path_index: unknown module path '{module_path}'"))
}

pub fn free_monoid_symbol_value_to_dotted_string(value: &v1_interpreter::Value) -> String {
    v1_interpreter::free_monoid_symbol_value_to_dotted_string(value)
}

pub fn free_monoid_symbol_value_from_dotted_string(
    ctx: &v1_interpreter::InterpContext,
    dotted: &str,
) -> v1_interpreter::Value {
    use v1_interpreter::{sorted_fields, Value};

    let fm_variant = |variant: &str, fields: Vec<_>| Value::Variant {
        type_name: ctx.sym("FreeMonoid"),
        variant_name: ctx.sym(variant),
        fields: Rc::new(fields),
    };
    if dotted.is_empty() {
        return fm_variant("Empty", vec![]);
    }
    let mut qn = fm_variant("Empty", vec![]);
    for seg in dotted.split('.').rev() {
        qn = fm_variant(
            "Cons",
            sorted_fields(vec![
                (ctx.sym("head"), str_value(seg.to_string())),
                (ctx.sym("tail"), qn),
            ]),
        );
    }
    qn
}

pub(crate) fn repo_rel(path: &Path) -> String {
    // Same out-of-tree fallback as the module index: corpus walks accept
    // caller-supplied roots (temp fixture trees, other checkouts), whose files key
    // by their absolute spelling; relative-not-under-root stays a refusal.
    module_index_path_key(path)
}

pub(crate) fn is_test_dag(path: &str) -> bool {
    path.ends_with("_test.dag")
}

pub(crate) fn corpus_dag_files() -> Vec<(String, String)> {
    let mut paths = Vec::new();
    for root in witness_layer_roots() {
        collect_dag_files_tolerant(&Path::new(&anchor_source_root(&root)), &mut paths);
    }
    let mut out = Vec::new();
    for p in paths {
        let rel = repo_rel(&p);
        if let Ok(content) = std::fs::read_to_string(&p) {
            out.push((rel, content));
        }
    }
    out.sort();
    out.dedup();
    out
}

pub(crate) fn strip_line_comment(line: &str) -> String {
    let bytes = line.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut in_string = false;
    let mut escaped = false;
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if in_string {
            if escaped {
                out.push(b' ');
                escaped = false;
            } else if b == b'\\' {
                out.push(b' ');
                escaped = true;
            } else if b == b'"' {
                out.push(b'"');
                in_string = false;
            } else {
                out.push(b' ');
            }
        } else if b == b'"' {
            in_string = true;
            out.push(b'"');
        } else if b == b'/' && i + 1 < bytes.len() && bytes[i + 1] == b'/' {
            break;
        } else {
            out.push(b);
        }
        i += 1;
    }
    String::from_utf8(out).expect("strip_line_comment output is valid UTF-8")
}

pub(crate) fn brace_delta(line: &str) -> i32 {
    let c = strip_line_comment(line);
    c.matches('{').count() as i32 - c.matches('}').count() as i32
}

type ModuleSourceIndex = HashMap<String, Rc<v1_compiler_compile::SourceFile>>;

fn build_module_index(source_roots: &[String]) -> ModuleSourceIndex {
    let mut index = ModuleSourceIndex::new();
    for (root_idx, root) in source_roots.iter().enumerate() {
        let anchored_root = anchor_source_root(root);
        let root_path = std::path::Path::new(&anchored_root);
        let mut dag_files = Vec::new();
        collect_dag_files(root_path, &mut dag_files);
        for path in dag_files {
            let content = std::fs::read_to_string(&path)
                .unwrap_or_else(|e| panic!("failed to read {:?}: {}", path, e));
            if let Some(module_path) = extract_module_path(&content) {
                let rel_path = module_index_path_key(&path);
                let rel_forward = rel_path.clone();
                if manifest_stub_superseded_by_overlay(&rel_forward, source_roots, root_idx) {
                    continue;
                }
                if let Some(existing) = index.get(&module_path) {
                    if existing.path != rel_path && !same_canonical_file(&existing.path, &rel_path)
                    {
                        if root_idx > 0 {
                            continue;
                        }
                        panic!(
                            "{}",
                            module_path_collision_panic_message(
                                &module_path,
                                &existing.path,
                                &rel_path,
                            )
                        );
                    }
                    continue;
                }
                index.insert(
                    module_path,
                    Rc::new(v1_compiler_compile::SourceFile {
                        path: rel_path,
                        content,
                    }),
                );
            }
        }
    }
    index
}

/// `primary-precedence` pool indexing: the first root is authoritative; later roots
/// fill only modules not already present (matches `gunbc compile --dependency-pool-index
/// primary-precedence` in `dag_compile_clean_transport`).
fn build_module_index_primary_precedence(source_roots: &[String]) -> ModuleSourceIndex {
    let mut index = ModuleSourceIndex::new();
    if source_roots.is_empty() {
        return index;
    }
    index_source_root_into_module_index(&source_roots[0], &mut index, false);
    for root in &source_roots[1..] {
        index_source_root_into_module_index(root, &mut index, true);
    }
    index
}

fn index_source_root_into_module_index(
    root: &str,
    index: &mut ModuleSourceIndex,
    pool_fill_only: bool,
) {
    let root_path = std::path::Path::new(root);
    if !root_path.exists() {
        panic!("source root does not exist: {}", root);
    }
    let mut dag_files = Vec::new();
    collect_dag_files(root_path, &mut dag_files);
    let mut within_root: HashMap<String, String> = HashMap::new();
    for path in dag_files {
        let content = std::fs::read_to_string(&path)
            .unwrap_or_else(|e| panic!("failed to read {:?}: {}", path, e));
        if let Some(module_path) = extract_module_path(&content) {
            let rel_path = path.to_string_lossy().to_string();
            if pool_fill_only {
                if index.contains_key(&module_path) {
                    continue;
                }
            } else if let Some(existing) = index.get(&module_path) {
                if existing.path != rel_path {
                    panic!(
                        "module-path collision: module '{}' is declared by both '{}' and '{}' — one module, one authority (DESIGN §3); silent last-root-wins shadowing broke the floor (extdeps.shell, 2026-07-01) — de-fork or rename one side",
                        module_path, existing.path, rel_path
                    );
                }
            }
            if let Some(existing_path) = within_root.get(&module_path) {
                panic!(
                    "duplicate module path '{}' within source root '{}': declared in both '{}' and '{}'",
                    module_path, root, existing_path, rel_path
                );
            }
            within_root.insert(module_path.clone(), rel_path.clone());
            index.insert(
                module_path,
                Rc::new(v1_compiler_compile::SourceFile {
                    path: rel_path,
                    content,
                }),
            );
        }
    }
}

fn load_compile_clean_entry_sources(
    source_roots: &[String],
    mei: &MultiEntryIndex,
    entry_path_filter: Option<&std::collections::HashSet<String>>,
) -> Result<Vec<Rc<v1_compiler_compile::SourceFile>>, String> {
    let index = &mei.source_files;
    let facts = &mei.module_graph_facts;
    let first_root = std::path::Path::new(&source_roots[0]);
    let mut entry_files = Vec::new();
    if first_root.is_dir() {
        let mut dag_paths = Vec::new();
        collect_dag_files(first_root, &mut dag_paths);
        for path in dag_paths {
            let rel = workspace_relative_repo_path(&path.to_string_lossy());
            if let Some(filter) = entry_path_filter {
                if !filter.contains(&rel) {
                    continue;
                }
            }
            let content = std::fs::read_to_string(&path)
                .unwrap_or_else(|e| panic!("failed to read {:?}: {}", path, e));
            entry_files.push((path.to_string_lossy().to_string(), content));
        }
    }

    let skipped_moduleless = moduleless_dag_entry_paths(&entry_files);
    report_moduleless_dag_entry_skips(&skipped_moduleless);

    let mut entry_for_queue = Vec::new();
    for (path, content) in &entry_files {
        if extract_module_path(content).is_some() {
            entry_for_queue.push(Rc::new(v1_compiler_compile::SourceFile {
                path: path.clone(),
                content: content.clone(),
            }));
        }
    }

    let mut sources = resolve_transitively(entry_for_queue, index, facts)?;
    for (path, content) in entry_files {
        if extract_module_path(&content).is_none() {
            continue;
        }
        if !sources.iter().any(|s| s.path == path) {
            sources.push(Rc::new(v1_compiler_compile::SourceFile { path, content }));
        }
    }
    // BOTH closures to a joint fixpoint via the ONE shared authority the witness
    // loader `load_sources_for_entry_with_pool` also calls (a §3 dissolution: this
    // gate loader previously ran ONLY `extend_with_reference_closure`, so an
    // affected entry reaching a provider purely through a bare name or a service
    // call — patterns.dag → `gcp.STS.Exchange`, no import — dropped that provider,
    // since the service-name → provider edge `gcp.STS` → dag/extdeps/cloud/gcp/sts.dag
    // lives ONLY in the bare closure, and its names went unresolved. Proven: ARM1
    // ref-only = 3 unresolved-type diags on patterns.dag's closure; +bare = 0).
    extend_sources_to_both_closure_fixpoint(sources, mei)
}

/// Reference-derived dependency closure (namespace Rule-1 interim). A qualified
/// reference `container.member` is a dependency edge exactly as an `import` line
/// was: with dag/ imports stripped, the import-edge closure alone silently drops
/// every module reached only by qualified reference (the referenced modules fall
/// out of the census and their qualified names refuse corpus-wide). Projection is
/// text-level longest-prefix against the declared module-path index, iterated to
/// fixpoint; each addition pulls its own import closure. The ONE closure authority
/// for both the whole-tree compile-clean walk and the per-entry claim/witness
/// loaders (a second closure rule would be a §3 fork). Dissolves into the
/// parsed-tree reference projection when the Rule-1 terminal step (import as
/// parse error, deps derived from references) lands.
fn extend_with_reference_closure(
    mut sources: Vec<Rc<v1_compiler_compile::SourceFile>>,
    index: &ModuleSourceIndex,
    facts: &ModuleGraphFactsLive,
) -> Result<Vec<Rc<v1_compiler_compile::SourceFile>>, String> {
    let path_lookup = path_to_source_lookup(index);
    let mut known_paths: std::collections::HashSet<String> = sources
        .iter()
        .flat_map(|s| [s.path.clone(), workspace_relative_repo_path(&s.path)])
        .collect();
    let mut scan_queue: Vec<Rc<v1_compiler_compile::SourceFile>> = sources.clone();
    while let Some(sf) = scan_queue.pop() {
        // Sub-attribution of `load` (entry-graph-union slice 1, operator review):
        // `load` being 68% of resolve-span time does not by itself say whether the cost is
        // this content scan, file I/O, or pool bookkeeping — and THAT ratio is what
        // separates "a content-hash memo on a pure function" from "a union graph". Timed
        // here because this is the call the duplication factor multiplies.
        let scan_started = std::time::Instant::now();
        let referenced = referenced_module_paths_in_text(&sf.content, index);
        resolve_stage_slot_add(|s| {
            s.load_reference_scan += scan_started.elapsed().as_nanos();
            s.load_reference_scan_bytes += sf.content.len() as u128;
            s.load_reference_scan_calls += 1;
        });
        for module_path in referenced {
            let Some(dep) = index.get(&module_path) else {
                continue;
            };
            let dep_rel = workspace_relative_repo_path(&dep.path);
            if known_paths.contains(&dep_rel) || known_paths.contains(&dep.path) {
                continue;
            }
            if !facts.declares_repo_path(&dep_rel) {
                return Err(format!(
                    "reference_closure: referenced module '{module_path}' at '{dep_rel}' \
                     has no provenance in the module-graph facts pool (fail-closed)"
                ));
            }
            for path in import_closure_live_paths_with_facts(&dep_rel, facts) {
                let rel = workspace_relative_repo_path(&path);
                if known_paths.contains(&rel) {
                    continue;
                }
                let Some(dep_sf) = path_lookup.get(&rel).cloned() else {
                    return Err(format!(
                        "reference_closure: closure path '{rel}' (via referenced module \
                         '{module_path}') has no provenance in module index (fail-closed)"
                    ));
                };
                known_paths.insert(rel);
                known_paths.insert(dep_sf.path.clone());
                sources.push(dep_sf.clone());
                scan_queue.push(dep_sf);
            }
        }
    }
    Ok(sources)
}

fn extend_with_reference_closure_for_pool(
    sources: Vec<Rc<v1_compiler_compile::SourceFile>>,
    mei: &MultiEntryIndex,
) -> Result<Vec<Rc<v1_compiler_compile::SourceFile>>, String> {
    let edges = both_closure_edge_index(mei)?;
    extend_sources_via_edge_map(
        sources,
        &edges.ref_out,
        None,
        &path_to_source_lookup(&mei.source_files),
    )
}

/// Candidate module paths referenced by dotted names in `content`: every maximal
/// `seg(.seg)+` identifier chain contributes its longest leading prefix that is a
/// declared module path in `index` (>= 2 segments — a bare single identifier is a
/// global-bare census reference, never a module projection). String literals are
/// skipped: a module path inside a string is data (a registry row, prose), not a
/// reference, and following it over-pulls modules the corpus never resolves against.
fn referenced_module_paths_in_text(content: &str, index: &ModuleSourceIndex) -> Vec<String> {
    let content: &str = &annotation_erased_scan_text(content);
    let bytes = content.as_bytes();
    let is_ident_start = |c: u8| c.is_ascii_alphabetic() || c == b'_';
    let is_ident = |c: u8| c.is_ascii_alphanumeric() || c == b'_';
    let mut out = std::collections::BTreeSet::new();
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] == b'"' {
            i += 1;
            while i < bytes.len() && bytes[i] != b'"' {
                if bytes[i] == b'\\' && i + 1 < bytes.len() {
                    i += 1;
                }
                i += 1;
            }
            i += 1;
            continue;
        }
        if !is_ident_start(bytes[i]) || (i > 0 && (is_ident(bytes[i - 1]) || bytes[i - 1] == b'.'))
        {
            i += 1;
            continue;
        }
        let start = i;
        let mut segment_ends: Vec<usize> = Vec::new();
        loop {
            while i < bytes.len() && is_ident(bytes[i]) {
                i += 1;
            }
            segment_ends.push(i);
            if i + 1 < bytes.len() && bytes[i] == b'.' && is_ident_start(bytes[i + 1]) {
                i += 1;
            } else {
                break;
            }
        }
        if segment_ends.len() >= 2 {
            for k in (2..=segment_ends.len()).rev() {
                let candidate = &content[start..segment_ends[k - 1]];
                if index.contains_key(candidate) {
                    out.insert(candidate.to_string());
                    break;
                }
            }
        }
    }
    out.into_iter().collect()
}

fn compile_clean_resolve_has_hard_errors(
    result: &v1_compiler_compile::ResolvedPipelineResult,
) -> bool {
    compile_clean_pipeline_has_hard_errors(result.diagnostics.as_ref())
}

const COMPILE_CLEAN_DIAGNOSTIC_POLICY_ENTRY: &str = "dag/gunbc/compile_clean_diagnostic_policy.dag";

/// Whether `UnlistedImportUse` blocks compile-clean per the single policy row
/// (`compile_clean_unlisted_import_use_enforcement` in `gunbc.compile_clean_diagnostic_policy`).
/// Both the floor receipt path and the CLI transport must read this — never restate the predicate.
/// The policy entry's OWN import closure, as an explicit source set.
///
/// Why this exists rather than a whole-tree resolve: reading one nullary `Bool` used to cost a
/// full resolve+typecheck over `default_source_roots()` — the whole tree — which is both
/// enormously oversized (the policy module has three imports) and, more seriously, a function
/// answering a question about the CALLER's world by consulting a DIFFERENT one. Measured, same
/// probe, only the caller's roots varied: 216ms when the caller's roots happened to match the
/// whole-tree key, 44886ms when they did not and the resolve paid a cold whole-tree load
/// (`docs/probes/qualified_name_resolution_cost_2026-08-23.md`).
///
/// FAIL-CLOSED BY CONSTRUCTION (DESIGN §5): every arm that cannot produce the exact closure
/// REFUSES with a typed, located message naming the module and the file. It must never fall back
/// to the whole tree — that arm would restore today's cost, zero the deficit's frequency by
/// construction, and make the widening unrankable ever after. Note the contrast with
/// `resolve_virtual_source_with_imports`, whose BFS silently SKIPS an import it cannot resolve;
/// a silent skip here would narrow the policy closure and answer from a graph missing the very
/// module the answer depends on.
/// PRECONDITION, UNCHECKED AND UNTIL NOW UNSTATED: THE ENTRY'S CLOSURE MUST BE IMPORT-COMPLETE.
///
/// This walks `extract_import_paths` — EXPLICIT IMPORT EDGES ONLY. This corpus also resolves BARE
/// references through the tree census (namespace Rule-1), which is what
/// `extend_sources_to_both_closure_fixpoint` exists to do and what this deliberately does not do.
/// So an entry whose closure reaches any name it does not import will typecheck to
/// `function '<name>' not found in scope` here, and the failure is a property of the ENTRY, not of
/// this function.
///
/// MEASURED, and the reason this comment exists: `dag/gunbc/output_policy.dag` was routed through
/// here and broke on `dag/std/observation.dag` reaching `fold_list` with no import for it. The one
/// surviving caller, `compile_clean_unlisted_import_use_blocks_from_policy`, is sound BY LUCK —
/// its closure happens to be import-complete, and import-completeness is not a property this
/// corpus guarantees. One bare reference authored into that closure and it breaks too.
///
/// It breaks LOUDLY there, which is the one thing that makes the luck survivable: that caller
/// returns `Result<bool, String>` and propagates with `?`. Same fragility, opposite failure mode
/// from the silent arm this helper's other caller used to have.
fn policy_entry_closure_sources(
    roots: &[String],
    entry_rel: &str,
    policy_module: &str,
) -> Result<Vec<Rc<v1_compiler_compile::SourceFile>>, String> {
    let ws = process_workspace_root();
    let module_index = build_module_path_index(roots);
    let read = |rel: &str| -> Result<String, String> {
        let abs = ws.join(rel);
        std::fs::read_to_string(&abs).map_err(|e| {
            format!(
                "{policy_module} closure: cannot read `{}` ({e})",
                abs.display()
            )
        })
    };

    let entry_content = read(entry_rel)?;
    let mut seen: HashMap<String, Rc<v1_compiler_compile::SourceFile>> = HashMap::new();
    let mut queue: Vec<String> = vec![entry_content.clone()];
    while let Some(content) = queue.pop() {
        for module_path in extract_import_paths(&content) {
            let Some(rel_path) = module_index.get(&module_path) else {
                return Err(format!(
                    "{policy_module} closure: import `{module_path}` \
                     (reached from `{entry_rel}`) names no module in the source roots"
                ));
            };
            // `entry_rel` may be absolute (an entry argument typically is) while the module
            // index stores workspace-relative keys, so compare canonically — a string compare
            // would miss and admit the entry twice under two spellings.
            if same_canonical_file(rel_path, entry_rel) || seen.contains_key(rel_path) {
                continue;
            }
            let file_content = read(rel_path)?;
            seen.insert(
                rel_path.clone(),
                Rc::new(v1_compiler_compile::SourceFile {
                    path: rel_path.clone(),
                    content: file_content.clone(),
                }),
            );
            queue.push(file_content);
        }
    }

    let mut sources: Vec<Rc<v1_compiler_compile::SourceFile>> =
        seen.into_iter().map(|(_, v)| v).collect();
    sources.sort_by(|a, b| a.path.cmp(&b.path));
    sources.push(Rc::new(v1_compiler_compile::SourceFile {
        path: entry_rel.to_string(),
        content: entry_content,
    }));
    Ok(sources)
}

pub fn compile_clean_unlisted_import_use_blocks_from_policy() -> Result<bool, String> {
    let roots = default_source_roots();
    let entry = resolve_entry_file_under_roots(&roots, COMPILE_CLEAN_DIAGNOSTIC_POLICY_ENTRY)
        .map_err(|e| format!("compile_clean_diagnostic_policy resolve: {e}"))?;
    let sources =
        policy_entry_closure_sources(&roots, &entry, "gunbc.compile_clean_diagnostic_policy")?;
    let (graph, indices) = resolved_graph_from_sources(sources, ResolveTypecheckGate::Strict)
        .map_err(|e| format!("compile_clean_diagnostic_policy resolve: {e}"))?;
    let ctx = make_eval_context(&graph, indices, v1_interpreter::ExecutionMode::Hermetic);
    match v1_interpreter::run_in_context_with_args(
        &ctx,
        "compile_clean_unlisted_import_use_blocks",
        &[],
        false,
    ) {
        Ok(v1_interpreter::Value::Bool(b)) => Ok(b),
        Ok(other) => Err(format!(
            "compile_clean_unlisted_import_use_blocks returned `{}`, expected Bool",
            ctx.format_value(&other)
        )),
        Err(e) => Err(format!("compile_clean_unlisted_import_use_blocks: {e}")),
    }
}

fn compile_clean_unlisted_import_use_blocks_cached() -> Result<bool, String> {
    thread_local! {
        static CACHED: RefCell<Option<Result<bool, String>>> = const { RefCell::new(None) };
        static LOGGED_REFUSAL: Cell<bool> = const { Cell::new(false) };
    }
    CACHED.with(|c| {
        if let Some(v) = c.borrow().clone() {
            return v;
        }
        let v = compile_clean_unlisted_import_use_blocks_from_policy();
        if let Err(ref e) = v {
            LOGGED_REFUSAL.with(|logged| {
                if !logged.get() {
                    eprintln!(
                        "compile-clean policy: refused to read disposition row ({e}); failing gate"
                    );
                    logged.set(true);
                }
            });
        }
        *c.borrow_mut() = Some(v.clone());
        v
    })
}

fn compile_clean_policy_read_refuses_gate() -> bool {
    compile_clean_unlisted_import_use_blocks_cached().is_err()
}

/// Single authority (DESIGN.md §3/§7): whether a diagnostic blocks compile-clean.
/// `UnlistedImportUse` is governed by `gunbc.compile_clean_diagnostic_policy` (issue 11);
/// all other classes delegate to `00_core.dag` `is_interpreter_blocking_diagnostic`.
pub fn compile_clean_diagnostic_is_hard(d: &Rc<ErrorNode>) -> bool {
    use crate::v1_std_core::CompilerDiagnostic;
    match d.diagnostic.as_ref() {
        CompilerDiagnostic::UnlistedImportUse { .. } => {
            match compile_clean_unlisted_import_use_blocks_cached() {
                Ok(blocks) => blocks,
                Err(_) => true,
            }
        }
        _ => crate::v1_std_core::is_interpreter_blocking_diagnostic(d.diagnostic.clone()),
    }
}

/// Advisory (non-blocking per current policy) diagnostics for compile-clean — the
/// complement of `compile_clean_diagnostic_is_hard` used by the CLI transport so it
/// does not print advisories as hard errors when the policy row says FloorNotYet.
pub fn compile_clean_diagnostic_is_advisory(d: &Rc<ErrorNode>) -> bool {
    !compile_clean_diagnostic_is_hard(d)
        && matches!(
            d.diagnostic.as_ref(),
            crate::v1_std_core::CompilerDiagnostic::UnlistedImportUse { .. }
                | crate::v1_std_core::CompilerDiagnostic::ComplexityUnknown { .. }
                | crate::v1_std_core::CompilerDiagnostic::WhereRefinementUnenforced { .. }
                // A non-blocking variant that is absent from this list is counted by
                // NEITHER predicate: `..._is_hard` rejects it and this allowlist does
                // not admit it, so it renders to the terminal while every count the
                // gate reports reads zero for it. That is a frontier claiming to be
                // counted while nothing counts it. The three variants below are the
                // method/conformance walls' non-blocking residue and belong here for
                // the same reason WhereRefinementUnenforced does.
                | crate::v1_std_core::CompilerDiagnostic::MethodExistenceFrontierAdmitted { .. }
                | crate::v1_std_core::CompilerDiagnostic::ReceiverTypeUnestablished { .. }
                // The service-config reference-judgment deferral is non-blocking, so it must
                // be admitted HERE or it would be counted by neither predicate — rendered to
                // the terminal while every count the gate reports reads zero for it, which is
                // the frontier-claiming-to-be-counted failure the comment above names.
                | crate::v1_std_core::CompilerDiagnostic::ServiceConfigReferenceJudgmentDeferred { .. }
        )
}

pub fn compile_clean_pipeline_has_hard_errors(diagnostics: &im::Vector<Rc<ErrorNode>>) -> bool {
    if compile_clean_policy_read_refuses_gate() {
        return true;
    }
    diagnostics.iter().any(compile_clean_diagnostic_is_hard)
}

/// `ResolvedPipelineResult` / `im::Vector` adapter for compile-clean checks.
pub fn compile_clean_im_vector_has_hard_errors(diagnostics: &im::Vector<Rc<ErrorNode>>) -> bool {
    if compile_clean_policy_read_refuses_gate() {
        return true;
    }
    diagnostics.iter().any(compile_clean_diagnostic_is_hard)
}

fn format_compile_clean_hard_diagnostic_line(d: &Rc<ErrorNode>) -> String {
    let span = diagnostic_to_span(d.diagnostic.clone());
    let msg = diagnostic_to_message(d.diagnostic.clone());
    if span.file.is_empty() {
        format!("compile-clean: {msg}")
    } else {
        format!("compile-clean: {}: {}", span.file, msg)
    }
}

fn eprint_compile_clean_hard_diagnostics(diagnostics: &im::Vector<Rc<ErrorNode>>) {
    const SHOWN_LIMIT: usize = 20;
    let mut shown = 0usize;
    let mut total = 0usize;
    // One pass, no accumulator: the total is counted, never collected (§6).
    for d in diagnostics
        .iter()
        .filter(|d| compile_clean_diagnostic_is_hard(d))
    {
        total += 1;
        if shown < SHOWN_LIMIT {
            eprintln!("{}", format_compile_clean_hard_diagnostic_line(d));
            shown += 1;
        }
    }
    if total > SHOWN_LIMIT {
        // Count the residue rather than hiding it (§5): a truncated burndown that
        // never reports its size makes the deficit unprioritizable.
        eprintln!("compile-clean: (truncated hard diagnostics at {SHOWN_LIMIT}; {total} total)");
    }
}

const COMPILE_CLEAN_SCOPE_ENTRY: &str = "dag/tools/dag_compile_clean_scope.dag";
const FLOOR_COMPILE_CLEAN_PREDICATES_ENTRY: &str =
    "src/v2/workflow/floor_compile_clean_predicates.dag";

fn call_compile_clean_bool_list_fn(
    fn_name: &str,
    arg_name: &str,
    paths: &[String],
) -> Result<bool, String> {
    let roots = default_source_roots();
    let (graph, indices) = resolve_entry_graph_shared(&roots, FLOOR_COMPILE_CLEAN_PREDICATES_ENTRY)
        .map_err(|e| format!("floor_compile_clean_predicates resolve: {e}"))?;
    let ctx = make_eval_context(&graph, indices, v1_interpreter::ExecutionMode::Hermetic);
    let values: Vec<v1_interpreter::Value> = paths.iter().map(|s| str_value(s.clone())).collect();
    let args = [(Some(arg_name.to_string()), list_value_from_vec(values))];
    match v1_interpreter::run_in_context_with_args(&ctx, fn_name, &args, false) {
        Ok(v1_interpreter::Value::Bool(b)) => Ok(b),
        Ok(other) => Err(format!(
            "{fn_name} returned `{}`, expected Bool",
            ctx.format_value(&other)
        )),
        Err(e) => Err(format!("{fn_name}: {e}")),
    }
}

