#[cfg(test)]
mod shared_cache_collision_guard_tests {
    use super::check_module_source_identity_map;

    // Collision-honesty receipt (union-resolve §6.3): the shared typed-module cache's
    // source-identity guard fails LOUD when one module name resolves from two declaring files
    // in a process, and stays green when the same file is re-seen through many import paths.
    // This is the guard exercised by execution with a red control — not an inert wall.
    #[test]
    fn source_identity_flags_coresidence_collision_but_allows_reexport() {
        let mut reg = std::collections::HashMap::new();
        // First sight records the identity.
        assert!(check_module_source_identity_map(&mut reg, "std.foo", "dag/std/foo.dag").is_ok());
        // GREEN control: the SAME module reached again (a legitimate re-export / second
        // import path) is benign — one authority, many hops — so no error.
        assert!(check_module_source_identity_map(&mut reg, "std.foo", "dag/std/foo.dag").is_ok());
        // A distinct name from a distinct file is fine.
        assert!(check_module_source_identity_map(&mut reg, "std.bar", "dag/std/bar.dag").is_ok());
        // RED control: the same name from a DIFFERENT declaring file is the co-residence
        // surprise — a loud typed error, never a silently divergent resolution.
        let err = check_module_source_identity_map(&mut reg, "std.foo", "src/v2/std/foo.dag")
            .expect_err("a colliding module name from a second file must fail closed");
        assert!(
            err.contains("co-residence collision") && err.contains("std.foo"),
            "collision error must name the module and the seam: {err}"
        );
    }
}

#[cfg(test)]
mod typed_module_content_key_tests {
    //! Typed-module content-key RED controls (cross-entry-typed-module-memo-sketch.md
    //! §1/§3, operator-signed 2026-07-16; PR-α — the store re-key).
    //!
    //! The typed store keys on `std.interface_summary.typed_module_key` — module source
    //! hash ⊕ direct-import interface hashes ⊕ compiler identity — never on authored
    //! module name. Each test is a discriminating control for one live key term, proven
    //! BY EXECUTION against the store (`typecheck_compute_count` counts genuine
    //! typechecks — a stale serve shows up as a missing compute):
    //!
    //!  - **source term**: mutate a module's source (same path, same authored name)
    //!    between two indexes sharing one cross-worker store → the mutated module MUST
    //!    recompute. Under the dissolved name key this control goes RED (stale serve,
    //!    0 computes).
    //!  - **import-interface term**: change an imported module's export surface (its v0
    //!    interface hash) without touching the dependent → the dependent MUST recompute.
    //!    RED under the name key the same way.
    //!  - **interface-grain minimality** (signed decision 1): a body-only edit in the
    //!    import leaves its v0 interface hash unchanged → the dependent must HIT (only
    //!    the edited module recomputes). A conservative source-transitive key would go
    //!    RED here by over-invalidating the dependent.
    //!
    //! The compiler-identity term cannot vary within one test process; it is witnessed
    //! at the algebra level by the PR1 .dag witnesses
    //! (`src/v2/test/claim/interface_summary/typed_module_key_test.dag`). Warm==cold
    //! byte-equivalence stays owned by `resolve_typed_cache_equivalence_test`.
    //!
    //! Mutations rewrite the SAME file path so the `module_source_identity` collision
    //! wall (name→file, unchanged by the re-key) never fires.

    use super::{
        build_multi_entry_index_with_shared_caches, new_shared_typecheck_caches,
        reset_typecheck_compute_count, resolve_entry_with_index, typecheck_compute_count,
        with_typecheck_compute_count_receipt, workspace_root,
    };
    use crate::shared_typecheck_store::SharedTypecheckCaches;
    use std::fs;
    use std::sync::{Arc, RwLock};

    const IMPORT_MODULE: &str = "module k.imp\nfn base() -> Int { 10 }\n";
    const IMPORT_MODULE_BODY_EDIT: &str = "module k.imp\nfn base() -> Int { 4 + 6 }\n";
    const IMPORT_MODULE_SURFACE_EDIT: &str =
        "module k.imp\nfn base() -> Int { 10 }\nfn extra() -> Int { 1 }\n";
    const DEPENDENT_MODULE: &str =
        "module k.dep\nimport k.imp { base }\nfn wit() -> Bool { base() == 10 }\n";
    // No `import` line: a namespace-wave-1 stripped module (PR #6848) that resolves `base`
    // through the corpus-wide bare-name census instead of a declared import.
    const DEPENDENT_MODULE_STRIPPED: &str = "module k.dep\nfn wit() -> Bool { base() == 10 }\n";

    struct Fixture {
        dir: std::path::PathBuf,
        roots: Vec<String>,
        entry: String,
    }

    impl Fixture {
        fn new(tag: &str) -> Fixture {
            use std::sync::atomic::{AtomicU64, Ordering};
            static SEQ: AtomicU64 = AtomicU64::new(0);
            let seq = SEQ.fetch_add(1, Ordering::SeqCst);
            let dir = workspace_root().join("target").join(format!(
                "typed-module-content-key-{tag}-{}-{seq}",
                std::process::id()
            ));
            let _ = fs::remove_dir_all(&dir);
            fs::create_dir_all(&dir).expect("create fixture dir");
            fs::write(dir.join("imp.dag"), IMPORT_MODULE).expect("write imp.dag");
            fs::write(dir.join("dep.dag"), DEPENDENT_MODULE).expect("write dep.dag");
            let roots = vec![dir.to_string_lossy().into_owned()];
            let entry = dir.join("dep.dag").to_string_lossy().into_owned();
            Fixture { dir, roots, entry }
        }

        /// Same shape as `new`, but `dep.dag` is import-less (stripped) and depends on
        /// `k.imp.base` only through the bare-name census — the PR #6848 case
        /// `typed_module_content_key`'s reference-derived term now covers.
        fn new_stripped(tag: &str) -> Fixture {
            use std::sync::atomic::{AtomicU64, Ordering};
            static SEQ: AtomicU64 = AtomicU64::new(0);
            let seq = SEQ.fetch_add(1, Ordering::SeqCst);
            let dir = workspace_root().join("target").join(format!(
                "typed-module-content-key-{tag}-{}-{seq}",
                std::process::id()
            ));
            let _ = fs::remove_dir_all(&dir);
            fs::create_dir_all(&dir).expect("create fixture dir");
            fs::write(dir.join("imp.dag"), IMPORT_MODULE).expect("write imp.dag");
            fs::write(dir.join("dep.dag"), DEPENDENT_MODULE_STRIPPED).expect("write dep.dag");
            let roots = vec![dir.to_string_lossy().into_owned()];
            let entry = dir.join("dep.dag").to_string_lossy().into_owned();
            Fixture { dir, roots, entry }
        }

        fn rewrite_import(&self, src: &str) {
            fs::write(self.dir.join("imp.dag"), src).expect("rewrite imp.dag");
        }
    }

    impl Drop for Fixture {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.dir);
        }
    }

    /// Resolve `entry` against a fresh index bound to `store`, returning how many genuine
    /// typecheck computes the resolve performed (misses; hits don't count).
    fn computes_with_store(
        store: &Arc<RwLock<SharedTypecheckCaches>>,
        roots: &[String],
        entry: &str,
    ) -> usize {
        let index = build_multi_entry_index_with_shared_caches(roots, store.clone());
        reset_typecheck_compute_count();
        resolve_entry_with_index(&index, entry).expect("resolve");
        typecheck_compute_count()
    }

    #[test]
    fn source_term_recomputes_mutated_module() {
        with_typecheck_compute_count_receipt(|| {
            let fx = Fixture::new("source-term");
            let store = new_shared_typecheck_caches();

            let cold = computes_with_store(&store, &fx.roots, &fx.entry);
            assert_eq!(cold, 2, "cold resolve computes both closure modules");

            // Unchanged snapshot, fresh index: full hit — the content key is stable.
            let warm = computes_with_store(&store, &fx.roots, &fx.entry);
            assert_eq!(warm, 0, "unchanged snapshot must be a full store hit");

            // Body-only mutation of the import: its source hash moves, so its key moves.
            fx.rewrite_import(IMPORT_MODULE_BODY_EDIT);
            let after_edit = computes_with_store(&store, &fx.roots, &fx.entry);
            assert!(
                after_edit >= 1,
                "mutated module must recompute (a stale serve is a §5 fail-open); \
                 got {after_edit} computes"
            );
        });
    }

    #[test]
    fn import_interface_term_recomputes_dependent() {
        with_typecheck_compute_count_receipt(|| {
            let fx = Fixture::new("import-term");
            let store = new_shared_typecheck_caches();

            let cold = computes_with_store(&store, &fx.roots, &fx.entry);
            assert_eq!(cold, 2, "cold resolve computes both closure modules");

            // Export-surface edit: a new exported fn changes k.imp's interface rollup.
            fx.rewrite_import(IMPORT_MODULE_SURFACE_EDIT);
            let after_edit = computes_with_store(&store, &fx.roots, &fx.entry);
            assert_eq!(
                after_edit, 2,
                "an interface change in the import must recompute the import AND its \
                 dependent (the dependent's typed result consumed that interface)"
            );
        });
    }

    #[test]
    fn body_only_edit_leaves_dependent_warm() {
        with_typecheck_compute_count_receipt(|| {
            let fx = Fixture::new("minimality");
            let store = new_shared_typecheck_caches();

            let cold = computes_with_store(&store, &fx.roots, &fx.entry);
            assert_eq!(cold, 2, "cold resolve computes both closure modules");

            fx.rewrite_import(IMPORT_MODULE_BODY_EDIT);
            let after_edit = computes_with_store(&store, &fx.roots, &fx.entry);
            assert_eq!(
                after_edit, 1,
                "body-only import edit: import recomputes, dependent stays warm \
                 (interface-grain minimality, signed decision 1)"
            );
        });
    }

    /// The stripped-module discriminating RED (namespace wave 1, PR #6848 follow-up): a
    /// dependent with NO `import` line reaches its provider only through the corpus-wide
    /// bare-name census (`selection_adjacency`'s reference-derived edges). Before this fix
    /// `typed_module_content_key` only folded `resolved.resolved_imports` — empty here — so
    /// the dependent's key was invariant under the provider's export-surface change and it
    /// served a STALE typed result (0 computes). This is the same control as
    /// `import_interface_term_recomputes_dependent` above, over a stripped dependent instead
    /// of an import-bearing one.
    #[test]
    fn reference_derived_interface_term_recomputes_stripped_dependent() {
        with_typecheck_compute_count_receipt(|| {
            let fx = Fixture::new_stripped("stripped-reference-term");
            let store = new_shared_typecheck_caches();

            let cold = computes_with_store(&store, &fx.roots, &fx.entry);
            assert_eq!(
                cold, 2,
                "cold resolve computes both closure modules (imp pulled in via bare-reference \
                 closure loading)"
            );

            // Export-surface edit: a new exported fn changes k.imp's interface rollup, exactly
            // as `import_interface_term_recomputes_dependent` — but dep.dag has no import line.
            fx.rewrite_import(IMPORT_MODULE_SURFACE_EDIT);
            let after_edit = computes_with_store(&store, &fx.roots, &fx.entry);
            assert_eq!(
                after_edit, 2,
                "a provider export-surface change must recompute a STRIPPED dependent too: \
                 the content key must consume the reference-derived import term, not just \
                 `resolved_imports` (DESIGN §5 — a stale serve here is cache impurity, and a \
                 provider fix in place is a wrong-answer-forever, not a cold-cache-once)"
            );
        });
    }
}

#[cfg(test)]
mod compile_clean_via_index_verdict_equivalence {
    //! Verdict-equivalence controls for the floor receipt's via-index compile
    //! (lever 1, typecheck investigation PR #6766): the raw pipeline
    //! (`floor_compile_clean_emit_ok`, still the oracle behind
    //! `witness_layer_roots_compile_clean_emit_check`) and the shared-index receipt
    //! path (`floor_compile_clean_emit_ok_via_index`) must agree — green on a clean
    //! corpus, red on a planted unresolved import, red on a planted type mismatch.
    //! The raw path shares no caches with the via-index path, so agreement is an
    //! independent second opinion, not a self-check. Whole-tree agreement receipts
    //! (green 377.7s vs 381.4s; planted-inject red 4.3s vs 361.6s; both agree) are
    //! recorded in PR #6766.

    use super::{floor_compile_clean_emit_ok, floor_compile_clean_emit_ok_via_index};
    use crate::v1_compiler_compile::SourceFile;
    use std::fs;
    use std::rc::Rc;

    struct Corpus {
        dir: std::path::PathBuf,
        roots: Vec<String>,
        sources: Vec<Rc<SourceFile>>,
    }

    impl Corpus {
        /// Write `files` under a fresh fixture dir (the via-index path builds its
        /// `process_shared_index` from on-disk roots) and mirror them as the source
        /// set both compile paths receive.
        fn new(tag: &str, files: &[(&str, &str)]) -> Corpus {
            use std::sync::atomic::{AtomicU64, Ordering};
            static SEQ: AtomicU64 = AtomicU64::new(0);
            let seq = SEQ.fetch_add(1, Ordering::SeqCst);
            let dir = super::workspace_root().join("target").join(format!(
                "compile-clean-equiv-{tag}-{}-{seq}",
                std::process::id()
            ));
            let _ = fs::remove_dir_all(&dir);
            fs::create_dir_all(&dir).expect("create fixture dir");
            let mut sources = Vec::new();
            for (name, content) in files {
                let path = dir.join(name);
                fs::write(&path, content).expect("write fixture module");
                sources.push(Rc::new(SourceFile {
                    path: path.to_string_lossy().into_owned(),
                    content: (*content).to_string(),
                }));
            }
            let roots = vec![dir.to_string_lossy().into_owned()];
            Corpus {
                dir,
                roots,
                sources,
            }
        }

        fn verdicts(&self) -> (bool, bool) {
            let raw = floor_compile_clean_emit_ok(self.sources.clone(), None);
            let via_index =
                floor_compile_clean_emit_ok_via_index(self.sources.clone(), &self.roots).0;
            (raw, via_index)
        }
    }

    impl Drop for Corpus {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.dir);
        }
    }

    #[test]
    fn green_corpus_agrees_green() {
        let corpus = Corpus::new(
            "green",
            &[
                ("imp.dag", "module eqv.imp\nfn base() -> Int { 10 }\n"),
                (
                    "dep.dag",
                    "module eqv.dep\nimport eqv.imp { base }\nfn wit() -> Bool { base() == 10 }\n",
                ),
            ],
        );
        let (raw, via_index) = corpus.verdicts();
        assert!(raw, "raw pipeline must be green on the clean corpus");
        assert!(
            via_index,
            "via-index path must be green on the clean corpus"
        );
    }

    /// §5 discriminating RED: an unresolved import must red BOTH paths.
    /// CAUSAL control for the regen-closure de-fork — the companion to
    /// `regen_subject_admits_a_provider_reached_only_by_reference`.
    ///
    /// That test proves the provider ENTERS the subject. It does not prove the
    /// provider enters BECAUSE OF THE REFERENCE, and those are different claims:
    /// if the closure admitted every module in the wider roots for some unrelated
    /// reason, the admitting test would still pass while the reference edge did no
    /// work at all. That is the both-arms-green failure one level up — a test whose
    /// subject is present for reasons the test does not control.
    ///
    /// So this fixture is byte-identical to that one EXCEPT that the seed does not
    /// name the provider. The provider must then be ABSENT from the subject. Taken
    /// together the pair establishes the edge is causal: reference present ->
    /// admitted, reference absent -> not admitted, everything else held fixed.
    #[test]
    fn regen_subject_omits_a_provider_nothing_references() {
        let base = super::workspace_root()
            .join("target")
            .join(format!("regen-closure-causal-{}", std::process::id()));
        let entry_root = base.join("seed");
        let provider_root = base.join("corpus");
        let _ = fs::remove_dir_all(&base);
        fs::create_dir_all(&entry_root).expect("create entry root");
        fs::create_dir_all(&provider_root).expect("create provider root");

        // The ONLY difference from the admitting test: no reference to the provider.
        fs::write(
            entry_root.join("seed.dag"),
            "module v1.regen_seed_probe\nfn probe() -> Int {\n  1\n}\n",
        )
        .expect("write seed");
        fs::write(
            provider_root.join("provider.dag"),
            "module std.regen_provider_probe\nfn regen_provider_probe_answer() -> Int {\n  7\n}\n",
        )
        .expect("write provider");

        let roots = vec![
            entry_root.to_string_lossy().into_owned(),
            provider_root.to_string_lossy().into_owned(),
        ];
        let admitted = super::regen_input_sources_over_roots(&entry_root, &roots)
            .expect("regen subject over the fixture roots");

        let _ = fs::remove_dir_all(&base);

        assert!(
            !admitted
                .iter()
                .any(|(_, c)| c.contains("module std.regen_provider_probe")),
            "an unreferenced provider must NOT be admitted -- if it is, the closure is \
             widening the subject rather than following edges, and the admitting test \
             proves nothing about causality; admitted {} module(s): {:?}",
            admitted.len(),
            admitted.iter().map(|(p, _)| p).collect::<Vec<_>>()
        );
    }

    #[test]
    fn planted_unresolved_import_agrees_red() {
        let corpus = Corpus::new(
            "unresolved",
            &[(
                "bad.dag",
                "module eqv.unresolved\nimport totally.nonexistent.module { Foo }\nfn probe() -> Int { 42 }\n",
            )],
        );
        let (raw, via_index) = corpus.verdicts();
        assert!(!raw, "raw pipeline must red on an unresolved import");
        assert!(
            !via_index,
            "via-index path must red on an unresolved import"
        );
    }

    /// §5 discriminating RED: a `SourceAnnotationRefused` in a module outside the
    /// scoped compile-clean closure must surface through whole-tree census fill —
    /// compiling only the affected entry must not hide annotation debt elsewhere.
    /// DISCRIMINATING RED for the regen-closure de-fork.
    ///
    /// A seed module that reaches its provider by REFERENCE ONLY -- no `import`
    /// line anywhere -- must still have that provider admitted to the regen
    /// subject. Before the de-fork, `regen_input_sources` grew its closure with
    /// `extract_import_paths` alone, so this fixture's provider was dropped.
    ///
    /// THE FIXTURE'S SHAPE IS THE WHOLE CONTROL, and an earlier version of this
    /// test got it wrong in a way worth recording: it wrote both modules into ONE
    /// directory and passed that directory as the entry root. `collect_dag_files_result`
    /// then picked the provider up as a SEED, so the closure was never asked to
    /// find anything and the test passed against the old import-only walk too --
    /// green in both arms, therefore evidence of nothing. The provider must live
    /// OUTSIDE the entry root and inside the wider root set, which is exactly
    /// production's shape: entry root `src/v1`, providers under `dag/`.
    #[test]
    fn regen_subject_admits_a_provider_reached_only_by_reference() {
        let base = super::workspace_root()
            .join("target")
            .join(format!("regen-closure-defork-{}", std::process::id()));
        let entry_root = base.join("seed");
        let provider_root = base.join("corpus");
        let _ = fs::remove_dir_all(&base);
        fs::create_dir_all(&entry_root).expect("create entry root");
        fs::create_dir_all(&provider_root).expect("create provider root");

        fs::write(
            entry_root.join("seed.dag"),
            "module v1.regen_seed_probe\nfn probe() -> Int {\n  regen_provider_probe_answer()\n}\n",
        )
        .expect("write seed");
        fs::write(
            provider_root.join("provider.dag"),
            "module std.regen_provider_probe\nfn regen_provider_probe_answer() -> Int {\n  7\n}\n",
        )
        .expect("write provider");

        // Preconditions, asserted rather than assumed -- if a later edit adds an
        // import to the fixture, or moves the provider under the entry root, this
        // test would keep passing while testing nothing (which is how its first
        // version failed).
        let seed_text = fs::read_to_string(entry_root.join("seed.dag")).expect("read seed");
        assert!(
            super::extract_import_paths(&seed_text).is_empty(),
            "fixture precondition: the seed reaches its provider by reference only"
        );
        let mut entry_files = Vec::new();
        super::collect_dag_files_result(&entry_root, &mut entry_files).expect("walk entry root");
        assert_eq!(
            entry_files.len(),
            1,
            "fixture precondition: the provider must NOT be reachable as a seed"
        );

        let roots = vec![
            entry_root.to_string_lossy().into_owned(),
            provider_root.to_string_lossy().into_owned(),
        ];
        let admitted = super::regen_input_sources_over_roots(&entry_root, &roots)
            .expect("regen subject over the fixture roots");

        let _ = fs::remove_dir_all(&base);

        assert!(
            admitted
                .iter()
                .any(|(_, c)| c.contains("module std.regen_provider_probe")),
            "a provider reached only by reference must be admitted to the regen subject; \
             admitted {} module(s): {:?}",
            admitted.len(),
            admitted.iter().map(|(p, _)| p).collect::<Vec<_>>()
        );
    }

    #[test]
    fn out_of_closure_annotation_refusal_blocks_scoped_compile_clean() {
        let corpus = Corpus::new(
            "annotation-census",
            &[
                ("good.dag", "module eqv.good\ndata probe: Int = 42\n"),
                (
                    "bad.dag",
                    "module eqv.bad\n\ndata alpha: String = \"a\" // trailing prose\n",
                ),
            ],
        );
        let compiled = vec![corpus.sources[0].clone()];
        let index = super::build_multi_entry_index_primary_precedence(&corpus.roots);

        assert!(
            floor_compile_clean_emit_ok(compiled.clone(), None),
            "the compile closure alone is green when census fill is omitted"
        );
        assert!(
            !floor_compile_clean_emit_ok(compiled.clone(), Some(&index)),
            "whole-tree census fill must surface out-of-closure annotation refusal on the raw path"
        );
        assert!(
            !floor_compile_clean_emit_ok_via_index(compiled, &corpus.roots).0,
            "whole-tree census fill must surface out-of-closure annotation refusal on the via-index path"
        );
    }

    /// Discriminating A: a BodyGrain annotation on a file IN the compile closure
    /// must red via-index. #8204's out-of-closure fill cannot explain this — the
    /// annotated file is the compiled set, so census_only is empty.
    #[test]
    fn in_closure_body_grain_blocks_via_index_compile_clean() {
        let corpus = Corpus::new(
            "in-closure-body",
            &[(
                "body.dag",
                "module eqv.body_grain\nfn probe(x: Int) -> Int {\n  // in-body prose\n  x\n}\n",
            )],
        );
        let raw = floor_compile_clean_emit_ok(corpus.sources.clone(), None);
        let (via_ok, detail) =
            floor_compile_clean_emit_ok_via_index(corpus.sources.clone(), &corpus.roots);
        assert!(!raw, "raw pipeline must red on in-closure BodyGrain");
        assert!(
            !via_ok,
            "via-index must red on in-closure BodyGrain; #8204 census_only is empty here"
        );
        assert!(
            detail.contains("inside a declaration body"),
            "via-index must report BodyGrainNotModeled, got {detail}"
        );
        assert!(
            detail.contains("body.dag"),
            "compile-clean must name the refusing file, got {detail}"
        );
    }

    /// Discriminating A: UnattachedAtScopeEnd on a compiled file must red via-index.
    #[test]
    fn in_closure_unattached_blocks_via_index_compile_clean() {
        let corpus = Corpus::new(
            "in-closure-unattached",
            &[(
                "unattached.dag",
                "module eqv.unattached\ndata probe: Int = 42\n\n// leftover with no following subject\n",
            )],
        );
        let raw = floor_compile_clean_emit_ok(corpus.sources.clone(), None);
        let (via_ok, detail) =
            floor_compile_clean_emit_ok_via_index(corpus.sources.clone(), &corpus.roots);
        assert!(
            !raw,
            "raw pipeline must red on in-closure UnattachedAtScopeEnd"
        );
        assert!(
            !via_ok,
            "via-index must red on in-closure UnattachedAtScopeEnd"
        );
        assert!(
            detail.contains("names no subject"),
            "via-index must report UnattachedAtScopeEnd, got {detail}"
        );
    }

    /// Positive control: a leading module-item annotation is admitted. A must not
    /// refuse the class the frontend already accepts.
    #[test]
    fn in_closure_leading_annotation_stays_green_via_index() {
        let corpus = Corpus::new(
            "in-closure-leading",
            &[(
                "leading.dag",
                "module eqv.leading\n\n// about probe\ndata probe: Int = 42\n",
            )],
        );
        let (raw, via_index) = corpus.verdicts();
        assert!(raw, "raw pipeline must stay green on leading item prose");
        assert!(via_index, "via-index must stay green on leading item prose");
    }

    /// Ordering: in-closure BodyGrain must surface even when resolve also fails.
    /// Admission runs in the via-index parse, before resolve, so the class cannot
    /// hide behind an unresolved import.
    #[test]
    fn in_closure_body_grain_does_not_hide_behind_resolve_refusal() {
        let corpus = Corpus::new(
            "in-closure-body-masked",
            &[(
                "masked.dag",
                "module eqv.masked\nimport totally.nonexistent.module { Foo }\nfn probe(x: Int) -> Int {\n  // in-body prose\n  x\n}\n",
            )],
        );
        let (via_ok, detail) =
            floor_compile_clean_emit_ok_via_index(corpus.sources.clone(), &corpus.roots);
        assert!(!via_ok, "combined resolve+annotation refusal must stay red");
        assert!(
            detail.contains("inside a declaration body"),
            "BodyGrain must remain visible when resolve also refuses, got {detail}"
        );
    }

    /// #8204 ordering: out-of-closure trailing refusal must surface even when the
    /// compiled closure fails resolve. Census fill runs independently of resolve.
    #[test]
    fn out_of_closure_annotation_does_not_hide_behind_resolve_refusal() {
        let corpus = Corpus::new(
            "census-masked",
            &[
                (
                    "unresolved.dag",
                    "module eqv.unresolved\nimport totally.nonexistent.module { Foo }\nfn probe() -> Int { 42 }\n",
                ),
                (
                    "bad.dag",
                    "module eqv.bad\n\ndata alpha: String = \"a\" // trailing prose\n",
                ),
            ],
        );
        let compiled = vec![corpus.sources[0].clone()];
        let (via_ok, detail) = floor_compile_clean_emit_ok_via_index(compiled, &corpus.roots);
        assert!(!via_ok, "resolve refusal must stay red");
        assert!(
            detail.contains("follows code on its own line")
                || detail.contains("(annotation-trailing)")
                || detail.contains("Trailing placement"),
            "out-of-closure trailing refusal must remain visible when resolve also refuses, got {detail}"
        );
    }

    /// Warm parse_cache must not erase compiled-file admission: a second via-index
    /// compile-clean of the same in-closure BodyGrain corpus still reds.
    #[test]
    fn in_closure_body_grain_reds_on_warm_parse_cache() {
        let corpus = Corpus::new(
            "in-closure-body-warm",
            &[(
                "body.dag",
                "module eqv.body_grain_warm\nfn probe(x: Int) -> Int {\n  // in-body prose\n  x\n}\n",
            )],
        );
        let first = floor_compile_clean_emit_ok_via_index(corpus.sources.clone(), &corpus.roots);
        let second = floor_compile_clean_emit_ok_via_index(corpus.sources.clone(), &corpus.roots);
        assert!(!first.0, "first via-index must red, got {}", first.1);
        assert!(
            !second.0,
            "warm parse_cache must not drop BodyGrain admission, got {}",
            second.1
        );
        assert!(
            second.1.contains("inside a declaration body"),
            "warm via-index must still report BodyGrainNotModeled, got {}",
            second.1
        );
    }

    /// `handle_serve` resolves `Memoize`, consumes `compile_clean_diags`, and shares
    /// `process_shared_index`. An Ephemeral compile-clean warms parse_cache without
    /// joining `resolved_graph_memo`, so the subsequent Memoize is a parse_cache hit
    /// and a memo miss — admission must not depend on that cache state.
    #[test]
    fn in_closure_body_grain_reds_on_warm_parse_cache_under_memoize() {
        let corpus = Corpus::new(
            "in-closure-body-warm-memoize",
            &[(
                "body.dag",
                "module eqv.body_grain_warm_memoize\nfn probe(x: Int) -> Int {\n  // in-body prose\n  x\n}\n",
            )],
        );
        let index = super::process_shared_index(&corpus.roots);
        let first = super::resolved_graph_from_sources_with_index(
            &index,
            corpus.sources.clone(),
            super::ResolveTypecheckGate::Strict,
            "ephemeral-warm",
            super::ResolvedGraphMemoShare::Ephemeral,
        )
        .expect("BodyGrain is an annotation refusal, not a parse/resolve refusal");
        assert!(
            first.2.iter().any(super::compile_clean_diagnostic_is_hard),
            "cold Ephemeral must contribute BodyGrain, got {}",
            super::format_first_compile_clean_hard_diagnostic(first.2.as_ref())
        );
        let second = super::resolved_graph_from_sources_with_index(
            &index,
            corpus.sources.clone(),
            super::ResolveTypecheckGate::Strict,
            "memoize-serve",
            super::ResolvedGraphMemoShare::Memoize,
        )
        .expect("Memoize via-index must assemble");
        let detail = super::format_first_compile_clean_hard_diagnostic(second.2.as_ref());
        assert!(
            second.2.iter().any(super::compile_clean_diagnostic_is_hard),
            "handle_serve Memoize on a warm parse_cache must still see BodyGrain, got {detail}"
        );
        assert!(
            detail.contains("inside a declaration body"),
            "warm Memoize must still report BodyGrainNotModeled, got {detail}"
        );
    }

    /// Attribution installs an annotation-erasing parse (`annotation_diags: None`).
    /// A later Memoize via-index of that file must still admit.
    #[test]
    fn in_closure_body_grain_reds_after_erasing_parse_cache_install() {
        let corpus = Corpus::new(
            "in-closure-body-erasing-install",
            &[(
                "body.dag",
                "module eqv.body_grain_erasing\nfn probe(x: Int) -> Int {\n  // in-body prose\n  x\n}\n",
            )],
        );
        let index = super::process_shared_index(&corpus.roots);
        super::parse_module_node_from_index_source(&index, corpus.sources[0].clone())
            .expect("erasing attribution parse must succeed");
        let resolved = super::resolved_graph_from_sources_with_index(
            &index,
            corpus.sources.clone(),
            super::ResolveTypecheckGate::Strict,
            "memoize-after-erasing",
            super::ResolvedGraphMemoShare::Memoize,
        )
        .expect("Memoize via-index must assemble");
        let detail = super::format_first_compile_clean_hard_diagnostic(resolved.2.as_ref());
        assert!(
            resolved
                .2
                .iter()
                .any(super::compile_clean_diagnostic_is_hard),
            "Memoize after an erasing parse_cache install must still see BodyGrain, got {detail}"
        );
        assert!(
            detail.contains("inside a declaration body"),
            "erasing-install Memoize must still report BodyGrainNotModeled, got {detail}"
        );
    }

    /// Roots-key canonicalization (review 39118): the executor's absolute CLI roots
    /// and the plan's relative `witness_layer_roots` are the SAME pool and must
    /// address ONE thread-local shared index — otherwise the compile-clean receipt
    /// warms an index batch-2 silently replaces, and the whole lever-1 sharing claim
    /// is void on the CI path. Rc pointer equality is the discriminating check: two
    /// spellings, one universe.
    #[test]
    fn shared_index_roots_key_canonicalizes_absolute_and_relative_spellings() {
        // Workspace cwd: canonical roots are repo-relative and the index build
        // resolves them against cwd — the executor always runs from the repo root;
        // cargo test does not.
        let ws = super::workspace_root();
        let prior = std::env::current_dir().ok();
        std::env::set_current_dir(&ws).expect("chdir workspace");
        let absolute = vec![
            ws.join("dag").to_string_lossy().into_owned(),
            ws.join("src/v2").to_string_lossy().into_owned(),
        ];
        let relative = vec!["dag".to_string(), "src/v2".to_string()];
        let a = super::process_shared_index(&absolute);
        let b = super::process_shared_index(&relative);
        if let Some(p) = prior {
            let _ = std::env::set_current_dir(p);
        }
        assert!(
            Rc::ptr_eq(&a, &b),
            "absolute and relative spellings of the same pool must address ONE shared \
             index — a roots-key fork gives the receipt and batch-2 two typed universes"
        );
    }

    /// §5 discriminating RED: a typecheck-stage red must red BOTH paths. The planted
    /// module is the same variant-mismatch shape as the transport's canonical
    /// `perturb_module_source` (`dag/tools/dag_compile_clean_transport.dag`) — `Some`
    /// matched against a `Present`-constructed optional — a proven raw-pipeline red.
    #[test]
    fn planted_typecheck_red_agrees_red() {
        let corpus = Corpus::new(
            "typecheck-red",
            &[(
                "bad.dag",
                "module eqv.typecheck_red\nfn probe() -> String? {\n  match Present { value: \"x\" } {\n    Some { value: s } => Some { value: s }\n    None => none\n  }\n}\n",
            )],
        );
        let (raw, via_index) = corpus.verdicts();
        assert!(
            !raw,
            "raw pipeline must red on the planted variant mismatch"
        );
        assert!(
            !via_index,
            "via-index path must red on the planted variant mismatch"
        );
    }
}

thread_local! {
    static MODULE_PATH_INDEX_CACHE: RefCell<HashMap<String, HashMap<String, String>>> =
        RefCell::new(HashMap::new());
}

thread_local! {
    static MODULE_GRAPH_FACTS_CACHE: RefCell<HashMap<String, ModuleGraphFactsLive>> =
        RefCell::new(HashMap::new());
}

pub(crate) fn build_module_graph_facts_live_uncached(
    pool_roots: &[String],
) -> ModuleGraphFactsLive {
    #[cfg(test)]
    MODULE_GRAPH_FACTS_BUILD_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    const EXCLUDE: &[String] = &[];
    let roots = pool_roots_for_module_graph_closure(pool_roots);
    // NOTE: the module-graph LOADER closure stays import-derived for now (Blocker-1 part 1). A
    // reference-derived closure changes every witness's load set tree-wide and surfaces latent issues
    // (import-less-but-referencing std files, witnesses that need src/v1 in their pool, the
    // pre-existing fleet_converge Srv3 red, and homonyms the bright-cat lane must qualify), so the
    // loader repoint is staged as a separate part after those land. The REFERENCE producer below is
    // was, until gunbc#8141, already live via the inert-lens reach (the strips' documented CI
    // blocker); that consumer is deleted, so the reference producer's remaining live readers are
    // affected-set selection and the loader closure.
    //
    // EDGE SOURCE — the swap `module_graph.dag`'s `dependency_edge_source_migration_note` designates:
    // "when [the namespace terminal step] lands, `dependency_resolution_facts_live` swaps to the
    // reference-derived producer and nothing above it changes". Imports were deleted from most of the
    // corpus without this half landing, which left ~530 claim modules with an empty adjacency and a
    // widen arm below that answered "affected" for all of them — the absorbing fallback DESIGN §5
    // names verbatim ("can't compute the affected set → rerun the entire suite").
    //
    // Attempted 2026-07-14 and REVERTED: unioning `reference_edges_as_import_facts(..., false)`
    // ballooned a single small witness entry's load set from 27 to 424 resolved sources. That
    // measurement was correct and its conclusion ("the information is unusable here") was not — it
    // was taken at the `strict = false` tier, which keeps `AmbiguousBare` edges, so every ubiquitous
    // homonym fans its referrers out across the pool (median closure 1136 of 2240 modules).
    //
    // The tier is the fix. `strict = true` keeps Qualified + UniqueBare and drops AmbiguousBare:
    // median closure 96, p95 554 — the same order as the import-only baseline's 54/175 — and 522 of
    // the 530 edgeless claim modules gain a real edge. Measured over 14 merged diffs the selected
    // witness share goes 70.3% → 49.4% (the `false` tier goes the wrong way, to 83.4%).
    //
    // The two consumers take DIFFERENT tiers on purpose, and conflating them is what made this look
    // impossible: for the LOADER an over-connected edge is harmless (a superset just compiles extra
    // modules), while for SELECTION it is precisely the thing that destroys the answer. The loader
    // (`extend_with_bare_reference_closure`) is deliberately left alone.
    //
    // Import-bearing files emit no reference edges at all (see `reference_resolution_facts` pass 2),
    // so on an un-stripped file the union is a no-op and the graph is byte-identical to before.
    let observation = import_resolution_facts_with_observation(&roots, &roots, EXCLUDE);
    let edges = observation.facts;
    let nodes = module_declaration_facts(&roots);
    // Loader tier: import edges only, unchanged. Every consumer that goes on to RESOLVE what it
    // reaches reads this one.
    let adjacency = build_import_adjacency(&edges, &nodes);
    // Selection tier: import edges + strict reference edges.
    let mut selection_edges = edges.clone();
    selection_edges.extend(reference_edges_as_import_facts(
        &reference_resolution_facts(&roots, &roots, EXCLUDE),
        /* strict */ true,
    ));
    let selection_adjacency = build_import_adjacency(&selection_edges, &nodes);
    let reference_unaccounted: HashSet<String> =
        reference_accounting_refusals(&roots, &roots, EXCLUDE)
            .into_iter()
            .map(|r| workspace_relative_repo_path(&r.path))
            .collect();
    let declared_paths = nodes
        .iter()
        .map(|n| workspace_relative_repo_path(&n.path))
        .collect();
    let path_to_module: HashMap<String, String> = nodes
        .iter()
        .map(|n| (workspace_relative_repo_path(&n.path), n.module.clone()))
        .collect();
    ModuleGraphFactsLive {
        nodes,
        adjacency,
        selection_adjacency,
        declared_paths,
        reference_unaccounted,
        path_to_module,
        read_refusals: observation.read_refusals,
    }
}

pub fn build_module_graph_facts_live(pool_roots: &[String]) -> ModuleGraphFactsLive {
    let key = pool_roots_for_module_graph_closure(pool_roots).join("\u{1f}");
    MODULE_GRAPH_FACTS_CACHE.with(|cache| {
        if let Some(facts) = cache.borrow().get(&key) {
            shared_fill::record_hit("module_graph_facts", &key);
            return facts.clone();
        }
        shared_fill::begin_fill();
        let start = std::time::Instant::now();
        let facts = build_module_graph_facts_live_uncached(pool_roots);
        shared_fill::record_fill(
            "module_graph_facts",
            &key,
            start.elapsed().as_nanos() as u64,
        );
        cache.borrow_mut().insert(key, facts.clone());
        facts
    })
}

/// Host realization of `v2.lens.module_graph.import_closure_live`.
pub fn import_closure_live_paths(
    entry_path: &str,
    pool_roots: &[String],
) -> Result<Vec<String>, String> {
    let facts = build_module_graph_facts_live(pool_roots);
    Ok(import_closure_live_paths_with_facts(entry_path, &facts))
}

pub fn import_closure_live_paths_with_facts(
    entry_path: &str,
    facts: &ModuleGraphFactsLive,
) -> Vec<String> {
    import_closure_from_adjacency(entry_path, &facts.adjacency)
}

impl ModuleGraphFactsLive {
    /// Repo-relative paths of every declared module in the facts scan — the existence
    /// set for refuse-vs-answer decisions (a module can be absent from `adjacency`
    /// legitimately by importing nothing; absence from `nodes` means the facts do not
    /// cover it and a selection question about it must refuse, never narrow).
    pub fn declared_repo_paths(&self) -> HashSet<String> {
        self.declared_paths.clone()
    }

    /// Does the facts pool declare this workspace-relative path as a module? The
    /// refuse-vs-answer membership test at entry grain — one hash lookup against
    /// the set precomputed at facts build.
    pub(crate) fn declares_repo_path(&self, rel: &str) -> bool {
        self.declared_paths.contains(rel)
    }

    /// The dotted module names `importer_repo_path` depends on ONLY through a strict-tier
    /// reference edge (`selection_adjacency` minus `adjacency`) — i.e. the direct-import term
    /// a stripped (no `import` line) module is otherwise missing from its typed-module content
    /// key (DESIGN §3: consumes the same `selection_adjacency` authority affected-set selection
    /// already reads; no second reference-edge producer). An import-bearing file's declared
    /// imports are already covered by `resolved.resolved_imports`, so this returns empty for it
    /// (`adjacency` and `selection_adjacency` agree on such a file — see
    /// `reference_resolution_facts` pass 2).
    /// Workspace-relative repo paths `importer_repo_path` depends on ONLY through a strict-tier
    /// reference edge (`selection_adjacency` minus `adjacency`). The path-grain authority
    /// `selection_adjacency` already carries; module names are derived only for diagnostics.
    pub(crate) fn reference_only_direct_import_paths(
        &self,
        importer_repo_path: &str,
    ) -> Vec<String> {
        let import_targets: HashSet<&str> = self
            .adjacency
            .get(importer_repo_path)
            .into_iter()
            .flatten()
            .map(|s| s.as_str())
            .collect();
        let mut out: Vec<String> = self
            .selection_adjacency
            .get(importer_repo_path)
            .into_iter()
            .flatten()
            .filter(|p| !import_targets.contains(p.as_str()))
            .cloned()
            .collect();
        out.sort();
        out.dedup();
        out
    }
}

/// Mirror of `v2.lens.module_graph.path_matches_touched` (strip a leading `./`, then
/// equality or suffix-containment either way) — the two sides must agree because the
/// module-grain receipt harness proves the dag-vs-Rust file-grain DECISION equal on
/// real diffs, and a matching-rule fork would surface there as a divergence.
fn repo_paths_match_touched(closure_path: &str, touched_path: &str) -> bool {
    let file = closure_path.strip_prefix("./").unwrap_or(closure_path);
    let target = touched_path.strip_prefix("./").unwrap_or(touched_path);
    file == target || file.ends_with(target) || target.ends_with(file)
}

/// Production `entry_file_touched` decision for the discovery corpus: is any touched
/// entry file inside this entry's transitive import closure?
///
/// GRAIN (declared interim, operator fork (c) 2026-07-10): the module-graph
/// import-closure relation — the same host-realized facts
/// (`import_resolution_facts`/`module_declaration_facts` → `facts.adjacency`) that the
/// `.dag` authority `v2.lens.module_graph.entry_affected_by_touched_paths` reads through
/// its `_live` builtins. The `.dag` lens stays the modeled authority; THIS realization is
/// certified against it by execution on real merged diffs by the module-grain receipt
/// harness (`affected_decision_module_grain` section below). This consciously unwinds
/// one piece of #6335 ("reground selection on DependencyView") for this channel only:
/// the fn-arrow output-grain chain both silently widened (substrate-not-whole-tree →
/// touched=true for every row; probe receipt 2026-07-10) and conflates decl identity
/// with output type (a touched file's test fns put the shared `Bool` node in the edit
/// locus set). The fn-arrow machinery remains in tree as the decl-level candidate.
/// Dissolve-on: the namespace-only resolution terminal step replaces import edges with
/// `container.member` reference edges — the closure query above the edge source is
/// grain-stable and survives; the grain itself re-decides then (see
/// `entry_file_touched_grain_interim` in `v2.lens.affected_set.entry_selection`).
///
/// Refusal, never widen: an entry absent from the facts' declared-module set is a
/// provenance gap — the relation cannot answer for it — and returns a typed error that
/// fails the batch (the §5 fail-closed arm lives HERE, on an actual refusal; the old
/// arm that called its widen "fail-closed" is deleted).
fn entry_file_touched_via_import_closure(
    entry_path: &str,
    facts: &ModuleGraphFactsLive,
    declared_paths: &HashSet<String>,
    touched_paths: &[String],
) -> Result<bool, String> {
    if touched_paths.is_empty() {
        return Ok(false);
    }
    let entry_rel = workspace_relative_repo_path(entry_path);
    if !declared_paths.contains(&entry_rel) {
        return Err(format!(
            "AFFECTED-SET REFUSAL cause=EntryOutsideModuleGraphFacts entry={entry_rel} — \
             the module-graph facts scan does not declare this entry, so the import-closure \
             relation cannot answer entry_file_touched for it; refusing the batch rather \
             than widening to run-all or narrowing to skip"
        ));
    }
    // The edgeless case is NOT a special arm. Now that the adjacency carries reference-derived
    // edges for import-less files, "no outgoing edges" means the producer looked and found none —
    // a builtin-only witness, say — and `import_closure_from_adjacency` already answers precisely
    // for it: the closure seeds with the entry itself, so the entry is affected iff its own file
    // is touched. Falling through computes that.
    //
    // The one state that may refuse is the producer being UNABLE TO ANSWER: an import-less file it
    // could not read or parse has an unknown dependency set, which is not the same fact as an empty
    // one. Answering "affected" for it (the arm deleted here) conflated ⊤-as-ignorance with
    // ⊤-as-answer and, because the widen was silent and uncounted, drove the deficit's observed
    // frequency to zero by construction while the cost showed up as a 95-minute CI floor rather
    // than as a diagnostic (DESIGN §5).
    if facts.reference_unaccounted.contains(&entry_rel) {
        return Err(format!(
            "AFFECTED-SET REFUSAL cause=ReferenceEdgesUnaccounted entry={entry_rel} — the \
             reference-edge producer could not read or parse this import-less entry, so its \
             dependency set is UNKNOWN, not empty; refusing the batch rather than widening to \
             run-all or narrowing to skip"
        ));
    }
    let closure = import_closure_from_adjacency(entry_path, &facts.selection_adjacency);
    Ok(touched_paths.iter().any(|touched| {
        closure
            .iter()
            .any(|member| repo_paths_match_touched(member, touched))
    }))
}

/// Receipted Rust mirror of the single authority `v2.std.live_read.live_read_carrier_homes_v0`
/// (`src/v2/std/live_read.dag`) — the module names of the 8 declared live-read carrier homes.
/// Kept in lockstep with that `.dag` roster by hand; a drift here under-approximates axis (iv)
/// fail-closed-safe direction only if this list is a SUPERSET of the `.dag` roster, so any
/// addition to the `.dag` roster must be mirrored here — the drift gate below
/// (`live_read_carrier_home_modules_v0_is_superset_of_dag_authority`) evaluates the `.dag`
/// authority through a real interpreter context and fails the build the moment this const falls
/// behind, so the mismatch cannot silently pass.
/// Dissolution trigger: every caller of `runtime_data_dependency_touched_via_carrier_closure`
/// (the skip-before-resolve fast path and the precompute-count helpers below) is itself a named
/// `SCAFFOLD (§7 hand-Rust shrink-to-zero)` whose own DELETE WHEN note ties dissolution to
/// `v2.workflow.affected_set_floor_runner`'s `.dag` disposition owning the same predicate
/// end-to-end. This const has no independent dissolution path or generator lane because it has
/// no independent caller: when those scaffolds delete, this const and its drift gate delete with
/// them, not before.
const LIVE_READ_CARRIER_HOME_MODULES_V0: &[&str] = &[
    "v2.lens.enforcement.cost_coverage",
    "v2.lens.enforcement.grammar_coverage",
    "v2.lens.complexity_accumulator_copy.roster_gate",
    "v2.compiler.self_host",
    "v2.std.decl_index",
    "v2.lens.module_graph",
    "tools.dag_compile_clean_shard_roster",
    "tools.dag_compile_clean_scope",
];

/// Axis (iv) of the fourth-axis law (`docs/plans/live-read-witness-classification-design.md`
/// §7): does `entry_path`'s import closure reach a declared live-read carrier home, and is
/// any path touched at all? This is a G1-only (module-closure) mirror of the landed G2
/// call-reachability lens (`v2.lens.live_read_classification`) — G2's carrier set is always
/// a superset of G1's under the same closure (`merge_g1_and_g2_carriers`), so this coarser
/// Rust check is fail-closed-safe relative to the full `.dag` authority: it may over-report
/// (an extra witness run) but never under-report (a missed run). It does not attempt to
/// prove which touched path a reached carrier actually reads at runtime (that precision is
/// G2/G3's job) — reachability plus any touch is treated as a hit.
fn import_closure_module_reaches_carrier_home(
    closure_modules: &HashSet<String>,
    carrier_home: &str,
) -> bool {
    closure_modules.iter().any(|module| {
        module == carrier_home
            || module
                .strip_prefix(carrier_home)
                .is_some_and(|suffix| suffix.starts_with('.'))
    })
}

fn runtime_data_dependency_touched_via_carrier_closure(
    entry_path: &str,
    facts: &ModuleGraphFactsLive,
    touched_paths: &[String],
) -> bool {
    if touched_paths.is_empty() {
        return false;
    }
    let mut closure_modules: HashSet<String> = HashSet::new();
    let closure_paths: HashSet<String> = import_closure_live_paths_with_facts(entry_path, facts)
        .into_iter()
        .map(|p| workspace_relative_repo_path(&p))
        .collect();
    for node in &facts.nodes {
        let rel = workspace_relative_repo_path(&node.path);
        if closure_paths.contains(&rel)
            || closure_paths
                .iter()
                .any(|closure_path| repo_paths_match_touched(closure_path, &rel))
        {
            closure_modules.insert(node.module.clone());
        }
    }
    LIVE_READ_CARRIER_HOME_MODULES_V0
        .iter()
        .any(|carrier_home| {
            import_closure_module_reaches_carrier_home(&closure_modules, carrier_home)
        })
}

#[cfg(test)]
mod live_read_carrier_home_roster_drift_gate_tests {
    use super::{
        build_multi_entry_index, make_eval_context, resolve_entry_with_index_for_discovery_corpus,
        workspace_root, LIVE_READ_CARRIER_HOME_MODULES_V0,
    };
    use crate::v1_interpreter::{self, str_value, ExecutionMode, Value};
    use std::collections::HashSet;

    const LIVE_READ_ENTRY: &str = "src/v2/std/live_read.dag";

    fn record_field<'a>(
        ctx: &v1_interpreter::InterpContext,
        fields: &'a [(v1_interpreter::Symbol, Value)],
        field_name: &str,
    ) -> Option<&'a Value> {
        fields
            .iter()
            .find(|(sym, _)| ctx.sym_eq(*sym, field_name))
            .map(|(_, v)| v)
    }

    // Reads the `.dag`-side single authority directly by evaluating
    // `live_read_carrier_homes_v0` in a real interpreter context — not a re-hand-authored Rust
    // copy of the roster — so this test's own expectation cannot drift the same way the
    // production const can.
    fn dag_carrier_home_modules() -> HashSet<String> {
        std::env::set_current_dir(workspace_root()).expect("chdir workspace");
        let index = build_multi_entry_index(&["dag".to_string(), "src/v2".to_string()]);
        let (graph, indices) =
            resolve_entry_with_index_for_discovery_corpus(&index, LIVE_READ_ENTRY)
                .unwrap_or_else(|e| panic!("resolve {LIVE_READ_ENTRY}: {e}"));
        let ctx = make_eval_context(&graph, indices, ExecutionMode::Wet);
        let val = v1_interpreter::with_active_context(&ctx, || {
            v1_interpreter::eval_data_item_value(&ctx, "live_read_carrier_homes_v0")
        })
        .unwrap_or_else(|e| panic!("eval live_read_carrier_homes_v0: {e}"))
        .unwrap_or_else(|| panic!("live_read_carrier_homes_v0 not found as a data item"));
        let Value::List(items) = val else {
            panic!("live_read_carrier_homes_v0 is not a List: {val:?}");
        };
        items
            .iter()
            .map(|item| {
                let Value::Record { fields, .. } = item else {
                    panic!("live_read_carrier_homes_v0 entry is not a Record: {item:?}");
                };
                match record_field(&ctx, fields, "module") {
                    Some(Value::Str(s)) => s.to_string(),
                    other => panic!("LiveReadCarrierHome.module is not a String: {other:?}"),
                }
            })
            .collect()
    }

    // The safety-critical drift direction (axis (iv)'s fail-closed-safe requirement, see the
    // doc-comment on `LIVE_READ_CARRIER_HOME_MODULES_V0`): the Rust const must be a SUPERSET of
    // the `.dag` roster. A `.dag`-only addition this const misses makes
    // `runtime_data_dependency_touched_via_carrier_closure` return `false` for that carrier —
    // silently fail-open on the exact axis this const backs.
    #[test]
    fn live_read_carrier_home_modules_v0_is_superset_of_dag_authority() {
        let dag_modules = dag_carrier_home_modules();
        let rust_modules: HashSet<String> = LIVE_READ_CARRIER_HOME_MODULES_V0
            .iter()
            .map(|s| s.to_string())
            .collect();
        let missing: Vec<&String> = dag_modules.difference(&rust_modules).collect();
        assert!(
            missing.is_empty(),
            "`.dag` authority `live_read_carrier_homes_v0` declares carrier home module(s) \
             {missing:?} not mirrored in Rust `LIVE_READ_CARRIER_HOME_MODULES_V0` \
             (src/v1/stage0/src/cli_run.rs) — add them there or axis (iv) silently fails open \
             for that carrier"
        );
    }
}

// SCAFFOLD (§7 HAND-RUST — `cli_run_discovery_skip_before_resolve`):
// ROADMAP lane `2-provenance-ingest` (gunbc.roadmap_authority / ROADMAP.md;
// docs/plans/affected-set-precompute-pruning.md Step 4 migrate floor) — host-side
// per-entry cold-resolve elision under SelectionApplied before `floor_kernel_would_skip`.
// Unblock: modeled `floor_kernel_precompute_would_skip` / skip-before-resolve arm on
// `v2.workflow.affected_set_floor_runner` realizes the same decision in `.dag` (N→1 with
// the Rust `NodeFrontierSeeds` parallel deleted per the de-fork plan).
// DELETE WHEN dissolved: `entry_eligible_for_discovery_skip_before_resolve`,
// `collect_import_closure_module_names_from_facts`, `resolve_discovery_entry_for_corpus_row`
// lazy-resolve arm, and the `SKIP-RESOLVE` / `ctx.is_none()` loop in `run_discovery_rows`
// (~120 LOC).
// Receipt: `rg cli_run_discovery_skip_before_resolve src/v1/stage0/src/cli_run.rs` == 1 until
// deletion; not a compiler_frontier `.dag` row (seed-Rust, counted here not in module census).
pub(crate) const CLI_RUN_DISCOVERY_SKIP_BEFORE_RESOLVE_SCAFFOLD_MARKER: &str =
    "cli_run_discovery_skip_before_resolve";

/// Module names for one entry at the loader both-closure grain (no resolve) — shared by
/// `roster_import_closure_nodes_pre_resolve` and skip-before-resolve augmentation.
fn collect_import_closure_module_names_from_facts(
    index: &MultiEntryIndex,
    entry_path: &str,
    out: &mut HashSet<String>,
) -> Result<(), String> {
    collect_both_closure_module_names_for_entry(index, entry_path, out)
}

fn entry_has_edited_test_fn_in_entry(diff_edits: &FloorDiffEdits, entry_path: &str) -> bool {
    diff_edits
        .edited_test_fns
        .iter()
        .any(|(file, _)| diff_file_matches_entry(file, entry_path))
}

/// Skip-before-resolve (discovery corpus, SelectionApplied): when the diff cannot possibly
/// affect any witness in this entry — outside import-closure, no edited test fn, not a
/// host-scaffold entry file — elide the cold entry resolve and treat every kernel witness
/// row as assumed-green.
///
/// INTERIM hand-Rust scaffold (`CLI_RUN_DISCOVERY_SKIP_BEFORE_RESOLVE_SCAFFOLD_MARKER` / §7):
/// dissolves under ROADMAP `2-provenance-ingest` when `floor_kernel_precompute_would_skip` in
/// `v2.workflow.affected_set_floor_runner` is the general per-entry authority.
fn entry_eligible_for_discovery_skip_before_resolve(
    skip_enabled: bool,
    reads_live_tree: bool,
    entry_path: &str,
    facts: &ModuleGraphFactsLive,
    declared_paths: &HashSet<String>,
    touched_paths: &[String],
    diff_edits: &FloorDiffEdits,
) -> Result<bool, String> {
    if !skip_enabled {
        return Ok(false);
    }
    // Fail-closed on the substrate-declared disposition (v2.std.live_tree): a
    // `ReadsLiveTree` entry reads state outside its resolved closure, so the diff
    // cannot bound its inputs — it never predict-skips. Replaces the deleted
    // entry-text classifier (`entry_text_indicates_live_host_scan`); the disposition
    // is entry-grain, parsed onto every DiscoveryRow of the entry.
    if reads_live_tree {
        return Ok(false);
    }
    if entry_has_edited_test_fn_in_entry(diff_edits, entry_path) {
        return Ok(false);
    }
    if entry_file_touched_via_import_closure(entry_path, facts, declared_paths, touched_paths)? {
        return Ok(false);
    }
    if runtime_data_dependency_touched_via_carrier_closure(entry_path, facts, touched_paths) {
        return Ok(false);
    }
    let declared_axis = declared_source_refs_axis_for_entry(
        entry_path,
        facts,
        &default_source_roots(),
        touched_paths,
    );
    if declared_axis != DeclaredSourceRefAxis::Absent {
        if declared_source_refs_blocks_skip(declared_axis) {
            return Ok(false);
        }
    } else if effect_reach_touched_via_path_literals(entry_path, facts, touched_paths) {
        return Ok(false);
    }
    if compile_clean_broad_stop_line_blocks_skip(entry_path, touched_paths) {
        return Ok(false);
    }
    Ok(true)
}

struct DiscoveryEntryResolve {
    ctx: v1_interpreter::InterpContext,
    closure_subject: String,
    resolve_nanos: u128,
    stage_nanos: ResolveStageNanos,
}

fn resolve_discovery_entry_for_corpus_row(
    index: &MultiEntryIndex,
    entry_path: &str,
    execution_mode: v1_interpreter::ExecutionMode,
    whole_tree_published_keys: Option<Rc<std::collections::HashSet<String>>>,
    closure_modules: &mut HashSet<String>,
) -> Result<DiscoveryEntryResolve, String> {
    let sources = load_sources_for_entry_with_pool(index, entry_path)
        .map_err(|msg| format!("load sources failed for {entry_path}: {msg}"))?;
    let closure_subject = subject_digest_for_closure(&sources);
    let resolve_started = std::time::Instant::now();
    set_phase(FloorPhase::Resolve, entry_path);
    let (graph, source_indices) = resolve_entry_with_index_for_discovery_corpus(index, entry_path)
        .map_err(|msg| format!("resolve failed for {entry_path}: {msg}"))?;
    let resolve_nanos = resolve_started.elapsed().as_nanos();
    // Same thread, immediately after the resolve that filled it: this entry's split.
    let stage_nanos = resolve_stage_slot_snapshot();
    collect_typed_module_names(
        graph.modules.iter().cloned(),
        &source_indices,
        closure_modules,
    );
    let entry_ctx = make_eval_context_with_runtime_options(
        &graph,
        source_indices,
        execution_mode,
        None,
        whole_tree_published_keys,
    );
    Ok(DiscoveryEntryResolve {
        ctx: entry_ctx,
        closure_subject,
        resolve_nanos,
        stage_nanos,
    })
}

/// The closure-node definition SHARED by the falsifier/floor calibration emission and
/// the space-lens memory predictor (single authority is THIS function — the predictor
/// binds to it, never a re-derivation; predictor design is in flight on PR #6442, and
/// the landed parent-lane authorities are docs/plans/compute-envelope-model.md (fleet
/// envelope) and docs/plans/input-envelope-roadmap.md (admission)): the deduped transitive
/// import-closure of every roster row plus the given prefix-context entries, counted at
/// the authored-module-name grain via the LOADER's both-closure source set
/// (`load_sources_for_entry_with_pool`) — the exact set `resolve_entry_with_parse_cache`
/// starts from — so equality with the post-resolve union
/// (`collect_typed_module_names` over what resolve actually loaded) holds by
/// construction WITHOUT resolving: no parse, no typecheck, and nothing installed
/// into `resolved_graph_memo`. The #6938 form of this helper ran the full
/// `resolve_entry_with_index_for_discovery_corpus` per entry, which made every
/// floor run resolve the ENTIRE roster on the width-1 pump thread and retain every
/// resolved graph co-resident in the uncapped memo (~17 GB scoped runs became
/// ~38 GB whole-corpus retention — the 2026-07-21 exit-137 floor kills).
/// On a completed width-1 run this equals `DiscoverySummary::roster_closure_nodes`,
/// and `run_discovery_corpus_with_options` asserts that equality as the definition-drift
/// oracle (a loader fork or seeding change localizes here instead of silently skewing
/// bytes-per-node).
fn collect_both_closure_module_names_for_entry(
    index: &MultiEntryIndex,
    entry_path: &str,
    out: &mut HashSet<String>,
) -> Result<(), String> {
    for source in load_sources_for_entry_with_pool(index, entry_path)? {
        match extract_module_path(&source.content) {
            Some(name) => {
                out.insert(name);
            }
            None => {
                return Err(format!(
                    "calibration closure: source '{}' in entry '{}' closure declares no \
                     module header — the loader-grain module-name count cannot include it \
                     (fail-closed; a headerless source in the pool is an indexing defect)",
                    source.path, entry_path
                ));
            }
        }
    }
    Ok(())
}

pub fn roster_import_closure_nodes_pre_resolve(
    rows: &[DiscoveryRow],
    prefix_entries: &[&str],
    index: &MultiEntryIndex,
) -> Result<usize, String> {
    let mut closure_modules: HashSet<String> = HashSet::new();
    for entry in rows
        .iter()
        .map(|r| r.entry.as_str())
        .chain(prefix_entries.iter().copied())
    {
        collect_both_closure_module_names_for_entry(index, entry, &mut closure_modules)?;
    }
    Ok(closure_modules.len())
}

#[cfg(test)]
fn resolve_transitively_bfs_legacy(
    entry_sources: Vec<Rc<v1_compiler_compile::SourceFile>>,
    index: &ModuleSourceIndex,
    mut seen: HashMap<String, Rc<v1_compiler_compile::SourceFile>>,
) -> Vec<Rc<v1_compiler_compile::SourceFile>> {
    let mut queue = entry_sources;
    while let Some(source) = queue.pop() {
        for module_path in extract_import_paths(&source.content) {
            if seen.contains_key(&module_path) {
                continue;
            }
            if let Some(imported) = index.get(&module_path) {
                seen.insert(module_path, imported.clone());
                queue.push(imported.clone());
            }
        }
    }
    let mut result: Vec<_> = seen.into_iter().map(|(_, v)| v).collect();
    result.sort_by(|a, b| a.path.cmp(&b.path));
    result
}

fn resolve_transitively(
    entry_sources: Vec<Rc<v1_compiler_compile::SourceFile>>,
    index: &ModuleSourceIndex,
    facts: &ModuleGraphFactsLive,
) -> Result<Vec<Rc<v1_compiler_compile::SourceFile>>, String> {
    let mut path_lookup = path_to_source_lookup(index);
    for entry in &entry_sources {
        let rel = workspace_relative_entry_path(&entry.path);
        path_lookup.entry(rel).or_insert_with(|| entry.clone());
        path_lookup
            .entry(entry.path.clone())
            .or_insert_with(|| entry.clone());
    }

    let mut all_paths: BTreeSet<String> = BTreeSet::new();
    for entry in &entry_sources {
        let entry_rel = workspace_relative_entry_path(&entry.path);
        // An entry the facts pool does not declare has NO import edges in the
        // adjacency — not because it imports nothing, but because the scan never
        // saw it. Answering with the entry-only closure would silently drop its
        // imports and surface downstream as `unresolved import` on modules that
        // exist (the interp_recorded fixture-witness dark red, masked since the
        // facts repoint in #6210). Refuse, never narrow (DESIGN §5).
        if !facts.declares_repo_path(&entry_rel) {
            return Err(format!(
                "import_closure_live: entry '{entry_rel}' has no provenance in the \
                 module-graph facts pool (outside every source root, or missing a \
                 module declaration), so its import closure cannot be derived \
                 (fail-closed); pass a --source-root that covers the entry — the \
                 module universe is workspace-anchored"
            ));
        }
        for path in import_closure_live_paths_with_facts(&entry_rel, facts) {
            all_paths.insert(workspace_relative_repo_path(&path));
        }
    }

    let mut result = Vec::with_capacity(all_paths.len());
    for path in all_paths {
        let sf = path_lookup.get(&path).cloned().ok_or_else(|| {
            format!(
                "import_closure_live: closure path '{path}' has no provenance in module index (fail-closed)"
            )
        })?;
        result.push(sf);
    }
    result.sort_by(|a, b| a.path.cmp(&b.path));
    Ok(result)
}

pub fn load_sources_for_entry(
    source_roots: &[String],
    entry_path: &str,
) -> Result<Vec<Rc<v1_compiler_compile::SourceFile>>, String> {
    let index = process_shared_index(source_roots);
    load_sources_for_entry_with_pool(&index, entry_path)
}

/// Pool-index-aware variant of `load_sources_for_entry`: builds the closure
/// index with the SAME dependency-pool policy the census pool uses, so the
/// reference-derived closure and the whole-tree name census agree on which root
/// provides a cross-root homonym module (DESIGN §3 single authority — the two
/// membership authorities must not fork on a duplicated module path). Without
/// this the `--entry` compile built its closure strict (all roots compete,
/// duplicate module path panics) while the census honored
/// `--dependency-pool-index primary-precedence` (root[0] wins, later roots fill
/// only absent modules), so the requested pool policy was silently ignored on
/// the closure side. `primary_precedence=true` selects root[0]-wins; `false`
/// keeps strict.
pub fn load_sources_for_entry_with_pool_index(
    source_roots: &[String],
    entry_path: &str,
    primary_precedence: bool,
) -> Result<Vec<Rc<v1_compiler_compile::SourceFile>>, String> {
    if primary_precedence {
        let index = build_multi_entry_index_primary_precedence(source_roots);
        return load_sources_for_entry_with_pool(&index, entry_path);
    }
    // Strict pool policy routes through the process-shared index (DESIGN §3 —
    // one index authority per (thread, canonical roots)). Before this, a
    // `gunbc compile --entry` process built its closure index here, dropped it,
    // and then the first compile-clean diagnostic classification rebuilt the
    // SAME index inside resolve_entry_graph_shared to evaluate the
    // compile_clean_diagnostic_policy row — a second full pool_parse of the
    // corpus (measured: 5,450 pool_parse files for a 2,725-module pool, two
    // tree censuses per root) to read one policy Bool. Same construction fn
    // (build_multi_entry_index), same canonical roots key, so sharing is a
    // cache hit, not a behavior change; primary-precedence keeps its own
    // fresh build (process_shared_index only builds strict).
    let index = process_shared_index(source_roots);
    load_sources_for_entry_with_pool(&index, entry_path)
}

// ── THE V2 EMISSION TRANSACTION: ONE PRODUCER, TWO CONSUMERS ─────────────────
//
// WHY THIS EXISTS AT ALL. On 2026-08-23 `gunbc compile --source-root dag --source-root
// src/v2 --entry src/v2/compiler/03_ingest.dag` refused outright on main -- no emitted
// tree, no cargo log -- while every required phase stayed green for hours. The required
// run parses `src/v1` .dag, compares the regen mirrors, and folds the witness floor;
// NONE OF THE THREE COMPILES A v2 ENTRY, so the emission path had no observer at all.
// The break was a trailing `//` annotation block with no declaration after it, authored
// under `dag/test/manual/`, which no required phase reads either.
//
// WHY IT IS A SHARED FUNCTION AND NOT A SECOND CALLER. The gate MUST refuse wherever
// the cargo board's producer refuses, or it can green while the board is broken -- two
// answers to one question, which is the failure this whole lane keeps finding. The board
// runs `gunbc compile --entry M --target rust --dependency-pool-index primary-precedence`
// (`docs/probes/curated_cargo_probe_one.sh`, whose EMIT_REFUSE verdict is exactly that
// command exiting nonzero). So the emission transaction lives HERE, and BOTH the CLI's
// `--entry` arm and the required phase call it. Keeping two callers equal by hand would
// have been a fork with three live parameters to drift on -- the pool-index policy, the
// census population, and the silent-pick gate -- and the first draft of this phase had
// already drifted on the first of them.
//
// WHAT MAKES ONE SMALL ENTRY SUFFICIENT FOR THE ESCAPED CLASS, measured rather than
// argued. An `--entry` compile is scoped in what it EMITS (the reference-derived closure)
// and whole-tree in what it PARSES: every indexed module outside the closure enters the
// name census, so the census parse reaches the whole of `dag` + `src/v2`. Measured on a
// tree carrying the day's two fixes:
//
//   entry                        closure   census   emitted   wall
//   dag/std/abi.dag                    4    3,847         9    135s
//   src/v2/compiler/03_ingest.dag    ~180    ~3,670      176    349s
//
// and with the real specimen planted back into `dag/test/manual/` the SMALL entry refuses,
// naming the file and byte range of the offending annotation. So the large entry's extra
// 214s buys emission coverage of the compiler's own closure, not coverage of the class
// that escaped. The entry roster is a `.dag` row (`gunbc.ci_layer_roots`
// `required_v2_emission_entries`) precisely so that trade is re-decidable without a Rust
// edit.
//
// WHAT THE INVARIANT IS, AND WHAT IT IS NOT. NOT a file count: a legitimate compiler
// change may alter a closure's size, so `emitted == 177` is a CHANGE DETECTOR wearing an
// invariant's clothes. The invariant is that emission COMPLETED -- the transaction ran to
// its end and produced a tree -- and the refusal predicate is not restated here either:
// it is `v1_compiler_compile` `stage0_self_compile_refusal_message`, the same authority
// the CLI already stops on (a blocking diagnostic, or an empty emitted file set), plus
// the CLI's own silent-pick gate. A gate that refused on ANY diagnostic would be
// permanently red -- 03_ingest carries 503 advisory diagnostics and 0 blocking -- so
// advisory diagnostics are COUNTED and reported and never refused on.
//
// WHAT THIS DOES NOT CATCH, named rather than left to be inferred: a rustc error in the
// emitted tree (nothing here compiles the emission), a semantic regression that still
// emits, or an emission break confined to a closure the configured entry does not reach.

/// The `.dag` entry paths a required v2-emission phase compiles, read live from
/// `gunbc.ci_layer_roots` `required_v2_emission_entries`. A `List<String>` rather than a
/// scalar because the axis is "which entries", not "the entry" -- adding a second entry
/// is a row, never a second host reader.
pub fn required_v2_emission_entries() -> Vec<String> {
    static ENTRIES: OnceLock<Vec<String>> = OnceLock::new();
    ENTRIES
        .get_or_init(|| {
            string_list_data_from_ci_layer_roots_source(
                ci_layer_roots_authority_content(),
                REQUIRED_V2_EMISSION_ENTRIES_DATA_NAME,
            )
        })
        .clone()
}

/// WHAT HAPPENED TO THE EMISSION, AS THREE STATES RATHER THAN TWO.
///
/// An `Option<refusal>` beside a counts line is a two-state carrier asked to express
/// three, and the third state is the dangerous one: a run that never reached the compiler
/// renders as `emitted=0 blocking=0`, which is byte-identical to a clean run of an empty
/// subject and is told apart only by whether an ADJACENT line exists. A parser that reads
/// one line at a time cannot make that distinction, and neither can a person skimming.
/// So the disposition is a variant, every rendering carries it, and "did not run" is
/// structurally unable to be read as "ran and found nothing".
#[derive(Debug, Clone)]
pub enum EntryEmissionDisposition {
    /// The transaction ran to its end and produced a tree.
    Completed { emitted_count: usize },
    /// The compiler REACHED the subject and refused it. `cause` is the refusal verbatim.
    Refused { phase: String, cause: String },
    /// The transaction never ran: an earlier step could not reach the subject at all.
    /// Distinct from `Refused` because the remedies differ -- a missing entry sends the
    /// caller to their invocation, a refusal sends them to the corpus.
    NotExecuted {
        earlier_phase: String,
        cause: String,
    },
}

impl EntryEmissionDisposition {
    /// The single word every rendering of this run carries, so one line is self-describing.
    pub fn tag(&self) -> &'static str {
        match self {
            EntryEmissionDisposition::Completed { .. } => "EmissionCompleted",
            EntryEmissionDisposition::Refused { .. } => "EmissionRefused",
            EntryEmissionDisposition::NotExecuted { .. } => "EmissionNotExecuted",
        }
    }

    pub fn is_completed(&self) -> bool {
        matches!(self, EntryEmissionDisposition::Completed { .. })
    }
}

/// One entry's emission transaction, measured. Counts are reported whatever the
/// disposition, because a stopped line is analysed before it restarts (DESIGN §5) -- but
/// they are reported BESIDE a disposition that says which state produced them, never in
/// place of one.
#[derive(Debug, Clone)]
pub struct EntryEmissionRun {
    pub entry: String,
    pub closure_modules: usize,
    pub census_modules: usize,
    pub blocking_diagnostics: usize,
    pub advisory_diagnostics: usize,
    pub wall_ms: u128,
    pub disposition: EntryEmissionDisposition,
    /// `None` exactly when the disposition is `NotExecuted` -- there is no result to hold.
    pub result: Option<Rc<v1_compiler_compile::PipelineResult>>,
    pub silent_pick: crate::v1_rt::SilentPickTelemetry,
}

impl EntryEmissionRun {
    /// The self-describing line both consumers print. One line, one disposition, no
    /// state inferable only from the presence of a neighbour.
    pub fn measurement_line(&self, prefix: &str) -> String {
        format!(
            "{prefix}: {} entry={} closure={} census={} emitted={} blocking={} advisory={} wall_ms={}",
            self.disposition.tag(),
            self.entry,
            self.closure_modules,
            self.census_modules,
            match &self.disposition {
                EntryEmissionDisposition::Completed { emitted_count } => emitted_count.to_string(),
                // NOT "0": a transaction that never ran has no emitted count, and a zero
                // there reads as a clean empty emission to anything summing the column.
                EntryEmissionDisposition::Refused { .. } => self
                    .result
                    .as_ref()
                    .map(|r| r.files.len().to_string())
                    .unwrap_or_else(|| "n/a".to_string()),
                EntryEmissionDisposition::NotExecuted { .. } => "n/a".to_string(),
            },
            match self.disposition {
                EntryEmissionDisposition::NotExecuted { .. } =>
                    "n/a".to_string(),
                _ => self.blocking_diagnostics.to_string(),
            },
            match self.disposition {
                EntryEmissionDisposition::NotExecuted { .. } =>
                    "n/a".to_string(),
                _ => self.advisory_diagnostics.to_string(),
            },
            self.wall_ms,
        )
    }
}

/// AN ENTRY OUTSIDE THE WORKSPACE ROOT IS A REFUSAL, NOT A PANIC, and the pair is the
/// assertion: an existing file outside the repo and an existing file inside it must reach
/// different fates through the SAME argument.
///
/// RED against the pre-fix code: the outside-the-root case did not return at all -- it
/// panicked in `repo_relative_path_normalized` while keying the module graph, so this test
/// aborts the process rather than failing an assertion. The inside-the-root control is what
/// makes the refusal specific rather than a function that refuses everything.
///
/// The absent-file arm is included because it is the neighbouring refusal a wrong fix would
/// collapse into: "does not exist" and "exists but is not ours" are different facts with
/// different remedies (create the file vs move it into the tree), and one message for both
/// would be the state-space conflation this file is full of warnings about.
#[cfg(test)]
mod entry_admission_tests {
    use super::*;

    fn cause_of(run: &EntryEmissionRun) -> (String, String) {
        match &run.disposition {
            EntryEmissionDisposition::NotExecuted {
                earlier_phase,
                cause,
            } => (earlier_phase.clone(), cause.clone()),
            other => panic!("expected NotExecuted, got {other:?}"),
        }
    }

    #[test]
    fn an_entry_outside_the_workspace_root_refuses_instead_of_panicking() {
        // THE FILENAME CARRIES THE PID because this fleet runs concurrent `cargo test`
        // invocations on one host: a fixed name lets two runs write and delete the same path,
        // and the loser sees the file vanish mid-test. That failure would surface as this test
        // flaking on the ABSENT-file arm -- reporting the neighbouring refusal it exists to
        // hold apart -- which is the most confusing possible symptom for the least
        // interesting possible cause (review 55343, non-blocking; taken because a flake class
        // costs more to diagnose later than to remove now).
        let outside = std::env::temp_dir().join(format!(
            "gunbc_entry_admission_probe_{}.dag",
            std::process::id()
        ));
        std::fs::write(
            &outside,
            "module probe
",
        )
        .expect("fixture write");
        let run = compile_entry_emission(
            &["dag".to_string()],
            outside.to_str().expect("utf8 fixture path"),
            false,
            crate::v1_compiler_artifact::RenderTarget::Rust,
        );
        let (phase, cause) = cause_of(&run);
        assert_eq!(phase, "entry-admission");
        assert!(
            cause.contains("outside the workspace root"),
            "the refusal must say WHY, not merely that it refused: {cause}"
        );
        assert!(
            cause.contains(&process_workspace_root().display().to_string()),
            "the refusal must name the root it resolved, or it is unactionable: {cause}"
        );
        let _ = std::fs::remove_file(&outside);
    }

    /// THE ADMISSION PREDICATE IS THE PROCESS-ROOT ONE, ASSERTED DIRECTLY, because the
    /// difference between the two candidates is not observable through
    /// `compile_entry_emission` in any environment where the process root and the
    /// compile-time root COINCIDE -- which is every environment this test runs in, including
    /// CI. So the discriminating input cannot be authored at the outer boundary, and claiming
    /// a fixture had proven it would be the decoration §4b warns about.
    ///
    /// What IS authorable is the predicate-level distinction, and that is what this asserts:
    /// for a path outside the process root, `repo_relative_path` refuses while
    /// `try_repo_relative_path_normalized` is the helper whose baked-root arm made the
    /// widening possible. The RED is real -- swap the call in `compile_entry_emission` back to
    /// the `try_` helper and the second assertion here is the one that documents why that is
    /// wrong for a user-supplied path (review 55344).
    #[test]
    fn the_entry_predicate_anchors_on_the_process_root_only() {
        let outside = std::env::temp_dir().join(format!(
            "gunbc_entry_predicate_probe_{}.dag",
            std::process::id()
        ));
        std::fs::write(&outside, "module probe\n").expect("fixture write");
        assert!(
            repo_relative_path(&outside).is_err(),
            "the process-root anchor must refuse a path outside the repository"
        );
        assert!(
            repo_relative_path(&process_workspace_root().join("dag")).is_ok(),
            "and must admit one inside it, or it refuses everything"
        );
        let _ = std::fs::remove_file(&outside);
    }

    #[test]
    fn a_missing_entry_keeps_its_own_distinct_refusal() {
        let run = compile_entry_emission(
            &["dag".to_string()],
            "dag/definitely_not_a_real_entry_file.dag",
            false,
            crate::v1_compiler_artifact::RenderTarget::Rust,
        );
        let (phase, cause) = cause_of(&run);
        assert_eq!(
            phase, "entry-read",
            "an absent file and a file outside the root are different facts"
        );
        assert!(cause.contains("does not exist"), "{cause}");
    }
}

fn entry_emission_not_executed(
    entry_path: &str,
    started: std::time::Instant,
    earlier_phase: &str,
    cause: String,
) -> EntryEmissionRun {
    EntryEmissionRun {
        entry: entry_path.to_string(),
        closure_modules: 0,
        census_modules: 0,
        blocking_diagnostics: 0,
        advisory_diagnostics: 0,
        wall_ms: started.elapsed().as_millis(),
        disposition: EntryEmissionDisposition::NotExecuted {
            earlier_phase: earlier_phase.to_string(),
            cause,
        },
        result: None,
        silent_pick: crate::v1_rt::SilentPickTelemetry::default(),
    }
}

/// THE EMISSION TRANSACTION. One entry, one render target, over `source_roots`.
///
/// Both consumers call this and neither reimplements it: `gunbc compile --entry` (which
/// then writes the tree and renders diagnostics) and `claim_executor --required-v2-emission`
/// (which drops the tree and reads only the disposition). That is what makes "the gate is
/// green" and "the board's producer emitted" the same fact rather than two.
///
/// Silent-pick telemetry is captured INSIDE the transaction because the CLI's own gate
/// reads it: a run that leaves it to the caller lets one consumer refuse where the other
/// does not.
pub fn compile_entry_emission(
    source_roots: &[String],
    entry_path: &str,
    primary_precedence: bool,
    render_target: crate::v1_compiler_artifact::RenderTarget,
) -> EntryEmissionRun {
    let started = std::time::Instant::now();
    // The entry is a FILE, so it is anchored against the workspace root directly rather
    // than through `anchor_source_root`, which asserts a directory and panics on a path.
    let entry_abs = if std::path::Path::new(entry_path).is_absolute() {
        std::path::PathBuf::from(entry_path)
    } else {
        process_workspace_root().join(entry_path)
    };
    if !entry_abs.is_file() {
        return entry_emission_not_executed(
            entry_path,
            started,
            "entry-read",
            format!(
                "entry file does not exist: {entry_path} (--entry names a repo path, not a module path)"
            ),
        );
    }
    // AN ENTRY OUTSIDE THE WORKSPACE ROOT REFUSES HERE, WHERE THE PATH IS STILL A CLI
    // ARGUMENT, instead of panicking four frames down in module-graph keying.
    //
    // THE PREDICATE IS `repo_relative_path`, NOT `try_repo_relative_path_normalized`, and the
    // difference is load-bearing (review 55344). The `try_` helper has a third arm that strips
    // the COMPILE-TIME `workspace_root()`, which exists so sccache-embedded absolute spellings
    // from another runner checkout still key correctly -- an internal concern about paths the
    // compiler produced. Reused for a USER-SUPPLIED path it becomes a widening fallback: on a
    // host where the build checkout still exists, `--entry /that/other/checkout/x.dag` would be
    // admitted and keyed as though it belonged to THIS tree, silently mixing two trees. That is
    // the §5 failure arm that widens instead of refusing, inside the guard added to stop a
    // different §5 failure. `repo_relative_path` anchors against the PROCESS root only and is
    // already fail-closed by its own contract.
    //
    // HAND-RUST RECEIPT: this adds NO new path predicate. It consumes the existing gate, whose
    // authority is `gunbc.cli_run_repo_grant` `cli_run_repo_path_admissible` and whose
    // Rust/authority equivalence is pinned by
    // `dag/test/claim/cli_run_repo_grant_hand_rust_equivalence_witness_test.dag` together with
    // this file's `cli_run_repo_grant_equivalence_tests`. Its dissolve-on is that module's:
    // cli_run.rs Chunk F (docs/plans/cli-run-reconcile-defork.md), when the refusal becomes the
    // located `std.access.AccessDecision::Deny` from the single grant policy. Routing a second
    // hand-rolled containment check beside it would have been the §3 fork this receipt exists
    // to prevent.
    //
    // `repo_relative_path_normalized` panics for a path it cannot anchor, and that is the
    // right shape THERE: by the time a path reaches module-index keying, being unanchorable
    // is a broken invariant and not an input. But `--entry` is an INPUT, and an existing
    // file outside the repository is an ordinary thing to hand it -- a scratch fixture in
    // `/tmp` is what anyone probing this compiler writes first. The existence check above
    // passes for such a file, so it used to reach the keying panic: `rc=101`, no phase, no
    // located cause, and a caller reading only stdout sees an empty result indistinguishable
    // from a clean compile (measured 2026-08-24 while validating an annotation-grain probe).
    //
    // A panic is loud and fabricates nothing, so this is not silent wrongness -- it is an
    // untyped, unlocated failure where §5 asks for a typed located diagnostic. The refusal
    // names both the path and the root, because "not under the workspace root" is unactionable
    // without saying which root the process resolved.
    if repo_relative_path(&entry_abs).is_err() {
        return entry_emission_not_executed(
            entry_path,
            started,
            "entry-admission",
            format!(
                "entry file is outside the workspace root: {} is not under {} \
                 (--entry names a path inside the repository; a fixture written elsewhere, \
                 such as /tmp, cannot be keyed into the module graph -- write it under a \
                 source root and delete it afterwards)",
                entry_abs.display(),
                process_workspace_root().display()
            ),
        );
    }

    crate::v1_rt::resolution_silent_pick_enable();
    // ONE INDEX BUILD, NOT TWO. The closure loader and the census fill both need the
    // module index, and calling `load_sources_for_entry_with_pool_index` and then building
    // a second index for the census parsed ~3,800 modules twice per invocation (review
    // 55167). Building it here and handing the SAME index to both also removes the
    // possibility that the closure and the census are computed against different
    // populations, which is a correctness property and not only a cost one.
    let index: Rc<MultiEntryIndex> = if primary_precedence {
        Rc::new(build_multi_entry_index_primary_precedence(source_roots))
    } else {
        // Strict routes through the process-shared index, so a second `--entry` compile in
        // one process is a cache hit rather than a rebuild.
        process_shared_index(source_roots)
    };
    let closure = match load_sources_for_entry_with_pool(&index, entry_path) {
        Ok(closure) => closure,
        Err(e) => {
            let _ = crate::v1_rt::resolution_silent_pick_disable();
            return entry_emission_not_executed(
                entry_path,
                started,
                "closure-load",
                format!("reference-derived closure load failed: {e}"),
            );
        }
    };
    let closure_modules: std::collections::HashSet<String> = closure
        .iter()
        .filter_map(|s| extract_module_path(&s.content))
        .collect();

    // Everything indexed and outside the closure enters the NAME CENSUS only. This is
    // what makes the transaction see a parse break anywhere under the source roots, and
    // membership is keyed on MODULE PATH rather than file path because the closure loader
    // and the index normalize paths differently -- a file-path compare would fail to
    // exclude closure modules and double-load them into the census.
    let mut census_only: Vec<Rc<v1_compiler_compile::SourceFile>> = index
        .source_files
        .iter()
        .filter(
            |(module_path, _): &(&String, &Rc<v1_compiler_compile::SourceFile>)| {
                !closure_modules.contains(*module_path)
            },
        )
        .map(|(_, source)| source.clone())
        .collect();
    census_only.sort_by(|a, b| a.path.cmp(&b.path));
    let census_modules = census_only.len();

    let options = Rc::new(v1_compiler_compile::CompilePipelineOptions {
        analyze_complexity: false,
        census_only_sources: Rc::new(census_only.into()),
    });
    let result = v1_compiler_compile::compile_sources_with_options(
        Rc::new(closure.clone().into()),
        render_target,
        options,
    );
    let silent_pick = crate::v1_rt::resolution_silent_pick_disable();

    // ONE REFUSAL AUTHORITY, NOT A SECOND ONE SPELLED HERE. `stage0_self_compile_refusal_message`
    // is what `gunbc compile` itself stops on; restating "blocking, or zero files" would be
    // a second representation of one rule (DESIGN §2/§3), free to drift.
    let refusal = v1_compiler_compile::stage0_self_compile_refusal_message(
        format!("compile of {entry_path}"),
        result.clone(),
    );
    let blocking =
        v1_compiler_compile::interpreter_blocking_diagnostic_messages(result.diagnostics.clone())
            .len();
    // The silent-pick gate is part of the CLI's refusal, so it is part of the transaction's:
    // a gate that skipped it would green on a tree `gunbc compile` exits nonzero on.
    let disposition = match refusal {
        Some(cause) => EntryEmissionDisposition::Refused {
            phase: "emit".to_string(),
            cause,
        },
        None if !silent_pick.fn_parent_first_hits.is_empty() => EntryEmissionDisposition::Refused {
            phase: "silent-pick-gate".to_string(),
            cause: format!(
                "{} fn_parent_first_hit silent pick(s) in this compile",
                silent_pick.fn_parent_first_hits.len()
            ),
        },
        None => EntryEmissionDisposition::Completed {
            emitted_count: result.files.len(),
        },
    };

    EntryEmissionRun {
        entry: entry_path.to_string(),
        closure_modules: closure.len(),
        census_modules,
        blocking_diagnostics: blocking,
        // Derived from one population rather than scanned twice, so the two counts cannot
        // disagree with the total.
        advisory_diagnostics: result.diagnostics.len().saturating_sub(blocking),
        wall_ms: started.elapsed().as_millis(),
        disposition,
        result: Some(result),
        silent_pick,
    }
}

/// Every configured entry, each compiled whatever the previous one did. A first refusal
/// hiding the rest is the failure the required run's phase ordering already refuses to
/// make (the stopped-line audit: it reports everything, it never greens).
///
/// The pool-index policy is `primary-precedence`, matching the board's own invocation
/// (`docs/probes/curated_cargo_probe_one.sh`) rather than the CLI's default -- the gate
/// and the board must resolve the same modules or they are measuring different programs.
pub fn run_required_v2_emission(source_roots: &[String]) -> Result<Vec<EntryEmissionRun>, String> {
    let entries = required_v2_emission_entries();
    if entries.is_empty() {
        // An EMPTY ROSTER REFUSES. Zero entries compiled is not zero breaks -- it is the
        // phase failing to reach any subject, and reporting it as clean is the
        // empty-observation narrow (DESIGN, recurring failure modes).
        return Err(
            "gunbc.ci_layer_roots required_v2_emission_entries is empty — the phase has no subject"
                .to_string(),
        );
    }
    Ok(entries
        .iter()
        .map(|entry| {
            compile_entry_emission(
                source_roots,
                entry,
                true,
                crate::v1_compiler_artifact::RenderTarget::Rust,
            )
        })
        .collect())
}

/// THE PHASE'S OWN EVIDENCE, EXECUTED RATHER THAN DESCRIBED.
///
/// Two controlled fixture roots, authored to differ in ONE thing: `fixtures/v2_emission_gate/red`
/// holds the real specimen -- a standalone `//` block trailing a module with no declaration
/// after it -- and `fixtures/v2_emission_gate/green` holds the same block moved above the
/// declaration it describes, which is the placement DESIGN §4c admits. The RED must refuse
/// and the GREEN must complete; either flipping is a failure, because a gate that cannot go
/// red is a decoration and a gate that cannot go green is not usable.
///
/// The fixture roots are their OWN source roots, so this runs in well under a second and
/// does not depend on the state of the repository corpus -- an oracle authored
/// independently of the tree it will judge (DESIGN §5, on what may serve as an oracle).
pub fn run_required_v2_emission_selftest() -> Vec<String> {
    let mut failures = Vec::new();
    let red_root = "fixtures/v2_emission_gate/red".to_string();
    let green_root = "fixtures/v2_emission_gate/green".to_string();

    let red = compile_entry_emission(
        &[red_root],
        "fixtures/v2_emission_gate/red/subject.dag",
        true,
        crate::v1_compiler_artifact::RenderTarget::Rust,
    );
    match &red.disposition {
        EntryEmissionDisposition::Completed { emitted_count } => failures.push(format!(
            "selftest RED did not refuse: {emitted_count} file(s) emitted from the trailing-annotation fixture"
        )),
        // The refusal must be the ANNOTATION one. A fixture that refuses for an unrelated
        // reason would keep this control permanently green while the class it stands for
        // went unobserved.
        //
        // The expected sentence is ASKED FOR rather than spelled: it comes from the single
        // message authority, `std_source_annotation` `annotation_attachment_refusal_message`,
        // keyed on the typed variant `UnattachedAtScopeEnd` that this fixture provokes. A
        // literal here would have been a positional pointer into a message -- a second
        // spelling of a sentence one function owns, which a rewording silently invalidates
        // (DESIGN §3). Grounded this way, a rewording moves both sides together and the
        // check cannot rot; the variant, not the wording, is the identity being asserted.
        EntryEmissionDisposition::Refused { cause, .. } => {
            let expected = crate::std_source_annotation::annotation_attachment_refusal_message(
                Rc::new(
                    crate::std_source_annotation::AnnotationAttachmentRefusal::UnattachedAtScopeEnd {
                        origin: Rc::new(crate::std_types::SourceSpan {
                            file: String::new(),
                            start: 0,
                            end: 0,
                        }),
                    },
                ),
            );
            if !cause.contains(&expected) {
                failures.push(format!(
                    "selftest RED refused for the wrong cause; expected the UnattachedAtScopeEnd refusal ({expected}), got: {cause}"
                ));
            }
        }
        EntryEmissionDisposition::NotExecuted {
            earlier_phase,
            cause,
        } => failures.push(format!(
            "selftest RED never ran ({earlier_phase}): {cause}"
        )),
    }

    let green = compile_entry_emission(
        &[green_root],
        "fixtures/v2_emission_gate/green/subject.dag",
        true,
        crate::v1_compiler_artifact::RenderTarget::Rust,
    );
    match &green.disposition {
        EntryEmissionDisposition::Completed { .. } => {}
        EntryEmissionDisposition::Refused { phase, cause } => {
            failures.push(format!("selftest GREEN refused at {phase}: {cause}"))
        }
        EntryEmissionDisposition::NotExecuted {
            earlier_phase,
            cause,
        } => failures.push(format!(
            "selftest GREEN never ran ({earlier_phase}): {cause}"
        )),
    }
    failures
}

/// Import-edge closure ONLY — no reference-derived or bare-reference extension.
/// Host twin for witnesses proving a module's cross-module bindings come from
/// declared `import` edges, not pool membership or bare-reference coincidence
/// (Class B controls per DESIGN import-strip witness-discovery cascade).
#[cfg(feature = "test_hooks")]
pub fn declared_import_closure_live_paths(
    source_roots: &[String],
    entry_path: &str,
) -> Result<Vec<String>, String> {
    let index = build_multi_entry_index_primary_precedence(source_roots);
    let entry_rel = workspace_relative_entry_path(entry_path);
    if !index.module_graph_facts.declares_repo_path(&entry_rel) {
        return Err(format!(
            "declared_import_closure_live_paths: entry '{entry_rel}' has no provenance in the module-graph facts pool (fail-closed)"
        ));
    }
    Ok(import_closure_live_paths_with_facts(
        &entry_rel,
        &index.module_graph_facts,
    ))
}

/// Whether `module_path` is indexed under primary-precedence `pool_roots`.
#[cfg(feature = "test_hooks")]
pub fn primary_precedence_pool_contains_module(pool_roots: &[String], module_path: &str) -> bool {
    let index = build_multi_entry_index_primary_precedence(pool_roots);
    index.source_files.contains_key(module_path)
}

/// Repo-relative paths of modules loaded for the entry's declared import closure.
#[cfg(feature = "test_hooks")]
pub fn declared_import_closure_source_paths(
    pool_roots: &[String],
    entry_path: &str,
) -> Result<Vec<String>, String> {
    let index = build_multi_entry_index_primary_precedence(pool_roots);
    let sources = load_declared_import_closure_sources(&index, entry_path)?;
    Ok(sources
        .iter()
        .map(|s| workspace_relative_repo_path(&s.path))
        .collect())
}

fn load_declared_import_closure_sources(
    index: &MultiEntryIndex,
    entry_path: &str,
) -> Result<Vec<Rc<v1_compiler_compile::SourceFile>>, String> {
    let entry_source = entry_source_from_index_or_disk(&index.source_files, entry_path)?;
    let rel_path = entry_source.path.clone();
    let mut sources = resolve_transitively(
        vec![entry_source.clone()],
        &index.source_files,
        &index.module_graph_facts,
    )?;
    if !sources
        .iter()
        .any(|s| s.path == rel_path || same_canonical_file(&s.path, &rel_path))
    {
        sources.push(entry_source);
    }
    sources.sort_by(|a, b| a.path.cmp(&b.path));
    sources.dedup_by(|a, b| a.path == b.path);
    Ok(sources)
}

/// Resolve/typecheck an entry using ONLY its declared import-edge closure.
#[cfg(feature = "test_hooks")]
pub fn compile_entry_on_declared_import_closure_only(
    source_roots: &[String],
    entry_path: &str,
) -> Result<Rc<v1_compiler_compile::ResolvedPipelineResult>, String> {
    compile_declared_import_closure_only_with_pool(source_roots, entry_path, None)
}

/// Pool-scoped variant: builds the module index from `pool_roots` but compiles only
/// the entry's declared import-edge closure. Use a tmp-root overlay (primary-precedence
/// root[0]) when simulating a stripped entry so pool membership can affect resolution
/// while the import closure stays entry-only; `entry_content_override` skips the pool
/// entirely and is only for fast isolated negative controls without ambient pressure.
pub fn compile_declared_import_closure_only_with_pool(
    pool_roots: &[String],
    entry_path: &str,
    entry_content_override: Option<&str>,
) -> Result<Rc<v1_compiler_compile::ResolvedPipelineResult>, String> {
    let index = build_multi_entry_index_primary_precedence(pool_roots);
    let sources = if let Some(content) = entry_content_override {
        vec![Rc::new(v1_compiler_compile::SourceFile {
            path: entry_path.to_string(),
            content: content.to_string(),
        })]
    } else {
        load_declared_import_closure_sources(&index, entry_path)?
    };
    Ok(v1_compiler_compile::compile_to_resolved(Rc::new(
        sources.into(),
    )))
}

/// Declaration identity + binding-source receipt for one cross-module symbol site.
#[cfg(feature = "test_hooks")]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CrossModuleBindingReceipt {
    pub definer_module: Option<String>,
    pub binding_source: Option<UnlistedImportBindingSource>,
}

/// Extract per-symbol binding receipts for a consumer module against a resolved graph.
#[cfg(feature = "test_hooks")]
pub fn cross_module_binding_receipts_for_symbols(
    graph: &ResolvedGraph,
    consumer_module: &str,
    symbols: &[&str],
) -> std::collections::BTreeMap<String, CrossModuleBindingReceipt> {
    use std::collections::BTreeMap;
    symbols
        .iter()
        .map(|sym| {
            let definer = definer_module_for_name(graph, sym);
            let binding_source = if definer.is_some() {
                Some(classify_unlisted_import_binding_source(graph, consumer_module, sym).0)
            } else {
                None
            };
            (
                (*sym).to_string(),
                CrossModuleBindingReceipt {
                    definer_module: definer,
                    binding_source,
                },
            )
        })
        .collect::<BTreeMap<_, _>>()
}

/// Builtins that REQUIRE a service registration to dispatch, paired with the
/// services-census key whose provider must therefore be in the closure. This is
/// the one dependency edge a name-derived closure cannot see: the builtin's
/// identifier is the interpreter's, not any module's, so no census lookup
/// reaches the provider — under imports the edge was a name-less `import
/// extdeps.filesystem.filesystem_io`, which the strip removed and nothing can
/// re-derive.
///
/// Rows mirror the hard `ctx.service_ops.contains_key(..)` REQUIREMENT gates in
/// `v1_interpreter` — not the optional ones (`Clock.UnixSecs`,
/// `shell.Env.Get`), which fall back to a transport when the service is absent
/// and so create no closure obligation. A missing row cannot fabricate a
/// result: the builtin's own gate still refuses, typed and located (that
/// refusal is exactly how this row was found — `interp_recorded_fixture`'s
/// nested replay, CI 29722434993).
/// Pairs are (builtin identifier, SERVICES-CENSUS key). The census key is the
/// service's authored name (`Filesystem`, or a dotted one like `cron.Tab`) —
/// NOT the interpreter's `service_ops` operation key (`Filesystem.Read`), which
/// appends the operation.
const BUILTIN_REQUIRED_SERVICE_KEYS: &[(&str, &str)] = &[("filesystem_read", "Filesystem")];

/// Bare (non-dotted) identifiers in `content`, split by whether any occurrence
/// sits in CALL POSITION (immediately followed by `(`). The split is the pull
/// discriminator: the census strips fn bodies, so a 0-arg fn and a type alias
/// share a census shape ("pending a discriminator", census note) — but a 0-arg
/// fn is referenced `name()` while a type name never is. Deliberately an
/// over-approximation on the name axis (locals and keywords are included): a
/// false candidate costs a census map miss, never a wrong closure. String
/// literals are skipped for the same reason as the dotted scan.
struct BareCandidates {
    names: BTreeSet<String>,
    call_position: BTreeSet<String>,
    /// Full dotted chains (`cron.Tab.List` in `cron.Tab.List()`): the dotted
    /// module-path scan owns chains whose prefix is a module path, but a
    /// SERVICE reference's prefix is a services-census key (`cron.Tab`,
    /// `llm.Codex` — service names are themselves dotted) with no module
    /// spelling — with its import stripped, only the services census can name
    /// its provider module. The consumer tries each dot-prefix of the chain
    /// against the services census.
    dotted_chains: BTreeSet<String>,
    /// Names seen in BINDING position (`let repo`, `data x`) or KEY position
    /// (`repo:` — field init, named arg, param decl) anywhere in the file. A
    /// dotted-chain head in this set is a local/param/field projection
    /// (`repo.operation_name`), never a cross-module data-const reference —
    /// consulted to keep dotted-head pulls from re-opening the over-pull the
    /// binder/key lexer closed for bare names.
    bound: BTreeSet<String>,
}

/// Byte offsets of `(` that open an arrow-lambda param list (`(a, b) => ...`,
/// no `fn` keyword) and of `{` that open a match/destructuring PATTERN
/// (`Variant { field: name } => ...`) — both shapes bind every leaf identifier
/// inside, but the single-pass scanner below only recognizes them once it has
/// already passed the opening delimiter, so a lookahead pre-pass locates the
/// delimiters whose matching close is followed by `=>`. Measured: `(acc,
/// step) =>` (no `fn`) in `extdeps/communication/fidelity_carriers.dag` leaked
/// bare `step`, and `HeadFound { value: h2 } =>` in
/// `std/cross_tree/resolution.dag` leaked bare `h2` — both census-unique-bound
/// to unrelated fn decls (`test.claim.materialization_ladder_witness.step`,
/// `gunbc.plans.md_helpers.h2`), over-pulling those modules into 13 unrelated
/// compiler-closure entries. String literals are skipped, matching the main
/// scan.
/// Blank every source-annotation (`//` to end of line) region, preserving byte
/// offsets and line structure so a scanner's spans stay valid.
///
/// DESIGN §4c: semantic passes receive only the annotation-erased projection.
/// The three raw-text scanners below (`referenced_module_paths_in_text`,
/// `destructuring_bound_spans`, `bare_identifier_candidates`) already skip
/// string literals; annotations were the remaining unerased region, so prose
/// carried in an annotation was lexed as program text. Measured on the M1C
/// prose migration: moving rationale out of a `data _note: String` — a region
/// the string skip already erased — into the sanctioned `//` form made the
/// English word `edge` in `v2.lens.identity_captured_navigation` a bare
/// reference, which bound to `v2.test.manual.ownership_movable`'s `fn edge`
/// and pulled that module (an off-path manual witness importing `src/v1`) into
/// an unrelated `src/v2` entry's pool, where its import cannot resolve.
/// Erasure is one authority, applied at each scan entry, rather than a
/// per-scanner comment rule.
fn annotation_erased_scan_text(content: &str) -> String {
    let bytes = content.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] == b'"' {
            out.push(bytes[i]);
            i += 1;
            while i < bytes.len() && bytes[i] != b'"' {
                if bytes[i] == b'\\' && i + 1 < bytes.len() {
                    out.push(bytes[i]);
                    i += 1;
                }
                out.push(bytes[i]);
                i += 1;
            }
            if i < bytes.len() {
                out.push(bytes[i]);
                i += 1;
            }
            continue;
        }
        if bytes[i] == b'/' && i + 1 < bytes.len() && bytes[i + 1] == b'/' {
            while i < bytes.len() && bytes[i] != b'\n' {
                out.push(b' ');
                i += 1;
            }
            continue;
        }
        out.push(bytes[i]);
        i += 1;
    }
    String::from_utf8(out).unwrap_or_else(|_| content.to_string())
}

fn destructuring_bound_spans(content: &str) -> (BTreeSet<usize>, BTreeSet<usize>) {
    let content: &str = &annotation_erased_scan_text(content);
    let bytes = content.as_bytes();
    let is_ident = |c: u8| c.is_ascii_alphanumeric() || c == b'_';
    let matching_close = |open_at: usize, open: u8, close: u8| -> Option<usize> {
        let mut depth = 0i32;
        let mut j = open_at;
        while j < bytes.len() {
            match bytes[j] {
                b'"' => {
                    j += 1;
                    while j < bytes.len() && bytes[j] != b'"' {
                        if bytes[j] == b'\\' && j + 1 < bytes.len() {
                            j += 1;
                        }
                        j += 1;
                    }
                }
                b if b == open => depth += 1,
                b if b == close => {
                    depth -= 1;
                    if depth == 0 {
                        return Some(j);
                    }
                }
                _ => {}
            }
            j += 1;
        }
        None
    };
    let mut lambda_paren_starts = BTreeSet::new();
    let mut pattern_brace_starts = BTreeSet::new();
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] == b'"' {
            i += 1;
            while i < bytes.len() && bytes[i] != b'"' {
                if bytes[i] == b'\\' && i + 1 < bytes.len() {
                    i += 1;
                }
                i += 1;
            }
            i += 1;
            continue;
        }
        if bytes[i] == b'(' && (i == 0 || !is_ident(bytes[i - 1])) {
            if let Some(close) = matching_close(i, b'(', b')') {
                let mut j = close + 1;
                while j < bytes.len() && bytes[j].is_ascii_whitespace() {
                    j += 1;
                }
                if content.as_bytes()[j..].starts_with(b"=>") {
                    lambda_paren_starts.insert(i);
                }
            }
        } else if bytes[i] == b'{' {
            if let Some(close) = matching_close(i, b'{', b'}') {
                let mut j = close + 1;
                while j < bytes.len() && bytes[j].is_ascii_whitespace() {
                    j += 1;
                }
                if content.as_bytes()[j..].starts_with(b"=>") {
                    pattern_brace_starts.insert(i);
                }
            }
        }
        i += 1;
    }
    (lambda_paren_starts, pattern_brace_starts)
}

fn bare_identifier_candidates(content: &str) -> BareCandidates {
    let content: &str = &annotation_erased_scan_text(content);
    let bytes = content.as_bytes();
    let is_ident_start = |c: u8| c.is_ascii_alphabetic() || c == b'_';
    let is_ident = |c: u8| c.is_ascii_alphanumeric() || c == b'_';
    let mut out = BareCandidates {
        names: BTreeSet::new(),
        call_position: BTreeSet::new(),
        dotted_chains: BTreeSet::new(),
        bound: BTreeSet::new(),
    };
    let (lambda_paren_starts, pattern_brace_starts) = destructuring_bound_spans(content);
    let mut i = 0usize;
    // Previous identifier token on the same run (whitespace-separated): a name
    // directly after a BINDER keyword is a binding occurrence, not a reference —
    // `let repo = ...` must not pull the module that declares a census-unique
    // `data repo` (measured: it coupled the gunbhub witness to the review-agent
    // tooling's health). Cleared by any non-ident, non-whitespace byte.
    let mut prev_token: Option<&str> = None;
    let binder_keywords = [
        "let",
        "data",
        "fn",
        "type",
        "import",
        "module",
        "service",
        "transport",
    ];
    // Depth of an open `fn(`-literal parameter list, OR an arrow-lambda param
    // list (`(a, b) => ...`, no `fn` — see `destructuring_bound_spans`): every
    // ident inside is a BINDER (untyped lambda params carry no `:` so the
    // key-position rule never sees them; measured: rust_test.dag's `fn(acc,
    // edge)` param leaked 'edge' into the reference set and pulled the
    // unresolvable ownership_movable test module into an unrelated entry).
    // Typed idents inside (`p: T`, and type names in `fn(A) -> B` annotations)
    // over-bind harmlessly: a suppressed pull fails LOUD at typecheck.
    let mut fn_params_depth: usize = 0;
    // Depth of an open match/destructuring PATTERN brace (`Variant { field:
    // name } => ...` — see `destructuring_bound_spans`): a bare leaf identifier
    // directly after `:` inside is a new local binding, not a reference. A
    // nested variant tag (`field: OtherType { .. }`, itself followed by `{`)
    // stays a real reference — the declaring module's runtime construction and
    // variant-tag identity still need it loaded.
    let mut pattern_depth: usize = 0;
    let mut just_saw_colon = false;
    while i < bytes.len() {
        if bytes[i] == b'"' {
            i += 1;
            while i < bytes.len() && bytes[i] != b'"' {
                if bytes[i] == b'\\' && i + 1 < bytes.len() {
                    i += 1;
                }
                i += 1;
            }
            i += 1;
            prev_token = None;
            just_saw_colon = false;
            continue;
        }
        if !is_ident_start(bytes[i]) || (i > 0 && (is_ident(bytes[i - 1]) || bytes[i - 1] == b'.'))
        {
            if bytes[i] == b'(' {
                if prev_token == Some("fn") || lambda_paren_starts.contains(&i) {
                    fn_params_depth = 1;
                } else if fn_params_depth > 0 {
                    fn_params_depth += 1;
                }
            } else if bytes[i] == b')' && fn_params_depth > 0 {
                fn_params_depth -= 1;
            } else if bytes[i] == b'{' && (pattern_depth > 0 || pattern_brace_starts.contains(&i)) {
                pattern_depth += 1;
            } else if bytes[i] == b'}' && pattern_depth > 0 {
                pattern_depth -= 1;
            }
            if bytes[i] == b':' {
                just_saw_colon = true;
            } else if !bytes[i].is_ascii_whitespace() {
                just_saw_colon = false;
            }
            if !bytes[i].is_ascii_whitespace() {
                prev_token = None;
            }
            i += 1;
            continue;
        }
        let start = i;
        while i < bytes.len() && is_ident(bytes[i]) {
            i += 1;
        }
        // Part of a dotted chain → the dotted scan owns module-path chains, but
        // record the FULL chain: a service reference (`cron.Tab.List()`) is a
        // dotted chain whose prefix is a services-census key, not a module path.
        if i < bytes.len() && bytes[i] == b'.' {
            while i < bytes.len()
                && bytes[i] == b'.'
                && i + 1 < bytes.len()
                && is_ident_start(bytes[i + 1])
            {
                i += 1;
                while i < bytes.len() && is_ident(bytes[i]) {
                    i += 1;
                }
            }
            out.dotted_chains.insert(content[start..i].to_string());
            prev_token = None;
            just_saw_colon = false;
            continue;
        }
        let name = &content[start..i];
        // A PARENTHESIS-FREE arrow lambda binds its single parameter: `any(t => ...)`,
        // `map(rm => ...)`, `fold(xs, init: 0, f: acc => ...)`. `destructuring_bound_spans`
        // only recognises the parenthesised form `(a, b) =>` and the pattern form
        // `{ .. } =>`, so this one leaked its binder into the reference set — and a
        // one-letter binder resolves against the WHOLE POOL, where some module
        // somewhere declares `fn t`. Receipt: `dag/std/algebra.dag`'s
        // `any(t => t.name == name)` pulled `dag/test/claim/pcb_footprint_witness_test.dag`
        // (which declares `fn t(component, terminal)`) and through it the entire PCB
        // product corpus into the v1 seed's compile closure.
        //
        // The guard is the PRECEDING token, not the arrow alone: a match arm head is
        // also `ident =>` but is preceded by `{`, `}` or a newline, whereas a lambda
        // parameter sits in argument position — after `(`, `,` or a named-argument
        // `:`. Measured over the corpus, all 4397 sites matching that shape are
        // lambdas; no match-arm head is preceded by any of the three.
        let is_bare_arrow_lambda_param = {
            let mut j = i;
            while j < bytes.len() && bytes[j].is_ascii_whitespace() {
                j += 1;
            }
            let arrow = content.as_bytes()[j..].starts_with(b"=>");
            let mut k = start;
            while k > 0 && bytes[k - 1].is_ascii_whitespace() {
                k -= 1;
            }
            let prev = if k > 0 { bytes[k - 1] } else { b'\0' };
            arrow && matches!(prev, b'(' | b',' | b':')
        };
        if is_bare_arrow_lambda_param {
            out.bound.insert(name.to_string());
            prev_token = Some(name);
            just_saw_colon = false;
            continue;
        }
        let was_after_colon = just_saw_colon;
        just_saw_colon = false;
        // Binding occurrence (`let repo`, `data repo`) — a name being BOUND is
        // never a reference to another module's decl.
        if fn_params_depth > 0 {
            out.bound.insert(name.to_string());
            prev_token = Some(name);
            continue;
        }
        if prev_token.is_some_and(|t| binder_keywords.contains(&t)) {
            out.bound.insert(name.to_string());
            prev_token = Some(name);
            continue;
        }
        // Pattern-value leaf (`Variant { field: name } => ...`): a bare leaf
        // directly after `:` inside a destructuring pattern brace introduces a
        // new local binding, never a reference — see `destructuring_bound_spans`.
        // A nested variant tag (itself followed by `{` or `(`) stays a real
        // reference.
        if pattern_depth > 0 && was_after_colon {
            let mut peek = i;
            while peek < bytes.len() && (bytes[peek] == b' ' || bytes[peek] == b'\t') {
                peek += 1;
            }
            let is_leaf = !(peek < bytes.len() && (bytes[peek] == b'{' || bytes[peek] == b'('));
            if is_leaf {
                out.bound.insert(name.to_string());
                prev_token = Some(name);
                continue;
            }
        }
        // Key position (`repo: value` — field init, named arg, param decl):
        // the name labels a slot; it never references a decl.
        let mut peek = i;
        while peek < bytes.len() && (bytes[peek] == b' ' || bytes[peek] == b'\t') {
            peek += 1;
        }
        if peek < bytes.len() && bytes[peek] == b':' {
            out.bound.insert(name.to_string());
            // A key is not a binder-keyword context: `type: User` must leave
            // `User` a collectable reference — carrying `type` forward as
            // prev_token made the binder-keyword rule swallow the VALUE after
            // any key that happens to spell a keyword.
            prev_token = None;
            continue;
        }
        if i < bytes.len() && bytes[i] == b'(' {
            out.call_position.insert(name.to_string());
        }
        out.names.insert(name.to_string());
        prev_token = Some(name);
    }
    out
}

#[cfg(test)]
mod bare_identifier_candidates_tests {
    use super::bare_identifier_candidates;

    // Green-by-execution + discriminating RED for the two over-pull shapes fixed by
    // `destructuring_bound_spans` (measured: `(acc, step) =>` in
    // `extdeps/communication/fidelity_carriers.dag` and `HeadFound { value: h2 } =>` in
    // `std/cross_tree/resolution.dag` census-unique-bound `step`/`h2` to unrelated fn
    // decls, over-pulling 13 compiler-closure entries — `extend_with_bare_reference_closure`
    // subtracts `candidates.bound` from `candidates.names` file-wide, so a name absent
    // from `bound` here is a name that still pulls its census homonym downstream).
    #[test]
    fn arrow_lambda_param_is_bound_not_referenced() {
        let content = "module test.lambda_user\n\nfn use_it() -> Bool {\n  fold_list(\n    xs: something,\n    empty: true,\n    cons: (acc, step) => decode_fidelity_merge(left: acc, right: step)\n  )\n}\n";
        let candidates = bare_identifier_candidates(content);
        assert!(
            candidates.bound.contains("step"),
            "an arrow-lambda param (`(acc, step) => ...`, no `fn`) must be recorded as \
             bound — a reader that only recognized `fn(...)` params would miss this"
        );
        assert!(
            candidates.bound.contains("acc"),
            "both arrow-lambda params must be bound, not just the first"
        );
    }

    #[test]
    fn pattern_value_leaf_is_bound_not_referenced() {
        let content = "module test.pattern_user\n\nfn use_it() -> Bool {\n  match something {\n    HeadFound { value: h2 } => h2\n    HeadAbsent => true\n  }\n}\n";
        let candidates = bare_identifier_candidates(content);
        assert!(
            candidates.bound.contains("h2"),
            "a pattern-value leaf (`HeadFound {{ value: h2 }} => ...`) must be recorded as \
             bound — it introduces a new local binding, not a reference to an unrelated \
             `h2` decl"
        );
        assert!(
            !candidates.bound.contains("HeadFound"),
            "a nested variant TAG inside a pattern brace is still a real reference to its \
             declaring module — only the post-colon leaf is bound"
        );
        assert!(
            candidates.names.contains("HeadFound"),
            "the variant tag must remain a collectable name candidate"
        );
    }
}

/// Per-module outgoing edges for the both-closure fixpoint — built once per
/// `MultiEntryIndex` process and reused across every entry load. Dissolves the
/// #6848 once-per-entry cost: the fixpoint becomes graph BFS over these edges
/// instead of re-scanning every module's text and re-querying the census on each
/// of ~2100 discovery entries (~140ms/witness PRE-fix).
struct BothClosureEdgeIndex {
    /// workspace-relative file path → files pulled by bare-reference resolution
    /// (each target is the full import-closure of the resolved provider).
    bare_out: HashMap<String, Vec<String>>,
    /// workspace-relative file path → files pulled by dotted module-path refs.
    ref_out: HashMap<String, Vec<String>>,
    /// Import-stripped files that may originate bare-reference edges.
    bare_scan_eligible: HashSet<String>,
}

/// The names a module declares FOR ITSELF, including the variant heads of its own
/// coproducts.
///
/// The bare census indexes top-level declaration heads. A coproduct VARIANT is not
/// one, so a module that declares `type VisibilityScope = Repo | Org | Network | World`
/// and then writes `World` was scanned as referencing some other module — and the
/// pool happens to contain `type World sole_constructor` in `dag/product/spatial_world.dag`,
/// so `std.cache_interface` acquired a closure edge to the spatial product corpus.
///
/// Three more of the identical shape in one closure: `Volume` (a variant of
/// `std.measure`'s own `Dimension`, pulled `gunbc.roadmap_model`), `Measured` (a
/// variant of `std.realization_schedule`'s own coproduct, pulled `std.observation`),
/// and `ExtentInFrame` (a variant in `std.spatial_frame`, pulled `std.attribution`).
///
/// This is not a tiebreak and not a policy: a name the module itself declares is
/// bound by that declaration, so it can never be a reference OUT. Skipping it is the
/// language's own scoping rule, not a heuristic about which candidate is likelier.
fn module_self_declared_names(content: &str) -> BTreeSet<String> {
    let content: &str = &annotation_erased_scan_text(content);
    let mut out = BTreeSet::new();
    let ident_head = |s: &str| -> Option<String> {
        let s = s.trim_start();
        let mut end = 0;
        for (idx, c) in s.char_indices() {
            if c.is_alphanumeric() || c == '_' {
                end = idx + c.len_utf8();
            } else {
                break;
            }
        }
        if end == 0 {
            None
        } else {
            Some(s[..end].to_string())
        }
    };
    let mut in_coproduct = false;
    for line in content.lines() {
        let l = line.trim_start();
        let decl_head = [
            "pub type ",
            "pub data ",
            "pub fn ",
            "pub func ",
            "type ",
            "data ",
            "fn ",
            "func ",
            "test fn ",
            "test data ",
        ]
        .iter()
        .find_map(|k| l.strip_prefix(*k));
        if let Some(rest) = decl_head {
            if let Some(name) = ident_head(rest) {
                out.insert(name);
            }
            // TYPE PARAMETERS on the declaration head. `type Result<ok, err> = Ok { value: ok }
            // | Err { value: err }` in `std.error_primitives` binds `ok` and `err`; scanned as
            // references they resolved against the whole pool to `fn ok(out: String) ->
            // SshSessionExecResult` in a spark serving witness test, so `std.error_primitives`
            // acquired closure edges to that witness and to `extdeps.ssh.session` — and
            // `extdeps.dns.domain_name`'s `Ok { value: labels |> list_push(label) }` then
            // typed `labels` as `SshSessionExecResult`.
            let after_name = rest.trim_start();
            let ident_end = after_name
                .find(|c: char| !(c.is_alphanumeric() || c == '_'))
                .unwrap_or(after_name.len());
            let tail = after_name[ident_end..].trim_start();
            if let Some(params) = tail.strip_prefix('<').and_then(|s| s.split_once('>')) {
                for part in params.0.split(',') {
                    if let Some(name) = ident_head(part) {
                        out.insert(name);
                    }
                }
            }
            // `type X = ...` opens a coproduct whose variant heads continue on this
            // line and on following lines beginning with `|`. The MULTILINE form puts
            // the `=` on the NEXT line instead —
            //
            //     type FrameExtent
            //       = ExtentInFrame { length: FrameLength }
            //       | ExtentFrameUnregistered { .. }
            //
            // — so a bare `type X` head opens one too, pending its `=`. Review 55386
            // caught this: without it `ExtentInFrame` and `Predicted` were never
            // collected, two of the four variants this guard exists for, and the
            // closure improvement measured for their modules came from those modules
            // leaving the closure for an unrelated reason. Right conclusion, wrong
            // evidence.
            //
            // The same-line extraction below is gated on the LINE's own `=` rather than
            // on the flag, so widening the flag cannot silently disable it.
            let is_type_head = l.starts_with("type ") || l.starts_with("pub type ");
            in_coproduct = is_type_head;
            if is_type_head {
                if let Some((_, body)) = l.split_once('=') {
                    // An ALIAS is not a declaration of its target. `type List<element> =
                    // FreeMonoid<element>` declares `List`; `FreeMonoid` is a REFERENCE
                    // OUT, and collecting it here suppresses the closure edge to whoever
                    // declares it — an under-pull, the dangerous direction (review 55399).
                    // The discriminator is the RHS's own shape: a coproduct alternates
                    // (`|`) or carries a record payload (`{`); an alias does neither.
                    let is_alias = !body.contains('|') && !body.contains('{');
                    if is_alias {
                        in_coproduct = false;
                    } else {
                        for part in body.split('|') {
                            if let Some(name) = ident_head(part) {
                                out.insert(name);
                            }
                        }
                    }
                }
            }
            continue;
        }
        if l.starts_with('|') || (in_coproduct && l.starts_with('=')) {
            in_coproduct = true;
            for part in l.trim_start_matches(['|', '=']).split('|') {
                if let Some(name) = ident_head(part) {
                    out.insert(name);
                }
            }
            continue;
        }
        if !l.is_empty() && !l.starts_with('|') {
            in_coproduct = in_coproduct && l.starts_with('{');
        }
    }
    out
}

fn source_declares_import_lines(content: &str) -> bool {
    content
        .lines()
        .any(|l| l.trim_start().starts_with("import "))
}

/// BFS closure extension over a precomputed per-file edge map.
fn extend_sources_via_edge_map(
    mut sources: Vec<Rc<v1_compiler_compile::SourceFile>>,
    edge_map: &HashMap<String, Vec<String>>,
    scan_eligible: Option<&HashSet<String>>,
    path_lookup: &HashMap<String, Rc<v1_compiler_compile::SourceFile>>,
) -> Result<Vec<Rc<v1_compiler_compile::SourceFile>>, String> {
    let mut known_paths: HashSet<String> = sources
        .iter()
        .flat_map(|s| [s.path.clone(), workspace_relative_repo_path(&s.path)])
        .collect();
    let mut queue: VecDeque<String> = sources
        .iter()
        .map(|s| workspace_relative_repo_path(&s.path))
        .collect();
    while let Some(file_rel) = queue.pop_front() {
        if scan_eligible.is_some_and(|eligible| !eligible.contains(&file_rel)) {
            continue;
        }
        let Some(pulled) = edge_map.get(&file_rel) else {
            continue;
        };
        for rel in pulled {
            if known_paths.contains(rel) {
                continue;
            }
            let Some(dep_sf) = path_lookup.get(rel).cloned() else {
                return Err(format!(
                    "closure_edge_map: pulled path '{rel}' (from '{file_rel}') has no \
                     provenance in module index (fail-closed)"
                ));
            };
            known_paths.insert(rel.clone());
            known_paths.insert(dep_sf.path.clone());
            sources.push(dep_sf.clone());
            queue.push_back(rel.clone());
        }
    }
    Ok(sources)
}

fn bare_reference_pull_paths_for_source(
    sf: &Rc<v1_compiler_compile::SourceFile>,
    index: &MultiEntryIndex,
) -> Result<Vec<String>, String> {
    use crate::v1_compiler_infer_env::GlobalBareLookupState;
    let file_rel = workspace_relative_repo_path(&sf.path);
    let Some(root) = source_tree_root_of(&index.source_roots, &file_rel) else {
        return Ok(Vec::new());
    };
    let (census, census_nanos) =
        nanos_net_of_pool_parse(|| tree_bare_census_for_root(index, &root));
    let census = census?;
    resolve_stage_slot_add(|st| {
        st.edge_index_tree_census += census_nanos;
        st.edge_index_tree_census_calls += 1;
    });
    let referencing_module = extract_module_path(&sf.content).unwrap_or_default();
    let cand_started = std::time::Instant::now();
    let candidates = bare_identifier_candidates(&sf.content);
    resolve_stage_slot_add(|st| st.edge_index_bare_candidates += cand_started.elapsed().as_nanos());
    // The name-universe fold: dotted-chain prefixes, builtin service keys, and the
    // unbound-name join that produces the roster the resolve loop below walks. Split
    // out because everything under the bare half that is neither the census nor the
    // candidate scan was landing in an unattributed remainder, and an unattributed
    // remainder large enough to be the second-largest term is a seam nobody has looked at.
    let universe_started = std::time::Instant::now();
    let mut service_prefixes: BTreeSet<String> = candidates
        .dotted_chains
        .iter()
        .flat_map(|chain| {
            let mut prefixes = Vec::new();
            let mut acc = String::new();
            for seg in chain.split('.') {
                if !acc.is_empty() {
                    acc.push('.');
                }
                acc.push_str(seg);
                prefixes.push(acc.clone());
            }
            prefixes
        })
        .collect();
    for (builtin_name, service_key) in BUILTIN_REQUIRED_SERVICE_KEYS {
        if candidates.call_position.contains(*builtin_name) {
            service_prefixes.insert((*service_key).to_string());
        }
    }
    let dotted_head_refs: Vec<String> = candidates
        .dotted_chains
        .iter()
        .filter_map(|chain| chain.split('.').next())
        .filter(|h| !candidates.bound.contains(*h) && !candidates.names.contains(*h))
        .map(|h| h.to_string())
        .collect();
    let all_names: Vec<(String, bool)> = candidates
        .names
        .iter()
        .filter(|n| !candidates.bound.contains(*n))
        .map(|n| (n.clone(), false))
        .chain(dotted_head_refs.into_iter().map(|n| (n, false)))
        .chain(service_prefixes.into_iter().map(|n| (n, true)))
        .collect();
    resolve_stage_slot_add(|st| {
        st.edge_index_bare_name_universe += universe_started.elapsed().as_nanos();
    });
    let self_declared = module_self_declared_names(&sf.content);
    let mut pulled: Vec<String> = Vec::new();
    let mut pulled_set: HashSet<String> = HashSet::new();
    let resolve_loop_started = std::time::Instant::now();
    let resolve_loop_pool_before = resolve_stage_slot_snapshot().pool_parse;
    for (name, service_head) in all_names {
        // Bound by this module's own declaration — see `module_self_declared_names`.
        if !service_head && self_declared.contains(&name) {
            continue;
        }
        let in_call_position = candidates.call_position.contains(&name);
        let pullable = |binding: &Rc<crate::v1_compiler_infer_env::TypeBinding>| {
            in_call_position
                || !binding.resolved.params.is_empty()
                || binding.resolved.type_annotation.is_some()
                || binding.resolved.connective != crate::v1_std_core::Connective::NoConnective
        };
        // Returns WHAT was selected and, beside it, WHICH CENSUS STATE produced the
        // selection. The state is the census's own verdict — `GlobalBareUniqueBinding`
        // versus `GlobalBareAmbiguousBinding` — and it is the authority on whether a
        // bare name has competing declarations. Reconstructing that from source with a
        // declaration-head scanner does not work: a line-leading `=`/`|` regex
        // undercounts (it misses `type Connective = Conj | Disj | NoConnective | Arrow`
        // entirely) and a permissive one overcounts (it reads an alias target and a
        // `data` initializer's head as variants), and the two answers differ by 30x on
        // the same trace. The census already knows; carrying its verdict costs nothing.
        let resolve_in = |census: &Rc<SymbolIndex>| -> (Option<String>, &'static str) {
            if service_head {
                return (
                    v1_rt::map_get(&census.services, name.clone())
                        .map(|entry| entry.module_path.clone()),
                    "service",
                );
            }
            match v1_rt::map_get(&census.global_bare, name.clone()) {
                Some(state) => match state.as_ref() {
                    GlobalBareLookupState::GlobalBareUniqueBinding {
                        module_path,
                        binding,
                    } => (
                        if pullable(binding) {
                            Some(module_path.clone())
                        } else {
                            None
                        },
                        "unique",
                    ),
                    GlobalBareLookupState::GlobalBareAmbiguousBinding { candidates } => (
                        crate::v1_compiler_infer_env::global_bare_nearest_ancestor_candidate(
                            referencing_module.clone(),
                            candidates.clone(),
                        )
                        .and_then(|c| {
                            if pullable(&c.binding) {
                                Some(c.module_path.clone())
                            } else {
                                None
                            }
                        }),
                        "ambiguous",
                    ),
                },
                None => (
                    if in_call_position {
                        v1_rt::map_get(&census.services, name.clone())
                            .map(|entry| entry.module_path.clone())
                    } else {
                        None
                    },
                    "absent",
                ),
            }
        };
        // WHICH ARM ANSWERED is a fact the caller needs and this match used to destroy
        // one line after computing it: `Some(m) => Some(m)` collapsed a scoped-census hit
        // and a whole-pool fallback hit into one `Option<String>`, so a name that the
        // file's own tree could NOT resolve — and that only the pool answered — was
        // indistinguishable from one resolved in scope. The two have different meanings:
        // the second is the closure depending on ambient pool membership rather than on
        // anything the file's tree provides, and it is exactly the state a zero-import
        // corpus can sit in while looking green.
        //
        // Carrying the provenance costs nothing (the arms already know it) and makes the
        // existing `GUNBC_BARE_PULL_TRACE` line answer "how was this resolved", not only
        // "what did it resolve to".
        let (target_module, resolution_arm, census_state) = match resolve_in(&census) {
            (Some(m), state) => (Some(m), "scoped", state),
            (None, _) => {
                let (m, state) = resolve_in(&pool_bare_census(index)?);
                (m, "pool-fallback", state)
            }
        };
        let Some(module_path) = target_module else {
            continue;
        };
        let Some(dep) = index.source_files.get(&module_path) else {
            return Err(format!(
                "bare_reference_closure: census resolved '{name}' in '{file_rel}' to \
                 module '{module_path}', but that module has no source file in the pool \
                 (fail-closed)"
            ));
        };
        let name_is_test_row = dep.content.lines().any(|l| {
            let t = l.trim_start();
            ["test fn ", "test data "].iter().any(|prefix| {
                t.strip_prefix(prefix).is_some_and(|rest| {
                    rest.strip_prefix(name.as_str()).is_some_and(|after| {
                        after
                            .chars()
                            .next()
                            .is_none_or(|c| !c.is_alphanumeric() && c != '_')
                    })
                })
            })
        });
        if name_is_test_row {
            continue;
        }
        let dep_rel = workspace_relative_repo_path(&dep.path);
        if std::env::var("GUNBC_BARE_PULL_TRACE").is_ok() {
            eprintln!(
                "[bare-pull] {} -> '{}' -> {} ({}) [{} {}]",
                file_rel, name, module_path, dep_rel, resolution_arm, census_state
            );
        }
        if !index.module_graph_facts.declares_repo_path(&dep_rel) {
            return Err(format!(
                "bare_reference_closure: referenced module '{module_path}' at \
                 '{dep_rel}' has no provenance in the module-graph facts pool \
                 (fail-closed)"
            ));
        }
        for path in import_closure_live_paths_with_facts(&dep_rel, &index.module_graph_facts) {
            let rel = workspace_relative_repo_path(&path);
            if pulled_set.insert(rel.clone()) {
                pulled.push(rel);
            }
        }
    }
    // `pool_bare_census` is the loop's cross-tree fallback and forces the same shared
    // parse. In practice the census above has already forced it, so this delta is
    // normally zero — but "normally" is an ordering accident and the row must not
    // depend on one.
    let resolve_loop_pool = resolve_stage_slot_snapshot()
        .pool_parse
        .saturating_sub(resolve_loop_pool_before);
    resolve_stage_slot_add(|st| {
        st.edge_index_bare_resolve_loop += resolve_loop_started
            .elapsed()
            .as_nanos()
            .saturating_sub(resolve_loop_pool);
    });
    Ok(pulled)
}

fn reference_pull_paths_for_source(
    sf: &Rc<v1_compiler_compile::SourceFile>,
    index: &ModuleSourceIndex,
    facts: &ModuleGraphFactsLive,
) -> Result<Vec<String>, String> {
    let mut pulled: Vec<String> = Vec::new();
    let mut pulled_set: HashSet<String> = HashSet::new();
    for module_path in referenced_module_paths_in_text(&sf.content, index) {
        let Some(dep) = index.get(&module_path) else {
            continue;
        };
        let dep_rel = workspace_relative_repo_path(&dep.path);
        if !facts.declares_repo_path(&dep_rel) {
            return Err(format!(
                "reference_closure: referenced module '{module_path}' at '{dep_rel}' \
                 has no provenance in the module-graph facts pool (fail-closed)"
            ));
        }
        let expand_started = std::time::Instant::now();
        let expanded = import_closure_live_paths_with_facts(&dep_rel, facts);
        resolve_stage_slot_add(|st| {
            st.edge_index_closure_expand += expand_started.elapsed().as_nanos();
            st.edge_index_closure_expand_calls += 1;
        });
        for path in expanded {
            let rel = workspace_relative_repo_path(&path);
            if pulled_set.insert(rel.clone()) {
                pulled.push(rel);
            }
        }
    }
    Ok(pulled)
}

fn build_both_closure_edge_index(
    index: &MultiEntryIndex,
) -> Result<Rc<BothClosureEdgeIndex>, String> {
    let mut bare_out: HashMap<String, Vec<String>> = HashMap::new();
    let mut ref_out: HashMap<String, Vec<String>> = HashMap::new();
    let mut bare_scan_eligible: HashSet<String> = HashSet::new();
    resolve_stage_slot_add(|st| {
        st.edge_index_builds += 1;
        st.edge_index_source_files += index.source_files.len() as u128;
    });
    for sf in index.source_files.values() {
        let file_rel = workspace_relative_repo_path(&sf.path);
        let ref_started = std::time::Instant::now();
        let ref_paths =
            reference_pull_paths_for_source(sf, &index.source_files, &index.module_graph_facts)?;
        resolve_stage_slot_add(|st| st.edge_index_ref_half += ref_started.elapsed().as_nanos());
        ref_out.insert(file_rel.clone(), ref_paths);
        if source_declares_import_lines(&sf.content) {
            continue;
        }
        bare_scan_eligible.insert(file_rel.clone());
        let (bare_paths, bare_nanos) =
            nanos_net_of_pool_parse(|| bare_reference_pull_paths_for_source(sf, index));
        let bare_paths = bare_paths?;
        resolve_stage_slot_add(|st| {
            st.edge_index_bare_half += bare_nanos;
            st.edge_index_bare_eligible += 1;
        });
        bare_out.insert(file_rel, bare_paths);
    }
    let publish_started = std::time::Instant::now();
    let built = Rc::new(BothClosureEdgeIndex {
        bare_out,
        ref_out,
        bare_scan_eligible,
    });
    resolve_stage_slot_add(|st| st.edge_index_publish += publish_started.elapsed().as_nanos());
    Ok(built)
}

fn both_closure_edge_index(index: &MultiEntryIndex) -> Result<Rc<BothClosureEdgeIndex>, String> {
    if let Some(hit) = index.both_closure_edges.borrow().as_ref() {
        return Ok(hit.clone());
    }
    let built = build_both_closure_edge_index(index)?;
    *index.both_closure_edges.borrow_mut() = Some(built.clone());
    Ok(built)
}

/// ONE observation of ONE shared preparation build — the unit whose cost is being
/// attributed. Reported per phase, never prorated across the claims that consume the
/// artifact: a per-row fraction would change whenever the roster changes, making a
/// row's admissibility depend on how many unrelated consumers happen to be enrolled.
/// TRIGGERED_BY IS NOT OWNED_BY. Mirrors `v2.workflow.required_floor` `SharedBuildProvenance`.
///
/// A `bool` was the wrong carrier and this replaces it: "already warm" records that SOMEONE ELSE
/// went first while discarding WHO, which is the one fact an attribution model exists to keep.
/// `BuiltByPreparation` is the intended state — trigger and owner coincide, which is what the warm
/// buys. `AlreadyWarmOnEntry` names the site that got there first, as PROVENANCE and never as an
/// assignment of cost: a run reporting it is reporting a defect in ordering.
pub enum SharedBuildProvenance {
    BuiltByPreparation,
    AlreadyWarmOnEntry { triggered_by: &'static str },
}

impl SharedBuildProvenance {
    /// The report form. Structural rather than prose: a reader (and a grep) sees which arm, and
    /// the `AlreadyWarmOnEntry` arm cannot be printed without naming its trigger.
    pub fn render(&self) -> String {
        match self {
            SharedBuildProvenance::BuiltByPreparation => "built-by-preparation".to_string(),
            SharedBuildProvenance::AlreadyWarmOnEntry { triggered_by } => {
                format!("already-warm-on-entry triggered_by={triggered_by}")
            }
        }
    }
}

pub struct SharedBuildObservation {
    pub cpu_ms: u64,
    pub wall_ms: u64,
    pub rss_growth_bytes: u64,
    pub source_files: usize,
    pub bare_eligible: usize,
    pub provenance: SharedBuildProvenance,
}

/// Build the bare-reference edge index (and, through it, the per-root tree bare census)
/// for `index` NOW, so that the one-time cost is paid by the caller that prepares the
/// subject rather than by whichever claim happens to reach it first.
///
/// WHY THIS EXISTS, and why it is the third warm in this file rather than an optimization:
/// `both_closure_edge_index` is memoized per `MultiEntryIndex` and `tree_bare_census_for_root`
/// per (index, root), so the work is already done exactly once per process — the trace
/// (`GUNBC_EDGE_INDEX_CENSUS_TRACE=1`) reports two misses on two roots against ONE index
/// address, with `edge_index_construction { builds: 1 }`. Memoization is therefore correct
/// and complete, and the defect is not duplication: it is ATTRIBUTION. The first claim to
/// resolve an entry paid the whole ~28s build inside its own per-claim timer and was
/// refused against a 5000ms per-claim safety limit that answers a different question, while
/// its sibling — reaching the identical computation milliseconds later — ran free.
/// Quarantining the payer only hands the bill to the next claim in evaluation order; the
/// module-path-index and shared-index warms directly above are the same repair, and the
/// three modules quarantined down that chain are the receipt for why relocation is not one.
///
/// This does NOT make the build cheaper and does not claim to. It moves the charge to the
/// unit that incurs it, where it is bounded by its own limits (`FloorPreparationRefused`)
/// instead of by a per-claim ceiling that was never about shared setup.
/// MEASURE ANY SHARED PREPARATION BUILD THE SAME WAY, so a phase declared protected by
/// `v2.workflow.required_floor` `FloorPreparationPhase` is protected by execution and not by the
/// type merely listing it (review 55338, and the finding was correct: the model named three phases
/// while exactly one was measured and adjudicated — two modeled safety walls were informational).
///
/// The closure runs between the same clock and RSS reads the edge-index warm uses, so all three
/// phases produce one comparable observation and go through one refusal.
fn observe_shared_build<T>(
    already_built: bool,
    triggered_by: &'static str,
    build: impl FnOnce() -> T,
) -> (T, SharedBuildObservation) {
    let provenance = if already_built {
        SharedBuildProvenance::AlreadyWarmOnEntry { triggered_by }
    } else {
        SharedBuildProvenance::BuiltByPreparation
    };
    let rss_before = current_rss_bytes().unwrap_or(0);
    let cpu_before = v1_interpreter::thread_cpu_nanos();
    let wall_before = std::time::Instant::now();
    let out = build();
    let wall_ms = wall_before.elapsed().as_millis() as u64;
    let cpu_ms =
        ((v1_interpreter::thread_cpu_nanos().saturating_sub(cpu_before)) / 1_000_000) as u64;
    let rss_growth_bytes = current_rss_bytes()
        .unwrap_or(rss_before)
        .saturating_sub(rss_before);
    (
        out,
        SharedBuildObservation {
            cpu_ms,
            wall_ms,
            rss_growth_bytes,
            source_files: 0,
            bare_eligible: 0,
            provenance,
        },
    )
}

pub fn warm_bare_reference_edge_index(
    index: &MultiEntryIndex,
) -> Result<SharedBuildObservation, String> {
    // NAMED, not a bool. If the index is already built when preparation reaches it, some EARLIER
    // site triggered it — an ordering defect this line must locate rather than merely note. The
    // trigger is not identified per call site here (the memo records no author), so the arm names
    // the boundary that is knowable: something ahead of preparation. That is honestly weaker than a
    // call-site name and is why the string is a fixed label rather than a fabricated attribution.
    let provenance = if index.both_closure_edges.borrow().is_some() {
        SharedBuildProvenance::AlreadyWarmOnEntry {
            triggered_by: "a-site-ahead-of-floor-preparation",
        }
    } else {
        SharedBuildProvenance::BuiltByPreparation
    };
    let rss_before = current_rss_bytes().unwrap_or(0);
    let cpu_before = v1_interpreter::thread_cpu_nanos();
    let wall_before = std::time::Instant::now();
    let edges = both_closure_edge_index(index)?;
    let wall_ms = wall_before.elapsed().as_millis() as u64;
    let cpu_ms =
        ((v1_interpreter::thread_cpu_nanos().saturating_sub(cpu_before)) / 1_000_000) as u64;
    let rss_growth_bytes = current_rss_bytes()
        .unwrap_or(rss_before)
        .saturating_sub(rss_before);
    Ok(SharedBuildObservation {
        cpu_ms,
        wall_ms,
        rss_growth_bytes,
        source_files: index.source_files.len(),
        bare_eligible: edges.bare_scan_eligible.len(),
        provenance,
    })
}

/// Extend the closure with the modules the tree census resolves each source's
/// BARE references to (namespace Rule-1 direction: deps derived from names, not
/// import statements — the import-stripped corpus has no import edges to follow,
/// which surfaced as `no such function` at witness runtime: typecheck resolved a
/// name through the census while the interpreter never loaded its body). A bare
/// name resolves exactly as the typecheck lookup will: census-unique → that
/// module; ambiguous → the nearest-ancestor candidate from the referencing
/// module's containment position; still ambiguous → load nothing (the typecheck
/// refusal stays the loud authority, the loader never guesses a side).
fn extend_with_bare_reference_closure(
    sources: Vec<Rc<v1_compiler_compile::SourceFile>>,
    index: &MultiEntryIndex,
) -> Result<Vec<Rc<v1_compiler_compile::SourceFile>>, String> {
    // Sub-attribution inside the bare-reference closure (entry-graph-union slice 1). The
    // fixpoint measured ~100% of `load`; these three rows say WHICH of its parts, which is
    // what decides whether the fix is a memo, an incremental closure, or a union graph.
    let (edges, edge_nanos) = nanos_net_of_pool_parse(|| both_closure_edge_index(index));
    let edges = edges?;
    resolve_stage_slot_add(|s| s.load_bare_edge_index += edge_nanos);
    let lookup_started = std::time::Instant::now();
    let lookup = path_to_source_lookup(&index.source_files);
    resolve_stage_slot_add(|s| {
        s.load_bare_path_lookup += lookup_started.elapsed().as_nanos();
        s.load_bare_path_lookup_calls += 1;
    });
    let walk_started = std::time::Instant::now();
    let out = extend_sources_via_edge_map(
        sources,
        &edges.bare_out,
        Some(&edges.bare_scan_eligible),
        &lookup,
    );
    resolve_stage_slot_add(|s| s.load_bare_edge_walk += walk_started.elapsed().as_nanos());
    out
}

/// The full name-derived closure for one entry: import edges + dotted-reference
/// modules + BARE-reference modules (via the tree census), iterated to a joint
/// fixpoint — a bare-pulled module can carry new dotted references and vice
/// versa. This is the loader the witness paths use; the raw-pair
/// `load_sources_for_entry_with_index` stays the dotted-only base for callers
/// without a pool index.
/// The ONE closure-extension authority: run the bare/service-name and the
/// module-path reference closures to a joint fixpoint (each newly-pulled module
/// can carry either edge kind). Both source loaders — the per-entry witness
/// loader and the affected-set compile-clean gate loader — call this, so the
/// single-authority claim in `extend_with_reference_closure`'s doc-comment is
/// true by construction rather than by two functions happening to hold identical
/// loop bodies (the §2 duplicate that dissolving the §3 fork would otherwise
/// have left behind).
fn extend_sources_to_both_closure_fixpoint(
    mut sources: Vec<Rc<v1_compiler_compile::SourceFile>>,
    mei: &MultiEntryIndex,
) -> Result<Vec<Rc<v1_compiler_compile::SourceFile>>, String> {
    loop {
        let before = sources.len();
        // Sub-attribution of `load` (entry-graph-union slice 1). This fixpoint is the
        // "#6848 once-per-entry bare-reference fixpoint" DESIGN's floor-memoization thread
        // names as the residual; the rows below are what let that claim be priced instead
        // of asserted.
        let bare_started = std::time::Instant::now();
        sources = extend_with_bare_reference_closure(sources, mei)?;
        resolve_stage_slot_add(|s| {
            s.load_bare_reference_closure += bare_started.elapsed().as_nanos()
        });
        let pool_started = std::time::Instant::now();
        sources = extend_with_reference_closure_for_pool(sources, mei)?;
        resolve_stage_slot_add(|s| {
            s.load_pool_reference_closure += pool_started.elapsed().as_nanos();
            s.load_fixpoint_rounds += 1;
        });
        sources.sort_by(|a, b| a.path.cmp(&b.path));
        sources.dedup_by(|a, b| a.path == b.path);
        if sources.len() == before {
            break;
        }
    }
    Ok(sources)
}

fn load_sources_for_entry_with_pool(
    index: &MultiEntryIndex,
    entry_path: &str,
) -> Result<Vec<Rc<v1_compiler_compile::SourceFile>>, String> {
    let cache_key = workspace_relative_entry_path(entry_path);
    if let Some(cached) = index.entry_closure_sources.borrow().get(&cache_key) {
        return Ok(cached.clone());
    }
    let sources = load_sources_for_entry_with_index(
        &index.source_files,
        &index.module_graph_facts,
        entry_path,
    )?;
    let sources = extend_sources_to_both_closure_fixpoint(sources, index)?;
    index
        .entry_closure_sources
        .borrow_mut()
        .insert(cache_key, sources.clone());
    Ok(sources)
}

fn load_sources_for_entry_with_index(
    index: &ModuleSourceIndex,
    facts: &ModuleGraphFactsLive,
    entry_path: &str,
) -> Result<Vec<Rc<v1_compiler_compile::SourceFile>>, String> {
    let entry_source = entry_source_from_index_or_disk(index, entry_path)?;
    let rel_path = entry_source.path.clone();

    let import_closure_started = std::time::Instant::now();
    let sources = resolve_transitively(vec![entry_source.clone()], index, facts)?;
    resolve_stage_slot_add(|s| {
        s.load_import_closure += import_closure_started.elapsed().as_nanos()
    });
    let mut sources = sources;
    if !sources
        .iter()
        .any(|s| s.path == rel_path || same_canonical_file(&s.path, &rel_path))
    {
        sources.push(entry_source);
    }
    let mut sources = extend_with_reference_closure(sources, index, facts)?;
    sources.sort_by(|a, b| a.path.cmp(&b.path));
    sources.dedup_by(|a, b| a.path == b.path);
    Ok(sources)
}

fn same_canonical_file(a: &str, b: &str) -> bool {
    // A relative path here is WORKSPACE-relative (the module index stores paths
    // stripped of the workspace prefix by `build_module_path_index`); an entry
    // argument is typically already absolute. Resolve a relative path against
    // `workspace_root()` — its real base — NOT the process CWD: `cargo`/`nextest`
    // run test binaries with CWD = the crate dir, so canonicalizing a
    // workspace-relative path against CWD fails, the dedup silently misses, and the
    // absolutely-spelled entry is minted as a SECOND declaring file for one module
    // (the `duplicate module declaration` + self-circular collision on a temp-dir-
    // under-target fixture; blackout-masked from CI's nextest gate). Fall back to a
    // CWD-relative canonicalize so a genuinely CWD-relative spelling still matches.
    let canon = |p: &str| -> Option<std::path::PathBuf> {
        let path = Path::new(p);
        if path.is_absolute() {
            return std::fs::canonicalize(path).ok();
        }
        std::fs::canonicalize(workspace_root().join(path))
            .or_else(|_| std::fs::canonicalize(path))
            .ok()
    };
    match (canon(a), canon(b)) {
        (Some(ca), Some(cb)) => ca == cb,
        _ => false,
    }
}

fn entry_source_from_index_or_disk(
    index: &ModuleSourceIndex,
    entry_path: &str,
) -> Result<Rc<v1_compiler_compile::SourceFile>, String> {
    let path = std::path::Path::new(entry_path);
    if !path.is_file() {
        return Err(format!(
            "entry file does not exist or is not a file: {}",
            entry_path
        ));
    }
    let content = std::fs::read_to_string(path)
        .map_err(|e| format!("failed to read entry {:?}: {}", path, e))?;
    let rel_path = path.to_string_lossy().to_string();
    if let Some(mod_path) = extract_module_path(&content) {
        if let Some(cached) = index.get(&mod_path) {
            // Identity is the FILE, not the spelling: a relative entry against an
            // absolutely-rooted index (or vice versa) must unify with the indexed
            // source, not mint a second declaring file — that false fork trips the
            // module-identity collision wall as "duplicate module declaration"
            // (red on main since the S1 shared index; blackout-masked). Genuine
            // two-file duplicates still collide: different canonical paths.
            if cached.path == rel_path || same_canonical_file(&cached.path, &rel_path) {
                return Ok(cached.clone());
            }
        }
    }
    Ok(Rc::new(v1_compiler_compile::SourceFile {
        path: rel_path,
        content,
    }))
}

/// Which budget a `ClaimOutcome::BudgetInterrupted` / `CompletedOverBudget` row blew. The two are measured on different
/// clocks and are not interchangeable: `Cpu` is thread CPU time (the stride-poll
/// metric, so a witness slowed by cold I/O or governor time-slicing is not
/// misclassified), `Wall` is whole-receipt wall time (emit + cargo subprocess I/O
/// counts). Collapsing them would conflate two states with different remedies.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BudgetKind {
    Cpu,
    Wall,
}

/// WHETHER THE NUMBER IS A MEASUREMENT OR A LOWER BOUND — the axis `BudgetKind` does not carry.
///
/// `BudgetKind` says which clock was consulted. It does not say whether the witness FINISHED,
/// and those are different facts with different arithmetic:
///
/// - `Interrupted` — an armed deadline fired and the witness was aborted. `elapsed_ms` is
///   right-censored: the true cost is at least that and is otherwise unknown. A row that would
///   have taken two seconds and one that would have taken forty report the same number, because
///   the number is the ceiling plus poll granularity rather than a property of the row.
/// - `CompletedOverBudget` — the witness ran to completion and passed, and the completion-side
///   backstop then reclassified it. `elapsed_ms` is exact.
///
/// Keeping the two apart is what makes a cost distribution computable at all: a spread taken
/// across a censoring boundary is an artifact of where the ceiling sits, not a fact about the
/// witnesses. It is also the condition named in `claim_executor.rs`'s cost-basis seeding guard,
/// which refuses to seed a basis from a deadline-killed row "until ClaimOutcome can
/// distinguish killed from completed".
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BudgetCompletion {
    Interrupted,
    CompletedOverBudget,
}

// WHY THIS IS NO LONGER A FIELD ON ONE ARM — the trade, re-decided on evidence rather than on
// the earlier argument's outcome.
//
// The discriminator used to sit INSIDE a single `ClaimOutcome::TimedOut`, and that is exactly
// what made the erasure writable: a `TimedOut { .. }` wildcard absorbs it. The prior note kept
// it there and declared the hazard "paid for by review", with a falsifiable next-rung trigger:
// THE NEXT CONSUMING SITE ADDED THAT DROPS THE AXIS. The trigger fired, and by more than one
// site — five live projections were found dropping it, four in this seed and one in the `.dag`
// AUTHORITY (`v2.workflow.floor_terminal_ledger` `claim_disposition`, wildcarding
// `ClaimSafetyOutcome` and answering `BudgetRefusedBeforeVerdict`). THE MODEL HAD THE
// DISTINCTION; EVERY PROJECTION OVER IT DROPPED IT. That is one habit of projecting a modelled
// axis away, not five copies of one slip, and review is demonstrably not the mechanism that
// stops it — the four seed sites were authored by the person who wrote the converters, on the
// day he was most primed to look for them, one of them a fabricated receipt protected by its
// own justifying comment.
//
// THE PRIOR DECISION IS NOT OVERRULED, because it was about a different axis. It argued against
// splitting on RAISE MECHANISM — in-eval poll versus completion-side backstop — which no
// consumer should act on, and unifying that is what closed an earlier absorption. The split
// here is on PASSED-VERSUS-INTERRUPTED, which that same note calls a real distinction because
// IT DETERMINES THE REMEDY: an interrupted row produced no verdict and its elapsed figure is a
// LOWER BOUND; a completed one passed, was reclassified on cost, and its figure is EXACT.
// Rendering one as the other is what produced a ledger describing a single row three
// inconsistent ways (`BUDGET-REFUSED`, `outcome=timed_out`, and "cost exactly 57193ms").
//
// The field names carry the reading, so the bound cannot be spelled as a cost: the interrupted
// arm has `elapsed_at_least_ms`, the completed arm `elapsed_ms`.
//
// `BudgetCompletion` IS DELIBERATELY NOT DELETED. It is the axis as data, and it is consumed
// where a value has to travel — `BudgetRefusal`, the wire verdict's `completion`, and the
// `budget_event` projection below. Deleting it here would force a second spelling of the same
// two states beside it; a dissolution that spawns a duplicate has dissolved nothing (§2/§3).
// What the split removes is the WRITABLE ERASURE, not the type.

/// Both budget arms projected into one value, for a consumer that legitimately treats them
/// alike and still has to render or transport the axis.
///
/// This is a PROJECTION, not a way back to the old shape: obtaining it is an explicit call, and
/// the two arms remain separate cases in every `match` over `ClaimOutcome`, so a labelling
/// consumer still cannot give one name to both by writing a wildcard.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BudgetEvent {
    pub elapsed_ms: u64,
    pub budget_ms: u64,
    pub kind: BudgetKind,
    pub completion: BudgetCompletion,
}

impl BudgetCompletion {
    /// How the elapsed number may be READ. Rendered beside every budget figure so a reader
    /// never has to know which mechanism produced it.
    pub fn elapsed_reading(self) -> &'static str {
        match self {
            BudgetCompletion::Interrupted => "at least",
            BudgetCompletion::CompletedOverBudget => "exactly",
        }
    }
}

impl ClaimOutcome {
    /// The budget arms projected; `None` for every other outcome.
    pub fn budget_event(&self) -> Option<BudgetEvent> {
        match self {
            ClaimOutcome::BudgetInterrupted {
                elapsed_at_least_ms,
                budget_ms,
                kind,
            } => Some(BudgetEvent {
                elapsed_ms: *elapsed_at_least_ms,
                budget_ms: *budget_ms,
                kind: *kind,
                completion: BudgetCompletion::Interrupted,
            }),
            ClaimOutcome::CompletedOverBudget {
                elapsed_ms,
                budget_ms,
                kind,
            } => Some(BudgetEvent {
                elapsed_ms: *elapsed_ms,
                budget_ms: *budget_ms,
                kind: *kind,
                completion: BudgetCompletion::CompletedOverBudget,
            }),
            _ => None,
        }
    }

    /// The budget arm for a given `completion`, so a producer holding the axis as data does not
    /// have to re-derive which variant carries it.
    pub fn budget_outcome(
        elapsed_ms: u64,
        budget_ms: u64,
        kind: BudgetKind,
        completion: BudgetCompletion,
    ) -> ClaimOutcome {
        match completion {
            BudgetCompletion::Interrupted => ClaimOutcome::BudgetInterrupted {
                elapsed_at_least_ms: elapsed_ms,
                budget_ms,
                kind,
            },
            BudgetCompletion::CompletedOverBudget => ClaimOutcome::CompletedOverBudget {
                elapsed_ms,
                budget_ms,
                kind,
            },
        }
    }
}

impl BudgetKind {
    pub fn label(self) -> &'static str {
        match self {
            BudgetKind::Cpu => "cpu",
            BudgetKind::Wall => "wall",
        }
    }
}

/// Mirror of `gunbc.observation_ci_render CiWitnessRuntimeCause`. One arm per
/// `v1_interpreter::InterpError` variant that can reach the witness boundary's untyped arm, and
/// no vocabulary of its own (DESIGN §3): the cause already exists upstream, this is it surviving
/// the seam.
///
/// FIVE `InterpError` VARIANTS ARE DELIBERATELY ABSENT. `HostToolUnresolved`,
/// `HermeticHostEffectRefused`, `EvalBudgetExceeded`, `WitnessWallBudgetExceeded` and the
/// pre-mapped `EvaluationBudgetExceeded` each have their OWN `ClaimOutcome` arm and are consumed
/// by earlier arms of the match in `run_claim`, so they cannot reach this classifier. They are
/// not silently folded into a neighbour: all five map to `MappedOutcomeEscaped`, a typed,
/// countable diagnostic meaning the mapper let one through. One arm rather than five because all
/// five share ONE remedy — repair the mapper — and the descend-or-collapse rule turns on shared
/// remedy, not on arm count.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum WitnessRuntimeCause {
    NoSuchFunction,
    NoSuchVariable,
    NoSuchField,
    TypeError,
    CrossRepresentationEquality,
    StringRealizationStraddle,
    PoolRootContributesNothing,
    PatternMatchFailure,
    DivisionByZero,
    IntegerOverflow,
    Unimplemented,
    EarlyReturn,
    AuthDeclaredButUnwired,
    ServiceConfigUnresolved,
    ServiceConfigMissing,
    ArgvExceedsHostArgMax,
    HostToolRelativePathAmbiguous,
    ShellOutputLimitExceeded,
    CallContractMismatch,
    /// An `InterpError` with its own `ClaimOutcome` arm reached the untyped classifier anyway.
    /// Loud rather than absorbed: this is a defect in the mapping above, and a run that produces
    /// it should say so on the row rather than presenting the throw as an ordinary one.
    MappedOutcomeEscaped,
}

impl WitnessRuntimeCause {
    /// Mirror of `ci_witness_runtime_cause_token`. Stable kebab tokens — the grep key a reader
    /// uses to pair an identity with its cause.
    pub fn token(self) -> &'static str {
        match self {
            WitnessRuntimeCause::NoSuchFunction => "no-such-function",
            WitnessRuntimeCause::NoSuchVariable => "no-such-variable",
            WitnessRuntimeCause::NoSuchField => "no-such-field",
            WitnessRuntimeCause::TypeError => "type-error",
            WitnessRuntimeCause::CrossRepresentationEquality => "cross-representation-equality",
            WitnessRuntimeCause::StringRealizationStraddle => "string-realization-straddle",
            WitnessRuntimeCause::PoolRootContributesNothing => "pool-root-contributes-nothing",
            WitnessRuntimeCause::PatternMatchFailure => "pattern-match-failure",
            WitnessRuntimeCause::DivisionByZero => "division-by-zero",
            WitnessRuntimeCause::IntegerOverflow => "integer-overflow",
            WitnessRuntimeCause::Unimplemented => "unimplemented",
            WitnessRuntimeCause::EarlyReturn => "early-return",
            WitnessRuntimeCause::AuthDeclaredButUnwired => "auth-declared-but-unwired",
            WitnessRuntimeCause::ServiceConfigUnresolved => "service-config-unresolved",
            WitnessRuntimeCause::ServiceConfigMissing => "service-config-missing",
            WitnessRuntimeCause::ArgvExceedsHostArgMax => "argv-exceeds-host-arg-max",
            WitnessRuntimeCause::HostToolRelativePathAmbiguous => {
                "host-tool-relative-path-ambiguous"
            }
            WitnessRuntimeCause::ShellOutputLimitExceeded => "shell-output-limit-exceeded",
            WitnessRuntimeCause::CallContractMismatch => "call-contract-mismatch",
            WitnessRuntimeCause::MappedOutcomeEscaped => "mapped-outcome-escaped",
        }
    }

    /// TOTAL over `InterpError`. Totality is the point rather than a formality: a new interpreter
    /// error variant must fail to compile HERE, where someone decides what its cause token is,
    /// rather than inheriting a neighbour's or falling into a wildcard.
    pub fn of_interp_error(err: &v1_interpreter::InterpError) -> Self {
        use v1_interpreter::InterpError as E;
        match err {
            E::NoSuchFunction { .. } => WitnessRuntimeCause::NoSuchFunction,
            E::NoSuchVariable { .. } => WitnessRuntimeCause::NoSuchVariable,
            E::NoSuchField { .. } => WitnessRuntimeCause::NoSuchField,
            E::TypeError { .. } => WitnessRuntimeCause::TypeError,
            E::CrossRepresentationEquality { .. } => {
                WitnessRuntimeCause::CrossRepresentationEquality
            }
            E::StringRealizationStraddle { .. } => WitnessRuntimeCause::StringRealizationStraddle,
            E::PoolRootContributesNothing { .. } => WitnessRuntimeCause::PoolRootContributesNothing,
            E::PatternMatchFailure { .. } => WitnessRuntimeCause::PatternMatchFailure,
            E::DivisionByZero => WitnessRuntimeCause::DivisionByZero,
            E::IntegerOverflow { .. } => WitnessRuntimeCause::IntegerOverflow,
            E::Unimplemented { .. } => WitnessRuntimeCause::Unimplemented,
            E::EarlyReturn { .. } => WitnessRuntimeCause::EarlyReturn,
            E::AuthDeclaredButUnwired { .. } => WitnessRuntimeCause::AuthDeclaredButUnwired,
            E::ServiceConfigUnresolved { .. } => WitnessRuntimeCause::ServiceConfigUnresolved,
            E::ServiceConfigMissing { .. } => WitnessRuntimeCause::ServiceConfigMissing,
            E::ArgvExceedsHostArgMax { .. } => WitnessRuntimeCause::ArgvExceedsHostArgMax,
            E::HostToolRelativePathAmbiguous { .. } => {
                WitnessRuntimeCause::HostToolRelativePathAmbiguous
            }
            E::ShellOutputLimitExceeded { .. } => WitnessRuntimeCause::ShellOutputLimitExceeded,
            E::CallContractMismatch { .. } => WitnessRuntimeCause::CallContractMismatch,
            // The five that should never arrive. See the type comment.
            E::HostToolUnresolved { .. }
            | E::HermeticHostEffectRefused { .. }
            | E::EvalBudgetExceeded { .. }
            | E::WitnessWallBudgetExceeded { .. }
            | E::EvaluationBudgetExceeded { .. } => WitnessRuntimeCause::MappedOutcomeEscaped,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ClaimOutcome {
    Pass,
    Fail,
    NotBool {
        got: String,
    },
    /// A THROW, WITH THE REASON IT THREW KEPT AS A TYPE.
    ///
    /// `message` used to be the whole content of this arm, built by `format!("{other}")` over
    /// `v1_interpreter::InterpError` — which is ALREADY a closed 24-arm coproduct. So the cause
    /// was known at this seam, destroyed here, and then guessed back downstream by slicing the
    /// first twelve whitespace-separated words off the prose (`known_red_runtime_error_causes`).
    /// That key embeds the missing NAME, so `no declaration named X` and `no declaration named Y`
    /// counted as two causes: on main `f9963a762` the floor reported **65 distinct signatures**
    /// across 142 identities for a population with about four actual causes. The number was an
    /// artifact of the key, and it said "many roots" where the truth is "one root, many names".
    ///
    /// This is the same repair `TimedOut` and `HostToolUnresolved` above already received, for
    /// the same stated reason, and the third instance is the argument for doing it by type
    /// rather than case by case.
    ///
    /// `message` SURVIVES beside the cause and is not redundant with it: the cause says WHICH
    /// class, the message says which name, which type, which arity. Two facts, two fields — the
    /// defect was never that prose existed, it was that prose was the only representation.
    RuntimeError {
        cause: WitnessRuntimeCause,
        message: String,
    },
    /// A budget refusal, with the pair that explains it kept as data.
    ///
    /// This used to be a `RuntimeError` holding `format!("{}", InterpError::…)`. That
    /// flattened the typed `{elapsed_ms, budget_ms}` at the seam, and the floor then
    /// recovered the classification by substring-matching the very prose it had just
    /// produced (`falsifier_failure_mode`'s `.contains("eval budget exceeded")`). One
    /// fact in two representations, the second guessed back from the first — and the
    /// classifier's fallback arm is `WitnessRed`, so rewording the message silently
    /// reclassified a budget refusal as a witness failure. Keeping the pair typed lets
    /// the mode be read off the value, and lets the receipt project a real
    /// `std.observation` `TimedOut { budget, elapsed }` instead of an opaque string.
    /// THE CLAIM WAS CUT OFF AT ITS BUDGET. It produced no verdict, and
    /// `elapsed_at_least_ms` is a LOWER BOUND on its cost, never the cost.
    BudgetInterrupted {
        elapsed_at_least_ms: u64,
        budget_ms: u64,
        kind: BudgetKind,
    },
    /// THE CLAIM REACHED ITS VERDICT and was then reclassified for exceeding its budget.
    /// `elapsed_ms` is an exact measurement, and the remedy is cost, not interruption.
    CompletedOverBudget {
        elapsed_ms: u64,
        budget_ms: u64,
        kind: BudgetKind,
    },
    /// A host-tool program could not be resolved to an existing executable path.
    /// Typed at the witness boundary so downstream classifiers do not substring-match
    /// `Display` prose from `InterpError::HostToolUnresolved`.
    HostToolUnresolved {
        name: String,
        probed: Vec<String>,
    },
    /// THE ROUTE HAD NO ARM. The claim reached a host effect that its EXECUTION ROUTE cannot
    /// realize, so it never reached its subject and produced no verdict.
    ///
    /// Typed here for exactly the reason `TimedOut` is (see its comment above): the same event
    /// used to arrive as `RuntimeError` carrying `InterpError`'s prose, so any consumer
    /// partitioning on the outcome saw a missing route as an ordinary failure on the subject.
    /// Those are different facts with different remedies — a failure says the witness is wrong,
    /// a route gap says the witness was never given a way to run — and the required floor's
    /// answer to the ambiguity was to decline the whole live-tree population rather than
    /// execute it.
    HostEffectRefused {
        operation: String,
        ground: v1_interpreter::HermeticEffectGround,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FloorRouteGapExpectedGround {
    UnpublishedMockCase,
    NoMockResponse,
    FilesystemRemoval,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct FloorRouteGapExpectation {
    operation: String,
    ground: FloorRouteGapExpectedGround,
}

fn floor_route_gap_expectation_mismatch(
    expectation: Option<&FloorRouteGapExpectation>,
    operation: &str,
    ground: &v1_interpreter::HermeticEffectGround,
) -> Option<String> {
    let expectation = expectation?;
    let observed_ground = match ground {
        v1_interpreter::HermeticEffectGround::UnpublishedMockCase { .. } => {
            FloorRouteGapExpectedGround::UnpublishedMockCase
        }
        v1_interpreter::HermeticEffectGround::NoMockResponse => {
            FloorRouteGapExpectedGround::NoMockResponse
        }
        v1_interpreter::HermeticEffectGround::FilesystemRemoval => {
            FloorRouteGapExpectedGround::FilesystemRemoval
        }
    };
    if expectation.operation == operation && expectation.ground == observed_ground {
        None
    } else {
        Some(format!(
            "typed route-gap enrollment expected operation={} ground={:?}, observed operation={} ground={:?}",
            expectation.operation, expectation.ground, operation, observed_ground
        ))
    }
}

/// Which clock a completed claim's cost is judged on. Operator ruling 2026-08-19 (BUDGET
/// POLICY CUT): chosen by the witness's PURPOSE — pure modeled computation is judged on CPU,
/// external/blocking interaction is judged on wall — and NEVER by which clock happened to
/// read higher. Both clocks are always recorded on a reached verdict regardless of which one
/// is the judged basis; the basis says which figure the completed-cost line is compared
/// against, not which figure exists.
///
/// Named `RequiredFloorCostBasis`, not the bare `WitnessCostBasis` the ruling's prose uses,
/// because `std_realization_schedule.rs` already declares a `WitnessCostBasis` for an
/// unrelated concept (`MeasuredAtExactSubject | EstimatedFromSiblingClass`, a realization
/// schedule's provenance for a cost figure, not a policy choice of which clock judges a
/// completed claim). Two same-named public enums in one crate is the exact citation ambiguity
/// DESIGN.md §3 rules against, so this type is scoped to the one lane that declares it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RequiredFloorCostBasis {
    CpuCost,
    WallCost,
}

/// `v2.workflow.required_floor`'s claims execute Hermetic (pure in-process evaluation), so
/// CPU is the judged basis. A lane that later admits an execution mode whose purpose is
/// external or blocking interaction picks wall instead — but the choice is made here, by
/// declaring the lane's purpose, not derived from a measurement.
pub fn required_floor_cost_basis() -> RequiredFloorCostBasis {
    RequiredFloorCostBasis::CpuCost
}

/// Which safety mechanism raised THIS occurrence — nothing stronger. Operator ruling
/// 2026-08-19 (BUDGET POLICY CUT, superseding correction): even "which deadline was crossed"
/// overstates the fact, because both the CPU and wall safety limits may already be crossed by
/// the time the interpreter next polls and only one check happens to be the one that raises
/// the stop. `raised_by` names the mechanism that raised this occurrence, not a claim about
/// which clock is "responsible" for the interruption — a `WallDeadlineRaised` occurrence does
/// NOT make the claim a wall-cost witness; that is `RequiredFloorCostBasis`'s question, decided
/// by the witness's declared purpose and never by which mechanism happened to fire
/// (`interrupt trigger -/-> cost basis` is the load-bearing independence the ruling states).
///
/// Distinct from `BudgetKind`, which stays the interpreter's internal raise-path vocabulary
/// (in-eval poll vs. completion-side backstop, consulted at many unrelated call sites); this is
/// the admission-facing fact of which mechanism raised one occurrence. `From<BudgetKind>` is
/// the one translation between them, kept at this seam so the two names never drift apart by
/// accident.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SafetyInterruptTrigger {
    CpuDeadlineRaised,
    WallDeadlineRaised,
}

impl From<BudgetKind> for SafetyInterruptTrigger {
    fn from(kind: BudgetKind) -> Self {
        match kind {
            BudgetKind::Cpu => SafetyInterruptTrigger::CpuDeadlineRaised,
            BudgetKind::Wall => SafetyInterruptTrigger::WallDeadlineRaised,
        }
    }
}

/// Whether one claim reached a verdict, or was interrupted before it could. Operator ruling
/// 2026-08-19 (BUDGET POLICY CUT, corrected by the operator's superseding message the same
/// day — read this doc comment, not an older diff, if the two disagree): the prior fused model
/// let a scheduler-sensitive wall crossing stand in for a judgment about a pure computation's
/// cost. `ClaimTerminality` separates that: did the claim finish, and what did it exactly cost
/// on both clocks (`VerdictReached`) — or did a safety deadline fire before it could
/// (`SafetyInterrupted`).
///
/// FIELD NAMES ARE CHOSEN FOR THEIR CONSUMER, not for how the number was obtained, and the two
/// arms are named for OPPOSITE facts on purpose:
///
/// - `VerdictReached.observed_cpu_ms` / `observed_wall_ms` — exact readings, but neither is a
///   canonical "cost of the witness": they are honest facts about this one occurrence, and nothing
///   stronger. (`exact_*_ms` was the prior spelling; retired because "exact" invited reading these
///   as a canonical cost rather than an occurrence fact.)
/// - `SafetyInterrupted.elapsed_cpu_at_least_ms` / `elapsed_wall_at_least_ms` — also exact
///   measurements of work observed up to the stopped return, but only LOWER BOUNDS on what
///   reaching a verdict would have required. The `_at_least` suffix stays on this arm because the
///   lower bound is the fact downstream admission actually needs: a consumer must not read either
///   duration as the claim's true cost, and the field name says so without requiring the consumer
///   to already know that `SafetyInterrupted` implies censoring. (An interim revision moved
///   `_at_least` off this arm entirely — that revision is withdrawn; the names stay here.)
///
/// `raised_by: SafetyInterruptTrigger` names the mechanism that raised this occurrence — see that
/// type's doc comment for why it is not "which clock the claim ran over".
///
/// TWO INDEPENDENT SAFETY LIMITS are carried on `SafetyInterrupted`, not one shared value: CPU
/// and wall protect against different failures (runaway evaluation vs. a blocked/descheduled
/// process) and must never be a mechanical copy of one figure into both fields — see
/// `WitnessSafetyPolicy` below.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ClaimTerminality {
    VerdictReached {
        verdict: ClaimOutcome,
        observed_cpu_ms: u64,
        observed_wall_ms: u64,
    },
    SafetyInterrupted {
        raised_by: SafetyInterruptTrigger,
        elapsed_cpu_at_least_ms: u64,
        elapsed_wall_at_least_ms: u64,
        cpu_safety_limit_ms: u64,
        wall_safety_limit_ms: u64,
    },
}

/// Two independently derived safety limits, never a scalar copied into both. For a Hermetic
/// pure in-process claim, CPU safety protects against runaway evaluation while wall safety
/// protects against a blocked or descheduled process — different jobs, so the wall limit must
/// be independently derived and LOOSER than the CPU limit, so ordinary host scheduling cannot
/// preempt a computation still inside its CPU envelope. For a genuinely blocking or effectful
/// claim wall may instead be the primary per-row guard. Neither limit is a cost allowance;
/// crossing either is `NotEvaluated` and blocks — see `RequiredFloorClaim`'s
/// `cpu_safety_limit_ms` / `wall_safety_limit_ms` fields for the live-wired instantiation of
/// this policy (`v2.workflow.required_floor`'s two `.dag` constants are its declared values).
///
/// PREEMPTION-1 (operator-directed, 2026-08-19): "crossing either blocks" holds only when
/// `eval_expr`'s cooperative stride-poll actually observes the crossing (see that function's own
/// comment on the residue this leaves, and `std.evaluation_budget`
/// `evaluation_budget_opaque_host_call_note` for the modeled fact). A claim whose cost accrues
/// entirely inside one opaque host call — a native `free_call.*` arm such as
/// `compile_dag_rust_emit_check`, which runs synchronously and never calls back into `eval_expr`
/// — crosses neither limit as far as the poll can tell, however long it runs, and completes as
/// `ClaimTerminality::VerdictReached` rather than `SafetyInterrupted`. Measured, not suspected:
/// floor run 32301212975 recorded `root_d_checkpoint_scalar_declared_arity_witness_holds`
/// (dominated by a `compile_dag_rust_emit_check` call) reaching a verdict at 60317ms CPU against
/// a 5000ms `cpu_ms` limit, twelve times over and uninterrupted, reported through
/// `RequiredFloorOutcome`'s `completed_over_cost_requirement` population rather than through a
/// safety interrupt. These two limits are real protection for cost that accrues across many
/// `eval_expr` calls and no protection — not weaker, none — for cost that accrues inside a
/// single opaque host call; nothing downstream may be built on the assumption that arming them
/// makes a host call interruptible.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WitnessSafetyPolicy {
    pub cpu_ms: u64,
    pub wall_ms: u64,
}

/// The single translation from a raw `(ClaimOutcome, PerformanceReceipt)` pair into the
/// terminality the policy layer reasons over. `run_claim`/`run_claim_measured` and the two
/// completion-side backstops (`budget_completion_outcome`, `wall_budget_completion_outcome`)
/// are unchanged by this — they still raise/detect exactly as before. Only an outcome that is
/// `TimedOut` with `completion: Interrupted` — a genuine pre-verdict abort — becomes
/// `SafetyInterrupted`; every other outcome, including a `TimedOut { completion:
/// CompletedOverBudget }` (the claim DID finish; the completion-side backstop only reclassified
/// its label), reached a verdict and carries exact costs read off the receipt.
///
/// `outcome`'s own `TimedOut.budget_ms` names only the ONE limit that was checked when the
/// interrupt fired, never the other clock's limit — so both limits are threaded in here from
/// the caller's `WitnessSafetyPolicy`, the same policy that armed both deadlines in the first
/// place, rather than reconstructed from a single-limit outcome.
///
/// `SafetyInterrupted`'s two elapsed readings are read off `receipt`, not off `outcome`'s single
/// `elapsed_ms`: `run_claim_measured` samples both clocks around the same call regardless of how
/// it ends, so both are genuine observations at interrupt time.
pub fn claim_terminality(
    outcome: &ClaimOutcome,
    receipt: &v1_interpreter::PerformanceReceipt,
    policy: WitnessSafetyPolicy,
) -> ClaimTerminality {
    match outcome {
        ClaimOutcome::BudgetInterrupted { kind, .. } => ClaimTerminality::SafetyInterrupted {
            raised_by: SafetyInterruptTrigger::from(*kind),
            elapsed_cpu_at_least_ms: (receipt.cpu_nanos / 1_000_000) as u64,
            elapsed_wall_at_least_ms: (receipt.wall_nanos / 1_000_000) as u64,
            cpu_safety_limit_ms: policy.cpu_ms,
            wall_safety_limit_ms: policy.wall_ms,
        },
        _ => ClaimTerminality::VerdictReached {
            verdict: outcome.clone(),
            observed_cpu_ms: (receipt.cpu_nanos / 1_000_000) as u64,
            observed_wall_ms: (receipt.wall_nanos / 1_000_000) as u64,
        },
    }
}

/// DIAGNOSTIC ONLY — never a merge-admission, quarantine, or cost-debt-population decision.
/// Operator ruling 2026-08-19 (BUDGET POLICY CUT, superseding correction): the completed-cost
/// line (`cost_line_ms`, presently 1552) is retired from deciding completed-cost admission, not
/// only from interruption. It was one 1527ms observation plus a scheduler quantum, and the
/// exact 1792ms/1928ms pair observed since shows terminal measurements vary materially across
/// admissible envelopes — a single literal line cannot honestly gate on that spread. This
/// function may remain historical calibration evidence and a diagnostic comparison; nothing in
/// the required-floor loop may call it to decide whether a run blocks. (Consistent with the
/// live code today: `RequiredFloorOutcome.completed_over_cost_requirement` is populated from
/// `BudgetCompletion::CompletedOverBudget` against the safety limit, never from this function or
/// from `cost_line_ms` — this comment states that constraint explicitly so a future edit cannot
/// wire this function back into admission by accident.)
///
/// Evaluated only on `VerdictReached` — an interrupted claim's cost is a lower bound, and
/// comparing a lower bound against a line is not the question this answers, so
/// `SafetyInterrupted` always reads `false` here.
pub fn exceeds_completed_cost_line(
    terminality: &ClaimTerminality,
    cost_line_ms: u64,
    basis: RequiredFloorCostBasis,
) -> bool {
    match terminality {
        ClaimTerminality::VerdictReached {
            observed_cpu_ms,
            observed_wall_ms,
            ..
        } => {
            let exact = match basis {
                RequiredFloorCostBasis::CpuCost => *observed_cpu_ms,
                RequiredFloorCostBasis::WallCost => *observed_wall_ms,
            };
            exact > cost_line_ms
        }
        ClaimTerminality::SafetyInterrupted { .. } => false,
    }
}

pub fn resolve_entry_graph(
    source_roots: &[String],
    entry_file: &str,
) -> Result<
    (
        Rc<v1_compiler_compile::ResolvedGraph>,
        Rc<HashMap<String, Rc<NewlineIndex>>>,
    ),
    String,
> {
    // Route through the same loader engine as `resolve_entry_graph_shared`
    // (proven behaviorally identical to the cold import-adjacency resolve by
    // resolve_typed_cache_equivalence_test): with imports stripped (namespace
    // wave 1) an entry's dependencies are name-derived, and the old
    // `load_sources_for_entry_with_index` walk only follows import edges — a
    // stripped fixed entry (e.g. the floor runner) failed to resolve at all.
    let index = process_shared_index(source_roots);
    resolve_entry_with_index(&index, entry_file)
}

// Process-level (per-thread) resolve store — the S1a increment of the resolver
// graph-major design (docs/plans/resolver-graph-major-design.md). Within one
// process the source tree is a fixed snapshot, so a resolved entry graph is a
// pure fact of (source_roots, entry) — the same purity assumption the walk memo
// (M1) and typed_module_cache already ship on. Routing every fixed-entry
// consumer (floor runner context, diff observer, output policy, group syntax,
// the executor's plan entry) through this store makes "resolve the same declared
// machinery twice in one process" unwritable on these paths, with failure
// semantics unchanged: a miss resolves exactly as before, including the typed
// error path. Thread-local by design: resolved graphs are Rc-based (not Send);
// shard threads keep their own store rather than smuggling Rc across threads.
thread_local! {
    #[allow(clippy::type_complexity)]
    static PROCESS_RESOLVE_STORE: RefCell<
        HashMap<
            (String, String),
            (
                Rc<v1_compiler_compile::ResolvedGraph>,
                Rc<HashMap<String, Rc<NewlineIndex>>>,
            ),
        >,
    > = RefCell::new(HashMap::new());

    // The thread's ONE shared resolve index (union-resolve S1,
    // docs/plans/resolver-graph-major-design.md §7). Every fixed-entry consumer routed
    // through resolve_entry_graph_shared (the executor prelude: plan entry + output
    // policy + group syntax, plus the floor runner) resolves against this single
    // MultiEntryIndex, so its parse/typed caches share the union of all those closures:
    // the shared std/spec prefix typechecks ONCE, not once per prelude entry. Keyed by
    // source_roots — a run's roots are fixed, so this is a get-or-build, rebuilt only on
    // the rare roots change. Thread-local by the same Rc-not-Send reason as the store:
    // each shard keeps its own index rather than smuggling Rc across threads.
    #[allow(clippy::type_complexity)]
    static PROCESS_RESOLVE_INDEX: RefCell<Option<(String, Rc<MultiEntryIndex>)>> =
        const { RefCell::new(None) };

    // While loading the materialization-provider authority, cross-process disk hits
    // must not re-enter provider routing (review 44268: bootstrap recursion).
    static CROSS_PROCESS_PROVIDER_ROUTING_SUPPRESSED: Cell<usize> = const { Cell::new(0) };
}

pub(crate) fn cross_process_provider_routing_suppressed() -> bool {
    CROSS_PROCESS_PROVIDER_ROUTING_SUPPRESSED.with(|c| c.get() > 0)
}

/// Count of resolved-graph stores skipped because the provider-bootstrap window was
/// open. The skip is bounded (only the provider's own closure resolves inside that
/// window) and observable, so the deficit can never be masked by silence.
static PROVIDER_BOOTSTRAP_STORE_SKIPS: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);

fn record_provider_bootstrap_store_skip() {
    PROVIDER_BOOTSTRAP_STORE_SKIPS.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
}

pub(crate) fn with_cross_process_provider_routing_suppressed<F, R>(f: F) -> R
where
    F: FnOnce() -> R,
{
    struct Guard;
    impl Drop for Guard {
        fn drop(&mut self) {
            CROSS_PROCESS_PROVIDER_ROUTING_SUPPRESSED.with(|c| {
                c.set(c.get().saturating_sub(1));
            });
        }
    }

    CROSS_PROCESS_PROVIDER_ROUTING_SUPPRESSED.with(|c| {
        c.set(c.get().saturating_add(1));
    });
    let _guard = Guard;
    f()
}

/// Canonical spelling for the shared-index roots — both the key AND the build
/// inputs: an absolute root under the workspace normalizes to its repo-relative
/// form, so the executor's CLI `$ROOT/dag` and the plan's declared `dag`
/// (`gunbc.ci_layer_roots` witness_layer_roots) address ONE index. Without this,
/// the compile-clean receipt (armed from CLI roots) and batch-2 discovery (plan
/// roots) keyed two separate typed universes in CI and the gate's warm store was
/// silently replaced before the corpus read it (review 39118 on PR #6783). Order
/// is preserved (primary-precedence pool semantics); a root outside the workspace
/// keeps its spelling — it is genuinely a different pool.
fn canonical_shared_index_roots(source_roots: &[String]) -> Vec<String> {
    source_roots
        .iter()
        .map(|r| {
            let p = Path::new(r);
            if p.is_absolute() {
                try_repo_relative_path_normalized(p).unwrap_or_else(|| r.replace('\\', "/"))
            } else {
                r.replace('\\', "/")
            }
        })
        .collect()
}

/// The thread-local shared resolve index for `source_roots` (union-resolve S1). Built once
/// per (thread, canonical roots) and reused, so consumers that resolve distinct entries
/// against it share one typed_module_cache — the union closure typechecks once per node.
/// Roots are canonicalized (`canonical_shared_index_roots`) before both keying and
/// building, so path-spelling variants of the same pool cannot fork the INDEX.
/// This does not canonicalize independently-read `SourceFile` objects: a consumer
/// that joins absolute-path reads to this relative-path index can still fork source
/// identity. The divergence census walls that site with parent-owned `Rc` identity;
/// the class-wide next rung is canonical `SourceFile` identity at construction.
pub fn process_shared_index(source_roots: &[String]) -> Rc<MultiEntryIndex> {
    let roots = canonical_shared_index_roots(source_roots);
    let roots_key = roots.join("\u{1f}");
    let existing = PROCESS_RESOLVE_INDEX.with(|s| {
        s.borrow().as_ref().and_then(|(k, idx)| {
            if *k == roots_key {
                Some(idx.clone())
            } else {
                None
            }
        })
    });
    if let Some(idx) = existing {
        return idx;
    }
    let build_started = std::time::Instant::now();
    let idx = Rc::new(build_multi_entry_index(&roots));
    discovery_phase_totals::add(
        &discovery_phase_totals::SHARED_INDEX_BUILD_MS,
        build_started.elapsed(),
    );
    PROCESS_RESOLVE_INDEX.with(|s| {
        *s.borrow_mut() = Some((roots_key, idx.clone()));
    });
    idx
}

pub fn resolve_entry_graph_shared(
    source_roots: &[String],
    entry_file: &str,
) -> Result<
    (
        Rc<v1_compiler_compile::ResolvedGraph>,
        Rc<HashMap<String, Rc<NewlineIndex>>>,
    ),
    String,
> {
    let key = (source_roots.join("\u{1f}"), entry_file.to_string());
    let hit = PROCESS_RESOLVE_STORE.with(|s| s.borrow().get(&key).cloned());
    if let Some(found) = hit {
        return Ok(found);
    }
    // Resolve through the thread's shared index instead of a fresh per-call module index.
    // resolve_entry_with_index is proven behaviorally identical to the cold resolve_entry_graph
    // by resolve_typed_cache_equivalence_test (cached == cold across every resolve order); the
    // win is that the union of all fixed-entry closures now typechecks once per node.
    let index = process_shared_index(source_roots);
    let resolved = resolve_entry_with_index(&index, entry_file)?;
    PROCESS_RESOLVE_STORE.with(|s| {
        s.borrow_mut().insert(key, resolved.clone());
    });
    Ok(resolved)
}

/// THE LIVE-READ SELECTION MANIFEST, and why it carries a subject rather than a timestamp.
///
/// G2 classification is expensive: it needs fn-arrow declaration facts reflected out of a
/// whole-tree resolved context, which is why the design pairs G2 path-intersection with carrier
/// memoization rather than treating the memo as an optimisation. But a memo whose validity is
/// implicit is a cache with no invalidation story — it serves whatever it holds and cannot say
/// which tree the answer came from.
///
/// So the manifest names its subject. `subject_id` is the content identity of the source
/// population the classifications were derived from; a lookup whose current index does not equal
/// that subject REFUSES rather than serving a classification built against a different tree. That
/// is the same discipline the freeze-gate baseline needed this morning: evidence that cannot name
/// its subject cannot be checked against it, and a stale answer that looks fresh is worse than no
/// answer at all — here it would license a skip.
///
/// Rows are DECLARATION grain, not entry grain. Coarsening to one verdict per entry would make a
/// single live-read witness render every sibling in its file unskippable, which is the same
/// precision loss the G1 union caused one layer down.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LiveReadSelectionManifest {
    /// The identity of the index that produced these rows. Not a caller-supplied label.
    pub subject: u64,
    pub rows: std::collections::HashMap<String, LiveReadSelectionRow>,
}

/// Mirror of `v2.std.live_read.PathPattern`.
///
/// The three arms are what makes a runtime read INTERSECTABLE with a diff rather than merely
/// present. A literal path can be compared against touched paths; a parameter reference names a
/// path this declaration receives rather than fixes, so its value is not knowable here; and an
/// unknown path is a read whose target the classification could not determine at all. Collapsing
/// them — which the previous `Vec<String>` did — leaves a consumer with only "some runtime read
/// happens", and the only safe reading of that is "every nonempty diff touches it", which is the
/// G1 over-selection this lane exists to remove, rebuilt one layer up.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LiveReadPathPattern {
    LiteralPath(String),
    ParamRef(String),
    UnknownPath,
}

/// Mirror of `v2.std.live_read.LiveReadCarrier`.
///
/// The variant matters to selection, not just the fact of a carrier: a filesystem read carries a
/// path that may intersect a diff, while a declaration-fact scan and a decl-fact reflection read
/// the corpus structurally and are touched by any source change. A consumer that cannot tell them
/// apart has to treat all three as the widest of them.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LiveReadCarrier {
    FilesystemReadPath(LiveReadPathPattern),
    ModuleDeclarationFactsScan,
    DeclFactsReflection { home: String },
}

/// Mirror of `v2.std.live_read.LiveReadClassification`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LiveReadClassification {
    LocalRead,
    RuntimeRead { carriers: Vec<LiveReadCarrier> },
}

/// One declaration's classification, mirroring `v2.std.live_read.LiveReadSelectionProjection`
/// arm for arm. `Refused` is not an error channel — it is the state that forbids a skip, so it
/// must survive into the seed rather than being flattened into a bool.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LiveReadSelectionRow {
    Classified(LiveReadClassification),
    Refused { cause: String },
}

impl LiveReadSelectionRow {
    /// Whether this declaration's live reads intersect `touched_paths`.
    ///
    /// One total fold over the mirrored structure, and every arm is decided rather than assumed:
    /// a refusal forbids a skip; a local read is untouched by any diff; a literal path is compared;
    /// and a parameter reference, an unknown path, or a structural corpus scan is touched by any
    /// nonempty diff because its target cannot be narrowed here. That last group is a genuine
    /// over-approximation computed AS the answer — the model's precision frontier — not a failure
    /// arm widening, which is why it is safe where the previous blanket bool was not.
    pub fn touched_by(&self, touched_paths: &[String]) -> bool {
        let carriers = match self {
            LiveReadSelectionRow::Refused { .. } => return true,
            LiveReadSelectionRow::Classified(LiveReadClassification::LocalRead) => return false,
            LiveReadSelectionRow::Classified(LiveReadClassification::RuntimeRead { carriers }) => {
                carriers
            }
        };
        carriers.iter().any(|carrier| match carrier {
            LiveReadCarrier::ModuleDeclarationFactsScan
            | LiveReadCarrier::DeclFactsReflection { .. } => !touched_paths.is_empty(),
            LiveReadCarrier::FilesystemReadPath(pattern) => match pattern {
                LiveReadPathPattern::ParamRef(_) | LiveReadPathPattern::UnknownPath => {
                    !touched_paths.is_empty()
                }
                LiveReadPathPattern::LiteralPath(path) => {
                    let want = workspace_relative_repo_path(path);
                    touched_paths
                        .iter()
                        .any(|touched| repo_paths_match_touched(&want, touched))
                }
            },
        })
    }
}

impl LiveReadSelectionManifest {
    /// Look up one enrolled declaration. A subject mismatch is a typed refusal, never a miss that
    /// silently falls back to recomputation against the wrong tree — and never a `None` the caller
    /// could read as "nothing known, proceed".
    pub fn row_for(
        &self,
        current_subject: u64,
        entry_path: &str,
        fn_name: &str,
    ) -> Result<&LiveReadSelectionRow, String> {
        if self.subject != current_subject {
            return Err(format!(
                "LIVE-READ MANIFEST REFUSAL cause=SubjectMismatch manifest_subject={} \
                 current_subject={current_subject} — the memo was built against a different index, \
                 so its classifications cannot be attributed to this tree. Serving them would \
                 license a skip derived from facts about another source population.",
                self.subject
            ));
        }
        let key = live_read_manifest_key(entry_path, fn_name);
        self.rows.get(&key).ok_or_else(|| {
            format!(
                "LIVE-READ MANIFEST REFUSAL cause=DeclarationAbsent key={key} — the manifest claims \
                 completeness for this subject but carries no row for an enrolled declaration. An \
                 absent row is not an absent runtime read; it is a gap in the classification, and \
                 the entry must not fast-skip on it."
            )
        })
    }
}

/// Declaration-grain key. Entry path plus function name, which is the identity the floor already
/// enrolls rows under.
pub fn live_read_manifest_key(entry_path: &str, fn_name: &str) -> String {
    format!("{}::{}", workspace_relative_repo_path(entry_path), fn_name)
}

/// One enrolled declaration to classify. Mirrors `v2.lens.live_read_classification`
/// `LiveReadSelectionRequest` field for field.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LiveReadSelectionRequest {
    pub entry_path: String,
    /// No `entry_module`: the module is DERIVED from the path by the `.dag` binder
    /// (`bind_g2_root`), so a request naming one module's path and another's function is
    /// unwritable rather than merely detected.
    pub fn_name: String,
}

/// The lens entry the manifest producer evaluates. Named here rather than at the call site so the
/// one authority the producer consumes is stated once.
const LIVE_READ_CLASSIFICATION_ENTRY: &str = "src/v2/lens/live_read_classification.dag";

/// Build the whole-tree live-read manifest by evaluating the `.dag` authority ONCE for the entire
/// request set.
///
/// The batching is not an optimisation detail, it is the reason the seam has this shape: the G2
/// classification needs the dependency-edge, module-declaration, and fn-arrow fact populations for
/// the whole tree, and those are derived per evaluation. A per-declaration call would rebuild all
/// three for every row — quadratic in the corpus against a population that does not change between
/// rows. `live_read_selection_manifest_over` therefore derives them once and folds the requests
/// over the shared closure, and this producer's job is to hand it the full request set in one go.
///
/// Every failure arm REFUSES. There is no arm that returns an empty or partial manifest, because a
/// manifest is consumed as a completeness claim — `row_for` treats an absent row as a refusal — and
/// a producer that answered "here is what I could classify" would convert its own failure into a
/// silent skip licence for everything it dropped (§5: a failure arm must refuse, never widen, and
/// here widening the *skippable* set is the under-selection direction that reads as a faster green).
pub fn build_live_read_selection_manifest(
    index: &MultiEntryIndex,
    requests: &[LiveReadSelectionRequest],
) -> Result<LiveReadSelectionManifest, String> {
    let source_roots = &index.source_roots;
    let (graph, indices) =
        resolve_entry_with_index_for_discovery_corpus(index, LIVE_READ_CLASSIFICATION_ENTRY)
            .map_err(|e| {
                format!(
                    "LIVE-READ MANIFEST REFUSAL cause=LensEntryUnresolved entry={LIVE_READ_CLASSIFICATION_ENTRY} \
                     detail={e} — the classification authority could not be resolved, so no \
                     declaration has an established classification and none may fast-skip."
                )
            })?;
    let ctx = make_eval_context(&graph, indices, v1_interpreter::ExecutionMode::Wet);

    let request_values: Vec<v1_interpreter::Value> = requests
        .iter()
        .map(|req| v1_interpreter::Value::Record {
            type_name: ctx.sym("LiveReadSelectionRequest"),
            fields: Rc::new(vec![
                (ctx.sym("entry_path"), str_value(req.entry_path.clone())),
                (ctx.sym("fn_name"), str_value(req.fn_name.clone())),
            ]),
        })
        .collect();
    let root_values: Vec<v1_interpreter::Value> =
        source_roots.iter().map(|r| str_value(r.clone())).collect();

    let args = vec![
        (
            Some("requests".to_string()),
            v1_interpreter::Value::List(Rc::new(request_values.into())),
        ),
        (
            Some("pool_roots".to_string()),
            v1_interpreter::Value::List(Rc::new(root_values.clone().into())),
        ),
        (
            Some("importer_roots".to_string()),
            v1_interpreter::Value::List(Rc::new(root_values.into())),
        ),
        (
            Some("exclude_substrings".to_string()),
            v1_interpreter::Value::List(Rc::new(im::Vector::new())),
        ),
    ];

    let produced = v1_interpreter::with_active_context(&ctx, || {
        v1_interpreter::run_in_context_with_args(
            &ctx,
            "live_read_selection_manifest_live",
            &args,
            false,
        )
    })
    .map_err(|e| {
        format!(
            "LIVE-READ MANIFEST REFUSAL cause=ProducerFailed detail={e} — the classification \
             authority did not produce a manifest, so no declaration is classified."
        )
    })?;

    let v1_interpreter::Value::List(row_values) = &produced else {
        return Err(format!(
            "LIVE-READ MANIFEST REFUSAL cause=ProducerShapeUnexpected got={} — expected a \
             List<LiveReadSelectionManifestRow>.",
            produced.type_label_public()
        ));
    };

    let mut rows = std::collections::HashMap::new();
    for row in row_values.iter() {
        let v1_interpreter::Value::Record { fields, .. } = row else {
            return Err(format!(
                "LIVE-READ MANIFEST REFUSAL cause=RowShapeUnexpected got={} — expected a \
                 LiveReadSelectionManifestRow record.",
                row.type_label_public()
            ));
        };
        let key = match ctx.field(fields, "key") {
            Some(Value::Str(k)) => k.to_string(),
            other => {
                return Err(format!(
                    "LIVE-READ MANIFEST REFUSAL cause=RowKeyUnexpected got={other:?} — a row \
                     without a String key cannot be attributed to a declaration."
                ))
            }
        };
        let projection = match ctx.field(fields, "projection") {
            Some(p) => p.clone(),
            None => {
                return Err(format!(
                    "LIVE-READ MANIFEST REFUSAL cause=RowProjectionAbsent key={key} — a row \
                     without a projection carries no classification."
                ))
            }
        };
        let decoded = decode_live_read_selection_row(&ctx, &projection)?;
        // A duplicate key REFUSES rather than overwriting. `HashMap::insert` returns the old value
        // and drops it, so two requests colliding on one `path::fn` key would silently keep the
        // last — and the two rows are exactly the case where they might disagree. Losing one
        // quietly is how a RuntimeRead gets replaced by a LocalRead that licenses a skip.
        if let Some(prior) = rows.insert(key.clone(), decoded) {
            return Err(format!(
                "LIVE-READ MANIFEST REFUSAL cause=DuplicateManifestKey key={key} — two requests \
                 produced the same declaration key. Keeping either row would discard a \
                 classification without saying which; prior={prior:?}"
            ));
        }
    }

    Ok(LiveReadSelectionManifest {
        subject: index.generation,
        rows,
    })
}

impl MultiEntryIndex {
    /// This index's opaque identity, for checking a manifest against the index about to consume it.
    pub fn generation(&self) -> u64 {
        self.generation
    }

    /// The live-read selection manifest for this index, built once and reused.
    ///
    /// The memo lives on the index rather than beside it because the index is what the subject
    /// identifies: a second index — including one over byte-identical source roots — gets its own
    /// generation and its own empty cell, so it cannot be served rows derived from another tree.
    pub fn live_read_manifest(
        &self,
        requests: &[LiveReadSelectionRequest],
    ) -> Result<Rc<LiveReadSelectionManifest>, String> {
        if let Some(cached) = self.live_read_manifest.borrow().as_ref() {
            return cached.clone().map_err(|e| e.clone()).map(|m| m);
        }
        let built = build_live_read_selection_manifest(self, requests).map(Rc::new);
        *self.live_read_manifest.borrow_mut() = Some(built.clone());
        built
    }
}

/// Decode one `v2.std.live_read.LiveReadSelectionProjection` value.
///
/// `LiveReadSelectionRefused` decodes to `Refused`, NOT to a decode error: it is a legitimate,
/// modelled state of the authority (the classification could not be established), and the seed's
/// job is to carry it through so the consumer forbids a skip. Collapsing it into an error here
/// would lose the located cause the authority already computed.
///
/// Everything else refuses. An earlier revision of this decoder accepted carrier list items only
/// as `Value::Str` or a record with a `module` field and fell through to an empty carrier vector
/// on anything else — but `LiveReadCarrier` is a coproduct, so every real carrier arrives as
/// `Value::Variant` and took that fallthrough. The result was a `RuntimeRead` whose carriers were
/// silently empty, which reads to a consumer as "runtime read, intersecting nothing" — the
/// under-selection direction, produced by an absorbing arm sitting directly beneath a comment
/// claiming fail-closed behaviour. There is no such arm now: an unrecognised shape at any depth
/// refuses.
fn decode_live_read_selection_row(
    ctx: &v1_interpreter::InterpContext,
    projection: &v1_interpreter::Value,
) -> Result<LiveReadSelectionRow, String> {
    let (variant_name, fields) = variant_parts(projection).ok_or_else(|| {
        format!(
            "LIVE-READ MANIFEST REFUSAL cause=ProjectionShapeUnexpected got={} — expected a \
             LiveReadSelectionProjection variant.",
            projection.type_label_public()
        )
    })?;
    if ctx.sym_eq(variant_name, "LiveReadSelectionRefused") {
        let cause = match ctx.field(fields, "cause") {
            Some(Value::Str(c)) => c.to_string(),
            _ => "typed refusal without a String cause".to_string(),
        };
        return Ok(LiveReadSelectionRow::Refused { cause });
    }
    if !ctx.sym_eq(variant_name, "LiveReadSelectionClassified") {
        return Err(
            "LIVE-READ MANIFEST REFUSAL cause=ProjectionVariantUnknown — the projection carried a \
             variant this seed does not model, so its classification cannot be attributed."
                .to_string(),
        );
    }
    let classification = ctx.field(fields, "classification").ok_or_else(|| {
        "LIVE-READ MANIFEST REFUSAL cause=ClassificationAbsent — a Classified projection with no \
         classification."
            .to_string()
    })?;
    Ok(LiveReadSelectionRow::Classified(
        decode_live_read_classification(ctx, classification)?,
    ))
}

/// `Value::Variant`'s name and fields, or `None` for anything else. Factored out because the
/// decoder walks four nested coproducts and each one needs the same refusal on a non-variant.
fn variant_parts(
    value: &v1_interpreter::Value,
) -> Option<(
    v1_interpreter::Symbol,
    &[(v1_interpreter::Symbol, v1_interpreter::Value)],
)> {
    match value {
        v1_interpreter::Value::Variant {
            variant_name,
            fields,
            ..
        } => Some((*variant_name, fields.as_slice())),
        _ => None,
    }
}

fn decode_live_read_classification(
    ctx: &v1_interpreter::InterpContext,
    value: &v1_interpreter::Value,
) -> Result<LiveReadClassification, String> {
    let (name, fields) = variant_parts(value).ok_or_else(|| {
        format!(
            "LIVE-READ MANIFEST REFUSAL cause=ClassificationShapeUnexpected got={} — expected a \
             LiveReadClassification variant.",
            value.type_label_public()
        )
    })?;
    if ctx.sym_eq(name, "LocalRead") {
        return Ok(LiveReadClassification::LocalRead);
    }
    if !ctx.sym_eq(name, "RuntimeRead") {
        return Err(
            "LIVE-READ MANIFEST REFUSAL cause=ClassificationVariantUnknown — neither LocalRead nor \
             RuntimeRead; this seed cannot decide whether a skip is licensed."
                .to_string(),
        );
    }
    let Some(v1_interpreter::Value::List(items)) = ctx.field(fields, "carriers") else {
        return Err(
            "LIVE-READ MANIFEST REFUSAL cause=CarrierListAbsent — a RuntimeRead whose carrier list \
             is missing or not a list. An empty carrier set intersects no diff, so accepting this \
             shape would license exactly the skip the runtime read forbids."
                .to_string(),
        );
    };
    let carriers = items
        .iter()
        .map(|item| decode_live_read_carrier(ctx, item))
        .collect::<Result<Vec<LiveReadCarrier>, String>>()?;
    Ok(LiveReadClassification::RuntimeRead { carriers })
}

fn decode_live_read_carrier(
    ctx: &v1_interpreter::InterpContext,
    value: &v1_interpreter::Value,
) -> Result<LiveReadCarrier, String> {
    let (name, fields) = variant_parts(value).ok_or_else(|| {
        format!(
            "LIVE-READ MANIFEST REFUSAL cause=CarrierShapeUnexpected got={} — expected a \
             LiveReadCarrier variant.",
            value.type_label_public()
        )
    })?;
    if ctx.sym_eq(name, "ModuleDeclarationFactsScan") {
        return Ok(LiveReadCarrier::ModuleDeclarationFactsScan);
    }
    if ctx.sym_eq(name, "DeclFactsReflection") {
        let home =
            match ctx.field(fields, "home") {
                Some(Value::Str(h)) => h.to_string(),
                _ => return Err(
                    "LIVE-READ MANIFEST REFUSAL cause=CarrierHomeUnexpected — DeclFactsReflection \
                     without a String home."
                        .to_string(),
                ),
            };
        return Ok(LiveReadCarrier::DeclFactsReflection { home });
    }
    if !ctx.sym_eq(name, "FilesystemReadPath") {
        return Err(
            "LIVE-READ MANIFEST REFUSAL cause=CarrierVariantUnknown — a carrier variant this seed \
             does not model. Its read target is therefore unknown, and an unknown target cannot be \
             intersected with a diff."
                .to_string(),
        );
    }
    let pattern = ctx.field(fields, "path_pattern").ok_or_else(|| {
        "LIVE-READ MANIFEST REFUSAL cause=PathPatternAbsent — FilesystemReadPath without a \
         path_pattern."
            .to_string()
    })?;
    Ok(LiveReadCarrier::FilesystemReadPath(
        decode_live_read_path_pattern(ctx, pattern)?,
    ))
}

fn decode_live_read_path_pattern(
    ctx: &v1_interpreter::InterpContext,
    value: &v1_interpreter::Value,
) -> Result<LiveReadPathPattern, String> {
    let (name, fields) = variant_parts(value).ok_or_else(|| {
        format!(
            "LIVE-READ MANIFEST REFUSAL cause=PathPatternShapeUnexpected got={} — expected a \
             PathPattern variant.",
            value.type_label_public()
        )
    })?;
    if ctx.sym_eq(name, "UnknownPath") {
        return Ok(LiveReadPathPattern::UnknownPath);
    }
    if ctx.sym_eq(name, "LiteralPath") {
        return match ctx.field(fields, "path") {
            Some(Value::Str(p)) => Ok(LiveReadPathPattern::LiteralPath(p.to_string())),
            _ => Err(
                "LIVE-READ MANIFEST REFUSAL cause=LiteralPathUnexpected — LiteralPath without a \
                 String path. Treating it as unknown would silently widen; refusing keeps the \
                 defect countable."
                    .to_string(),
            ),
        };
    }
    if ctx.sym_eq(name, "ParamRef") {
        return match ctx.field(fields, "name") {
            Some(Value::Str(n)) => Ok(LiveReadPathPattern::ParamRef(n.to_string())),
            _ => Err(
                "LIVE-READ MANIFEST REFUSAL cause=ParamRefUnexpected — ParamRef without a String \
                 name."
                    .to_string(),
            ),
        };
    }
    Err(
        "LIVE-READ MANIFEST REFUSAL cause=PathPatternVariantUnknown — a path pattern this seed does \
         not model."
            .to_string(),
    )
}

// The producer's executing consumer. A `pub fn` that compiles is not evidence it works (§5:
// specification-without-execution) — these run it against the real tree, and the decoder controls
// below run each coproduct arm the classification can carry.
#[cfg(test)]
mod live_read_selection_manifest_producer_tests {
    use super::{
        build_live_read_selection_manifest, build_multi_entry_index,
        decode_live_read_selection_row, make_eval_context,
        resolve_entry_with_index_for_discovery_corpus, workspace_root, LiveReadCarrier,
        LiveReadClassification, LiveReadPathPattern, LiveReadSelectionRequest,
        LiveReadSelectionRow, LIVE_READ_CLASSIFICATION_ENTRY,
    };
    use crate::v1_interpreter::{self, str_value, ExecutionMode, Value};
    use std::rc::Rc;

    fn source_roots() -> Vec<String> {
        vec!["dag".to_string(), "src/v2".to_string()]
    }

    // A declaration inside a declared carrier home whose body reaches the carrier callee, and one
    // pure declaration that reaches nothing. The pair is the discriminator: a producer that
    // answered the same thing for both would prove nothing, so the test asserts they DIFFER.
    fn requests() -> Vec<LiveReadSelectionRequest> {
        vec![
            LiveReadSelectionRequest {
                entry_path: "src/v2/lens/module_graph.dag".to_string(),
                fn_name: "module_declaration_facts_live".to_string(),
            },
            LiveReadSelectionRequest {
                entry_path: "src/v2/lens/live_read_classification.dag".to_string(),
                fn_name: "classification_is_local_read".to_string(),
            },
        ]
    }

    fn enter_workspace() {
        std::env::set_current_dir(workspace_root()).expect("chdir workspace");
    }

    #[test]
    fn manifest_classifies_a_carrier_reaching_decl_apart_from_a_pure_one() {
        enter_workspace();
        let index = build_multi_entry_index(&source_roots());
        let manifest = build_live_read_selection_manifest(&index, &requests())
            .unwrap_or_else(|e| panic!("producer refused: {e}"));

        let carrier_row = manifest
            .row_for(
                index.generation(),
                "src/v2/lens/module_graph.dag",
                "module_declaration_facts_live",
            )
            .unwrap_or_else(|e| panic!("carrier row lookup: {e}"));
        let pure_row = manifest
            .row_for(
                index.generation(),
                "src/v2/lens/live_read_classification.dag",
                "classification_is_local_read",
            )
            .unwrap_or_else(|e| panic!("pure row lookup: {e}"));

        // The pure declaration must classify LocalRead. If it did not, the producer would be
        // marking the whole corpus unskippable — safe, but it would also mean the manifest carries
        // no information and the discriminator below is vacuous.
        assert_eq!(
            pure_row,
            &LiveReadSelectionRow::Classified(LiveReadClassification::LocalRead),
            "a pure predicate classified as something other than LocalRead"
        );
        // And the carrier-reaching one must NOT. This is the direction that matters for safety:
        // a LocalRead here would license the exact skip that under-selected the falsifier.
        assert_ne!(
            carrier_row, pure_row,
            "a declaration reaching a live-read carrier classified identically to a pure \
             predicate — the manifest is not discriminating, so every row it carries is suspect"
        );
        // A RuntimeRead with an EMPTY carrier list would satisfy the inequality above while
        // intersecting no diff — the under-selection shape the old decoder produced silently.
        if let LiveReadSelectionRow::Classified(LiveReadClassification::RuntimeRead { carriers }) =
            carrier_row
        {
            assert!(
                !carriers.is_empty(),
                "a RuntimeRead carrying no carriers intersects nothing and licenses a skip"
            );
        }
    }

    // The subject wall. A manifest built by one index must refuse to answer for another, rather
    // than serving a classification derived from facts about a different tree. The mismatched
    // subject here is a REAL second index over the SAME source roots — not an invented string —
    // because that is the case a caller-supplied label could not distinguish.
    #[test]
    fn manifest_lookup_refuses_for_a_different_index() {
        enter_workspace();
        let index = build_multi_entry_index(&source_roots());
        let other = build_multi_entry_index(&source_roots());
        assert_ne!(
            index.generation(),
            other.generation(),
            "two indices over identical source roots must still have distinct identities, or the \
             subject check cannot see a swapped tree"
        );
        let manifest = build_live_read_selection_manifest(&index, &requests())
            .unwrap_or_else(|e| panic!("producer refused: {e}"));
        let err = manifest
            .row_for(
                other.generation(),
                "src/v2/lens/module_graph.dag",
                "module_declaration_facts_live",
            )
            .expect_err("a lookup under a different index was served rather than refused");
        assert!(
            err.contains("SubjectMismatch"),
            "refusal did not name the cause: {err}"
        );
    }

    // An enrolled declaration the manifest does not carry is a gap in the classification, not an
    // absence of runtime reads — so the lookup refuses rather than returning a miss the caller
    // could read as "nothing known, proceed".
    #[test]
    fn manifest_lookup_refuses_on_absent_declaration() {
        enter_workspace();
        let index = build_multi_entry_index(&source_roots());
        let manifest = build_live_read_selection_manifest(&index, &requests())
            .unwrap_or_else(|e| panic!("producer refused: {e}"));
        let err = manifest
            .row_for(
                index.generation(),
                "src/v2/lens/module_graph.dag",
                "no_such_fn",
            )
            .expect_err("an unenrolled declaration was served rather than refused");
        assert!(
            err.contains("DeclarationAbsent"),
            "refusal did not name the cause: {err}"
        );
    }

    // The memo is on the index, so the same index builds once and a distinct index rebuilds.
    #[test]
    fn manifest_is_memoized_per_index_and_a_distinct_index_rebuilds() {
        enter_workspace();
        let index = build_multi_entry_index(&source_roots());
        let first = index.live_read_manifest(&requests()).expect("first build");
        let second = index.live_read_manifest(&requests()).expect("memo hit");
        assert!(
            Rc::ptr_eq(&first, &second),
            "the second call rebuilt instead of hitting the memo"
        );
        let other = build_multi_entry_index(&source_roots());
        let third = other.live_read_manifest(&requests()).expect("other build");
        assert!(
            !Rc::ptr_eq(&first, &third),
            "a distinct index served another index's manifest"
        );
        assert_eq!(third.subject, other.generation());
    }

    // ---- decoder controls, one per coproduct arm ----------------------------------------
    //
    // These build real `.dag` values in an interpreter context and decode them. They exist
    // because the previous decoder handled only `Value::Str` and `Value::Record` while every
    // carrier is a `Value::Variant`, so all five arms below took an absorbing fallthrough that
    // produced an empty carrier list. Deleting any arm from the decoder must red its control.

    fn ctx_for_decoding() -> v1_interpreter::InterpContext {
        enter_workspace();
        let index = build_multi_entry_index(&source_roots());
        let (graph, indices) =
            resolve_entry_with_index_for_discovery_corpus(&index, LIVE_READ_CLASSIFICATION_ENTRY)
                .unwrap_or_else(|e| panic!("resolve lens: {e}"));
        make_eval_context(&graph, indices, ExecutionMode::Wet)
    }

    fn variant(
        ctx: &v1_interpreter::InterpContext,
        type_name: &str,
        name: &str,
        fields: Vec<(&str, Value)>,
    ) -> Value {
        Value::Variant {
            type_name: ctx.sym(type_name),
            variant_name: ctx.sym(name),
            fields: Rc::new(fields.into_iter().map(|(k, v)| (ctx.sym(k), v)).collect()),
        }
    }

    fn classified(ctx: &v1_interpreter::InterpContext, carriers: Vec<Value>) -> Value {
        let runtime = variant(
            ctx,
            "LiveReadClassification",
            "RuntimeRead",
            vec![("carriers", Value::List(Rc::new(carriers.into())))],
        );
        variant(
            ctx,
            "LiveReadSelectionProjection",
            "LiveReadSelectionClassified",
            vec![("classification", runtime)],
        )
    }

    fn decoded_carriers(
        ctx: &v1_interpreter::InterpContext,
        carriers: Vec<Value>,
    ) -> Vec<LiveReadCarrier> {
        match decode_live_read_selection_row(ctx, &classified(ctx, carriers))
            .unwrap_or_else(|e| panic!("decode: {e}"))
        {
            LiveReadSelectionRow::Classified(LiveReadClassification::RuntimeRead { carriers }) => {
                carriers
            }
            other => panic!("expected a RuntimeRead, got {other:?}"),
        }
    }

    fn fs_carrier(ctx: &v1_interpreter::InterpContext, pattern: Value) -> Value {
        variant(
            ctx,
            "LiveReadCarrier",
            "FilesystemReadPath",
            vec![("path_pattern", pattern)],
        )
    }

    #[test]
    fn decodes_filesystem_read_of_a_literal_path() {
        let ctx = ctx_for_decoding();
        let pattern = variant(
            &ctx,
            "PathPattern",
            "LiteralPath",
            vec![("path", str_value("dag/gunbc/ci_spec.dag".to_string()))],
        );
        assert_eq!(
            decoded_carriers(&ctx, vec![fs_carrier(&ctx, pattern)]),
            vec![LiveReadCarrier::FilesystemReadPath(
                LiveReadPathPattern::LiteralPath("dag/gunbc/ci_spec.dag".to_string())
            )]
        );
    }

    #[test]
    fn decodes_filesystem_read_of_a_param_ref() {
        let ctx = ctx_for_decoding();
        let pattern = variant(
            &ctx,
            "PathPattern",
            "ParamRef",
            vec![("name", str_value("roster_path".to_string()))],
        );
        assert_eq!(
            decoded_carriers(&ctx, vec![fs_carrier(&ctx, pattern)]),
            vec![LiveReadCarrier::FilesystemReadPath(
                LiveReadPathPattern::ParamRef("roster_path".to_string())
            )]
        );
    }

    #[test]
    fn decodes_filesystem_read_of_an_unknown_path() {
        let ctx = ctx_for_decoding();
        let pattern = variant(&ctx, "PathPattern", "UnknownPath", vec![]);
        assert_eq!(
            decoded_carriers(&ctx, vec![fs_carrier(&ctx, pattern)]),
            vec![LiveReadCarrier::FilesystemReadPath(
                LiveReadPathPattern::UnknownPath
            )]
        );
    }

    #[test]
    fn decodes_a_module_declaration_facts_scan() {
        let ctx = ctx_for_decoding();
        let carrier = variant(
            &ctx,
            "LiveReadCarrier",
            "ModuleDeclarationFactsScan",
            vec![],
        );
        assert_eq!(
            decoded_carriers(&ctx, vec![carrier]),
            vec![LiveReadCarrier::ModuleDeclarationFactsScan]
        );
    }

    #[test]
    fn decodes_a_decl_facts_reflection() {
        let ctx = ctx_for_decoding();
        let carrier = variant(
            &ctx,
            "LiveReadCarrier",
            "DeclFactsReflection",
            vec![("home", str_value("v2.std.decl_index".to_string()))],
        );
        assert_eq!(
            decoded_carriers(&ctx, vec![carrier]),
            vec![LiveReadCarrier::DeclFactsReflection {
                home: "v2.std.decl_index".to_string()
            }]
        );
    }

    // The shape the old decoder silently accepted: a carrier that is not a variant at all. It must
    // refuse, because an unreadable carrier set intersects nothing and licenses a skip.
    #[test]
    fn a_non_variant_carrier_refuses_rather_than_decoding_to_nothing() {
        let ctx = ctx_for_decoding();
        let err = decode_live_read_selection_row(
            &ctx,
            &classified(&ctx, vec![str_value("v2.lens.module_graph".to_string())]),
        )
        .expect_err("a String carrier was accepted");
        assert!(
            err.contains("CarrierShapeUnexpected"),
            "refusal did not name the cause: {err}"
        );
    }

    #[test]
    fn an_unmodelled_carrier_variant_refuses() {
        let ctx = ctx_for_decoding();
        let carrier = variant(&ctx, "LiveReadCarrier", "SomeCarrierAddedLater", vec![]);
        let err = decode_live_read_selection_row(&ctx, &classified(&ctx, vec![carrier]))
            .expect_err("an unmodelled carrier variant was accepted");
        assert!(
            err.contains("CarrierVariantUnknown"),
            "refusal did not name the cause: {err}"
        );
    }

    // ---- the selection fold ---------------------------------------------------------------

    fn touched(paths: &[&str]) -> Vec<String> {
        paths.iter().map(|p| p.to_string()).collect()
    }

    #[test]
    fn a_literal_path_carrier_intersects_only_its_own_path() {
        let row = LiveReadSelectionRow::Classified(LiveReadClassification::RuntimeRead {
            carriers: vec![LiveReadCarrier::FilesystemReadPath(
                LiveReadPathPattern::LiteralPath("dag/gunbc/ci_spec.dag".to_string()),
            )],
        });
        assert!(row.touched_by(&touched(&["dag/gunbc/ci_spec.dag"])));
        // The whole point of preserving the literal: an unrelated diff does NOT select it. A
        // `runtime_read: bool` row could not express this and had to say true here.
        assert!(!row.touched_by(&touched(&["dag/gunbc/unrelated.dag"])));
    }

    #[test]
    fn param_unknown_and_scan_carriers_are_touched_by_any_nonempty_diff() {
        for carrier in [
            LiveReadCarrier::FilesystemReadPath(LiveReadPathPattern::ParamRef("p".to_string())),
            LiveReadCarrier::FilesystemReadPath(LiveReadPathPattern::UnknownPath),
            LiveReadCarrier::ModuleDeclarationFactsScan,
            LiveReadCarrier::DeclFactsReflection {
                home: "v2.std.decl_index".to_string(),
            },
        ] {
            let row = LiveReadSelectionRow::Classified(LiveReadClassification::RuntimeRead {
                carriers: vec![carrier.clone()],
            });
            assert!(
                row.touched_by(&touched(&["dag/gunbc/unrelated.dag"])),
                "{carrier:?} must be touched by any nonempty diff — its target is not narrowable"
            );
            assert!(
                !row.touched_by(&[]),
                "{carrier:?} must not be touched by an empty diff"
            );
        }
    }

    #[test]
    fn a_local_read_is_never_touched_and_a_refusal_always_is() {
        let local = LiveReadSelectionRow::Classified(LiveReadClassification::LocalRead);
        assert!(!local.touched_by(&touched(&["dag/gunbc/ci_spec.dag"])));
        let refused = LiveReadSelectionRow::Refused {
            cause: "partial subject".to_string(),
        };
        assert!(
            refused.touched_by(&[]),
            "a refusal must forbid a skip even on an empty diff — it is the absence of a \
             classification, not a classification of absence"
        );
    }
}

/// Per-file parse memo for `resolved_graph_from_sources_with_index`.
///
/// `annotation_diags` is `Some` when this entry was installed by a parse that ran
/// `admit_source_annotations`. `None` means an annotation-erasing `tokenize`
/// installed it (attribution). Via-index must still admit on `None`, and must
/// consume `Some` on every `ResolvedGraphMemoShare` — `handle_serve` resolves
/// `Memoize`, reads `compile_clean_diags`, and shares `process_shared_index`'s
/// cache. Gating re-admission on `Ephemeral` made admission depend on cache
/// state rather than source content.
#[derive(Clone)]
struct ParseCacheEntry {
    parse_result: Rc<v1_compiler_parse::ParseResult>,
    newline_index: Rc<NewlineIndex>,
    annotation_diags: Option<Rc<im::Vector<Rc<ErrorNode>>>>,
}

pub struct MultiEntryIndex {
    /// Opaque identity of THIS index, minted at construction (see `next_index_generation`).
    generation: u64,
    source_files: ModuleSourceIndex,
    module_graph_facts: ModuleGraphFactsLive,
    /// Per-index typed results, keyed by the typed-module CONTENT key
    /// (`std.interface_summary.typed_module_key`: module source hash ⊕ direct-import
    /// interface hashes ⊕ compiler identity) — never by authored module name. The
    /// content key is the soundness license for eviction (PR-β) and the S2b-ready
    /// backend shape (cross-entry-typed-module-memo-sketch.md §1, operator-signed
    /// 2026-07-16); within one process it also makes a same-name/different-file
    /// collision structurally unable to serve the wrong typecheck (the name-keyed
    /// store relied on `module_source_identity` failing loud instead).
    typed_module_cache:
        RefCell<std::collections::HashMap<String, Rc<v1_compiler_infer::TypecheckModuleResult>>>,
    /// Counted evictions from the host-budget-derived typed-cache entry cap (width=1
    /// drain accumulation lane). Each eviction is a typed, located diagnostic — never
    /// a silent widen (§5).
    typed_cache_evictions: Cell<u64>,
    /// Host-budget-derived typed-cache entry cap, sampled ONCE for this index's
    /// lifetime — a run-start fact, never re-read per insert. Re-deriving the cap
    /// from a live, host-shared signal (`/proc/meminfo MemAvailable`, the fallback
    /// when no private cgroup memory limit is discoverable) on every insert was the
    /// 2026-07-21 fleet OOM incident: the cap chased the host's real-time noise
    /// across every co-resident session, and each eviction's recompute-on-miss
    /// added the exact memory pressure the cap exists to relieve — a thrashing
    /// feedback loop, not a bound. `OnceCell` gives lazy single-sample semantics
    /// so index construction stays free of the governor read for callers that
    /// never touch the typed cache.
    typed_module_cache_cap: std::cell::OnceCell<usize>,
    /// Source-content hashes by file path, recorded in the parse loop (where the
    /// `SourceFile.content` is in hand) — the source-hash key term for
    /// `typed_module_content_key`. A reconcile of a module whose file never passed
    /// the parse loop is a fail-closed error, never a silently keyless entry.
    source_hash_by_file: RefCell<std::collections::HashMap<String, String>>,
    /// Per-index collision registry when `cross_worker_store` is absent.
    module_source_identity: RefCell<std::collections::HashMap<String, String>>,
    /// Cross-worker serde-byte transport when increment C is explicitly armed (tests / future Arc).
    cross_worker_store: Option<Arc<RwLock<SharedTypecheckCaches>>>,
    /// Per-index intern table — paired with `parse_cache` on this worker (never shared).
    intern_table: RefCell<Rc<InternTable>>,
    parse_cache: RefCell<std::collections::HashMap<String, ParseCacheEntry>>,
    normalize_diag_cache: RefCell<std::collections::HashMap<String, Rc<im::Vector<Rc<ErrorNode>>>>>,
    ownership_diag_cache: RefCell<std::collections::HashMap<String, Rc<im::Vector<Rc<ErrorNode>>>>>,
    /// The source roots this index was built from — the tree identities behind the
    /// per-tree bare census layers (a module's bare-name universe is its own tree).
    source_roots: Vec<String>,
    /// Parse-grade pool snapshot (every indexed module parsed once, with pool-wide
    /// newline indexes) — the shared input of the qualified fill and the per-tree
    /// bare layers below. Entry-independent, built once per process.
    pool_parse: RefCell<Option<Rc<PoolParse>>>,
    /// Whole-pool QUALIFIED-ONLY census layer (entries keyed by qualified name;
    /// empty global_bare/services), built once per process and underlaid beneath
    /// each entry's closure census (namespace-resolution-design.md §7.5: "fill =
    /// whole tree; policy gates lookup, never fill").
    pool_qualified_fill: RefCell<Option<Rc<SymbolIndex>>>,
    /// Per-source-root full census (bare + qualified + services) over that root's
    /// pool modules — the SAME-TREE bare layer underlaid beneath a module's closure
    /// census when it typechecks (bare = own tree; qualified = whole pool; cross-
    /// tree bare reach stays refused). Keyed by source root, built lazily.
    tree_bare_census: RefCell<std::collections::HashMap<String, Rc<SymbolIndex>>>,
    /// Whole-pool census (every pool module, both trees) — the LOADER's cross-
    /// tree fallback: a bare reference that misses the referencing file's own
    /// tree census resolves here so the provider still gets pulled into the
    /// closure (fill = whole tree). Same-tree resolution keeps priority — this
    /// is consulted only on an own-tree miss, so cross-tree homonyms cannot
    /// steal a same-tree name. Typecheck-side bare visibility is unchanged
    /// (closure census + own-tree underlay); the pulled provider becomes
    /// closure-visible, which is what serves the name at typecheck.
    pool_bare_census: RefCell<Option<Rc<SymbolIndex>>>,
    /// Memo: normalized entry path → name-derived closure sources. The bare-
    /// reference fixpoint (`extend_sources_to_both_closure_fixpoint`) is pure
    /// for a fixed pool; witnesses sharing an entry file within one floor worker
    /// reused the loader without this and re-paid the #6848 walk each time.
    entry_closure_sources: RefCell<HashMap<String, Vec<Rc<v1_compiler_compile::SourceFile>>>>,
    /// Per-pool precomputed bare/reference closure edges — built once per process,
    /// amortized across every entry's both-closure fixpoint walk.
    /// The live-read selection manifest for this index, built at most once. The memo keys on
    /// nothing because the index IS the key: a different index is a different object with its own
    /// generation and its own empty cell. A refusal is memoized too — recomputing a producer that
    /// already refused would only refuse again, more slowly.
    live_read_manifest: RefCell<Option<Result<Rc<LiveReadSelectionManifest>, String>>>,
    both_closure_edges: RefCell<Option<Rc<BothClosureEdgeIndex>>>,
    // Per-process subject-digest → resolved-graph share, the ReferenceTier in
    // front of the cross-process store (materialization-ladder tier ordering:
    // the share serves repeats, the store serves the process's FIRST touch of a
    // subject, and a store hit is INSTALLED here so every later demand takes the
    // reference). Always populated on first assembly — not gated on
    // GUNBC_RESOLVED_GRAPH_CACHE_DIR (the disk tier is opt-in separately).
    // Without the install-back, N same-subject resolves each retained an independent
    // graph — the reconcile_assembly per-entry rerun receipt (resolve-split #6535).
    resolved_graph_memo: RefCell<
        HashMap<
            String,
            (
                Rc<v1_compiler_compile::ResolvedGraph>,
                Rc<HashMap<String, Rc<NewlineIndex>>>,
                Rc<im::Vector<Rc<ErrorNode>>>,
            ),
        >,
    >,
    /// Schedule-derived per-module retention bookkeeping (v1-run-stability M2 — the
    /// retention keystone). Armed at the start of a private-index (`cross_worker_store
    /// == None`) discovery run from the schedule's per-entry closures, driven per
    /// entry-completion in `run_discovery_rows`. `None` when unarmed (Adaptive shared
    /// store, single-claim paths, tests): retention stays the pre-M2 process-lifetime
    /// hold, so the mechanism is strictly additive. Authority: modeled policy in
    /// `dag/gunbc/executor_schedule_retention.dag`, mirrored above.
    schedule_retention: RefCell<Option<ScheduleRetention>>,
}

pub fn new_shared_typecheck_caches() -> Arc<RwLock<SharedTypecheckCaches>> {
    shared_typecheck_store::new_shared_typecheck_caches()
}

pub use shared_typecheck_store::{
    reset_shared_typecheck_store_counters_for_test, shared_typecheck_store_counters_snapshot,
    SharedTypecheckStoreCounters,
};

pub fn build_multi_entry_index(source_roots: &[String]) -> MultiEntryIndex {
    new_multi_entry_index_shell(build_module_index(source_roots), source_roots, None)
}

/// Primary-precedence `MultiEntryIndex` — the index shape the compile-clean gate
/// uses (`--dependency-pool-index primary-precedence`: root[0] wins, later roots
/// fill only absent modules). Needed so `load_compile_clean_entry_sources` can run
/// the SAME both-closure fixpoint as the witness loader (`extend_with_bare_reference_closure`
/// requires the `MultiEntryIndex` for its per-tree bare census), dissolving the §3
/// closure-authority fork the two loaders' doc-comments each falsely claimed to be single.
fn build_multi_entry_index_primary_precedence(source_roots: &[String]) -> MultiEntryIndex {
    new_multi_entry_index_shell(
        build_module_index_primary_precedence(source_roots),
        source_roots,
        None,
    )
}

pub fn build_multi_entry_index_with_shared_caches(
    source_roots: &[String],
    cross_worker_store: Arc<RwLock<SharedTypecheckCaches>>,
) -> MultiEntryIndex {
    new_multi_entry_index_shell(
        build_module_index(source_roots),
        source_roots,
        Some(cross_worker_store),
    )
}

