/// The drop-attributable term names, in the order the decomposition reports them.
/// `source_files` is deliberately absent (see `drop_private_term_for_test`).
#[cfg(any(test, feature = "interp_test_witness"))]
pub fn drop_attributable_terms_for_test() -> &'static [&'static str] {
    &[
        "resolved_graph_memo",
        "typed_module_cache",
        "parse_cache",
        "pool_parse",
        "both_closure_edges",
        "pool_bare_census",
        "tree_bare_census",
        "pool_qualified_fill",
        "entry_closure_sources",
        "intern_table",
        "normalize_diag_cache",
        "ownership_diag_cache",
        "source_hash_by_file",
        "module_source_identity",
    ]
}

fn new_multi_entry_index_shell(
    source_files: ModuleSourceIndex,
    source_roots: &[String],
    cross_worker_store: Option<Arc<RwLock<SharedTypecheckCaches>>>,
) -> MultiEntryIndex {
    MultiEntryIndex {
        generation: next_index_generation(),
        source_files,
        module_graph_facts: build_module_graph_facts_live(source_roots),
        typed_module_cache: RefCell::new(std::collections::HashMap::new()),
        typed_cache_evictions: Cell::new(0),
        typed_module_cache_cap: std::cell::OnceCell::new(),
        source_hash_by_file: RefCell::new(std::collections::HashMap::new()),
        module_source_identity: RefCell::new(std::collections::HashMap::new()),
        cross_worker_store,
        intern_table: RefCell::new(seed_kernel_intern_names(empty_intern_table())),
        parse_cache: RefCell::new(std::collections::HashMap::new()),
        normalize_diag_cache: RefCell::new(std::collections::HashMap::new()),
        ownership_diag_cache: RefCell::new(std::collections::HashMap::new()),
        resolved_graph_memo: RefCell::new(HashMap::new()),
        schedule_retention: RefCell::new(None),
        source_roots: source_roots.to_vec(),
        pool_parse: RefCell::new(None),
        pool_qualified_fill: RefCell::new(None),
        tree_bare_census: RefCell::new(std::collections::HashMap::new()),
        pool_bare_census: RefCell::new(None),
        entry_closure_sources: RefCell::new(HashMap::new()),
        both_closure_edges: RefCell::new(None),
        live_read_manifest: RefCell::new(None),
    }
}

/// Monotone per-process index identity.
///
/// The manifest's subject must be minted by the thing that PRODUCED the facts, never handed in by
/// a caller. A caller-supplied string can be paired with facts from any workspace — the comparison
/// then proves only that two strings match, which is the shape of the question it was meant to
/// answer. A counter is opaque, unforgeable from outside, and distinguishes two indices built over
/// byte-identical source roots, which a content hash of the roots would not.
fn next_index_generation() -> u64 {
    static NEXT: AtomicU64 = AtomicU64::new(1);
    NEXT.fetch_add(1, Ordering::Relaxed)
}

/// Parse-grade pool snapshot: every indexed module's declaration heads plus the
/// pool-wide newline indexes, in deterministic (sorted module path) order.
/// Function bodies are stripped (shared marker only) — census consumers read
/// `module_items` / `local_binding_for_item`, never bodies.
struct PoolParse {
    /// Workspace-relative file path → census-head module node.
    nodes_by_file: Vec<(String, Rc<Node>)>,
    combined_si: Rc<HashMap<String, Rc<NewlineIndex>>>,
}

// Shared per-thread stand-in so stripped fn decls keep `body.is_some()` for
// `local_binding_for_item`'s fn discriminator. Loud-on-inference only:
// `ExprErrorKind::CensusHeadsBodyStripped` raises a hard diagnostic in `infer_expr`;
// it is NOT a complete guard against non-inference body-content reads (direct
// ExprData traversal, emit, node-count, etc.). `is_census_heads_fn_stand_in` and
// `census_heads_body_traversal_refusal` are dev-convenience query helpers, not the
// safety mechanism.
// 🟡 dissolve-on (B): `pool_nodes_by_file_consumers_must_not_descend_into_body` —
// standing test forbidding any `pool.nodes_by_file` consumer from non-inference body
// descent; lands the construction wall and retires `CensusHeadsBodyStripped` as a
// validation-only backstop.
const CENSUS_HEADS_FN_STAND_IN_NAME: &str = "^census_heads_fn_stand_in";

thread_local! {
    static STRIPPED_FN_BODY_MARKER: Rc<Node> = Rc::new(Node {
        name: CENSUS_HEADS_FN_STAND_IN_NAME.to_string(),
        span: no_span(),
        ident_span: None,
        children: empty_node_list(),
        connective: Connective::NoConnective,
        params: empty_node_list(),
        inferred: None,
        return_cardinality: Cardinality::Required,
        uses: empty_node_list(),
        body: None,
        transport: None,
        properties: empty_node_list(),
        type_annotation: None,
        is_self_recursive: false,
        has_non_tail_self_call: false,
        match_pattern: None,
        expr_data: Rc::new(ExprData::ExprError {
            kind: ExprErrorKind::CensusHeadsBodyStripped,
            message: "pool census heads-only: function body stripped — refuse to interpret"
                .to_string(),
        }),
        ident: None,
    });
}

fn stripped_fn_body_marker() -> Rc<Node> {
    STRIPPED_FN_BODY_MARKER.with(Rc::clone)
}

pub fn is_census_heads_fn_stand_in(node: &Rc<Node>) -> bool {
    node.name == CENSUS_HEADS_FN_STAND_IN_NAME
        || STRIPPED_FN_BODY_MARKER.with(|marker| Rc::ptr_eq(node, marker))
}

#[cfg(any(test, feature = "interp_test_witness"))]
pub fn census_heads_fn_stand_in_for_test() -> Rc<Node> {
    stripped_fn_body_marker()
}

#[cfg(any(test, feature = "interp_test_witness"))]
pub fn census_heads_module_node_for_test(module: Rc<Node>) -> Rc<Node> {
    census_heads_module_node(module)
}

fn census_heads_children(children: &Rc<im::Vector<Rc<Node>>>) -> Rc<im::Vector<Rc<Node>>> {
    Rc::new(
        children
            .iter()
            .cloned()
            .map(census_heads_module_item)
            .collect(),
    )
}

/// Fn-decl discriminator for heads-only shrink — must match `local_binding_for_item`'s
/// fn arm (`04_infer.dag`: `NoConnective && body.is_some() && transport.is_none()`).
fn census_heads_item_is_fn_decl(item: &Rc<Node>) -> bool {
    item.connective == Connective::NoConnective && item.body.is_some() && item.transport.is_none()
}

fn census_heads_module_item(item: Rc<Node>) -> Rc<Node> {
    let body = if census_heads_item_is_fn_decl(&item) {
        Some(stripped_fn_body_marker())
    } else {
        None
    };
    let children = if item.children.is_empty() {
        item.children.clone()
    } else {
        census_heads_children(&item.children)
    };
    Rc::new(Node {
        name: item.name.clone(),
        span: item.span.clone(),
        ident_span: item.ident_span.clone(),
        children,
        connective: item.connective.clone(),
        params: item.params.clone(),
        inferred: item.inferred.clone(),
        return_cardinality: item.return_cardinality.clone(),
        uses: empty_node_list(),
        body,
        transport: item.transport.clone(),
        properties: item.properties.clone(),
        type_annotation: item.type_annotation.clone(),
        is_self_recursive: item.is_self_recursive,
        has_non_tail_self_call: item.has_non_tail_self_call,
        match_pattern: None,
        expr_data: Rc::new(ExprData::NoExprData),
        ident: item.ident.clone(),
    })
}

fn census_heads_module_node(module: Rc<Node>) -> Rc<Node> {
    Rc::new(Node {
        name: module.name.clone(),
        span: module.span.clone(),
        ident_span: module.ident_span.clone(),
        children: Rc::new(
            module_items(module.clone())
                .iter()
                .cloned()
                .map(census_heads_module_item)
                .collect(),
        ),
        connective: module.connective.clone(),
        params: module.params.clone(),
        inferred: module.inferred.clone(),
        return_cardinality: module.return_cardinality.clone(),
        uses: empty_node_list(),
        body: None,
        transport: module.transport.clone(),
        properties: module.properties.clone(),
        type_annotation: module.type_annotation.clone(),
        is_self_recursive: module.is_self_recursive,
        has_non_tail_self_call: module.has_non_tail_self_call,
        match_pattern: None,
        expr_data: Rc::new(ExprData::NoExprData),
        ident: module.ident.clone(),
    })
}

// Once-per-node resolve receipt (union-resolve minimum-upper-bound contract, §6.2 of
// many module typechecks were actually COMPUTED (cache misses). When every consumer of
// the process shares one typed_module_cache, this stays ≤ the distinct module count of
// the process union.
static TYPECHECK_COMPUTE_COUNT: AtomicUsize = AtomicUsize::new(0);

// Union-resolve receipt tests reset/read process-wide oracles (`TYPECHECK_COMPUTE_COUNT`,
// repeated-typecheck attribution probe state). `cargo test` runs `#[test]` fns in parallel
// by default — serialize those oracles (not production use).
static UNION_RESOLVE_PROCESS_RECEIPT_LOCK: Mutex<()> = Mutex::new(());

/// Run a counter-based receipt test with exclusive access to `TYPECHECK_COMPUTE_COUNT`.
pub fn with_typecheck_compute_count_receipt<R>(f: impl FnOnce() -> R) -> R {
    let _guard = UNION_RESOLVE_PROCESS_RECEIPT_LOCK
        .lock()
        .expect("union resolve process receipt lock poisoned");
    f()
}

pub fn typecheck_compute_count() -> usize {
    TYPECHECK_COMPUTE_COUNT.load(Ordering::SeqCst)
}

pub fn reset_typecheck_compute_count() {
    TYPECHECK_COMPUTE_COUNT.store(0, Ordering::SeqCst);
}

fn bump_typecheck_compute_count() {
    TYPECHECK_COMPUTE_COUNT.fetch_add(1, Ordering::SeqCst);
}

fn shared_caches_read<'a>(
    lock: &'a Arc<RwLock<SharedTypecheckCaches>>,
) -> Result<std::sync::RwLockReadGuard<'a, SharedTypecheckCaches>, String> {
    lock.read()
        .map_err(|e| format!("shared typecheck caches lock poisoned: {e}"))
}

fn shared_caches_write<'a>(
    lock: &'a Arc<RwLock<SharedTypecheckCaches>>,
) -> Result<std::sync::RwLockWriteGuard<'a, SharedTypecheckCaches>, String> {
    lock.write()
        .map_err(|e| format!("shared typecheck caches lock poisoned: {e}"))
}

/// The typed-module content key for `resolved` — the Rust realization of
/// `std.interface_summary.typed_module_key` over the live store's inputs
/// (cross-entry-typed-module-memo-sketch.md §1, operator-signed 2026-07-16):
///
///   key = typed_module_key(module_key(source_hash, direct-import interface hashes),
///                          compiler identity)
///
/// - `source_hash` was recorded by `note_source_hash` in the parse loop; a module whose
///   file never passed that loop REFUSES (fail-closed) — the key never silently drops a
///   term.
/// - Direct-import interface hashes come from `interface_hash_by_name`, filled in
///   dependency order as import results are obtained (hit or computed); a missing import
///   hash likewise refuses — it would mean the schedule dispatched a dependent before
///   its import. The interface hash is the Inc-B `ModuleInterface.summary.interface_hash`
///   (v0 fingerprint; its declared-weak grain and upgrade trigger live at
///   `src/v1/04_infer.dag` `interface_signature_fingerprint_v0_note`).
/// - Compiler identity is `resolved_graph_cache::transform_content_digest` — the same
///   single authority the resolved-graph subject digest consumes (§3: one concept, one
///   authority; a seed rebuild invalidates both stores through one term).
fn closure_path_to_authored_name_map<'a>(
    closure_modules: &[Rc<v1_compiler_resolve::ResolvedModule>],
    closure_names: &'a [String],
) -> HashMap<String, &'a str> {
    closure_modules
        .iter()
        .zip(closure_names.iter())
        .map(|(resolved, name)| {
            (
                workspace_relative_repo_path(&resolved.module.span.file),
                name.as_str(),
            )
        })
        .collect()
}

fn typed_key_dependency_hash_not_ready(err: &str) -> bool {
    err.contains("typed-module content key refused:") && err.contains("has no interface hash yet")
}

fn typed_module_content_key(
    index: &MultiEntryIndex,
    resolved: &Rc<v1_compiler_resolve::ResolvedModule>,
    mod_name: &str,
    interface_hash_by_name: &std::collections::HashMap<String, String>,
    closure_names: &std::collections::HashSet<&str>,
    closure_path_to_authored_name: &HashMap<String, &str>,
    include_reference_derived_term: bool,
) -> Result<String, String> {
    let file = &resolved.module.span.file;
    let source_hash = index
        .source_hash_by_file
        .borrow()
        .get(file)
        .cloned()
        .ok_or_else(|| {
            format!(
                "typed-module content key refused: no source hash recorded for '{file}' \
                 (module '{mod_name}') — every reconciled module must pass the parse loop \
                 in this process before its typed result is keyed"
            )
        })?;
    let mut import_hashes: im::Vector<String> = im::Vector::new();
    for import in resolved.resolved_imports.iter() {
        let hash = interface_hash_by_name
            .get(&import.module_path)
            .cloned()
            .ok_or_else(|| {
                format!(
                    "typed-module content key refused: direct import '{}' of module \
                     '{mod_name}' has no interface hash yet — imports must be typechecked \
                     (or cache-served) before their dependents are keyed",
                    import.module_path
                )
            })?;
        import_hashes.push_back(hash);
    }
    // Stripped (no `import` line) modules resolve their dependencies through the corpus-wide
    // bare-name census instead — real cross-module dependencies that `resolved_imports` above
    // cannot see (PR #6848, namespace wave 1: 815/2301 modules). Without this term a stripped
    // dependent's content key is invariant under a provider's export-surface change, which is
    // cache impurity (DESIGN §5/recurring-failure-modes: key on declared-input content). The
    // reference-only targets come from the SAME `selection_adjacency` authority affected-set
    // selection already consumes (DESIGN §3: no second edge producer), strict-tier only
    // (Qualified + UniqueBare — an AmbiguousBare homonym is not a declared dependency).
    let file_rel = workspace_relative_repo_path(file);
    if include_reference_derived_term {
        for dep_path in index
            .module_graph_facts
            .reference_only_direct_import_paths(&file_rel)
        {
            // The loader is deliberately import-only (build_module_graph_facts_live_uncached):
            // selection_adjacency's reference-derived edges are census-wide and tuned for the
            // affected-set consumer's tolerance of an over-connected false positive, not as a
            // hard dependency authority. A target this resolve's closure never loaded cannot
            // have influenced this compile's typed result, so it is not a term in this key —
            // mirroring module_schedule_batches's existing dangling-edge tolerance, not an
            // absorbing fallback (DESIGN §5): the exclusion is structurally forced, not a
            // substitute for a precision we failed to compute.
            let Some(dep_authored) = closure_path_to_authored_name.get(dep_path.as_str()) else {
                continue;
            };
            if !closure_names.contains(dep_authored) {
                continue;
            }
            let hash = interface_hash_by_name
                .get(*dep_authored)
                .cloned()
                .ok_or_else(|| {
                    format!(
                        "typed-module content key refused: reference-derived dependency \
                     '{dep_authored}' (path '{dep_path}') of stripped module '{mod_name}' has \
                     no interface hash yet — its bare-name dependencies must be typechecked \
                     (or cache-served) before it is keyed"
                    )
                })?;
            import_hashes.push_back(hash);
        }
    }
    fn structural_from_wire(hex: String) -> Rc<crate::std_content_hash::Fnv1a64Structural> {
        fnv1a64_structural_hex_digest(hex).unwrap_or_else(|| {
            panic!("typed-module content key refused: reconcile digest is not a valid fnv1a64 structural wire form")
        })
    }
    Ok(typed_module_key(
        module_key(
            structural_from_wire(source_hash),
            Rc::new(
                import_hashes
                    .iter()
                    .cloned()
                    .map(|h| structural_from_wire(h))
                    .collect(),
            ),
        ),
        structural_from_wire(transform_content_digest()),
    )
    .digest
    .clone())
}

/// Record `mod_name`'s interface hash for downstream key derivation (one entry per
/// module per reconcile; the interface is a pure projection of the typed result).
fn note_interface_hash(
    interface_hash_by_name: &mut std::collections::HashMap<String, String>,
    mod_name: &str,
    tc_result: &Rc<v1_compiler_infer::TypecheckModuleResult>,
) {
    interface_hash_by_name.insert(
        mod_name.to_string(),
        tc_result
            .typed
            .interface
            .summary
            .interface_hash
            .digest
            .clone(),
    );
}

// ─────────────────────────────────────────────────────────────────────────────
// Schedule-derived retention (v1-run-stability throughline M2 — the retention
// keystone). The executor holds the WHOLE batch schedule before it runs a witness,
// so per-module retention can be EXACT: refcount each module's retained typed state
// by the number of remaining scheduled entries whose closure reaches it, and drop it
// the moment that count hits zero. The policy is DERIVED from declared inputs (the
// schedule × the module-graph closure) — no threshold, no recency heuristic, no GC.
//
// Authority is the modeled carrier `dag/gunbc/executor_schedule_retention.dag`; the
// consts below MIRROR it and `schedule_retention_policy_matches_modeled_authority`
// (this module's tests) reds on drift — the `extdeps.realization.resolved_graph`
// `SizeBounded`-cap lockstep pattern applied to a policy instead of a number.
//
// Correctness license (why evicting typed state can never yield a wrong verdict):
// the typed-module cache is CONTENT-keyed, so a later entry that reaches an evicted
// module simply recomputes it (cache miss → identical result). The interpreter never
// reads typed envs at eval (#5892: floor GREEN with envs evicted, RED with items
// evicted). Eviction therefore frees bytes without touching meaning; the only risk
// it must guard is a SCHEDULE-DERIVATION defect, which it refuses loudly (below).
// ─────────────────────────────────────────────────────────────────────────────

/// Single-authority mirror of the modeled policy fact
/// `gunbc.executor_schedule_retention.schedule_retention_tunable_count`
/// (`dag/gunbc/executor_schedule_retention.dag`). Zero by construction: the retention
/// rule is the schedule's remaining demand, full stop. A nonzero here would be a
/// smuggled heuristic (DESIGN §4/§5) and must move BOTH surfaces and face review.
/// Kept in lockstep by `schedule_retention_policy_matches_modeled_authority`.
const SCHEDULE_RETENTION_TUNABLE_COUNT: i64 = 0;

/// Mirror of `gunbc.executor_schedule_retention`
/// `schedule_retention_entry_line_asserts_execution` (false): the per-entry drain line
/// witnesses the SCHEDULE PASSING an entry, never that the entry was selected or run —
/// `index_arm_schedule_retention` walks every discovered row before any predict-skip.
/// Kept in lockstep by `schedule_retention_policy_matches_modeled_authority`.
const SCHEDULE_RETENTION_ENTRY_LINE_ASSERTS_EXECUTION: bool = false;

/// Mirror of `gunbc.executor_schedule_retention`
/// `schedule_retention_release_and_eviction_counted_apart` (true): `schedule_releases`
/// counts refcount-zero releases, `schedule_evictions` counts only the releases that
/// actually dropped cached state. Discriminating RED:
/// `unreconciled_module_releases_without_evicting`.
const RELEASE_AND_EVICTION_COUNTED_APART: bool = true;

/// Measurement control (RED #1): with `GUNBC_SCHEDULE_RETENTION_EVICT=0` the schedule
/// still ARMS and COUNTS (refcounts, RetentionUnknown, decrement-underflow refusals)
/// but drops nothing — reproducing today's pegged peak so the mechanism's effect on
/// RSS is measurable both directions. This is NOT a §5 escape hatch: it bypasses no
/// fail-closed refusal (RetentionUnknown still retains-and-counts; a schedule
/// underflow still refuses) — it only chooses whether the freed-by-schedule bytes are
/// actually released, the retain-all pole being exactly the pre-M2 behavior.
fn schedule_retention_evict_enabled() -> bool {
    !matches!(
        std::env::var("GUNBC_SCHEDULE_RETENTION_EVICT")
            .ok()
            .as_deref(),
        Some("0") | Some("false") | Some("off")
    )
}

/// The cache keys one module holds in the process-shared `MultiEntryIndex`, recorded
/// as the module reconciles so eviction drops exactly its per-module state — never a
/// head (the whole-pool parse snapshot and census layers are not per-module state and
/// are never recorded here, so `schedule_retention_heads_stay_resident` holds by
/// construction).
#[derive(Default, Clone)]
struct ModuleCacheKeys {
    /// Content keys under which this module's typed result lives in `typed_module_cache`.
    typed_keys: HashSet<String>,
    /// Raw `span.file` keys under which this module lives in the parse / normalize-diag
    /// / ownership-diag / source-hash caches (all keyed by the same raw file path).
    raw_files: HashSet<String>,
}

/// One entry-completion's eviction decision — applied to the index caches by the
/// caller (this struct owns no cache handles, so it stays a pure, unit-testable
/// bookkeeper; the RED controls exercise it in isolation).
///
/// RELEASE and EVICTION are separate facts and are counted separately. A module is
/// RELEASED when its refcount reaches zero (no remaining scheduled entry reaches it);
/// it is EVICTED only when that release actually dropped recorded cache state. The two
/// diverge on every run where an armed module was never reconciled — the ordinary case,
/// since arming spans the whole discovered roster while the affected set resolves a
/// subset. Counting the release as an eviction overstated the mechanism by the whole
/// unresolved population (a live receipt read `schedule_evictions=2200` against
/// `modules_refcounted=2200` and `typed_cache_peak=883`: it claimed to have evicted
/// every module it had ever heard of, ~2.5x the modules that were ever cached).
#[derive(Default, Debug, PartialEq, Eq)]
pub struct ScheduleEvictionBatch {
    pub typed_keys: Vec<String>,
    pub raw_files: Vec<String>,
    /// Module names whose refcount reached zero this step — released, whether or not
    /// any cache state existed to drop (for the located receipt line).
    pub released_modules: Vec<String>,
    /// The subset of `released_modules` that actually dropped recorded cache keys —
    /// the only names for which state left a cache. Always a subset, never equal by
    /// construction.
    pub evicted_modules: Vec<String>,
}

/// Schedule-derived per-module retention bookkeeping (pure). Refcount is keyed by
/// REPO-RELATIVE MODULE PATH — the identity `selection_closure_live_paths_with_facts`
/// (arming, a cheap prebuilt-adjacency BFS) and `workspace_relative_repo_path`
/// (reconcile's `decl_file`) both produce. A path-form mismatch between those two —
/// the only latent hazard — degrades to "retain + count as RetentionUnknown", never
/// to a wrong verdict (proven aligned on a live index by
/// `schedule_eviction_end_to_end_on_real_index`).
pub struct ScheduleRetention {
    /// module path → remaining scheduled entries whose closure reaches it.
    refcount: std::collections::HashMap<String, usize>,
    /// entry path → the closure module paths it reaches (stored at arm time so the
    /// per-entry decrement uses the SAME paths arming counted).
    entry_closures: std::collections::HashMap<String, Vec<String>>,
    /// module path → its recorded cache keys (filled as modules reconcile; a cache
    /// hit re-records idempotently so a module first cached under an earlier entry
    /// still carries its keys when its refcount finally reaches zero).
    cache_keys: std::collections::HashMap<String, ModuleCacheKeys>,
    /// names already counted as RetentionUnknown (cached but reachability-uncomputable)
    /// — counted once, retained forever (never evicted).
    unknown_counted: HashSet<String>,
    /// Modules whose refcount reached zero (released). NOT an eviction count: a module
    /// the run never reconciled has no cache state to drop, so its release frees nothing.
    schedule_releases: u64,
    /// Modules whose release actually dropped recorded cache keys — the honest measure
    /// of state this mechanism removed.
    schedule_evictions: u64,
    retention_unknown: u64,
    /// Assembled `ResolvedGraph`s dropped from `resolved_graph_memo` on entry completion
    /// (Fact #4): each strong-`Rc`-pins the very `TypedModule`s per-module eviction drops,
    /// so without this the module bytes never free ("strong Rc pins from elsewhere").
    resolved_graph_evictions: u64,
    /// Measurement pole (RED #1): false ⇒ compute everything, drop nothing.
    evict_enabled: bool,
}

impl ScheduleRetention {
    /// Arm from each DISTINCT scheduled entry's closure module names. `refcount[name]`
    /// becomes the count of entries whose closure contains `name`. Entries whose
    /// closure could not be computed are simply absent — their modules become
    /// `RetentionUnknown` (retained + counted) at reconcile, the fail-closed arm.
    pub fn armed(per_entry: Vec<(String, Vec<String>)>, evict_enabled: bool) -> Self {
        let mut refcount: std::collections::HashMap<String, usize> =
            std::collections::HashMap::new();
        let mut entry_closures: std::collections::HashMap<String, Vec<String>> =
            std::collections::HashMap::new();
        for (entry, names) in per_entry {
            for name in &names {
                *refcount.entry(name.clone()).or_insert(0) += 1;
            }
            // Last distinct occurrence wins; rows are grouped by entry so an entry
            // appears once, but be robust to a repeat by keeping the widest closure.
            entry_closures
                .entry(entry)
                .and_modify(|existing| {
                    if names.len() > existing.len() {
                        *existing = names.clone();
                    }
                })
                .or_insert(names);
        }
        ScheduleRetention {
            refcount,
            entry_closures,
            cache_keys: std::collections::HashMap::new(),
            unknown_counted: HashSet::new(),
            schedule_releases: 0,
            schedule_evictions: 0,
            retention_unknown: 0,
            resolved_graph_evictions: 0,
            evict_enabled,
        }
    }

    /// Record a module's cache keys as it reconciles (hit or miss; idempotent). A
    /// module whose name the arming never reached is a provenance gap: count it ONCE
    /// as `RetentionUnknown` and retain it — never silently drop, never widen to
    /// retain-everything (that absorbing fallback is the §5 review-reject).
    pub fn record_module(&mut self, name: &str, typed_key: &str, raw_file: &str) {
        if !self.refcount.contains_key(name) && self.unknown_counted.insert(name.to_string()) {
            self.retention_unknown += 1;
        }
        let entry = self.cache_keys.entry(name.to_string()).or_default();
        if !typed_key.is_empty() {
            entry.typed_keys.insert(typed_key.to_string());
        }
        if !raw_file.is_empty() {
            entry.raw_files.insert(raw_file.to_string());
        }
    }

    /// One scheduled entry finished: decrement each of its closure names, collect the
    /// names that reached zero (no remaining entry can read them) with their recorded
    /// cache keys for the caller to drop. A decrement of a name already at zero means a
    /// scheduled entry demands state the refcount said was fully consumed — a
    /// schedule-derivation defect — and REFUSES, typed and located (never a silent
    /// wrong verdict against evicted state). `RetentionUnknown` names carry no refcount
    /// entry, so they are never decremented and never evicted.
    pub fn entry_completed(&mut self, entry: &str) -> Result<ScheduleEvictionBatch, String> {
        let names = match self.entry_closures.get(entry) {
            Some(names) => names.clone(),
            None => return Ok(ScheduleEvictionBatch::default()),
        };
        self.decrement_closure(entry, &names)
    }

    /// Test injection for RED #3: run the decrement over an EXPLICIT closure, so a
    /// synthetic corruption (an entry reaching a module the arming under-counted) can
    /// exercise the underflow refusal — a state the consistent stored-closure path
    /// cannot reach in production (refcount is derived from the same closures it
    /// decrements), which is the whole point: the wall is unreachable by construction
    /// and refuses if a future refactor ever breaches it.
    #[cfg(test)]
    pub fn force_entry_completed_for_test(
        &mut self,
        entry: &str,
        names: &[String],
    ) -> Result<ScheduleEvictionBatch, String> {
        self.decrement_closure(entry, names)
    }

    fn decrement_closure(
        &mut self,
        entry: &str,
        names: &[String],
    ) -> Result<ScheduleEvictionBatch, String> {
        let mut batch = ScheduleEvictionBatch::default();
        for name in names {
            let name = name.clone();
            let Some(rc) = self.refcount.get_mut(&name) else {
                // Not refcounted (RetentionUnknown or never armed): retained.
                continue;
            };
            if *rc == 0 {
                return Err(format!(
                    "SCHEDULE-RETENTION REFUSAL cause=RefcountUnderflow module='{name}' \
                     entry='{entry}' — a scheduled entry's closure reaches a module whose \
                     retention refcount was already zero (its state may have been evicted). \
                     The schedule derivation under-counted this module's demand; refusing \
                     rather than serving a verdict against missing state (DESIGN §5)."
                ));
            }
            *rc -= 1;
            if *rc == 0 {
                // Keep the (name → 0) entry resident rather than removing it: a later
                // decrement of an under-counted module then hits the `*rc == 0` arm
                // above and REFUSES, instead of silently reading as "never armed". The
                // map is bounded by module count, so retaining zeros is free.
                if self.evict_enabled {
                    // Release and eviction are counted apart. A module the run never
                    // reconciled carries no recorded keys, so its release drops nothing
                    // — counting it as an eviction is a claim about freed state that no
                    // cache can corroborate.
                    let mut dropped_state = false;
                    if let Some(keys) = self.cache_keys.remove(&name) {
                        dropped_state = !keys.typed_keys.is_empty() || !keys.raw_files.is_empty();
                        batch.typed_keys.extend(keys.typed_keys);
                        batch.raw_files.extend(keys.raw_files);
                    }
                    self.schedule_releases += 1;
                    if dropped_state {
                        self.schedule_evictions += 1;
                        batch.evicted_modules.push(name.clone());
                    }
                    batch.released_modules.push(name);
                }
            }
        }
        Ok(batch)
    }

    /// Modules released (refcount reached zero). Bounded above by the armed module
    /// count and, at run end, equal to it — which is exactly why it is not an
    /// eviction measure and never labelled as one.
    pub fn schedule_releases(&self) -> u64 {
        self.schedule_releases
    }
    /// Modules whose release actually dropped recorded cache state.
    pub fn schedule_evictions(&self) -> u64 {
        self.schedule_evictions
    }
    pub fn retention_unknown(&self) -> u64 {
        self.retention_unknown
    }
    pub fn resolved_graph_evictions(&self) -> u64 {
        self.resolved_graph_evictions
    }
    /// The eviction switch this retention was armed with (false =
    /// `GUNBC_SCHEDULE_RETENTION_EVICT=0`, the retain-all measurement pole). Consumers
    /// outside the bookkeeper — the index's resolved-graph pin drop — gate on it so the
    /// pole retains resolved graphs too, not just the per-module caches (D0.4: the pre-M2
    /// baseline was invalid because it kept dropping graphs unconditionally).
    pub fn evict_enabled(&self) -> bool {
        self.evict_enabled
    }
    pub fn note_graph_eviction(&mut self) {
        self.resolved_graph_evictions += 1;
    }
    /// Number of distinct modules the arming refcounted — for the unconditional
    /// ARMED receipt line.
    pub fn refcount_len(&self) -> usize {
        self.refcount.len()
    }
}

/// Arm schedule-derived retention over a discovery run's WHOLE schedule (`rows` = every
/// scheduled entry's rows). Called ONCE by the drain caller (Serial: the single run; Adaptive
/// width=1: before the entry-group loop) so refcounts span the whole batch and a shared module
/// survives until its last consumer — NOT per `run_discovery_rows` call, which would hand the
/// Adaptive inline drain a one-entry schedule per group (refcount 1 on the whole closure → the
/// entries=1 cold-recompute churn). Only the private index path (`cross_worker_store == None`)
/// arms — the serial + adaptive-width-1 inline drains that share the long-lived process index
/// whose typed mass this bounds. The Adaptive plural/shared-store worker path keeps its current
/// behavior (typed results live in the byte store whose scheduled eviction is the PR-β
/// `SpacePacked` follow-on) — a declared, typed frontier, never a silent widen. A per-entry
/// closure that cannot be computed is skipped (its modules become counted `RetentionUnknown` at
/// reconcile), so arming never fails the run.
fn index_arm_schedule_retention(index: &MultiEntryIndex, rows: &[DiscoveryRow]) {
    if index.cross_worker_store.is_some() {
        return;
    }
    let mut per_entry: Vec<(String, Vec<String>)> = Vec::new();
    let mut seen: HashSet<&str> = HashSet::new();
    for row in rows {
        if !seen.insert(row.entry.as_str()) {
            continue;
        }
        // Arm from the LOADER's EXACT closure — `load_sources_for_entry_with_pool`, the
        // same function the discovery reconcile path runs (`resolve_entry_with_parse_cache`).
        // This is the ONE closure authority the arming and the loader now share (D0.3 /
        // the #6985 Class-B root, third appearance): the prior CHEAP
        // `selection_closure_live_paths_with_facts` walked only `selection_adjacency`
        // (import edges + strict reference edges for import-LESS files), so it OMITTED
        // modules the loader reaches via qualified-projection references emitted by
        // import-BEARING files. Such a module, being present in some OTHER entry's global
        // refcount, was counted neither `RetentionUnknown` nor re-evicted after it was
        // re-cached on load — an invisible resident leak. Consuming the loader's own output
        // makes the armed closure ⊇ the reconciled set BY CONSTRUCTION, not by two closures
        // happening to agree (the doc's "name the one closure authority, don't add a third
        // adjacency"). Cost is neutral, not the front-load the old comment feared: the pool
        // loader MEMOIZES into `entry_closure_sources`, so this pre-load is exactly what
        // discovery would compute and is reused on the entry's resolve, never doubled. Keyed
        // by `workspace_relative_repo_path(&sf.path)` — the identical form the reconcile
        // record site derives from `resolved.module.span.file` (`decl_file`), so refcount
        // keys and record keys still coincide. A closure that cannot be loaded is skipped:
        // its modules become counted `RetentionUnknown` at reconcile (retained — §5
        // fail-closed), so arming still never fails the run.
        let paths = match load_sources_for_entry_with_pool(index, &row.entry) {
            Ok(sources) => sources
                .iter()
                .map(|sf| workspace_relative_repo_path(&sf.path))
                .collect::<Vec<String>>(),
            Err(_) => continue,
        };
        per_entry.push((row.entry.clone(), paths));
    }
    let evict_enabled = schedule_retention_evict_enabled();
    let entries = per_entry.len();
    if !evict_enabled {
        // Loud, once per armed run: an accidentally-set env must not silently revert the
        // M2 memory win in CI. Without this line the receipt's `schedule_evictions=0` is
        // the only tell, and a zero reads as "nothing to evict" rather than "eviction off".
        eprintln!(
            "[floor-drain] SCHEDULE-RETENTION EVICTION DISABLED \
             (GUNBC_SCHEDULE_RETENTION_EVICT=0): arming + counting only, dropping NOTHING — \
             the retain-all measurement pole (pre-M2 process-lifetime retention). \
             schedule_evictions will be 0 BY CONSTRUCTION; unset the env to restore eviction."
        );
    }
    let sr = ScheduleRetention::armed(per_entry, evict_enabled);
    // Unconditional ARMED receipt: proves schedule-derived retention is LIVE on this run,
    // so a later `schedule_evictions=0` reads as "shared closure held resident" rather
    // than "never armed" (the private-index serial regime is the only one that arms).
    // The legend is part of the receipt because the per-entry lines below are otherwise
    // read as an execution log: they are not one, and `discovered_entries` says why —
    // arming walks the DISCOVERED roster, before selection decides anything.
    eprintln!(
        "[floor-drain] schedule-retention ARMED: discovered_entries={entries} \
         modules_refcounted={} evict_enabled={evict_enabled} \
         (legend: a `schedule_passed_entry=` line below marks the schedule moving past an \
         entry — discovery + arming only; it does NOT mean the entry was selected or run. \
         `released_modules` = refcount reached zero; `evicted_modules` = the subset that \
         actually dropped cached state.)",
        sr.refcount_len()
    );
    *index.schedule_retention.borrow_mut() = Some(sr);
}

/// Record a reconciled module's cache keys with the armed schedule retention (no-op
/// when unarmed). Called from the reconcile loop where the authored name, content
/// key, and raw file are all in hand.
fn index_record_schedule_module(
    index: &MultiEntryIndex,
    name: &str,
    typed_key: &str,
    raw_file: &str,
) {
    if let Some(sr) = index.schedule_retention.borrow_mut().as_mut() {
        sr.record_module(name, typed_key, raw_file);
    }
}

/// Kept so `gunbc.observation_emit_census` roster hygiene cannot go stale after the
/// raw `[typecheck-attribution]` key=value shape dissolves into the observation projection.
#[allow(dead_code)]
pub const TYPECHECK_ATTRIBUTION_CENSUS_MARKER: &str = "[typecheck-attribution]";

/// Kept so `gunbc.observation_emit_census` roster hygiene cannot go stale after the
/// raw `[measurement] … bytes (VmHWM)` dump dissolves into `ci_measurement_rss_line`.
#[allow(dead_code)]
pub const MEASUREMENT_CENSUS_MARKER: &str = "[measurement]";

const MEASUREMENT_UNREADABLE_CAUSE: &str = "no /proc/self/status";

fn measurement_human_bytes(bytes: u64) -> String {
    // Mirror of ci_gibibyte_tenths: (bytes * 10) / gibibyte_scale_factor_bytes (2^30).
    let tenths = (bytes.saturating_mul(10)) / 1_073_741_824;
    format!("{}.{} GiB", tenths / 10, tenths % 10)
}

/// Mirror of `gunbc.observation_seed_render.seed_peak_rss_line` —
/// `ci_measurement_rss_line ∘ ci_render_line`. Identity-first label, human GiB.
/// When `rss_bytes` is `None`, `unreadable_cause` names the MeasuredUnavailable cause
/// (seed default: `no /proc/self/status`).
pub fn render_peak_rss_line_mirror(label: &str, rss_bytes: Option<u64>, emoji: bool) -> String {
    render_peak_rss_line_mirror_with_cause(label, rss_bytes, MEASUREMENT_UNREADABLE_CAUSE, emoji)
}

pub fn render_peak_rss_line_mirror_with_cause(
    label: &str,
    rss_bytes: Option<u64>,
    unreadable_cause: &str,
    emoji: bool,
) -> String {
    let _ = MEASUREMENT_CENSUS_MARKER;
    let glyph = if emoji { "🕐" } else { "◷" };
    let rss = match rss_bytes {
        Some(b) => measurement_human_bytes(b),
        None => format!("unreadable ({unreadable_cause})"),
    };
    format!("{glyph} {label} — {rss}")
}

const TYPECHECK_MINUTE_SWITCH_SECONDS: u64 = 90;

fn typecheck_emoji() -> bool {
    std::env::var("GITHUB_ACTIONS").as_deref() == Ok("true")
}

fn typecheck_human_duration(ms: u64) -> String {
    if ms < 1_000 {
        format!("{ms}ms")
    } else if ms < TYPECHECK_MINUTE_SWITCH_SECONDS * 1_000 {
        format!("{} seconds", ms / 1_000)
    } else {
        format!("{} minutes", ms / 60_000)
    }
}

/// Mirror of `gunbc.observation_seed_render.typecheck_begin_line` —
/// leaf text is `typecheck <module>` (ModuleSegment + PhaseSegment).
pub fn render_typecheck_begin_line_mirror(module_path: &str, emoji: bool) -> String {
    let glyph = if emoji { "🔄" } else { "◐" };
    format!("{glyph} started typecheck {module_path}")
}

/// Mirror of `gunbc.observation_seed_render.typecheck_concluded_line`.
pub fn render_typecheck_concluded_line_mirror(
    module_path: &str,
    elapsed_ms: u64,
    emoji: bool,
) -> String {
    let glyph = if emoji { "✅" } else { "✓" };
    format!(
        "{glyph} typecheck {module_path} done in {}",
        typecheck_human_duration(elapsed_ms)
    )
}

/// Snapshot of the floor's active-batch progress, sampled by the detached
/// floor-memory heartbeat thread. Armed only when `entry_total` is known and
/// non-zero — never a fabricated 0-of-0 (observation law 2 / §5).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct HeartbeatFeedSnapshot {
    pub batch_index: u64,
    pub batch_label: String,
    pub entry_done: u64,
    pub entry_total: u64,
}

struct HeartbeatFeedState {
    batch_index: u64,
    batch_label: String,
    /// `None` while a discovery batch has entered but its roster entry-count is
    /// not yet known — the heartbeat thread skips emit until this is `Some(n>0)`.
    entry_total: Option<u64>,
    entry_done: AtomicU64,
}

/// Process-wide feed the floor-memory heartbeat samples. Updated at batch-enter
/// (label + total when known) and at each `index_schedule_entry_completed` (and
/// SingleClaim completion) — the existing per-entry point, never a parallel counter.
static HEARTBEAT_FEED: Mutex<Option<HeartbeatFeedState>> = Mutex::new(None);

/// Enter a floor batch. `entry_total = Some(n)` arms the feed when `n > 0`;
/// `None` leaves it pending (discovery: total filled once the roster is known).
/// Resets `entry_done` to 0. A zero total is refused (§5: never fabricate 0-of-0).
pub fn heartbeat_feed_enter_batch(batch_index: u64, label: &str, entry_total: Option<u64>) {
    let total = match entry_total {
        Some(0) => None,
        other => other,
    };
    let mut g = HEARTBEAT_FEED.lock().unwrap_or_else(|p| p.into_inner());
    *g = Some(HeartbeatFeedState {
        batch_index,
        batch_label: label.to_string(),
        entry_total: total,
        entry_done: AtomicU64::new(0),
    });
}

/// Fill the entry total once a discovery roster's entry-group count is known.
/// No-op when `total == 0` (refuses to arm a 0-of-0). No-op when no batch is open.
pub fn heartbeat_feed_set_entry_total(total: u64) {
    if total == 0 {
        return;
    }
    let mut g = HEARTBEAT_FEED.lock().unwrap_or_else(|p| p.into_inner());
    if let Some(state) = g.as_mut() {
        state.entry_total = Some(total);
    }
}

/// Record one completed entry (discovery source-file grain, or one SingleClaim).
/// Caps at `entry_total` when known so a late double-complete cannot invent
/// "entry N+1 of N".
pub fn heartbeat_feed_entry_completed() {
    let g = HEARTBEAT_FEED.lock().unwrap_or_else(|p| p.into_inner());
    if let Some(state) = g.as_ref() {
        let prev = state.entry_done.fetch_add(1, Ordering::Relaxed);
        if let Some(total) = state.entry_total {
            if prev >= total {
                // Undo the overshoot — saturating at total.
                state.entry_done.store(total, Ordering::Relaxed);
            }
        }
    }
}

/// The armed snapshot, or `None` when no batch is open / total still pending.
/// The heartbeat thread skips emit on `None` rather than printing a fabricated
/// progress line.
pub fn heartbeat_feed_snapshot() -> Option<HeartbeatFeedSnapshot> {
    let g = HEARTBEAT_FEED.lock().unwrap_or_else(|p| p.into_inner());
    let state = g.as_ref()?;
    let entry_total = state.entry_total?;
    let entry_done = state.entry_done.load(Ordering::Relaxed).min(entry_total);
    Some(HeartbeatFeedSnapshot {
        batch_index: state.batch_index,
        batch_label: state.batch_label.clone(),
        entry_done,
        entry_total,
    })
}

/// One in-flight witness attempt the floor has admitted but not yet finished.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ActiveWorksetEntry {
    pub attempt_id: String,
    pub entry: String,
    pub function: String,
}

struct ActiveWorksetState {
    entries: Vec<ActiveWorksetEntry>,
}

static ACTIVE_WORKSET: Mutex<ActiveWorksetState> = Mutex::new(ActiveWorksetState {
    entries: Vec::new(),
});

const FLOOR_PHASE_JOURNAL_ENV: &str = "GUNBC_FLOOR_PHASE_JOURNAL";

// TEMPORARY PROJECTION (operator ruling 2026-08-13, #8239 → #8163): active-workset
// admit/completed rows in GUNBC_FLOOR_PHASE_JOURNAL carry in-flight witness identity until
// subject + measurement events land on the #8163 RecordedObservation per-producer ledger
// (target/floor-attempts/<attempt>/events/<producer>.jsonl). Dissolve-on: #8163 on main +
// floor walk emits through that ledger with a dedicated producer identity; delete this append
// path once FLOOR2 consumes the ledger green by execution. NOT serialized into the floor
// component receipt — see floor_component_resource_checkpoint_note.
fn append_active_workset_phase_journal(state: &str, detail: &str) {
    let Some(path) = std::env::var_os(FLOOR_PHASE_JOURNAL_ENV) else {
        return;
    };
    let path = PathBuf::from(path);
    if let Some(parent) = path.parent() {
        if let Err(e) = std::fs::create_dir_all(parent) {
            eprintln!(
                "cli_run: create floor phase journal directory {}: {e}",
                parent.display()
            );
            return;
        }
    }
    let mut file = match std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
    {
        Ok(file) => file,
        Err(e) => {
            eprintln!("cli_run: open floor phase journal {}: {e}", path.display());
            return;
        }
    };
    let unix_millis = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis();
    let clean_detail = detail.replace(['\t', '\r', '\n'], " ");
    let row = format!(
        "{unix_millis}\t{}\tactive-workset\t{state}\t{clean_detail}\n",
        std::process::id()
    );
    use std::io::Write as _;
    if let Err(e) = file
        .write_all(row.as_bytes())
        .and_then(|()| file.flush())
        .and_then(|()| file.sync_data())
    {
        eprintln!(
            "cli_run: persist floor phase journal {}: {e}",
            path.display()
        );
    }
}

pub fn floor_walk_attempt_id_from_env() -> String {
    std::env::var("GUNBC_FLOOR_WALK_ATTEMPT_ID")
        .or_else(|_| std::env::var("GUNBC_WALK_ATTEMPT_ID"))
        .unwrap_or_else(|_| "local".to_string())
}

pub fn witness_attempt_id(entry: &str, function: &str) -> String {
    format!(
        "{}|{}|{}",
        floor_walk_attempt_id_from_env(),
        entry,
        function
    )
}

pub fn active_workset_admit(entry: &str, function: &str) {
    let attempt_id = witness_attempt_id(entry, function);
    append_active_workset_phase_journal(
        "admitted",
        &format!("attempt_id={attempt_id} entry={entry} function={function}"),
    );
    let mut g = ACTIVE_WORKSET.lock().unwrap_or_else(|p| p.into_inner());
    g.entries.retain(|e| e.attempt_id != attempt_id);
    g.entries.push(ActiveWorksetEntry {
        attempt_id,
        entry: entry.to_string(),
        function: function.to_string(),
    });
}

pub fn active_workset_complete(entry: &str, function: &str) {
    let attempt_id = witness_attempt_id(entry, function);
    append_active_workset_phase_journal(
        "completed",
        &format!("attempt_id={attempt_id} entry={entry} function={function}"),
    );
    let mut g = ACTIVE_WORKSET.lock().unwrap_or_else(|p| p.into_inner());
    g.entries.retain(|e| e.attempt_id != attempt_id);
}

pub fn active_workset_snapshot() -> Vec<ActiveWorksetEntry> {
    ACTIVE_WORKSET
        .lock()
        .unwrap_or_else(|p| p.into_inner())
        .entries
        .clone()
}

/// Test helper: clears the process-wide active-workset registry between discriminating tests.
#[doc(hidden)]
pub fn active_workset_reset_for_test() {
    ACTIVE_WORKSET
        .lock()
        .unwrap_or_else(|p| p.into_inner())
        .entries
        .clear();
}

/// Drive one entry-completion: decrement the entry's closure refcounts, drop the
/// per-module state that reached zero from every per-module cache (typed, parse,
/// normalize-diag, ownership-diag, source-hash), AND drop the entry's assembled
/// `ResolvedGraph` from `resolved_graph_memo` (keyed by `subject`) — the graph strong-
/// `Rc`-pins the same modules, so without it the per-module eviction frees no bytes
/// (Fact #4 / the brief's "strong Rc pins from elsewhere"). Heads are never touched. A
/// schedule underflow propagates as a typed, located refusal. Emits an unconditional
/// per-entry progress line so a timed-out walk still shows eviction working (the early-
/// receipt discipline — the walk-end receipt never lands on a step-cap death).
fn index_schedule_entry_completed(
    index: &MultiEntryIndex,
    entry: &str,
    subject: Option<&str>,
) -> Result<(), String> {
    let (batch, evict_enabled) = {
        let mut slot = index.schedule_retention.borrow_mut();
        match slot.as_mut() {
            Some(sr) => (sr.entry_completed(entry)?, sr.evict_enabled()),
            None => {
                // Schedule unarmed — the drain still advanced an entry; feed the heartbeat.
                heartbeat_feed_entry_completed();
                return Ok(());
            }
        }
    };
    // The same per-entry point feeds the observation heartbeat — one counter, not a fork.
    heartbeat_feed_entry_completed();
    if !batch.typed_keys.is_empty() {
        let mut cache = index.typed_module_cache.borrow_mut();
        for key in &batch.typed_keys {
            cache.remove(key);
        }
    }
    if !batch.raw_files.is_empty() {
        let mut parse = index.parse_cache.borrow_mut();
        let mut norm = index.normalize_diag_cache.borrow_mut();
        let mut own = index.ownership_diag_cache.borrow_mut();
        let mut src = index.source_hash_by_file.borrow_mut();
        for file in &batch.raw_files {
            parse.remove(file);
            norm.remove(file);
            own.remove(file);
            src.remove(file);
        }
    }
    // Drop the completed entry's assembled graph. The entry's own `InterpContext` still
    // holds it until the next resolve, so this only removes the memo's pin; a rare later
    // entry with the identical closure re-resolves (a memo miss, cost only).
    // Gate the resolved-graph pin drop on the SAME eviction switch as the per-module drops
    // above: with GUNBC_SCHEDULE_RETENTION_EVICT=0 the retain-all measurement pole must
    // retain EVERYTHING — graphs included — so it faithfully reproduces pre-M2 peak
    // retention (D0.4). Before this the pole understated peak by silently freeing graphs.
    let graph_evicted = match subject {
        Some(subj) if evict_enabled => index
            .resolved_graph_memo
            .borrow_mut()
            .remove(subj)
            .is_some(),
        _ => false,
    };
    let (sched_releases, sched_evictions, retention_unknown, graph_evictions) = {
        let mut slot = index.schedule_retention.borrow_mut();
        match slot.as_mut() {
            Some(sr) => {
                if graph_evicted {
                    sr.note_graph_eviction();
                }
                (
                    sr.schedule_releases(),
                    sr.schedule_evictions(),
                    sr.retention_unknown(),
                    sr.resolved_graph_evictions(),
                )
            }
            None => (0, 0, 0, 0),
        }
    };
    // Unconditional (not floor_verbose-gated) so the receipt survives a step-cap timeout.
    //
    // `schedule_passed_entry=` names what this line actually witnesses: the schedule
    // moved PAST that entry, so its per-module state can no longer be read. It asserts
    // nothing about selection or execution — arming spans the whole discovered roster
    // (`index_arm_schedule_retention` walks every row, before any predict-skip), so this
    // line appears for entries the affected set skipped without ever resolving them. The
    // former `entry='…'` spelling was read as "this entry was scheduled and ran" by two
    // independent readers hours apart, which is a property of the label, not the readers.
    // Routine drain steps FOLD (law 4): the schedule passing an entry is the most ordinary event
    // the floor produces — one line per discovered entry, thousands per run, none of them carrying
    // a fact a reader acts on. What a reader acts on is `retention_unknown` GROWING, which is the
    // drain admitting it could not classify a module's retention, so that is the arm that pierces.
    //
    // The trigger is the INCREASE, not the total: the total is monotone, so gating on `> 0` would
    // print every remaining entry once the first unknown appeared — the fold would collapse exactly
    // when the run got interesting. The aggregate `[floor-drain] receipt:` line still reports the
    // totals at close, so folding here loses no count, only the per-entry retelling of it.
    let unknown_grew = {
        // `fetch_max`, not `swap`: retention_unknown is a cumulative monotone counter, and a swap
        // lets two threads observing real growth each read the other's newer value as `prev` and
        // conclude nothing grew — the signal is lost on both. fetch_max returns the previous
        // maximum, so exactly the thread that raised it reports, and a raise is never dropped.
        static LAST_UNKNOWN: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
        let prev = LAST_UNKNOWN.fetch_max(retention_unknown, std::sync::atomic::Ordering::Relaxed);
        retention_unknown > prev
    };
    if !unknown_grew && routine_rollup_folds() {
        return Ok(());
    }
    eprintln!(
        "[floor-drain] schedule-retention: schedule_passed_entry='{entry}' \
         released_modules={} evicted_modules={} evicted_graph={} \
         schedule_releases={sched_releases} schedule_evictions={sched_evictions} \
         graph_evictions={graph_evictions} retention_unknown={retention_unknown} \
         typed_cache={} resolved_graphs={}",
        batch.released_modules.len(),
        batch.evicted_modules.len(),
        graph_evicted as u8,
        index.typed_module_cache.borrow().len(),
        index.resolved_graph_memo.borrow().len(),
    );
    Ok(())
}

#[cfg(test)]
mod heartbeat_feed_red_controls {
    use super::{
        heartbeat_feed_enter_batch, heartbeat_feed_entry_completed, heartbeat_feed_set_entry_total,
        heartbeat_feed_snapshot,
    };

    #[test]
    fn never_arms_a_fabricated_zero_of_zero() {
        heartbeat_feed_enter_batch(0, "witness discovery", Some(0));
        assert_eq!(
            heartbeat_feed_snapshot(),
            None,
            "entry_total=0 must not arm the feed"
        );
        heartbeat_feed_enter_batch(0, "witness discovery", None);
        assert_eq!(
            heartbeat_feed_snapshot(),
            None,
            "pending total must not arm the feed"
        );
        heartbeat_feed_set_entry_total(0);
        assert_eq!(
            heartbeat_feed_snapshot(),
            None,
            "set_entry_total(0) must refuse to arm"
        );
        heartbeat_feed_set_entry_total(602);
        let snap = heartbeat_feed_snapshot().expect("armed after real total");
        assert_eq!(snap.batch_label, "witness discovery");
        assert_eq!(snap.entry_done, 0);
        assert_eq!(snap.entry_total, 602);
        heartbeat_feed_entry_completed();
        let snap = heartbeat_feed_snapshot().expect("still armed");
        assert_eq!(snap.entry_done, 1);
    }
}

#[cfg(test)]
mod active_workset_kill_path_controls {
    use super::{
        active_workset_admit, active_workset_complete, active_workset_reset_for_test,
        active_workset_snapshot, witness_attempt_id,
    };

    static ACTIVE_WORKSET_TEST_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    fn with_active_workset_test_lock<F: FnOnce()>(f: F) {
        let _guard = ACTIVE_WORKSET_TEST_LOCK
            .lock()
            .unwrap_or_else(|p| p.into_inner());
        active_workset_reset_for_test();
        let run = std::panic::catch_unwind(std::panic::AssertUnwindSafe(f));
        active_workset_reset_for_test();
        match run {
            Ok(()) => {}
            Err(payload) => std::panic::resume_unwind(payload),
        }
    }

    /// SIGKILL / step-cap / panic paths never run `active_workset_complete`. Durable
    /// in-flight identity for that class is the GUNBC_FLOOR_PHASE_JOURNAL active-workset
    /// rows (admitted without a matching completed), not the floor component receipt —
    /// see floor_component_resource_checkpoint_note and floor_component_phase_journal_scaffold_note.
    #[test]
    fn admitted_entry_survives_without_completion() {
        with_active_workset_test_lock(|| {
            std::env::set_var("GUNBC_FLOOR_WALK_ATTEMPT_ID", "kill-control-admit-only");
            let entry = "dag/test/claim/floor_component_receipt_witness_test.dag";
            let function = "floor_component_receipt_run_incomplete_tail_holds";
            active_workset_admit(entry, function);
            let snap = active_workset_snapshot();
            assert_eq!(
                snap.len(),
                1,
                "kill path must leave admitted entry in registry without completion"
            );
            assert_eq!(snap[0].entry, entry);
            assert_eq!(snap[0].function, function);
            assert_eq!(snap[0].attempt_id, witness_attempt_id(entry, function));
        });
    }

    #[test]
    fn phase_journal_records_admit_without_completed_on_kill_path() {
        with_active_workset_test_lock(|| {
            let dir =
                std::env::temp_dir().join(format!("active-workset-journal-{}", std::process::id()));
            let _ = std::fs::remove_dir_all(&dir);
            std::fs::create_dir_all(&dir).expect("journal dir");
            let journal = dir.join("phase.tsv");
            std::env::set_var("GUNBC_FLOOR_PHASE_JOURNAL", &journal);
            std::env::set_var("GUNBC_FLOOR_WALK_ATTEMPT_ID", "kill-control-journal");
            let entry = "dag/test/claim/kill_path_fixture_test.dag";
            let function = "kill_path_fixture_holds";
            active_workset_admit(entry, function);
            let text = std::fs::read_to_string(&journal).expect("journal written on admit");
            assert!(
                text.contains("active-workset") && text.contains("admitted"),
                "admit must land in phase journal before any completion handler runs: {text}"
            );
            assert!(
                text.contains("attempt_id="),
                "journal row must carry attempt identity: {text}"
            );
            assert!(
                !text.contains("completed"),
                "kill path must not fabricate a completion journal row: {text}"
            );
            std::env::remove_var("GUNBC_FLOOR_PHASE_JOURNAL");
            let _ = std::fs::remove_dir_all(&dir);
        });
    }

    #[test]
    fn completion_removes_entry_after_graceful_exit() {
        with_active_workset_test_lock(|| {
            std::env::set_var("GUNBC_FLOOR_WALK_ATTEMPT_ID", "graceful-complete-control");
            let entry = "dag/test/claim/graceful_fixture_test.dag";
            let function = "graceful_fixture_holds";
            active_workset_admit(entry, function);
            assert_eq!(active_workset_snapshot().len(), 1);
            active_workset_complete(entry, function);
            assert!(
                active_workset_snapshot().is_empty(),
                "graceful completion must drop the entry"
            );
        });
    }
}

#[cfg(test)]
mod schedule_retention_red_controls {
    use super::{
        ScheduleRetention, RELEASE_AND_EVICTION_COUNTED_APART,
        SCHEDULE_RETENTION_ENTRY_LINE_ASSERTS_EXECUTION, SCHEDULE_RETENTION_TUNABLE_COUNT,
    };

    /// Locate the modeled retention-policy carrier by walking up from the crate
    /// manifest dir until `dag/gunbc/executor_schedule_retention.dag` appears — the
    /// same workspace-anchoring the resolved-graph cap lockstep test uses.
    fn read_modeled_policy() -> String {
        let mut dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"));
        loop {
            let candidate = dir.join("dag/gunbc/executor_schedule_retention.dag");
            if candidate.exists() {
                return std::fs::read_to_string(&candidate)
                    .expect("read executor_schedule_retention.dag");
            }
            if !dir.pop() {
                panic!(
                    "could not locate dag/gunbc/executor_schedule_retention.dag from manifest dir"
                );
            }
        }
    }

    fn modeled_int(dag: &str, name: &str) -> i64 {
        let line = dag
            .lines()
            .find(|l| l.trim_start().starts_with(&format!("data {name}:")))
            .unwrap_or_else(|| panic!("modeled `data {name}` not found"));
        line.split('=')
            .nth(1)
            .and_then(|rhs| rhs.trim().parse::<i64>().ok())
            .unwrap_or_else(|| panic!("modeled `{name}` is not a bare Int"))
    }

    fn modeled_bool(dag: &str, name: &str) -> bool {
        let line = dag
            .lines()
            .find(|l| l.trim_start().starts_with(&format!("data {name}:")))
            .unwrap_or_else(|| panic!("modeled `data {name}` not found"));
        line.split('=')
            .nth(1)
            .map(|rhs| rhs.trim() == "true")
            .unwrap()
    }

    /// LOCKSTEP: the Rust realization mirrors the modeled policy authority. Reds if the
    /// modeled `.dag` and the Rust drift — the `resolved_graph` `SizeBounded`-cap
    /// lockstep pattern applied to the policy (its "no tunables" fact and fail-closed
    /// shape).
    #[test]
    fn schedule_retention_policy_matches_modeled_authority() {
        let dag = read_modeled_policy();
        assert_eq!(
            modeled_int(&dag, "schedule_retention_tunable_count"),
            SCHEDULE_RETENTION_TUNABLE_COUNT,
            "Rust SCHEDULE_RETENTION_TUNABLE_COUNT drifted from the modeled policy — a \
             nonzero tunable count is a smuggled heuristic (DESIGN §4/§5); move BOTH and \
             face review"
        );
        // The fail-closed policy shape the mechanism realizes (asserted true in the model).
        for flag in [
            "schedule_retention_grain_is_per_module",
            "schedule_retention_heads_stay_resident",
            "schedule_retention_retain_on_unknown",
            "schedule_retention_underflow_refuses",
            "schedule_retention_release_and_eviction_counted_apart",
        ] {
            assert!(modeled_bool(&dag, flag), "modeled {flag} must be true");
        }
        assert_eq!(
            modeled_bool(&dag, "schedule_retention_entry_line_asserts_execution"),
            SCHEDULE_RETENTION_ENTRY_LINE_ASSERTS_EXECUTION,
            "the per-entry drain line witnesses the schedule passing an entry, never its \
             execution — arming walks the discovered roster before selection decides \
             anything, so a line that claims execution asserts a fact the mechanism \
             cannot support"
        );
        assert!(
            RELEASE_AND_EVICTION_COUNTED_APART,
            "release (refcount reached zero) and eviction (cached state actually dropped) \
             are counted apart in the realization"
        );
    }

    /// GREEN: eviction fires exactly at refcount zero. A shared module survives until
    /// its LAST scheduled entry; an entry-unique module drops the moment its entry
    /// completes. Heads are never recorded here, so they are never evicted.
    #[test]
    fn schedule_eviction_drops_at_refcount_zero() {
        // entry a: {shared, a_only}; entry b: {shared, b_only}
        let mut sr = ScheduleRetention::armed(
            vec![
                ("a".to_string(), vec!["shared".into(), "a_only".into()]),
                ("b".to_string(), vec!["shared".into(), "b_only".into()]),
            ],
            true,
        );
        sr.record_module("shared", "tk_shared", "f_shared");
        sr.record_module("a_only", "tk_a", "f_a");
        sr.record_module("b_only", "tk_b", "f_b");

        // Finishing a drops a_only (rc 1→0); shared stays (rc 2→1).
        let batch_a = sr.entry_completed("a").expect("no underflow");
        assert_eq!(batch_a.released_modules, vec!["a_only".to_string()]);
        assert_eq!(batch_a.evicted_modules, vec!["a_only".to_string()]);
        assert_eq!(batch_a.typed_keys, vec!["tk_a".to_string()]);
        assert_eq!(sr.schedule_releases(), 1);
        assert_eq!(sr.schedule_evictions(), 1);

        // Finishing b drops shared (rc 1→0) and b_only.
        let batch_b = sr.entry_completed("b").expect("no underflow");
        let mut got: Vec<String> = batch_b.released_modules.clone();
        got.sort();
        assert_eq!(got, vec!["b_only".to_string(), "shared".to_string()]);
        assert_eq!(sr.schedule_releases(), 3);
        assert_eq!(sr.schedule_evictions(), 3);
        assert_eq!(sr.retention_unknown(), 0);
    }

    /// RED for the counter defect this PR fixes: a module the run ARMED but never
    /// reconciled has no recorded cache keys, so its refcount reaching zero frees
    /// nothing. It must count as a RELEASE and NOT as an eviction. Before the fix both
    /// counters were the same increment, so a live receipt read schedule_evictions=2200
    /// against a typed_cache_peak of 883 — a claim of freed state that no cache could
    /// corroborate. This asserts the two counters DIVERGE on that population; if a
    /// future edit re-fuses them, `schedule_evictions` here goes 1 -> 2 and reds.
    #[test]
    fn unreconciled_module_releases_without_evicting() {
        let mut sr = ScheduleRetention::armed(
            vec![(
                "a".to_string(),
                vec!["reconciled".into(), "never_reconciled".into()],
            )],
            true,
        );
        // Only one of the two armed modules ever reaches reconcile (the ordinary case:
        // arming spans the discovered roster, the affected set resolves a subset).
        sr.record_module("reconciled", "tk", "f");

        let batch = sr.entry_completed("a").expect("no underflow");
        let mut released = batch.released_modules.clone();
        released.sort();
        assert_eq!(
            released,
            vec!["never_reconciled".to_string(), "reconciled".to_string()],
            "both armed modules are released — refcount reached zero for each"
        );
        assert_eq!(
            batch.evicted_modules,
            vec!["reconciled".to_string()],
            "only the module that had recorded cache state is evicted"
        );
        assert_eq!(sr.schedule_releases(), 2);
        assert_eq!(
            sr.schedule_evictions(),
            1,
            "an unreconciled module's release must not be counted as an eviction"
        );
    }

    /// RED #1 (eviction-disabled control): with `evict_enabled=false` the schedule
    /// still arms, records, counts, and REFUSES underflow — but drops nothing, so peak
    /// retention is the pre-M2 process-lifetime hold. This is the control run that
    /// reproduces today's peak to prove the mechanism moves RSS.
    #[test]
    fn schedule_eviction_disabled_retains_everything_but_still_counts() {
        let mut sr = ScheduleRetention::armed(
            vec![("a".to_string(), vec!["m".into()])],
            false, // eviction disabled (measurement pole)
        );
        sr.record_module("m", "tk", "f");
        sr.record_module("orphan", "tk_o", "f_o"); // not in any closure → RetentionUnknown
        let batch = sr.entry_completed("a").expect("no underflow");
        assert!(
            batch.released_modules.is_empty() && batch.evicted_modules.is_empty(),
            "disabled pole drops nothing"
        );
        assert_eq!(sr.schedule_releases(), 0);
        assert_eq!(sr.schedule_evictions(), 0);
        assert_eq!(
            sr.retention_unknown(),
            1,
            "counting still on with eviction off"
        );
    }

    /// RED #3 (reachability corruption → typed refusal): a schedule whose arming
    /// under-counted a module's demand (a later entry reaches state the refcount said
    /// was fully consumed) REFUSES, typed and located — never a silent wrong verdict
    /// against evicted state.
    #[test]
    fn schedule_underflow_refuses_typed() {
        // `m` is armed for ONE entry but reached by TWO — a corrupted (too-low) count.
        let mut sr = ScheduleRetention::armed(
            vec![
                ("a".to_string(), vec!["m".into()]),
                ("b".to_string(), vec![]), // b's closure was mis-derived to omit m
            ],
            true,
        );
        // Hand b the closure it REALLY reaches (includes m) to simulate the corruption.
        // (In production the two come from one arming source; this forces the underflow.)
        sr.entry_completed("a").expect("first consume ok"); // m: 1→0, evicted
        let err = sr
            .force_entry_completed_for_test("b", &["m".to_string()])
            .expect_err("underflow must refuse");
        assert!(
            err.contains("RefcountUnderflow") && err.contains("module='m'"),
            "refusal must be typed and located, got: {err}"
        );
    }

    /// RED #4 (RetentionUnknown counted): a module cached but reached by no scheduled
    /// entry's closure (a provenance gap) shows up as a nonzero, per-module count —
    /// retained, visible, prioritizable — never absorbed into a silent retain-all.
    #[test]
    fn retention_unknown_is_counted_per_module_once() {
        let mut sr = ScheduleRetention::armed(vec![("a".to_string(), vec!["known".into()])], true);
        sr.record_module("known", "tk", "f");
        sr.record_module("gap", "tk_g", "f_g");
        sr.record_module("gap", "tk_g2", "f_g2"); // re-record same gap: counted once
        assert_eq!(sr.retention_unknown(), 1);
        // The gap is never decremented/evicted: finishing `a` leaves it retained.
        let batch = sr.entry_completed("a").expect("no underflow");
        assert!(!batch.released_modules.contains(&"gap".to_string()));
        assert!(!batch.evicted_modules.contains(&"gap".to_string()));
    }

    /// END-TO-END WIRING (real index, real closure computation, real cache eviction):
    /// two entries sharing one library module. PREWARM the caches, arm from the schedule
    /// AFTER prewarming, then re-resolve both entries through reconcile's all-hits probe
    /// (the D0.2 registration path), then drive per-entry completion. The
    /// shared module survives entry A's completion (still reachable by B) and drops
    /// only when B completes — proving the mechanism frees real per-module state on a
    /// live `MultiEntryIndex`, not just in the pure bookkeeper above.
    #[test]
    fn schedule_eviction_end_to_end_on_real_index() {
        // Probe corpus must live UNDER the workspace root — path normalization
        // refuses anything outside it. `target/` is gitignored, so it stays clean.
        let dir = super::workspace_root()
            .join("target")
            .join(format!("sched_ret_probe_{}_e2e", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).expect("mkdir probe corpus");
        std::fs::write(
            dir.join("shared_lib.dag"),
            "module sched_ret_probe.shared_lib\n\ndata shared_val: Int = 7\n",
        )
        .unwrap();
        std::fs::write(
            dir.join("entry_a.dag"),
            "module sched_ret_probe.entry_a\n\nimport sched_ret_probe.shared_lib { shared_val }\n\ndata a_val: Int = shared_val\n",
        )
        .unwrap();
        std::fs::write(
            dir.join("entry_b.dag"),
            "module sched_ret_probe.entry_b\n\nimport sched_ret_probe.shared_lib { shared_val }\n\ndata b_val: Int = shared_val\n",
        )
        .unwrap();

        let root = dir.to_string_lossy().to_string();
        let entry_a = dir.join("entry_a.dag").to_string_lossy().to_string();
        let entry_b = dir.join("entry_b.dag").to_string_lossy().to_string();
        let index = super::build_multi_entry_index(&[root.clone()]);

        let rows = vec![
            super::DiscoveryRow {
                label: "a".into(),
                entry: entry_a.clone(),
                function: "a_probe".into(),
                reads_live_tree: false,
            },
            super::DiscoveryRow {
                label: "b".into(),
                entry: entry_b.clone(),
                function: "b_probe".into(),
                reads_live_tree: false,
            },
        ];
        // PREWARM the per-module typed cache WITHOUT arming — the production order:
        // compile-clean warms the shared index before discovery arms retention. Then clear
        // the per-entry resolved-graph memo (D0.1 makes compile-clean's warming Ephemeral:
        // modules cached, no per-entry graph pin) so the arm-time re-resolves MISS the memo
        // and go through reconcile's ALL-HITS probe — the exact path D0.2 fixed. The
        // pre-D0.4 order (arm, THEN first resolve) sent every module cold through the slow
        // recording path and never exercised the probe, so the all-hit no-registration
        // defect passed green: the §7 order-blindness this control now closes.
        super::resolve_entry_with_index(&index, &entry_a).expect("prewarm a");
        super::resolve_entry_with_index(&index, &entry_b).expect("prewarm b");
        super::clear_resolved_graph_memo_for_test(&index);

        // Arm AFTER prewarming, then re-resolve: per-module cache warm + graph memo cold ⇒
        // reconcile takes `try_reconcile_all_cache_hits`, which MUST register each hit's
        // schedule keys (D0.2) or the completions below evict nothing and this test reds.
        super::index_arm_schedule_retention(&index, &rows);
        super::resolve_entry_with_index(&index, &entry_a).expect("resolve a (all-hit)");
        super::resolve_entry_with_index(&index, &entry_b).expect("resolve b (all-hit)");

        // Both closures reconciled → all three modules cached, and each entry's
        // assembled ResolvedGraph is memoized (the strong-Rc pin Fact #4 drops).
        let full = super::typed_module_cache_len_for_test(&index);
        assert_eq!(full, 3, "entry_a + entry_b + shared_lib cached");
        let subj_a = super::subject_digest_for_closure(
            &super::load_sources_for_entry_with_pool(&index, &entry_a).unwrap(),
        );
        let subj_b = super::subject_digest_for_closure(
            &super::load_sources_for_entry_with_pool(&index, &entry_b).unwrap(),
        );
        let graphs_full = super::index_retention_snapshot(&index).resolved_graph_memo_entries;
        assert!(
            graphs_full >= 2,
            "each entry's ResolvedGraph memoized (got {graphs_full})"
        );

        // Completing A drops entry_a's unique module AND its ResolvedGraph pin (Fact #4).
        super::index_schedule_entry_completed(&index, &entry_a, Some(&subj_a)).expect("complete a");
        assert_eq!(
            super::typed_module_cache_len_for_test(&index),
            2,
            "entry_a evicted; shared_lib + entry_b remain"
        );
        assert_eq!(
            super::index_retention_snapshot(&index).resolved_graph_memo_entries,
            graphs_full - 1,
            "entry_a's ResolvedGraph dropped"
        );

        // Completing B drops entry_b AND the now-unreachable shared_lib (+ B's graph).
        super::index_schedule_entry_completed(&index, &entry_b, Some(&subj_b)).expect("complete b");
        assert_eq!(
            super::typed_module_cache_len_for_test(&index),
            0,
            "shared_lib survived until its last entry, then dropped"
        );

        let snap = super::index_retention_snapshot(&index);
        assert_eq!(snap.schedule_evictions, 3);
        assert_eq!(snap.retention_unknown, 0);
        assert_eq!(
            snap.resolved_graph_memo_entries, 0,
            "both entries' ResolvedGraphs evicted — the pin is released"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// RED (D0.4 retain-all baseline on a REAL index): with eviction DISABLED the pole
    /// must retain EVERYTHING a completion would otherwise drop — the per-module caches
    /// AND the assembled resolved graph. Before the D0.4 production fix the graph pin was
    /// dropped UNCONDITIONALLY, so the "retain-all" baseline silently understated peak
    /// retention (an invalid pre-M2 measurement pole). Installs a disabled retention
    /// directly rather than racing the process-global `GUNBC_SCHEDULE_RETENTION_EVICT`.
    #[test]
    fn schedule_eviction_disabled_retains_resolved_graph_on_real_index() {
        let dir = super::workspace_root()
            .join("target")
            .join(format!("sched_ret_probe_{}_retainall", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).expect("mkdir probe corpus");
        std::fs::write(
            dir.join("shared_lib.dag"),
            "module sched_ret_ra.shared_lib\n\ndata shared_val: Int = 7\n",
        )
        .unwrap();
        std::fs::write(
            dir.join("entry_a.dag"),
            "module sched_ret_ra.entry_a\n\nimport sched_ret_ra.shared_lib { shared_val }\n\ndata a_val: Int = shared_val\n",
        )
        .unwrap();
        let root = dir.to_string_lossy().to_string();
        let entry_a = dir.join("entry_a.dag").to_string_lossy().to_string();
        let index = super::build_multi_entry_index(&[root]);

        // Prewarm the per-module cache, then clear the graph memo (Ephemeral warming).
        super::resolve_entry_with_index(&index, &entry_a).expect("prewarm a");
        super::clear_resolved_graph_memo_for_test(&index);

        // Arm with eviction DISABLED, keyed on the loader's exact closure (D0.3 authority).
        let paths = super::load_sources_for_entry_with_pool(&index, &entry_a)
            .unwrap()
            .iter()
            .map(|sf| super::workspace_relative_repo_path(&sf.path))
            .collect::<Vec<String>>();
        super::install_schedule_retention_for_test(&index, vec![(entry_a.clone(), paths)], false);

        // Re-resolve so the all-hits probe records keys under the disabled retention, then
        // snapshot the resident state right before completion.
        super::resolve_entry_with_index(&index, &entry_a).expect("resolve a (all-hit)");
        let typed_before = super::typed_module_cache_len_for_test(&index);
        let graphs_before = super::index_retention_snapshot(&index).resolved_graph_memo_entries;
        assert!(
            graphs_before >= 1,
            "entry_a's graph memoized before completion"
        );
        let subj_a = super::subject_digest_for_closure(
            &super::load_sources_for_entry_with_pool(&index, &entry_a).unwrap(),
        );

        // Complete the entry: the disabled pole must drop NOTHING — not the per-module
        // caches, not the resolved graph.
        super::index_schedule_entry_completed(&index, &entry_a, Some(&subj_a)).expect("complete a");
        assert_eq!(
            super::typed_module_cache_len_for_test(&index),
            typed_before,
            "retain-all pole: per-module cache must be unchanged"
        );
        assert_eq!(
            super::index_retention_snapshot(&index).resolved_graph_memo_entries,
            graphs_before,
            "retain-all pole: the resolved GRAPH must be retained too (D0.4) — before the \
             production fix a completion dropped it unconditionally"
        );
        assert_eq!(
            super::index_retention_snapshot(&index).schedule_evictions,
            0,
            "disabled pole counts zero evictions"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }
}

/// Interim width=1 floor-drain retention (v1-run-stability throughline, parent
/// governor lane): instrument accumulation + host-budget entry cap on the private
/// `typed_module_cache` only. Whole-row eviction here is a counted safety backstop,
/// not cross-entry-typed-module-memo-sketch PR-β (`SpacePacked` + interface-summary
/// payload). Dissolve-on: PR-β lands the content-keyed outer ring.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct IndexRetentionSnapshot {
    pub typed_module_cache_entries: usize,
    pub parse_cache_entries: usize,
    pub resolved_graph_memo_entries: usize,
    pub normalize_diag_cache_entries: usize,
    pub ownership_diag_cache_entries: usize,
    pub intern_table_entries: usize,
    pub typed_cache_evictions: u64,
    /// Schedule-derived per-module RELEASES (v1-run-stability M2): modules whose
    /// refcount reached zero because no remaining scheduled entry's closure reaches
    /// them. At run end this equals the armed module count by construction, so it is
    /// a progress measure, not an eviction measure — see `schedule_evictions`.
    pub schedule_releases: u64,
    /// The releases that actually dropped cached state — the honest count of modules
    /// this mechanism removed from a cache.
    pub schedule_evictions: u64,
    /// Counted `RetentionUnknown` rows: modules cached but reachability-uncomputable,
    /// retained (correctness-fail-closed) — visible and prioritizable, never absorbed.
    pub retention_unknown: u64,
    /// Cumulative `resolved_graph_memo` pin drops (v1-run-stability M2 Fact #4):
    /// distinct from `schedule_evictions` (per-module typed-state drops) — this
    /// counts assembled-graph pin drops, the P1 receipt's `graphs_evicted` field.
    pub resolved_graph_evictions: u64,
    pub peak_rss_bytes: Option<u64>,
}

/// Conservative per-entry estimate for deriving a typed-cache cap from the host
/// memory envelope (v1-run-stability M0/M1 receipts: ~2–11 MiB/module; 3 MiB is
/// the interim declared fraction denominator until measured space lands).
/// SEED MIRROR of `gunbc.typed_module_cache_capacity` `typed_module_bytes_per_entry_estimate`.
/// Written as a canonical decimal literal (3 * 1024 * 1024) so the mirror lens can join it to
/// its authority row; see `test.claim.seed_mirror_constant_lens_witness_test`.
const TYPED_MODULE_BYTES_PER_ENTRY_ESTIMATE: u64 = 3145728;
/// SEED MIRROR of `gunbc.typed_module_cache_capacity` `typed_module_cache_entries_floor`.
const TYPED_MODULE_CACHE_MAX_ENTRIES_FLOOR: usize = 100;
/// SEED MIRROR of `gunbc.typed_module_cache_capacity` `typed_module_cache_entries_ceiling`.
const TYPED_MODULE_CACHE_MAX_ENTRIES_CEIL: usize = 4000;

/// One derivation of the typed-cache entry cap: env override, else the host
/// budget divided by the per-entry estimate. Returns `(cap, source_label,
/// degraded)` — `degraded` is true exactly when the budget did not come from
/// a private cgroup `memory.max`/`memory.high` (i.e. it fell through to the
/// host-wide `MemAvailable`/`MemTotal` last resort, or no budget was found at
/// all and the ceiling was used). Pure and side-effect-free: callers decide
/// how often to invoke it and whether to log the degraded case.
fn typed_module_cache_cap_derivation() -> (usize, String, bool) {
    if let Ok(raw) = std::env::var("GUNBC_TYPED_MODULE_CACHE_MAX_ENTRIES") {
        if let Ok(n) = raw.trim().parse::<usize>() {
            if n > 0 {
                return (
                    n.min(TYPED_MODULE_CACHE_MAX_ENTRIES_CEIL),
                    "env override GUNBC_TYPED_MODULE_CACHE_MAX_ENTRIES".to_string(),
                    false,
                );
            }
            // Zero override is invalid — fall through to derived cap.
        }
        // Malformed override — fall through to derived cap (fail-closed).
    }
    let (budget, source_label) = crate::memory_governor::read_host_budget_bytes();
    // String-scan of read_host_budget_bytes' label — acceptable while that fn returns
    // (Option<u64>, String); if it ever grows a typed source enum, ground this check on
    // the enum instead of re-parsing its display label (§3, avoid a second representation).
    let degraded = !(source_label.contains("memory.max") || source_label.contains("memory.high"));
    // REFUSE rather than widen when no budget is readable (operator ruling 2026-08-05;
    // authority `dag/gunbc/host_budget_source.dag` `HostBudgetUnreadable`).
    //
    // This was `.unwrap_or(TYPED_MODULE_CACHE_MAX_ENTRIES_CEIL)`: a budget that could not
    // be computed became the MOST PERMISSIVE cap available — top-as-answer conflated with
    // top-as-ignorance, the absorbing fallback DESIGN section 5 forbids by name. It is not
    // hypothetical. It OOM-killed the full witness corpus twice on a macOS dev machine
    // (exit 137): nothing readable, cap defaults to the ceiling, nothing bounds the resolve,
    // kernel ends the process. The deficit's frequency was zero by construction, so it never
    // ranked for fixing, and the cost arrived as a dead process instead of a diagnostic.
    //
    // Every platform this runs on now has a modeled source — procfs on Linux, sysctl
    // hw.memsize on Darwin — so reaching this arm means an unmodeled host, which is exactly
    // when admitting against an invented bound is least defensible. Panicking here is a hard
    // stop by design: this runs inside resolution, there is no caller that could honour a
    // typed refusal without threading Result through the cache seam, and continuing is the
    // one option ruled out.
    let Some(budget_bytes) = budget else {
        panic!(
            "HostBudgetUnreadable: no modeled host memory source answered ({source_label}). \
             The typed-module cache cap bounds the memory used to RESOLVE the corpus, so an \
             unknown budget cannot be defaulted — the previous default was the ceiling, which \
             OOM-killed this process rather than refusing. Declare one with \
             GUNBC_MEMORY_BUDGET_BYTES, or model this platform's memory source \
             (dag/gunbc/host_budget_source.dag)."
        );
    };
    let cap = ((budget_bytes / TYPED_MODULE_BYTES_PER_ENTRY_ESTIMATE) as usize).clamp(
        TYPED_MODULE_CACHE_MAX_ENTRIES_FLOOR,
        TYPED_MODULE_CACHE_MAX_ENTRIES_CEIL,
    );
    (cap, source_label, degraded)
}

/// The typed-cache cap for `index`, sampled exactly ONCE for this index's
/// lifetime (a run-start fact, never re-read per insert). On first call, if
/// the budget source is degraded (no private cgroup limit found), emits a
/// typed, counted `[floor-drain] degraded_budget_source` diagnostic — an
/// honesty arm, not a widened failure: the cap still derives from whatever
/// source was found, it is simply named so the degraded case is observable
/// and prioritizable rather than silent.
fn typed_module_cache_cap(index: &MultiEntryIndex) -> usize {
    *index.typed_module_cache_cap.get_or_init(|| {
        let (cap, source, degraded) = typed_module_cache_cap_derivation();
        if degraded {
            eprintln!(
                "[floor-drain] degraded_budget_source: cap={cap} source={source} (no private cgroup memory.max/memory.high found)"
            );
        }
        cap
    })
}

pub fn index_retention_snapshot(index: &MultiEntryIndex) -> IndexRetentionSnapshot {
    IndexRetentionSnapshot {
        typed_module_cache_entries: index.typed_module_cache.borrow().len(),
        parse_cache_entries: index.parse_cache.borrow().len(),
        resolved_graph_memo_entries: index.resolved_graph_memo.borrow().len(),
        normalize_diag_cache_entries: index.normalize_diag_cache.borrow().len(),
        ownership_diag_cache_entries: index.ownership_diag_cache.borrow().len(),
        intern_table_entries: index.intern_table.borrow().index.len(),
        typed_cache_evictions: index.typed_cache_evictions.get(),
        schedule_releases: index
            .schedule_retention
            .borrow()
            .as_ref()
            .map(|s| s.schedule_releases())
            .unwrap_or(0),
        schedule_evictions: index
            .schedule_retention
            .borrow()
            .as_ref()
            .map(|s| s.schedule_evictions())
            .unwrap_or(0),
        retention_unknown: index
            .schedule_retention
            .borrow()
            .as_ref()
            .map(|s| s.retention_unknown())
            .unwrap_or(0),
        resolved_graph_evictions: index
            .schedule_retention
            .borrow()
            .as_ref()
            .map(|s| s.resolved_graph_evictions())
            .unwrap_or(0),
        peak_rss_bytes: peak_rss_vhwm_bytes(),
    }
}

fn floor_drain_retention_detail_enabled() -> bool {
    std::env::var("GUNBC_FLOOR_DRAIN_RETENTION")
        .ok()
        .as_deref()
        .map(|v| matches!(v, "1" | "true" | "TRUE"))
        .unwrap_or(false)
}

fn retention_snapshot_peak(
    a: &IndexRetentionSnapshot,
    b: &IndexRetentionSnapshot,
) -> IndexRetentionSnapshot {
    IndexRetentionSnapshot {
        typed_module_cache_entries: a
            .typed_module_cache_entries
            .max(b.typed_module_cache_entries),
        parse_cache_entries: a.parse_cache_entries.max(b.parse_cache_entries),
        resolved_graph_memo_entries: a
            .resolved_graph_memo_entries
            .max(b.resolved_graph_memo_entries),
        normalize_diag_cache_entries: a
            .normalize_diag_cache_entries
            .max(b.normalize_diag_cache_entries),
        ownership_diag_cache_entries: a
            .ownership_diag_cache_entries
            .max(b.ownership_diag_cache_entries),
        intern_table_entries: a.intern_table_entries.max(b.intern_table_entries),
        typed_cache_evictions: a.typed_cache_evictions.max(b.typed_cache_evictions),
        schedule_releases: a.schedule_releases.max(b.schedule_releases),
        schedule_evictions: a.schedule_evictions.max(b.schedule_evictions),
        retention_unknown: a.retention_unknown.max(b.retention_unknown),
        resolved_graph_evictions: a.resolved_graph_evictions.max(b.resolved_graph_evictions),
        peak_rss_bytes: match (a.peak_rss_bytes, b.peak_rss_bytes) {
            (Some(x), Some(y)) => Some(x.max(y)),
            (Some(x), None) => Some(x),
            (None, Some(y)) => Some(y),
            (None, None) => None,
        },
    }
}

fn emit_floor_drain_group_line(
    group_idx: usize,
    total_groups: usize,
    prev: &IndexRetentionSnapshot,
    cur: &IndexRetentionSnapshot,
) {
    eprintln!(
        "[floor-drain] group={group_idx}/{total_groups} \
         typed_cache={}({:+}) parse_cache={}({:+}) resolved_memo={}({:+}) \
         intern_table={}({:+}) evictions={} peak_rss={}",
        cur.typed_module_cache_entries,
        cur.typed_module_cache_entries as i64 - prev.typed_module_cache_entries as i64,
        cur.parse_cache_entries,
        cur.parse_cache_entries as i64 - prev.parse_cache_entries as i64,
        cur.resolved_graph_memo_entries,
        cur.resolved_graph_memo_entries as i64 - prev.resolved_graph_memo_entries as i64,
        cur.intern_table_entries,
        cur.intern_table_entries as i64 - prev.intern_table_entries as i64,
        cur.typed_cache_evictions,
        cur.peak_rss_bytes
            .map(|b| b.to_string())
            .unwrap_or_else(|| "unreadable".into()),
    );
}

/// P1 retention-vs-drain cohort receipt (docs/plans/floor-prep-tax-program.md §P1):
/// per-entry-group instrumentation distinct from `emit_floor_drain_group_line`'s
/// cumulative cache-size line — this line prices the per-group wall/resolve/eval
/// tax the program's diagnosing, plus the typecheck-cache-hit / resolved-graph-hit
/// / eviction facts needed to tell "shared prep reused" from "shared prep re-paid":
/// `typecheck_cache_hit` is whether `typecheck_compute_count()` moved during this
/// group (a typecheck-memo hit/miss signal, NOT schedule-retention cache
/// occupancy — schedule-retention has no per-group hit/miss concept to read,
/// only cumulative eviction counters, which is why `modules_evicted`/
/// `graphs_evicted` carry that side of the story instead). Gated on its own env var
/// (never folded into `GUNBC_FLOOR_DRAIN_RETENTION`) so enabling one measurement
/// mode does not silently change the other's log shape (§3 — two distinct facts,
/// two distinct switches).
///
/// Scaffold, not a second production floor driver: this instrumentation and its
/// sole consumer, `p1_cohort_probe`, are diagnostic-only (opt-in, zero effect on
/// default eviction behavior — see `docs/plans/p1-retention-vs-drain-cohort-receipt.md`).
/// Dissolve-on: once P1 is banked and no other open lane needs cohort-scoped A/B
/// retention receipts, delete `emit_p1_cohort_entry_line`/`p1_cohort_receipt_enabled`/
/// `p1_cohort_cgroup_memory`, `resolved_graph_evictions` on `IndexRetentionSnapshot`,
/// and `src/v1/stage0/src/bin/p1_cohort_probe.rs` together (§6 — no parallel-ledger
/// mechanism kept around past the measurement it was built for).
fn p1_cohort_receipt_enabled() -> bool {
    std::env::var("GUNBC_P1_COHORT_RECEIPT")
        .ok()
        .as_deref()
        .map(|v| matches!(v, "1" | "true" | "TRUE"))
        .unwrap_or(false)
}

/// P1 cohort / 2×2 matrix experiment is active — gates optional shared-store arms on Serial
/// and private-store arms on ControlledWidthTwo without affecting production defaults.
fn p1_cohort_experiment_active() -> bool {
    p1_cohort_receipt_enabled()
        || std::env::var("GUNBC_P1_MATRIX_CELL").is_ok()
        || std::env::var("GUNBC_P1_SHARED_TYPED_STORE").is_ok()
}

fn p1_matrix_cell() -> Option<char> {
    let raw = std::env::var("GUNBC_P1_MATRIX_CELL")
        .unwrap_or_default()
        .trim()
        .to_ascii_uppercase();
    if raw.is_empty() {
        return None;
    }
    let cell = raw.chars().next()?;
    if matches!(cell, 'A' | 'B' | 'C' | 'D') {
        Some(cell)
    } else {
        None
    }
}

/// Whether the cross-worker JSON byte store arms typed-module sharing for this run.
/// Production: ControlledWidthTwo always shares; Serial never shares on the pump index.
/// Experiment (`p1_cohort_experiment_active`): matrix cell or `GUNBC_P1_SHARED_TYPED_STORE`.
pub fn p1_experimental_arm_shared_typed_store(scheduled_width: usize) -> bool {
    if let Some(cell) = p1_matrix_cell() {
        return matches!(cell, 'B' | 'D');
    }
    let raw = std::env::var("GUNBC_P1_SHARED_TYPED_STORE")
        .unwrap_or_else(|_| "auto".to_string())
        .trim()
        .to_ascii_lowercase();
    match raw.as_str() {
        "1" | "true" | "shared" => true,
        "0" | "false" | "private" => false,
        _ => scheduled_width > 1,
    }
}

#[allow(clippy::too_many_arguments)]
fn emit_p1_cohort_entry_line(
    group_idx: usize,
    total_groups: usize,
    entry: &str,
    wall_ms: u128,
    resolve_ms: u128,
    eval_ms: u128,
    typecheck_cache_hit: bool,
    resolved_graph_hit: bool,
    modules_evicted: u64,
    graphs_evicted: u64,
    process_rss: Option<u64>,
    cgroup_memory_current: Option<u64>,
    cgroup_memory_peak: Option<u64>,
) {
    eprintln!(
        "[p1-cohort] entry={group_idx}/{total_groups} name='{entry}' wall_ms={wall_ms} \
         resolve_ms={resolve_ms} eval_ms={eval_ms} typecheck_cache_hit={} \
         resolved_graph_hit={} modules_evicted={modules_evicted} graphs_evicted={graphs_evicted} \
         process_rss={} cgroup_memory_current={} cgroup_memory_peak={}",
        typecheck_cache_hit as u8,
        resolved_graph_hit as u8,
        process_rss
            .map(|b| b.to_string())
            .unwrap_or_else(|| "unreadable".into()),
        cgroup_memory_current
            .map(|b| b.to_string())
            .unwrap_or_else(|| "unreadable".into()),
        cgroup_memory_peak
            .map(|b| b.to_string())
            .unwrap_or_else(|| "unreadable".into()),
    );
}

/// Best-effort cgroup `memory.current` / `memory.peak` readback for the P1 cohort
/// receipt (§3 reuse of `memory_governor`'s cgroup-walk authority — no second
/// cgroup-path derivation here). `memory.peak` is absent on some kernels; that
/// arm reads `None` rather than fabricating a value (§5).
pub fn p1_cohort_cgroup_memory() -> (Option<u64>, Option<u64>) {
    match crate::memory_governor::leaf_cgroup_dir() {
        Some(dir) => (
            crate::memory_governor::read_cgroup_u64(&dir, "memory.current"),
            crate::memory_governor::read_cgroup_u64(&dir, "memory.peak"),
        ),
        None => (None, None),
    }
}

fn emit_floor_drain_receipt(
    index: &MultiEntryIndex,
    total_groups: usize,
    peaks: &IndexRetentionSnapshot,
) {
    eprintln!(
        "[floor-drain] receipt: groups={total_groups} \
         typed_cache_peak={} parse_cache_peak={} resolved_memo_peak={} \
         intern_table_peak={} evictions={} schedule_releases={} schedule_evictions={} \
         retention_unknown={} peak_rss={} cap_entries={}",
        peaks.typed_module_cache_entries,
        peaks.parse_cache_entries,
        peaks.resolved_graph_memo_entries,
        peaks.intern_table_entries,
        peaks.typed_cache_evictions,
        peaks.schedule_releases,
        peaks.schedule_evictions,
        peaks.retention_unknown,
        peaks
            .peak_rss_bytes
            .map(|b| b.to_string())
            .unwrap_or_else(|| "unreadable".into()),
        typed_module_cache_cap(index),
    );
}

/// Enforce the host-budget-derived entry cap on the private typed cache. Evictions
/// are counted and logged — a typed, located diagnostic, never a silent widen.
/// Victim selection is arbitrary (first `HashMap` key), not LRU or load-aware:
/// correctness is preserved by content-key recompute on miss; only cost/frequency
/// is affected if a hot entry is dropped.
fn enforce_typed_cache_entry_cap(index: &MultiEntryIndex) {
    if index.cross_worker_store.is_some() {
        return;
    }
    let cap = typed_module_cache_cap(index);
    let mut cache = index.typed_module_cache.borrow_mut();
    let mut evicted = 0u64;
    while cache.len() > cap {
        let Some(key) = cache.keys().next().cloned() else {
            break;
        };
        cache.remove(&key);
        evicted += 1;
    }
    drop(cache);
    if evicted > 0 {
        let total = index.typed_cache_evictions.get() + evicted;
        index.typed_cache_evictions.set(total);
        eprintln!(
            "[floor-drain] typed_cache_eviction: evicted={evicted} cap={cap} total_evictions={total}"
        );
    }
}

/// Read the typed cache: per-index `Rc` when private; shared byte snapshots only when
/// cross-worker store is armed (no local duplicate — serde transport is one authority).
/// `typed_key` is the content key from `typed_module_content_key`, never a module name.
fn index_get_typed(
    index: &MultiEntryIndex,
    typed_key: &str,
) -> Result<Option<Rc<v1_compiler_infer::TypecheckModuleResult>>, String> {
    let Some(store) = index.cross_worker_store.as_ref() else {
        shared_typecheck_store::record_private_store_fallback();
        return Ok(index.typed_module_cache.borrow().get(typed_key).cloned());
    };
    shared_get_typed(store, typed_key)
}

fn check_index_module_source_identity(
    index: &MultiEntryIndex,
    mod_name: &str,
    decl_file: &str,
) -> Result<(), String> {
    if let Some(store) = &index.cross_worker_store {
        let mut caches = shared_caches_write(store)?;
        check_module_source_identity_map(&mut caches.module_source_identity, mod_name, decl_file)
    } else {
        check_module_source_identity_map(
            &mut index.module_source_identity.borrow_mut(),
            mod_name,
            decl_file,
        )
    }
}

fn index_insert_typed(
    index: &MultiEntryIndex,
    typed_key: String,
    result: Rc<v1_compiler_infer::TypecheckModuleResult>,
) -> Result<Rc<v1_compiler_infer::TypecheckModuleResult>, String> {
    let Some(store) = index.cross_worker_store.as_ref() else {
        shared_typecheck_store::record_private_store_fallback();
        index
            .typed_module_cache
            .borrow_mut()
            .insert(typed_key, result.clone());
        enforce_typed_cache_entry_cap(index);
        return Ok(result);
    };
    if let Some(bytes) = {
        let caches = shared_caches_read(store)?;
        caches.clone_typed_bytes(&typed_key)
    } {
        return SharedTypecheckCaches::decode_typed_snapshot(bytes.as_slice());
    }
    let encoded = SharedTypecheckCaches::encode_typed_snapshot(&result)?;
    let raced_bytes = {
        let mut caches = shared_caches_write(store)?;
        if let Some(existing) = caches.clone_typed_bytes(&typed_key) {
            Some(existing)
        } else {
            caches.insert_typed_preencoded(typed_key.clone(), encoded);
            None
        }
    };
    if let Some(bytes) = raced_bytes {
        return SharedTypecheckCaches::decode_typed_snapshot(bytes.as_slice());
    }
    // Insert won the race: bytes live in the shared store only (no per-index Rc copy).
    Ok(result)
}

/// Read the shared typed cache with a brief lock hold; decode happens after the guard drops.
fn shared_get_typed(
    shared_caches: &Arc<RwLock<SharedTypecheckCaches>>,
    typed_key: &str,
) -> Result<Option<Rc<v1_compiler_infer::TypecheckModuleResult>>, String> {
    let bytes = {
        let caches = shared_caches_read(shared_caches)?;
        caches.clone_typed_bytes(typed_key)
    };
    match bytes {
        Some(snapshot) => {
            SharedTypecheckCaches::decode_typed_snapshot(snapshot.as_slice()).map(Some)
        }
        None => Ok(None),
    }
}

/// Accumulate the authored module names of a set of typed modules into `out`.
///
/// This is the closure-size primitive: `|out|` after folding every graph a shard resolved is the
/// distinct-module count of that shard's union closure. It reads the resolved graph, so it is a
/// fact about the source snapshot — unlike `typecheck_compute_count()`, which reads a cumulative
/// per-thread miss counter and therefore reports a closure size only when the thread started cold.
fn collect_typed_module_names(
    modules: impl IntoIterator<Item = Rc<TypedModule>>,
    source_indices: &Rc<HashMap<String, Rc<NewlineIndex>>>,
    out: &mut HashSet<String>,
) {
    for m in modules {
        out.insert(authored_name_at(source_indices.clone(), m.module.clone()));
    }
}

fn seed_kernel_intern_names(table: Rc<InternTable>) -> Rc<InternTable> {
    let mut t = table;
    for name in v1_rt::map_keys(&kernel_type_set()).iter().cloned() {
        t = intern(t, name).table.clone();
    }
    for name in ["Optional", "Present", "Absent", "value", "none"] {
        t = intern(t, name.to_string()).table.clone();
    }
    for name in v1_rt::map_keys(&compiler_recursive_types()).iter().cloned() {
        t = intern(t, name).table.clone();
    }
    t
}

/// Primary-precedence pool for affected-set attribution of `src/v1/*.dag` edits:
/// witness_layer_roots (dag + src/v2) cannot resolve v1.compiler.* modules alone.
fn build_v1_attribution_multi_entry_index() -> MultiEntryIndex {
    let roots = vec![
        "dag".to_string(),
        "src/v2".to_string(),
        "src/v1".to_string(),
    ];
    new_multi_entry_index_shell(build_module_index_primary_precedence(&roots), &roots, None)
}

pub fn resolve_entry_with_index(
    index: &MultiEntryIndex,
    entry_file: &str,
) -> Result<
    (
        Rc<v1_compiler_compile::ResolvedGraph>,
        Rc<HashMap<String, Rc<NewlineIndex>>>,
    ),
    String,
> {
    resolve_entry_with_parse_cache(index, entry_file, ResolveTypecheckGate::Strict)
}

pub fn resolve_entry_with_index_for_discovery_corpus(
    index: &MultiEntryIndex,
    entry_file: &str,
) -> Result<
    (
        Rc<v1_compiler_compile::ResolvedGraph>,
        Rc<HashMap<String, Rc<NewlineIndex>>>,
    ),
    String,
> {
    resolve_entry_with_parse_cache(
        index,
        entry_file,
        ResolveTypecheckGate::DiscoveryCorpusAdvisory,
    )
}

/// Per-entry stage attribution for the one-lump `resolve_nanos` (run-stability
/// throughline, docs/plans/v1-run-stability-throughline.md): per-entry resolve cost
/// was a single undifferentiated number, so which stage to memoize at module grain
/// could not be chosen by receipt. Filled per entry by `resolve_entry_with_parse_cache`
/// (reconcile internals accumulate their own rows) through a worker-local slot — each
/// floor worker resolves its entries sequentially on its own thread, so a thread-local
/// is per-worker-correct at width > 1, unlike the process-global last-writer-wins
/// `phase_profile` sampler, which is explicitly not attribution.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct ResolveStageNanos {
    /// `load_sources_for_entry_with_index` inside the timed window (closure walk over the index).
    pub load: u128,
    /// Parse-cache assembly loop: tokenize+parse on miss, cache clone on hit.
    pub parse: u128,
    /// `resolve_modules` + its blocking-diagnostic scan (per-module import resolution, closure topo/dup).
    pub resolve: u128,
    /// `normalize_graph` + its blocking-diagnostic scan (pure per-module diagnostics).
    pub normalize: u128,
    /// Genuine `typecheck_module` computes inside reconcile (typed-cache misses only).
    pub typecheck_compute: u128,
    /// `collect_parent_envs` calls inside reconcile (every module, cache hit or miss).
    pub parent_envs: u128,
    /// Reconcile total minus the rows above and the assembly sub-rows below: the
    /// unattributed whole-closure assembly residue that reruns per entry even at
    /// 100% cache hits.
    pub reconcile_assembly: u128,
    /// `extract_ownership_proofs` + its diagnostics walk.
    pub ownership: u128,
    // Assembly sub-rows (floor batch-3 lane, 2026-07-25). `reconcile_assembly` was one
    // undifferentiated number covering ~96% of the discovery-corpus resolve wall — the same
    // condition this struct's own doc-comment was written to end one level up, so the split
    // is the same move applied to its own residue. These rows located
    // `rewire_type_env_import_str_binding_identity` as 58% of the wall (see
    // docs/plans/floor-time-namespace-walk-regression-diagnosis.md §7). Same dissolution
    // trigger as `[gantt]` / `phase_profile`: a `.dag` `PerformanceReceipt` per-stage carrier
    // (realization_measurement_loop Phase 0) consumed by a floor witness makes this the
    // model's own attribution rather than a host-side stderr projection.
    /// `module_schedule_batches` — antichain schedule build over the closure.
    pub assembly_schedule: u128,
    /// `try_reconcile_all_cache_hits` pass 1: per-module content key + store probe.
    pub assembly_probe: u128,
    /// Closure vectors and the final `ResolvedGraph` view (per entry).
    pub assembly_graph: u128,
    /// Closure-scoped symbol-index census construction (per entry with cache misses).
    pub assembly_symbol_index: u128,
    /// Whole-pool qualified fill lookup/build (per index; later calls are memo hits).
    pub assembly_pool_fill: u128,
    /// Merge the closure census with the pool qualified fill (per entry with misses).
    pub assembly_symbol_index_merge: u128,
    /// Closure variant-owner base construction (per entry with cache misses).
    pub assembly_variant_base: u128,
    /// Compose the closure index with one source tree's bare census (once per root used).
    pub assembly_root_symbol_index: u128,
    /// Variant-owner base for a composed per-root symbol index (once per root used).
    pub assembly_root_variant_base: u128,
    /// Interface/variant surface installation (per computed or cached module membership).
    pub assembly_environment: u128,
    /// Diagnostic chunk/fork-ledger collection and diagnostic flattening.
    pub assembly_diagnostics: u128,
    /// `item_registry` merge fold across the closure's typed modules.
    pub assembly_registry: u128,
    /// `expand_transitive_services` (bounded 5-pass fixpoint over every bodied item).
    pub assembly_services: u128,
    /// The three `rewire_*` passes (type-env parents, import-str identity, func-env parents).
    pub assembly_rewire: u128,
    /// `rewire_type_env_parent_links` alone.
    pub assembly_rewire_type_env: u128,
    /// `rewire_type_env_import_str_binding_identity` alone.
    pub assembly_rewire_import_str: u128,
    /// `rewire_func_env_parent_links` alone.
    pub assembly_rewire_func_env: u128,
    /// `corpus_has_v1_seed_source_indices` + `build_emit_graph_info`.
    pub assembly_emit_info: u128,
    // `load` sub-rows (entry-graph-union slice 1, operator review 2026-07-31). INCLUSIVE
    // within `load` — never added to the exclusive sum. `load` dominating the partition
    // does not say WHICH part of the closure walk costs; the split below is the number
    // that decides whether a per-source content-hash memo suffices or a union graph is
    // needed, because only `load_reference_scan` is a pure function of source content.
    /// `referenced_module_paths_in_text` — the unmemoized full-content byte scan run once
    /// per (entry, module) pair. The unit the duplication factor multiplies.
    pub load_reference_scan: u128,
    /// Bytes fed to that scan (sum over calls) — lets the scan be priced per byte rather
    /// than per module, which is what the closure-size spread demands.
    pub load_reference_scan_bytes: u128,
    /// Number of scan calls.
    pub load_reference_scan_calls: u128,
    /// `resolve_transitively` — the import-edge closure, including its file reads.
    pub load_import_closure: u128,
    /// `extend_with_bare_reference_closure` inside the both-closure fixpoint — the
    /// "#6848 once-per-entry bare-reference fixpoint" DESIGN names as the floor residual.
    pub load_bare_reference_closure: u128,
    /// `extend_with_reference_closure_for_pool` inside the same fixpoint.
    pub load_pool_reference_closure: u128,
    /// Fixpoint iterations (a round is one bare + one pool pass).
    pub load_fixpoint_rounds: u128,
    /// MEASUREMENT INSTRUMENTATION (CONFIDENCE-0 edge-index receipt, commissioned
    /// 2026-08-09). These rows decompose `load_bare_edge_index` along the seams the
    /// constructor ACTUALLY has, rather than a presumed stage pipeline: the ref half,
    /// the bare half, the import-closure expansion inside them, and publish. They are
    /// INCLUSIVE rows, so they never enter `sum_exclusive` and cannot break the
    /// accounting law. Dissolve-on: either the memo fix lands and these retire to a
    /// regression control, or the v2 materialization substrate absorbs the closure.
    /// `edge_index_builds` is the row that separates the operator's two outcomes —
    /// construction fundamentally slow (optimize the measured stage) versus
    /// construction merely repeated (materialize once). It is a COUNT and not nanos
    /// deliberately: a cache HIT still adds its own small elapsed time to
    /// `load_bare_edge_index`, so `nanos == 0` is unassertable on a second query and
    /// "small" is not a claim this partition's accounting style permits.
    pub edge_index_builds: u128,
    /// Source files enumerated by the constructor's one loop.
    pub edge_index_source_files: u128,
    /// Files eligible to originate bare edges (import-free), a subset of the above.
    pub edge_index_bare_eligible: u128,
    /// `reference_pull_paths_for_source` — the dotted-reference half, summed per file.
    pub edge_index_ref_half: u128,
    /// `bare_reference_pull_paths_for_source` — the bare-name half, summed per file.
    pub edge_index_bare_half: u128,
    /// `import_closure_live_paths_with_facts` — the NAMED SUSPECT. A module's import
    /// closure is a pure function of the adjacency map, and `import_closure_from_adjacency`
    /// recomputes it from nothing on every call (fresh HashSet + VecDeque, a String
    /// clone per edge, then a sort), once per (source file, referenced module) pair.
    pub edge_index_closure_expand: u128,
    /// Calls to that expansion — the multiplicity the per-call cost is paid at.
    pub edge_index_closure_expand_calls: u128,
    /// `tree_bare_census_for_root` inside the bare half — the per-tree bare census,
    /// NET of the shared whole-corpus `pool_parse` it may be the first to force.
    pub edge_index_tree_census: u128,
    /// Calls to that census.
    pub edge_index_tree_census_calls: u128,
    /// Cold builds of that census (MISSES only). The count that makes the nanos above
    /// interpretable: total/calls is an average over mostly-free hits and describes no
    /// real call.
    pub edge_index_tree_census_misses: u128,
    /// Nanos spent in cold census builds only, NET of `pool_parse` (see that row): the
    /// census's own BFS over the root's compile closure plus
    /// `build_symbol_index_census_nodes`, and nothing else.
    pub edge_index_tree_census_miss_nanos: u128,
    /// `pool_parse` — the WHOLE-CORPUS tokenize+parse behind every pool-derived term
    /// (the per-root bare census, the qualified fill, the pool bare census). It is
    /// memoized on the index and forced LAZILY by whichever consumer reaches it first,
    /// so it has no single owner: charging it to that consumer reports one term's cost
    /// under another term's name. Measured 2026-08-24 on `dag` + `src/v2`: 14.25s of
    /// the 21.3s that `edge_index_tree_census_miss_nanos` used to report, because the
    /// miss timer started before the pool force.
    ///
    /// EVERY window that can contain the parse is recorded NET of it, via
    /// `nanos_net_of_pool_parse` or the same subtraction inline. The forcing paths are
    /// two, and they land in DIFFERENT top-level rows — which is why this row is an
    /// exclusive peer rather than a child of any of them:
    ///   - `load` -> the bare-reference closure -> the edge index -> the per-root census
    ///     (and, as the loop's cross-tree fallback, `pool_bare_census`);
    ///   - reconcile -> `assembly_pool_fill` (via `pool_qualified_fill`) and
    ///     `assembly_root_symbol_index` (via the per-root census again).
    /// `assembly_pool_fill` runs first in the reconcile path, so on that path it is the
    /// real payer — not a hypothetical one (review 55349).
    pub pool_parse: u128,
    /// Cold builds of the pool parse — 1 per index that forces it, 0 if nothing does.
    pub pool_parse_builds: u128,
    /// Modules parsed by those cold builds.
    pub pool_parse_modules: u128,
    /// `bare_identifier_candidates` — the per-file identifier scan.
    pub edge_index_bare_candidates: u128,
    pub edge_index_bare_name_universe: u128,
    pub edge_index_bare_resolve_loop: u128,
    /// `Rc::new` + hand-off of the finished index.
    pub edge_index_publish: u128,
    /// `both_closure_edge_index` (memoized on the index; nonzero here is the first build).
    pub load_bare_edge_index: u128,
    /// `path_to_source_lookup` — a corpus-wide map rebuilt on EVERY call (no memo).
    pub load_bare_path_lookup: u128,
    pub load_bare_path_lookup_calls: u128,
    /// `extend_sources_via_edge_map` — the actual closure walk over the edge map.
    pub load_bare_edge_walk: u128,
}

impl ResolveStageNanos {
    pub fn accumulate(&mut self, other: &ResolveStageNanos) {
        self.load += other.load;
        self.parse += other.parse;
        self.resolve += other.resolve;
        self.normalize += other.normalize;
        self.typecheck_compute += other.typecheck_compute;
        self.parent_envs += other.parent_envs;
        self.reconcile_assembly += other.reconcile_assembly;
        self.ownership += other.ownership;
        self.assembly_schedule += other.assembly_schedule;
        self.assembly_probe += other.assembly_probe;
        self.assembly_graph += other.assembly_graph;
        self.assembly_symbol_index += other.assembly_symbol_index;
        self.assembly_pool_fill += other.assembly_pool_fill;
        self.assembly_symbol_index_merge += other.assembly_symbol_index_merge;
        self.assembly_variant_base += other.assembly_variant_base;
        self.assembly_root_symbol_index += other.assembly_root_symbol_index;
        self.assembly_root_variant_base += other.assembly_root_variant_base;
        self.assembly_environment += other.assembly_environment;
        self.assembly_diagnostics += other.assembly_diagnostics;
        self.assembly_registry += other.assembly_registry;
        self.assembly_services += other.assembly_services;
        self.assembly_rewire += other.assembly_rewire;
        self.assembly_rewire_type_env += other.assembly_rewire_type_env;
        self.assembly_rewire_import_str += other.assembly_rewire_import_str;
        self.assembly_rewire_func_env += other.assembly_rewire_func_env;
        self.assembly_emit_info += other.assembly_emit_info;
        self.load_reference_scan += other.load_reference_scan;
        self.load_reference_scan_bytes += other.load_reference_scan_bytes;
        self.load_reference_scan_calls += other.load_reference_scan_calls;
        self.load_import_closure += other.load_import_closure;
        self.load_bare_reference_closure += other.load_bare_reference_closure;
        self.edge_index_builds += other.edge_index_builds;
        self.edge_index_source_files += other.edge_index_source_files;
        self.edge_index_bare_eligible += other.edge_index_bare_eligible;
        self.edge_index_ref_half += other.edge_index_ref_half;
        self.edge_index_bare_half += other.edge_index_bare_half;
        self.edge_index_closure_expand += other.edge_index_closure_expand;
        self.edge_index_closure_expand_calls += other.edge_index_closure_expand_calls;
        self.edge_index_tree_census += other.edge_index_tree_census;
        self.edge_index_tree_census_calls += other.edge_index_tree_census_calls;
        self.edge_index_tree_census_misses += other.edge_index_tree_census_misses;
        self.edge_index_tree_census_miss_nanos += other.edge_index_tree_census_miss_nanos;
        self.pool_parse += other.pool_parse;
        self.pool_parse_builds += other.pool_parse_builds;
        self.pool_parse_modules += other.pool_parse_modules;
        self.edge_index_bare_candidates += other.edge_index_bare_candidates;
        self.edge_index_bare_name_universe += other.edge_index_bare_name_universe;
        self.edge_index_bare_resolve_loop += other.edge_index_bare_resolve_loop;
        self.edge_index_publish += other.edge_index_publish;
        self.load_pool_reference_closure += other.load_pool_reference_closure;
        self.load_fixpoint_rounds += other.load_fixpoint_rounds;
        self.load_bare_edge_index += other.load_bare_edge_index;
        self.load_bare_path_lookup += other.load_bare_path_lookup;
        self.load_bare_path_lookup_calls += other.load_bare_path_lookup_calls;
        self.load_bare_edge_walk += other.load_bare_edge_walk;
    }

    /// Sum of the attributed stages; the caller's lump minus this is the
    /// unattributed residue (early cache-hit returns, diagnostic formatting).
    pub fn attributed_total(&self) -> u128 {
        self.load
            + self.parse
            + self.resolve
            + self.normalize
            + self.typecheck_compute
            + self.parent_envs
            + self.reconcile_assembly
            + self.ownership
            + self.assembly_schedule
            + self.assembly_probe
            + self.assembly_graph
            + self.assembly_symbol_index
            + self.assembly_pool_fill
            + self.assembly_symbol_index_merge
            + self.assembly_variant_base
            + self.assembly_root_symbol_index
            + self.assembly_root_variant_base
            + self.assembly_environment
            + self.assembly_diagnostics
            + self.assembly_registry
            + self.assembly_services
            + self.assembly_rewire_type_env
            + self.assembly_rewire_import_str
            + self.assembly_rewire_func_env
            + self.assembly_emit_info
    }

    /// Exclusive rows nested inside one reconcile span. Callers must subtract a
    /// pre-span snapshot: the thread-local slot can already contain assembly work
    /// performed while loading the entry (notably whole-tree census preparation).
    fn reconcile_attributed_total(&self) -> u128 {
        self.typecheck_compute
            + self.parent_envs
            + self.assembly_schedule
            + self.assembly_probe
            + self.assembly_graph
            + self.assembly_symbol_index
            + self.assembly_pool_fill
            + self.assembly_symbol_index_merge
            + self.assembly_variant_base
            + self.assembly_root_symbol_index
            + self.assembly_root_variant_base
            + self.assembly_environment
            + self.assembly_diagnostics
            + self.assembly_registry
            + self.assembly_services
            + self.assembly_rewire_type_env
            + self.assembly_rewire_import_str
            + self.assembly_rewire_func_env
            + self.assembly_emit_info
    }
}

