/// INTERIM hand-Rust scaffold (`CLI_RUN_WITNESS_ADMISSION_SOURCE_SCAN_SCAFFOLD_MARKER` / §7).
///
/// Fail-closed in BOTH directions (§5): every occurrence of a recognized row head either
/// parses to a key, is a verified definition or non-literal pass-through site, or PANICS with
/// its location — a mis-parse stops the line and never silently excuses an orphan; and a
/// consumer expressed in an unrecognized form yields NO key, so its deferred row surfaces as
/// a loud orphan rather than being absorbed.
fn witness_admission_entry_function_keys_from_source(
    source_label: &str,
    content: &str,
) -> Vec<String> {
    const WINDOW: usize = 400;
    let mut keys: Vec<String> = Vec::new();
    fn push_pair(keys: &mut Vec<String>, entry: &str, function: &str) {
        // U3 file-grain: empty `f: ""` means every test decl in the entry. Admission
        // keys must expand the same way `expand_explicit_entries` does for execution —
        // otherwise deferred leaf rows (entry::leaf) never match the unexpanded
        // consumer key (entry::) and Phase 0(b) falsely refuses (roadmap_belt #7273).
        if test_module_hygiene_bridge::is_file_grain_function(function) {
            let path = workspace_root().join(entry);
            let names = test_module_hygiene_bridge::enumerate_entry_test_fns(
                path.to_str().unwrap_or(entry),
            )
            .unwrap_or_else(|e| {
                panic!(
                    "witness admission: file-grain `{entry}` failed to enumerate test decls: {e}"
                )
            });
            for name in names {
                let key = witness_admission_manifest_key(entry, &name);
                if !keys.iter().any(|k| k == &key) {
                    keys.push(key);
                }
            }
            return;
        }
        let key = witness_admission_manifest_key(entry, function);
        if !keys.iter().any(|k| k == &key) {
            keys.push(key);
        }
    }
    // `known_red_probe(` replaced `probe_red(` and the seed-emitter wet row constructor when the
    // quarantine moved to one function-grain authority (2026-08-03): both cadences now author the
    // same row shape in `gunbc.explicit_witness_admission`, so one head reads both.
    let heads: [(&str, &str); 7] = [
        ("bin_wet(", "entry: String"),
        ("known_red_probe(", "entry: NonEmptyStr"),
        (
            "source_root_ingest_gate_admitted_witness(",
            "entry: NonEmptyStr",
        ),
        ("self_host_wet_entry(", "entry: String"),
        ("SelfHostWetReceiptBinding {", ""),
        ("RehomedBinWetRow {", ""),
        ("SubstrateLongLaneRow {", ""),
    ];
    for (head, def_sig) in heads {
        let mut search_from = 0;
        while let Some(rel) = content[search_from..].find(head) {
            let occ = search_from + rel;
            search_from = occ + head.len();
            // Word-boundary guard: `bin_wet(` must not match inside a longer identifier
            // (`witness_exclusion_row_is_rehomed_bin_wet(row: …)` — the class that panicked
            // run 30033250697). A head preceded by an identifier char is a different name.
            if occ > 0 {
                let prev = content.as_bytes()[occ - 1];
                if prev.is_ascii_alphanumeric() || prev == b'_' {
                    continue;
                }
            }
            let after = &content[search_from..];
            // WINDOW is a BYTE budget, but `after` is UTF-8: clamping with `min` alone
            // slices mid-character whenever byte `WINDOW` lands inside a multi-byte char,
            // and the admission rows this reads are prose that routinely contains one
            // (em dash, arrow). That panicked the whole floor worker — exit 101, no
            // terminal receipt — on a row whose reason string simply happened to put an
            // em dash across byte 400. Every other slice in this function takes its
            // offset from `find`/`split_once`, which return char boundaries; this fixed
            // offset was the only unguarded one. Walk down to the nearest boundary so a
            // long row is truncated rather than fatal.
            let window_end = {
                let mut end = after.len().min(WINDOW);
                while end > 0 && !after.is_char_boundary(end) {
                    end -= 1;
                }
                end
            };
            let window = &after[..window_end];
            let trimmed = window.trim_start();
            if !def_sig.is_empty() && trimmed.starts_with(def_sig) {
                continue;
            }
            if def_sig.is_empty() && content[..occ].ends_with("type ") {
                continue;
            }
            let Some(entry_rel) = window.find("entry: \"") else {
                if window.contains("entry: ") {
                    continue;
                }
                panic!(
                    "witness admission: {source_label}: `{head}` at byte {occ} has no \
                     recognizable `entry:` argument in range — refusing; a mis-parse must \
                     stop the line, never excuse an orphan"
                );
            };
            let entry_start = entry_rel + "entry: \"".len();
            let Some((entry, after_entry)) = window[entry_start..].split_once('"') else {
                panic!(
                    "witness admission: {source_label}: unterminated entry literal after \
                     `{head}` at byte {occ} — refusing"
                );
            };
            let marker = after_entry.find("f: \"").map(|p| (p, "f: \"")).or_else(|| {
                after_entry
                    .find("function: \"")
                    .map(|p| (p, "function: \""))
            });
            let Some((fn_pos, fn_marker)) = marker else {
                panic!(
                    "witness admission: {source_label}: `{head}` row for entry {entry:?} at \
                     byte {occ} has no `f:`/`function:` literal in range — refusing"
                );
            };
            let fn_start = fn_pos + fn_marker.len();
            let Some((function, _)) = after_entry[fn_start..].split_once('"') else {
                panic!(
                    "witness admission: {source_label}: unterminated function literal after \
                     `{head}` row for entry {entry:?} at byte {occ} — refusing"
                );
            };
            push_pair(&mut keys, entry, function);
        }
    }
    keys.sort();
    keys
}

pub fn witness_admission_explicit_consumer_keys() -> Vec<String> {
    static KEYS: OnceLock<Vec<String>> = OnceLock::new();
    KEYS.get_or_init(|| {
        let mut keys = witness_admission_entry_function_keys_from_source(
            "dag/gunbc/ci_layer_roots.dag",
            ci_layer_roots_authority_content(),
        );
        let wet =
            std::fs::read_to_string(workspace_root().join(WET_RECEIPT_ENROLLMENT_AUTHORITY_REL))
                .unwrap_or_else(|e| {
                    panic!(
                        "witness admission: failed to read {}: {e}",
                        WET_RECEIPT_ENROLLMENT_AUTHORITY_REL
                    )
                });
        for key in witness_admission_entry_function_keys_from_source(
            WET_RECEIPT_ENROLLMENT_AUTHORITY_REL,
            &wet,
        ) {
            if !keys.iter().any(|k| k == &key) {
                keys.push(key);
            }
        }
        for key in explicit_witness_admission_keys().iter().cloned() {
            if !keys.iter().any(|k| k == &key) {
                keys.push(key);
            }
        }
        for key in commit_roster_witness_claim_keys().iter().cloned() {
            if !keys.iter().any(|k| k == &key) {
                keys.push(key);
            }
        }
        keys.sort();
        keys
    })
    .clone()
}

/// The exact witness admission keys (`entry::function`) read from the one function-grain
/// authority. Same interim source scan as the sibling rosters
/// (`CLI_RUN_WITNESS_ADMISSION_SOURCE_SCAN_SCAFFOLD_MARKER`), one file instead of two.
fn explicit_witness_admission_keys() -> &'static [String] {
    static KEYS: OnceLock<Vec<String>> = OnceLock::new();
    KEYS.get_or_init(|| {
        let content = std::fs::read_to_string(
            workspace_root().join(EXPLICIT_WITNESS_ADMISSION_AUTHORITY_REL),
        )
        .unwrap_or_else(|e| {
            panic!(
                "witness admission: failed to read {}: {e}",
                EXPLICIT_WITNESS_ADMISSION_AUTHORITY_REL
            )
        });
        witness_admission_entry_function_keys_from_source(
            EXPLICIT_WITNESS_ADMISSION_AUTHORITY_REL,
            &content,
        )
    })
}

/// The same keys split back into `(entry, function)` pairs — the grain the exclusion is decided
/// at. An empty function is the declared file-grain form and is expanded upstream, so it never
/// reaches here as a pair.
pub(crate) fn explicit_witness_admission_pairs() -> Vec<(String, String)> {
    explicit_witness_admission_keys()
        .iter()
        .filter_map(|key| key.split_once("::"))
        .map(|(entry, function)| (entry.to_string(), function.to_string()))
        .collect()
}

// SCAFFOLD (§7 HAND-RUST — `cli_run_witness_deferral_freeze`): the seed realization of the
// frozen path-deferral wall. Registered disposition, dissolution sequence and measured LOC delta:
// `gunbc.cli_run_witness_deferral_freeze_scaffold` (authority `gunbc.witness_deferral_freeze`).
// The .dag side being the authority does NOT exempt this realization — cli_run.rs is the largest
// hand-maintained Rust wall in the program and is growing against its own hollowing plan, so this
// block is accounted for rather than admitted quietly. DELETE WHEN: the frozen-deferral projection
// is emitted or natively realized (then the source-scan helpers go), the classification path
// follows it (then the rest goes), or the frozen population reaches zero (then all of it goes with
// the freeze itself). Not a compiler_frontier `.dag` row: seed-Rust, counted here.

/// The THIRD source of an executing consumer, and the one that was missing. `commit_gate_roster`
/// carries `CommitWitnessClaim` rows at function grain; `project_ci_floor_witness_entries` and
/// `project_falsifier_witness_entries` turn them into explicit entries that RUN, and explicit rows
/// merge after discovery with no exclusion filter — so an enrolled witness under an offline path
/// executes even though the path excludes it (the two-edit rule `enforcement_coverage_exclusion_note`
/// records: offlining such a witness requires deleting its enrollment too).
///
/// Without this, the freeze wall would refuse 31 identities that already have a real consumer —
/// a fail-closed FALSE POSITIVE, which is still a wrong answer. Only surfaces that execute count:
/// `GitPrePushHook` is fmt-only since 2026-07-25 and runs no witness, so an enrollment naming only
/// that surface is not a consumer.
fn commit_roster_witness_claim_keys() -> &'static [String] {
    static KEYS: OnceLock<Vec<String>> = OnceLock::new();
    KEYS.get_or_init(|| {
        let content = std::fs::read_to_string(workspace_root().join(COMMIT_WORKFLOW_AUTHORITY_REL))
            .unwrap_or_else(|e| {
                panic!("witness admission: failed to read {COMMIT_WORKFLOW_AUTHORITY_REL}: {e}")
            });
        commit_roster_witness_claim_keys_from_source(&content)
    })
}

fn commit_roster_witness_claim_keys_from_source(content: &str) -> Vec<String> {
    // The ROW head, not the bare constructor name: `CommitWitnessClaim {` also opens the coproduct
    // declaration and every pattern-match arm over it, and one such arm's window happens to reach a
    // prose `entry:` literal in a neighbouring note. A row is always a `check:` field of a
    // `CommitCheckEnrollment`, so that prefix is the identity of a row rather than a guess about it.
    const HEAD: &str = "check: CommitWitnessClaim {";
    const EXECUTING_SURFACES: [&str; 2] = ["GithubActionsCiJob", "FalsifierCadenceJob"];
    let mut keys: Vec<String> = Vec::new();
    let mut cursor = 0usize;
    while let Some(offset) = content[cursor..].find(HEAD) {
        let at = cursor + offset;
        cursor = at + HEAD.len();
        let rest = &content[cursor..];
        let Some(entry) = quoted_after_field(rest, "entry:") else {
            panic!(
                "witness admission: CommitWitnessClaim row at byte {at} of \
                 {COMMIT_WORKFLOW_AUTHORITY_REL} has no parseable `entry:` literal"
            );
        };
        let Some(list) = bracket_list_after_field(rest, "check_fns:") else {
            panic!(
                "witness admission: CommitWitnessClaim row `{entry}` in \
                 {COMMIT_WORKFLOW_AUTHORITY_REL} has no parseable `check_fns:` list"
            );
        };
        let Some(surfaces) = bracket_list_after_field(rest, "surfaces:") else {
            panic!(
                "witness admission: CommitWitnessClaim row `{entry}` in \
                 {COMMIT_WORKFLOW_AUTHORITY_REL} has no parseable enrollment `surfaces:` list"
            );
        };
        if !EXECUTING_SURFACES.iter().any(|s| surfaces.contains(s)) {
            continue;
        }
        for function in quoted_literals(&list) {
            let key = witness_admission_manifest_key(&entry, &function);
            if !keys.iter().any(|k| k == &key) {
                keys.push(key);
            }
        }
    }
    keys
}

/// The frozen legacy path-deferral population, read from the one `.dag` authority by the same
/// interim source scan as the sibling rosters (`CLI_RUN_WITNESS_ADMISSION_SOURCE_SCAN_SCAFFOLD_MARKER`).
///
/// Fail-closed like its siblings: a `FrozenPathDeferral {` head that does not parse PANICS with
/// its location rather than yielding no key, because a silently-dropped freeze row would refuse a
/// legitimately frozen witness — and a silently-*added* one is impossible since keys only come
/// from parsed heads.
fn frozen_path_deferral_keys() -> &'static [String] {
    static KEYS: OnceLock<Vec<String>> = OnceLock::new();
    KEYS.get_or_init(|| {
        let content =
            std::fs::read_to_string(workspace_root().join(WITNESS_DEFERRAL_FREEZE_AUTHORITY_REL))
                .unwrap_or_else(|e| {
                    panic!(
                        "witness deferral freeze: failed to read {WITNESS_DEFERRAL_FREEZE_AUTHORITY_REL}: {e}"
                    )
                });
        frozen_path_deferral_keys_from_source(&content)
    })
}

fn frozen_path_deferral_rows_from_source(content: &str) -> Vec<(String, Vec<String>)> {
    const HEAD: &str = "FrozenPathDeferral {";
    let mut rows: Vec<(String, Vec<String>)> = Vec::new();
    let mut cursor = 0usize;
    while let Some(offset) = content[cursor..].find(HEAD) {
        let at = cursor + offset;
        cursor = at + HEAD.len();
        // `type FrozenPathDeferral {` is the declaration, not a row.
        if content[..at].trim_end().ends_with("type") {
            continue;
        }
        let rest = &content[cursor..];
        let entry = quoted_after_field(rest, "entry:").unwrap_or_else(|| {
            panic!(
                "witness deferral freeze: FrozenPathDeferral head at byte {at} of \
                 {WITNESS_DEFERRAL_FREEZE_AUTHORITY_REL} has no parseable `entry:` literal"
            )
        });
        let list = bracket_list_after_field(rest, "functions:").unwrap_or_else(|| {
            panic!(
                "witness deferral freeze: FrozenPathDeferral row `{entry}` in \
                 {WITNESS_DEFERRAL_FREEZE_AUTHORITY_REL} has no parseable `functions:` list"
            )
        });
        let functions = quoted_literals(&list);
        if functions.is_empty() {
            panic!(
                "witness deferral freeze: FrozenPathDeferral row `{entry}` declares an empty \
                 function list — a freeze row covering nothing is a row that should be deleted"
            );
        }
        rows.push((entry, functions));
    }
    rows
}

fn frozen_path_deferral_keys_from_source(content: &str) -> Vec<String> {
    let mut keys: Vec<String> = Vec::new();
    for (entry, functions) in frozen_path_deferral_rows_from_source(content) {
        for function in functions {
            let key = witness_admission_manifest_key(&entry, &function);
            if !keys.iter().any(|k| k == &key) {
                keys.push(key);
            }
        }
    }
    keys
}

/// The same freeze rows, joined against the ENROLLED-ROSTER identity space instead of the
/// admission-key space: `module.function` (as `floor_expected_red_roster` writes it) rather
/// than `entry::function` (as `witness_admission_manifest_key` writes it). Two different keys
/// over the same two facts, kept as two functions rather than one that returns both — a caller
/// asking "is this frozen?" wants the admission key; a caller asking "is this row also known-red?"
/// wants the qualified name, and conflating them would let a shape mismatch hide a real miss.
///
/// The module name is read from each entry file's own `module ...` line (`extract_module_path`),
/// the same authority `run_required_floor` reads for every other qualified name it reports — not
/// re-derived from the path string, which would silently diverge from the interpreter's own
/// binding the day a file's module line stops matching its directory.
fn frozen_path_deferral_qualified_identities_from_source(
    content: &str,
    root: &std::path::Path,
) -> Vec<(String, String)> {
    let mut out: Vec<(String, String)> = Vec::new();
    for (entry, functions) in frozen_path_deferral_rows_from_source(content) {
        let file_content = match std::fs::read_to_string(root.join(&entry)) {
            Ok(c) => c,
            // A frozen row naming a file the tree no longer carries is stale-path debt, not a
            // roster-intersection question — `collect_stale_frozen_path_deferrals` already owns
            // that disposition, so this join skips it rather than panicking a second authority.
            Err(_) => continue,
        };
        let module = match extract_module_path(&file_content) {
            Some(m) => m,
            None => continue,
        };
        for function in functions {
            out.push((entry.clone(), format!("{module}.{function}")));
        }
    }
    out
}

/// The contradictory-intersection wall's pure decision: which frozen (entry, qualified-name)
/// rows also name an identity enrolled in an executing witness roster. Pure and side-effect-free
/// so it is testable without a corpus checkout or a git repository — the file-reading half
/// (`frozen_path_deferral_qualified_identities_from_source`) and the git-head half
/// (`current_git_head_or_unresolved`) are kept out of it deliberately.
fn executing_roster_freeze_intersection(
    frozen_qualified: &[(String, String)],
    executing_roster: &HashSet<String>,
) -> Vec<(String, String)> {
    let mut colliding: Vec<(String, String)> = frozen_qualified
        .iter()
        .filter(|(_, qualified)| executing_roster.contains(qualified))
        .cloned()
        .collect();
    colliding.sort();
    colliding.dedup();
    colliding
}

fn expected_red_freeze_intersection(
    frozen_qualified: &[(String, String)],
    expected_red_roster: &HashSet<String>,
) -> Vec<(String, String)> {
    executing_roster_freeze_intersection(frozen_qualified, expected_red_roster)
}

fn route_gap_freeze_intersection(
    frozen_qualified: &[(String, String)],
    route_gap_roster: &HashSet<String>,
) -> Vec<(String, String)> {
    executing_roster_freeze_intersection(frozen_qualified, route_gap_roster)
}

fn current_git_head_or_unresolved() -> String {
    std::process::Command::new("git")
        .args(["rev-parse", "HEAD"])
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        .unwrap_or_else(|| "HEAD-unresolved".to_string())
}

fn format_expected_red_freeze_intersection_refusal(
    colliding: &[(String, String)],
    head: &str,
) -> String {
    let mut detail = String::new();
    for (entry, qualified) in colliding {
        detail.push_str(&format!("\n  - {qualified} (frozen via entry \"{entry}\")"));
    }
    format!(
        "REQUIRED-FLOOR REFUSAL cause=ExpectedRedFreezeIntersection count={} head={head} — {} \
         identity(ies) are simultaneously enrolled in \
         v2.workflow.floor_expected_red.floor_expected_red_roster (known-red, removable only by \
         an observed pass) AND path-deferred in dag/gunbc/witness_deferral_freeze.dag \
         frozen_path_deferrals (LegacyFrozenPathDeferral, admitted as never-executed). Both \
         claims cannot hold of one identity: this roster's own did-not-execute check below \
         proves every enrolled row here DOES execute, so the freeze row is stale evidence, not a \
         live exemption. This count is bound to the head above — measure again at merge time, \
         never cite it bare. Disposition: retire the frozen_path_deferrals row (it already has \
         an executing consumer — this required floor) with a receipt in \
         witness_deferral_freeze.dag's shrink log, or if the identity is not genuinely \
         executing, fix floor_expected_red_roster/required_floor's admission instead of leaving \
         the contradiction standing. Colliding identities:{detail}",
        colliding.len(),
        colliding.len()
    )
}

fn format_route_gap_freeze_intersection_refusal(
    colliding: &[(String, String)],
    head: &str,
) -> String {
    let mut detail = String::new();
    for (entry, qualified) in colliding {
        detail.push_str(&format!("\n  - {qualified} (frozen via entry \"{entry}\")"));
    }
    format!(
        "REQUIRED-FLOOR REFUSAL cause=RouteGapFreezeIntersection count={} head={head} — {} \
         identity(ies) are simultaneously enrolled in \
         v2.workflow.floor_route_gap.floor_route_gap_roster (a typed witness that this required \
         floor attempts to execute but cannot route to its subject) AND path-deferred in \
         dag/gunbc/witness_deferral_freeze.dag frozen_path_deferrals \
         (LegacyFrozenPathDeferral, admitted as having no executing consumer). Both claims cannot \
         hold of one identity: the typed route-gap receipt exists only because this required \
         floor consumed the row, so the freeze classification is stale evidence, not a live \
         exemption. This count is bound to the head above — measure again at merge time, never \
         cite it bare. Disposition: retire the frozen_path_deferrals row with a receipt in \
         witness_deferral_freeze.dag's shrink log, or if the floor does not genuinely consume \
         the identity, remove it from floor_route_gap_roster instead of leaving the contradiction \
         standing. Colliding identities:{detail}",
        colliding.len(),
        colliding.len()
    )
}

fn quoted_after_field(text: &str, field: &str) -> Option<String> {
    let at = text.find(field)? + field.len();
    let open = text[at..].find('"')? + at + 1;
    let close = text[open..].find('"')? + open;
    Some(text[open..close].to_string())
}

fn bracket_list_after_field(text: &str, field: &str) -> Option<String> {
    let at = text.find(field)? + field.len();
    let open = text[at..].find('[')? + at;
    let close = text[open..].find(']')? + open;
    Some(text[open + 1..close].to_string())
}

fn quoted_literals(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let bytes: Vec<char> = text.chars().collect();
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] == '"' {
            let mut j = i + 1;
            let mut buf = String::new();
            while j < bytes.len() && bytes[j] != '"' {
                buf.push(bytes[j]);
                j += 1;
            }
            if !buf.is_empty() {
                out.push(buf);
            }
            i = j + 1;
        } else {
            i += 1;
        }
    }
    out
}

/// Phase 0(b): every deferred witness row must name an executing consumer (explicit roster, or a
/// fixture roster), and — since 2026-08-04 — a broad `OfflineLocalRecipe` path policy is no longer
/// an answer on its own. A row that policy claims is admitted only while it sits in the frozen
/// legacy population (`gunbc.witness_deferral_freeze`); anything new refuses.
/// Per-row EXECUTION STANDING — what actually runs this witness. Mirrors the
/// `WitnessExecutionStanding` coproduct in `std.witness_admission` arm for arm, and the split is
/// the point: `LegacyFrozenPathDeferral` means TOLERATED BY THE MIGRATION RATCHET, never COVERED.
/// A frozen row has no executing consumer — that is the entire content of its debt — so the two
/// gates below are deliberately different rather than one success arm serving both questions.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WitnessExecutionStanding {
    HasExecutingConsumer,
    LegacyFrozenPathDeferral,
    UnclassifiedPathDeferral,
    UnexecutedDeferredWitness,
}

/// One deferred row with its standing, so a caller can ask the coverage question and the floor
/// question separately instead of receiving one boolean that answers neither honestly.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeferredRowStanding {
    pub entry: String,
    pub function: String,
    pub standing: WitnessExecutionStanding,
}

pub fn classify_deferred_discovery_rows(
    deferred_rows: &[DeferredDiscoveryRow],
) -> Vec<DeferredRowStanding> {
    classify_deferred_discovery_rows_in(
        deferred_rows,
        &witness_admission_explicit_consumer_keys(),
        &witness_admission_offline_exclusion_substrings(),
        &witness_admission_fixture_exclusion_substrings(),
        frozen_path_deferral_keys(),
    )
}

/// The same fold over supplied rosters — the grain the fixture controls plant into, so a control
/// can hold the row fixed and move only freeze membership (the discriminator this wall adds).
fn classify_deferred_discovery_rows_in(
    deferred_rows: &[DeferredDiscoveryRow],
    explicit: &[String],
    offline: &[String],
    fixture: &[String],
    frozen: &[String],
) -> Vec<DeferredRowStanding> {
    deferred_rows
        .iter()
        .map(|row| {
            let key = witness_admission_manifest_key(&row.entry, &row.function);
            let standing = if explicit.iter().any(|k| k == &key) {
                WitnessExecutionStanding::HasExecutingConsumer
            } else if path_matches_any_substring(&row.entry, offline) {
                if frozen.iter().any(|k| k == &key) {
                    WitnessExecutionStanding::LegacyFrozenPathDeferral
                } else {
                    WitnessExecutionStanding::UnclassifiedPathDeferral
                }
            } else if path_matches_any_substring(&row.entry, fixture) {
                WitnessExecutionStanding::HasExecutingConsumer
            } else {
                WitnessExecutionStanding::UnexecutedDeferredWitness
            };
            DeferredRowStanding {
                entry: row.entry.clone(),
                function: row.function.clone(),
                standing,
            }
        })
        .collect()
}

/// THE COVERAGE QUESTION. Only one arm means covered. A frozen row answers `false`, so nothing
/// downstream asking "is this behavior exercised" receives an admission success for a witness that
/// executes nowhere.
pub fn witness_standing_has_executing_consumer(standing: WitnessExecutionStanding) -> bool {
    matches!(standing, WitnessExecutionStanding::HasExecutingConsumer)
}

/// THE FLOOR GATE, a different question: may the floor proceed with this row today. It admits a
/// real consumer unconditionally and additionally TOLERATES the frozen legacy debt — but the
/// toleration is conditional on the roster axis, enforced by
/// `refuse_frozen_path_deferral_additions` and `refuse_stale_frozen_path_deferrals` above, which
/// stop the whole run when the baseline grows or rots. That is why this function does not silently
/// widen: the frozen arm is only reachable while those two refusals are silent.
pub fn collect_unexecuted_deferred_witnesses(
    deferred_rows: &[DeferredDiscoveryRow],
) -> Vec<DeferredAdmissionRefusal> {
    refusals_from_standings(&classify_deferred_discovery_rows(deferred_rows))
}

fn refusals_from_standings(rows: &[DeferredRowStanding]) -> Vec<DeferredAdmissionRefusal> {
    rows.iter()
        .filter_map(|row| {
            let cause = match row.standing {
                WitnessExecutionStanding::UnclassifiedPathDeferral => {
                    DeferredAdmissionCause::UnclassifiedPathDeferral
                }
                WitnessExecutionStanding::UnexecutedDeferredWitness => {
                    DeferredAdmissionCause::UnexecutedDeferredWitness
                }
                WitnessExecutionStanding::HasExecutingConsumer
                | WitnessExecutionStanding::LegacyFrozenPathDeferral => return None,
            };
            Some(DeferredAdmissionRefusal {
                entry: row.entry.clone(),
                function: row.function.clone(),
                cause,
            })
        })
        .collect()
}

/// The tolerated-but-uncovered population, counted so the debt is observable in the receipt rather
/// than hidden inside a green gate. This is the number that must fall to zero, and it is a COUNT
/// OF A DERIVED SET rather than a stored literal — nothing asserts it against a number.
pub fn count_legacy_frozen_debt_rows(rows: &[DeferredRowStanding]) -> usize {
    rows.iter()
        .filter(|r| r.standing == WitnessExecutionStanding::LegacyFrozenPathDeferral)
        .count()
}

/// The second direction of the identity join: a frozen row whose witness the tree no longer
/// carries is a standing exemption for an identity nothing checks, so it refuses and must be
/// deleted. Reads the filesystem and the pattern authority only — deliberately independent of the
/// caller's source roots, so a scoped batch cannot make the whole freeze look stale.
pub fn collect_stale_frozen_path_deferrals() -> Vec<(String, String, &'static str)> {
    let offline = witness_admission_offline_exclusion_substrings();
    let mut stale: Vec<(String, String, &'static str)> = Vec::new();
    let mut decls_cache: std::collections::BTreeMap<String, Option<Vec<String>>> =
        std::collections::BTreeMap::new();
    for key in frozen_path_deferral_keys() {
        let Some((entry, function)) = key.split_once("::") else {
            continue;
        };
        if !path_matches_any_substring(entry, &offline) {
            stale.push((
                entry.to_string(),
                function.to_string(),
                "entry no longer matches any OfflineLocalRecipe path policy",
            ));
            continue;
        }
        let decls = decls_cache.entry(entry.to_string()).or_insert_with(|| {
            std::fs::read_to_string(workspace_root().join(entry))
                .ok()
                .map(|c| {
                    scan_test_decl_lines(&c)
                        .into_iter()
                        .map(|(name, _)| name)
                        .collect()
                })
        });
        match decls {
            None => stale.push((
                entry.to_string(),
                function.to_string(),
                "entry file is absent",
            )),
            Some(names) if !names.iter().any(|n| n == function) => stale.push((
                entry.to_string(),
                function.to_string(),
                "entry no longer declares this test decl",
            )),
            Some(_) => {}
        }
    }
    stale
}

/// The freeze is a MONOTONE debt contract, and this is what makes that a wall rather than a
/// convention. The forward and backward identity joins keep the roster honest about the tree, but
/// neither stops an author appending a row in the same change that adds the witness — which is the
/// original escape hatch one level up, now with a typed carrier. So the roster's identity set may
/// only SHRINK relative to the diff baseline.
///
/// Fail-closed on the baseline itself: an unresolvable base ref REFUSES rather than proceeding
/// unchecked, because "I could not read the baseline" and "the baseline permits this" are different
/// states. The one non-refusing arm is the base ref resolving while the roster file is ABSENT from
/// it — that is the change introducing the freeze, where "may only shrink" has nothing to shrink
/// from; it is decidable, it is reachable exactly once, and every later PR sees the file at base.
///
/// WHAT THIS GATE CONSUMES, and the two forks it took to get here. `gunbc.diff_baseline` is the
/// single authority for what a run compares against — it exists as "the de-fork of the origin/main
/// policy-as-literal". This gate originally hardcoded `origin/main`, which is that fork at the
/// SOURCE. The first repair deleted the literal but then imposed `merge-base(base, HEAD)` on every
/// arm, which is the same fork one member over — at the RELATION. Both are the same underlying
/// defect: consuming an untyped baseline STRING where the authority resolves a comparison WINDOW.
/// So the carrier that crosses the seam is `FloorDiffComparisonReadout`: resolved base, resolved
/// head, and the relation between them, with the mode as the discriminator so no consumer can pick
/// a relation for itself.
pub fn collect_frozen_path_deferral_additions() -> Result<Vec<String>, String> {
    let comparison = floor_diff_comparison_readout().map_err(|reason| {
        format!(
            "WITNESS ADMISSION REFUSAL cause=FreezeBaselineUnresolved — the frozen path-deferral \
             roster is a monotone debt contract and gunbc.diff_baseline could not resolve the \
             comparison window this run is taken over, so growth cannot be ruled out. \
             Could-not-resolve and permits-this are different states and this arm refuses rather \
             than conflating them (it does NOT fall back to a constant ref — that fork is what \
             this gate was repaired to delete). Resolver reason: {reason}"
        )
    })?;
    collect_frozen_path_deferral_additions_for(&workspace_root(), &comparison)
}

/// THE COMPARISON WINDOW, as the seed sees it. Mirrors `FloorDiffComparisonReadout` arm for arm;
/// the mode is a variant rather than a flag because it selects which commit the base side is read
/// at, and a bool would let a caller forget to ask.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FreezeBaselineComparison {
    /// Two-dot: the endpoints are compared directly. `PushBefore` and `ExactReplayBoundary` are
    /// this, and for them the base is EXACT — imposing a merge base here is what passes real
    /// growth on a rewritten push.
    Direct {
        base: String,
        head: String,
        kind: String,
    },
    /// Three-dot: the comparison is against the point the head departed the base from, so a base
    /// that moves after the subject is fixed does not change the verdict.
    MergeBase {
        base: String,
        head: String,
        kind: String,
    },
}

impl FreezeBaselineComparison {
    fn base(&self) -> &str {
        match self {
            Self::Direct { base, .. } | Self::MergeBase { base, .. } => base,
        }
    }

    fn head(&self) -> &str {
        match self {
            Self::Direct { head, .. } | Self::MergeBase { head, .. } => head,
        }
    }

    fn kind(&self) -> &str {
        match self {
            Self::Direct { kind, .. } | Self::MergeBase { kind, .. } => kind,
        }
    }
}

/// The gate against an explicit repository root and an explicit comparison — the grain the controls
/// execute, so every arm can be proven against a hermetic git history instead of being asserted
/// about the live tree, whose history no test may author.
pub fn collect_frozen_path_deferral_additions_for(
    root: &std::path::Path,
    comparison: &FreezeBaselineComparison,
) -> Result<Vec<String>, String> {
    let run = |args: &[&str]| -> Result<std::process::Output, String> {
        std::process::Command::new("git")
            .args(args)
            .current_dir(root)
            .output()
            .map_err(|e| format!("git {args:?}: {e}"))
    };
    let located = |msg: String| -> String {
        format!(
            "{msg} (comparison base={} head={} kind={} mode={})",
            comparison.base(),
            comparison.head(),
            comparison.kind(),
            match comparison {
                FreezeBaselineComparison::Direct { .. } => "two-dot",
                FreezeBaselineComparison::MergeBase { .. } => "merge-base",
            }
        )
    };
    let base = comparison.base();
    let resolve = |rev: &str, role: &str| -> Result<String, String> {
        let out = run(&[
            "rev-parse",
            "--verify",
            "--quiet",
            &format!("{rev}^{{commit}}"),
        ])?;
        if !out.status.success() {
            return Err(located(format!(
                "WITNESS ADMISSION REFUSAL cause=FreezeBaselineUnobservable {role}={rev} — the \
                 frozen path-deferral roster is a monotone debt contract and one endpoint of its \
                 comparison could not be read, so growth cannot be ruled out. Could-not-read and \
                 permits-this are different states and this arm refuses rather than conflating \
                 them. Fetch the ref, or set GUNBC_CI_DIFF_BASE to a resolvable rev."
            )));
        }
        Ok(String::from_utf8_lossy(&out.stdout).trim().to_string())
    };
    let base_commit = resolve(base, "base")?;
    let head_commit = resolve(comparison.head(), "head")?;

    // THE BASELINE COMMIT, and the whole content of the relation half: two-dot compares the exact
    // base, merge-base compares the departure point. Choosing one for both is a fork of the
    // authority's own decision, and the direction it fails matters — imposing merge-base on a
    // two-dot arm passes growth (a fail-open), so this match may never grow a default.
    let baseline_commit = match comparison {
        FreezeBaselineComparison::Direct { .. } => base_commit,
        FreezeBaselineComparison::MergeBase { .. } => {
            let merge_base = run(&["merge-base", &base_commit, &head_commit])?;
            if !merge_base.status.success() {
                return Err(located(format!(
                    "WITNESS ADMISSION REFUSAL cause=FreezeBaselineUnrelatedHistory base={base} — \
                     this comparison is merge-base mode, so the roster is monotone against the \
                     commit the head DEPARTED from, and git merge-base found no common ancestor. \
                     No-common-ancestor and permits-this are different states and this arm refuses \
                     rather than conflating them. (Under two-dot mode the same history is directly \
                     comparable and does NOT reach here.)"
                )));
            }
            let fork_point = String::from_utf8_lossy(&merge_base.stdout)
                .trim()
                .to_string();
            if fork_point.is_empty() {
                return Err(located(format!(
                    "WITNESS ADMISSION REFUSAL cause=FreezeBaselineUnrelatedHistory base={base} — \
                     git merge-base succeeded but named no commit, so the baseline is unobservable \
                     and growth cannot be ruled out."
                )));
            }
            fork_point
        }
    };

    // THE CURRENT SIDE IS THE SELECTED HEAD, not an ambient one, and this runs BEFORE any arm that
    // can permit. Reading the live filesystem keeps an uncommitted local roster edit in scope (the
    // check must catch a row added but not yet committed), so the coherence is established rather
    // than assumed: the workspace must BE at the resolved head. An exact replay whose head is some
    // other commit therefore refuses instead of silently answering about whatever is checked out.
    //
    // ORDER IS LOAD-BEARING, and it was wrong when this wall first landed. The confirmed-absence
    // arm below returns `Ok` — a PERMIT — and it sat above this check, so a comparison whose
    // baseline predates the freeze file was blessed without ever establishing which tree was being
    // adjudicated. Discriminating history: base B has no roster, selected head H introduces {X},
    // the actual checkout C is some later commit carrying {X, Y}; the gate saw B lacking the roster
    // and permitted, never noticing it had answered about C rather than H. Bounded in practice
    // (today's push and PR baselines all carry the roster) but reachable through an exact replay or
    // an operator-selected historical baseline — and it contradicted the very law this check
    // states. A validation that any permitting arm can jump over is not a wall, so it is hoisted
    // above every one of them.
    let checkout = run(&["rev-parse", "--verify", "--quiet", "HEAD^{commit}"])?;
    let checkout_commit = String::from_utf8_lossy(&checkout.stdout).trim().to_string();
    if !checkout.status.success() || checkout_commit != head_commit {
        return Err(located(format!(
            "WITNESS ADMISSION REFUSAL cause=FreezeHeadEndpointMismatch resolved_head={head_commit} \
             checkout={checkout_commit} — the current side of this comparison is read from the \
             working tree, and the working tree is not at the head the authority selected, so the \
             roster it reports is not the roster of the subject under check. Answering about the \
             checkout anyway would substitute one endpoint for another."
        )));
    }

    let base_keys = match read_frozen_roster_at_commit(&run, &baseline_commit).map_err(located)? {
        Some(source) => frozen_path_deferral_keys_from_source(&source),
        None => {
            // CONFIRMED absent at a valid commit — not a failed read. This is the change that
            // introduces the freeze, the one arm with no baseline to shrink from. Counted, never
            // silent, and unreachable once the roster is on the base branch.
            eprintln!(
                "{} [freeze-monotonicity] {WITNESS_DEFERRAL_FREEZE_AUTHORITY_REL} is confirmed \
                 absent at baseline_commit={baseline_commit} (base={base}) — treating this change \
                 as the freeze point",
                floor_ts()
            );
            return Ok(Vec::new());
        }
    };
    let current_source = std::fs::read_to_string(root.join(WITNESS_DEFERRAL_FREEZE_AUTHORITY_REL))
        .map_err(|e| {
            located(format!(
                "WITNESS ADMISSION REFUSAL cause=FreezeRosterUnreadable — the frozen path-deferral \
                 roster {WITNESS_DEFERRAL_FREEZE_AUTHORITY_REL} could not be read from the \
                 repository under check, so growth cannot be ruled out: {e}"
            ))
        })?;
    Ok(frozen_path_deferral_additions_in(
        &frozen_path_deferral_keys_from_source(&current_source),
        &base_keys,
    ))
}

/// Read the roster at a commit, distinguishing CONFIRMED ABSENCE from FAILURE TO OBSERVE.
///
/// `git show <commit>:<path>` cannot tell those apart — it exits nonzero for a path that is not in
/// the tree AND for an unreadable object, a broken repository, or an I/O failure — so treating its
/// nonzero exit as "absent, therefore the introducing change" converts ignorance into permission
/// and admits the entire current roster. `ls-tree` separates them: the command either succeeds (and
/// its emptiness is a positive fact about the tree) or it does not (and that is ignorance).
///
/// `Ok(None)` therefore means "this commit is valid and does not contain the path". Every other
/// unhappy path is an `Err`.
fn read_frozen_roster_at_commit(
    run: &dyn Fn(&[&str]) -> Result<std::process::Output, String>,
    commit: &str,
) -> Result<Option<String>, String> {
    let listed = run(&[
        "ls-tree",
        "-z",
        commit,
        "--",
        WITNESS_DEFERRAL_FREEZE_AUTHORITY_REL,
    ])?;
    if !listed.status.success() {
        return Err(format!(
            "WITNESS ADMISSION REFUSAL cause=FreezeBaselineUnobservable commit={commit} — \
             `git ls-tree` could not observe whether {WITNESS_DEFERRAL_FREEZE_AUTHORITY_REL} \
             exists at the baseline, so neither its presence nor its absence is established and \
             growth cannot be ruled out: {}",
            String::from_utf8_lossy(&listed.stderr).trim()
        ));
    }
    if String::from_utf8_lossy(&listed.stdout).trim().is_empty() {
        return Ok(None);
    }
    let spec = format!("{commit}:{WITNESS_DEFERRAL_FREEZE_AUTHORITY_REL}");
    let shown = run(&["show", &spec])?;
    if !shown.status.success() {
        // ls-tree says the path IS there, so a failed blob read is a real failure, never absence.
        return Err(format!(
            "WITNESS ADMISSION REFUSAL cause=FreezeBaselineUnobservable commit={commit} — \
             {WITNESS_DEFERRAL_FREEZE_AUTHORITY_REL} is present at the baseline per ls-tree but \
             its blob could not be read, so the baseline population is unknown: {}",
            String::from_utf8_lossy(&shown.stderr).trim()
        ));
    }
    Ok(Some(String::from_utf8_lossy(&shown.stdout).into_owned()))
}

/// The pure fold the gate is built from — the grain the fixture controls plant into.
fn frozen_path_deferral_additions_in(current: &[String], base: &[String]) -> Vec<String> {
    current
        .iter()
        .filter(|k| !base.iter().any(|b| b == *k))
        .cloned()
        .collect()
}

fn refuse_frozen_path_deferral_additions(additions: &[String]) -> Result<(), String> {
    if additions.is_empty() {
        return Ok(());
    }
    let mut lines: Vec<String> = additions.iter().take(8).cloned().collect();
    if additions.len() > 8 {
        lines.push(format!("… and {} more added row(s)", additions.len() - 8));
    }
    Err(format!(
        "WITNESS ADMISSION REFUSAL cause=FrozenPathDeferralGrew count={} — \
         gunbc.witness_deferral_freeze gained identities relative to the diff baseline. The roster \
         is the FROZEN legacy population, so it may only shrink: adding a row is re-opening the \
         escape hatch it exists to close, because it admits a witness that executes nowhere. If \
         this is a new or relocated witness, give it an exact row in gunbc.explicit_witness_admission \
         naming the cadence that executes it; if it is genuinely a pre-existing identity the freeze \
         missed, that is a bug in the freeze and the fix belongs in a change that says so. Added: {}",
        additions.len(),
        lines.join("; ")
    ))
}

fn refuse_stale_frozen_path_deferrals(
    stale: &[(String, String, &'static str)],
) -> Result<(), String> {
    if stale.is_empty() {
        return Ok(());
    }
    let mut lines: Vec<String> = stale
        .iter()
        .take(8)
        .map(|(entry, function, why)| format!("{function} ({entry}) — {why}"))
        .collect();
    if stale.len() > 8 {
        lines.push(format!("… and {} more stale row(s)", stale.len() - 8));
    }
    Err(format!(
        "WITNESS ADMISSION REFUSAL cause=StaleFrozenPathDeferral count={} — \
         gunbc.witness_deferral_freeze row(s) name witnesses the tree no longer carries. A freeze \
         row is a debt marker for one exact (entry, function); left behind it becomes a standing \
         exemption the next witness to take that name inherits. Delete the listed row(s) in the \
         change that removed or renamed the witness: {}",
        stale.len(),
        lines.join("; ")
    ))
}

fn refuse_unexecuted_deferred_witnesses(
    orphans: &[DeferredAdmissionRefusal],
) -> Result<(), String> {
    if orphans.is_empty() {
        return Ok(());
    }
    let unclassified = orphans
        .iter()
        .filter(|o| o.cause == DeferredAdmissionCause::UnclassifiedPathDeferral)
        .count();
    let mut lines: Vec<String> = orphans
        .iter()
        .take(8)
        .map(|o| format!("{} [{}] ({})", o.function, o.cause.label(), o.entry))
        .collect();
    if orphans.len() > 8 {
        lines.push(format!("… and {} more orphan row(s)", orphans.len() - 8));
    }
    Err(format!(
        "WITNESS ADMISSION REFUSAL count={} ({unclassified} UnclassifiedPathDeferral) — enrolled \
         witness row(s) excluded from discovery name zero executing consumers (Phase 0(b) \
         admission invariant). An UnexecutedDeferredWitness matches no policy at all: put it on \
         falsifier_self_host_wet, bin_witness_wet, falsifier_rehomed_bin_wet, known_red_probe, or \
         a fixture roster. An UnclassifiedPathDeferral sits under an OfflineLocalRecipe directory, \
         which stopped being an admission answer on 2026-08-04: a directory cannot decide that a \
         witness runs, so give it an exact row in gunbc.explicit_witness_admission naming the \
         cadence that executes it — moving a file under a long/ or offline path removes it from \
         per-PR discovery and executes it NOWHERE. Rows: {}",
        orphans.len(),
        lines.join("; ")
    ))
}

fn eprintln_deferred_discovery_rows(rows: &[DeferredDiscoveryRow]) {
    if rows.is_empty() {
        return;
    }
    let live = rows.iter().filter(|r| r.reads_live_tree).count();
    let frozen_debt = count_legacy_frozen_debt_rows(&classify_deferred_discovery_rows(rows));
    let ts = floor_ts();
    eprintln!(
        "{ts} [deferred-discovery] {} witness row(s) excluded from per-PR discovery \
         ({} declare ReadsLiveTree, {} are frozen legacy debt with NO executing consumer — \
         tolerated by the migration ratchet, not covered) — counted, not silent",
        rows.len(),
        live,
        frozen_debt
    );
    for row in rows.iter().take(8) {
        eprintln!(
            "{ts} [deferred-discovery]   {} ({}) reason={}",
            row.function, row.entry, row.exclude_reason
        );
    }
    if rows.len() > 8 {
        eprintln!(
            "{ts} [deferred-discovery]   … and {} more deferred row(s)",
            rows.len() - 8
        );
    }
}

/// Does this tree hold at least one `.dag` file? EXISTENCE, not inventory.
///
/// `collect_dag_files_tolerant` answers "which files" and costs the whole subtree; this answers
/// "any file" and stops at the first hit. They are different questions and the pool-root gate asks
/// this one -- collecting every file beneath a root in order to call `is_empty` on the result is
/// the copied-accumulator shape, an O(subtree) walk to settle something the first file decides.
/// Directory recursion is depth-first for the same reason: a hit anywhere ends the walk.
pub(crate) fn dag_tree_holds_any_file(dir: &Path) -> bool {
    let entries = match std::fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return false,
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            if is_cargo_target_output_dir(dir, &path) {
                continue;
            }
            if dag_tree_holds_any_file(&path) {
                return true;
            }
        } else if path.extension().and_then(|e| e.to_str()) == Some("dag") {
            return true;
        }
    }
    false
}

pub(crate) fn collect_dag_files_tolerant(dir: &Path, out: &mut Vec<PathBuf>) {
    let entries = match std::fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            if is_cargo_target_output_dir(dir, &path) {
                continue;
            }
            collect_dag_files_tolerant(&path, out);
        } else if path.extension().and_then(|e| e.to_str()) == Some("dag") {
            out.push(path);
        }
    }
}

fn scan_test_decl_names(content: &str) -> Vec<String> {
    scan_test_decl_lines(content)
        .into_iter()
        .map(|(name, _line)| name)
        .collect()
}

fn scan_wire_contract_decl_names(content: &str) -> Vec<String> {
    let mut out = Vec::new();
    for line in content.lines() {
        let trimmed = line.trim_start();
        if let Some(rest) = trimmed.strip_prefix("data ") {
            let name: String = rest
                .chars()
                .take_while(|c| c.is_alphanumeric() || *c == '_')
                .collect();
            if name.is_empty() {
                continue;
            }
            let after_name = rest.get(name.len()..).unwrap_or("").trim_start();
            if after_name.starts_with(": CoproductWireContract")
                || after_name.starts_with(": VariantEncoding")
            {
                out.push(name);
            }
        }
    }
    out
}

fn scan_test_decl_lines(content: &str) -> Vec<(String, i64)> {
    let mut out = Vec::new();
    for (i, line) in content.lines().enumerate() {
        let trimmed = line.trim_start();
        let rest = trimmed
            .strip_prefix("test fn ")
            .or_else(|| trimmed.strip_prefix("test data "));
        if let Some(rest) = rest {
            let name: String = rest
                .chars()
                .take_while(|c| c.is_alphanumeric() || *c == '_')
                .collect();
            if !name.is_empty() {
                out.push((name, (i + 1) as i64));
            }
        }
    }
    out
}

/// The producer entry above is repo-relative, and every resolve of it ultimately reads the
/// path **cwd-relative** (`entry_source_from_index_or_disk` does a bare `Path::is_file`).
/// The floor runs from the repo root, so that ambient dependency is invisible in production
/// — but it is not invisible under `cargo test`, whose process cwd is the crate directory:
/// the resolve then fails with `entry file does not exist`, and that refusal fires *before*
/// whatever the caller was actually asking about, masking it. `set_current_dir` is not the
/// fix; this crate's harness is multi-threaded and chdir is process-global (the race is
/// already documented at the sibling fixture tests in this file).
///
/// So locate the entry rather than assume a cwd: `process_workspace_root` is git-toplevel
/// derived, hence identical in both worlds. Every workspace-root-relative entry goes through
/// this typed boundary so `resolve_entry_graph_shared` sees one anchored spelling per entry —
/// alternate spellings would resolve the same closure twice.
///
/// Part of the `cli_run_runtime_workspace_root_plumbing` scaffold (see
/// `CLI_RUN_RUNTIME_WORKSPACE_ROOT_SCAFFOLD_MARKER`): it dissolves with the rest of the
/// anchoring plumbing when entry resolution stops reading cwd.
#[derive(Clone, Copy)]
struct WorkspaceRootRelativeEntry(&'static str);

const FLOOR_DISCOVERY_PRODUCER_ENTRY: WorkspaceRootRelativeEntry =
    WorkspaceRootRelativeEntry("src/v2/workflow/floor_discovery_producer.dag");

fn resolve_workspace_entry(
    source_roots: &[String],
    entry: WorkspaceRootRelativeEntry,
) -> Result<
    (
        Rc<v1_compiler_compile::ResolvedGraph>,
        Rc<HashMap<String, Rc<NewlineIndex>>>,
    ),
    String,
> {
    let anchored = process_workspace_root().join(entry.0);
    resolve_entry_graph_shared(source_roots, &anchored.to_string_lossy())
}

fn owned_data_decl_record_to_value(
    rec: &OwnedDataDeclRecord,
    ctx: &v1_interpreter::InterpContext,
) -> v1_interpreter::Value {
    use std::rc::Rc;
    use v1_interpreter::{sorted_fields, Value};
    let initializer = match &rec.initializer {
        OwnedDataDeclInitializer::BoolWitnessClaim {
            witness_entry,
            witness_function,
        } => Value::Variant {
            type_name: ctx.sym("OwnedDataDeclInitializer"),
            variant_name: ctx.sym("OwnedBoolWitnessClaimInit"),
            fields: Rc::new(sorted_fields(vec![
                (ctx.sym("witness_entry"), str_value(witness_entry.clone())),
                (
                    ctx.sym("witness_function"),
                    str_value(witness_function.clone()),
                ),
            ])),
        },
        OwnedDataDeclInitializer::NodeCorpus => Value::Variant {
            type_name: ctx.sym("OwnedDataDeclInitializer"),
            variant_name: ctx.sym("OwnedNodeCorpusInit"),
            fields: Rc::new(vec![]),
        },
        OwnedDataDeclInitializer::Other { resolved } => Value::Variant {
            type_name: ctx.sym("OwnedDataDeclInitializer"),
            variant_name: ctx.sym("OwnedOtherInit"),
            fields: Rc::new(sorted_fields(vec![(
                ctx.sym("resolved"),
                Value::Record {
                    type_name: ctx.sym("ResolvedDeclRef"),
                    fields: Rc::new(sorted_fields(vec![
                        (ctx.sym("module"), str_value(resolved.module.clone())),
                        (ctx.sym("name"), str_value(resolved.name.clone())),
                    ])),
                },
            )])),
        },
    };
    Value::Record {
        type_name: ctx.sym("OwnedDataDeclRecord"),
        fields: Rc::new(sorted_fields(vec![
            (ctx.sym("entry"), str_value(rec.entry.clone())),
            (ctx.sym("module"), str_value(rec.module.clone())),
            (ctx.sym("decl_name"), str_value(rec.decl_name.clone())),
            (ctx.sym("initializer"), initializer),
        ])),
    }
}

fn parse_reads_live_tree_disposition(
    ctx: &v1_interpreter::InterpContext,
    val: &v1_interpreter::Value,
) -> Result<bool, String> {
    use v1_interpreter::Value;
    match val {
        Value::Variant {
            type_name,
            variant_name,
            ..
        } if ctx.sym_eq(*type_name, "LiveTreeDisposition") => {
            if ctx.sym_eq(*variant_name, "ReadsLiveTree") {
                Ok(true)
            } else if ctx.sym_eq(*variant_name, "SubstrateInputsOnly") {
                Ok(false)
            } else {
                Err(format!(
                    "unknown LiveTreeDisposition variant `{}`",
                    ctx.resolve(*variant_name)
                ))
            }
        }
        other => Err(format!(
            "expected LiveTreeDisposition, got `{}`",
            ctx.format_value(other)
        )),
    }
}

fn discovery_row_from_floor_discovery_row_value(
    ctx: &v1_interpreter::InterpContext,
    val: &v1_interpreter::Value,
) -> Result<DiscoveryRow, String> {
    use v1_interpreter::Value;
    let Value::Record { fields, .. } = val else {
        return Err(format!(
            "expected FloorDiscoveryRow record, got `{}`",
            ctx.format_value(val)
        ));
    };
    let label = match ctx.field(fields, "label") {
        Some(Value::Str(s)) => s.to_string(),
        _ => return Err("FloorDiscoveryRow missing `label`".to_string()),
    };
    let entry = match ctx.field(fields, "entry") {
        Some(Value::Str(s)) => s.to_string(),
        _ => return Err("FloorDiscoveryRow missing `entry`".to_string()),
    };
    let function = match ctx.field(fields, "function") {
        Some(Value::Str(s)) => s.to_string(),
        _ => return Err("FloorDiscoveryRow missing `function`".to_string()),
    };
    let reads_live_tree = match ctx.field(fields, "reads_live_tree") {
        Some(v) => parse_reads_live_tree_disposition(ctx, v)?,
        None => return Err("FloorDiscoveryRow missing `reads_live_tree`".to_string()),
    };
    Ok(DiscoveryRow {
        label,
        entry,
        function,
        reads_live_tree,
    })
}

fn parse_floor_discovery_producer_result(
    ctx: &v1_interpreter::InterpContext,
    val: &v1_interpreter::Value,
) -> Result<Vec<DiscoveryRow>, String> {
    use v1_interpreter::Value;
    match val {
        Value::Variant {
            type_name,
            variant_name,
            fields,
            ..
        } if ctx.sym_eq(*type_name, "FloorDiscoveryProducerResult")
            && ctx.sym_eq(*variant_name, "FloorDiscoveryAccepted") =>
        {
            let rows_val = ctx
                .field(fields, "rows")
                .ok_or_else(|| "FloorDiscoveryAccepted missing `rows`".to_string())?;
            match rows_val {
                Value::List(items) => {
                    let mut out = Vec::with_capacity(items.len());
                    for item in items.iter() {
                        out.push(discovery_row_from_floor_discovery_row_value(ctx, item)?);
                    }
                    out.sort_by(|a, b| {
                        a.entry
                            .cmp(&b.entry)
                            .then_with(|| a.function.cmp(&b.function))
                    });
                    Ok(out)
                }
                other => Err(format!(
                    "FloorDiscoveryAccepted.rows not a List: `{}`",
                    ctx.format_value(other)
                )),
            }
        }
        Value::Variant {
            type_name,
            variant_name,
            fields,
            ..
        } if ctx.sym_eq(*type_name, "FloorDiscoveryProducerResult")
            && ctx.sym_eq(*variant_name, "FloorDiscoveryRefused") =>
        {
            let reason = match ctx.field(fields, "reason") {
                Some(Value::Str(s)) => s.to_string(),
                _ => "floor discovery refused (no reason)".to_string(),
            };
            Err(reason)
        }
        other => Err(format!(
            "discover_floor_corpus_rows_from_host_facts returned `{}`, expected FloorDiscoveryProducerResult",
            ctx.format_value(other)
        )),
    }
}

pub(crate) fn invoke_floor_discovery_producer(
    source_roots: &[String],
    scan_dirs: &[String],
    exclude_substrings: &[String],
) -> Result<Vec<DiscoveryRow>, String> {
    invoke_floor_discovery_producer_over_corpus(
        source_roots,
        source_roots,
        scan_dirs,
        exclude_substrings,
    )
}

/// Two roles `source_roots` fuses, here separate parameters: `producer_roots` locates the
/// MACHINERY (the `.dag` producer that decides discovery and its sidecar refusals), while
/// `corpus_roots` is the SUBJECT (the roots whose `.dag` files are walked and judged).
/// Production passes the same list for both — that is the whole floor's shape and does not
/// change. What the fusion prevented was *asking about one file*: any question had to submit
/// the entire live `src/v2` + `dag` corpus for judgement too, so an unrelated corpus file's
/// refusal could answer first and mask the one under test (review 44641). The producer stays
/// real machinery; only the subject narrows.
fn invoke_floor_discovery_producer_over_corpus(
    producer_roots: &[String],
    corpus_roots: &[String],
    scan_dirs: &[String],
    exclude_substrings: &[String],
) -> Result<Vec<DiscoveryRow>, String> {
    let excludes: Vec<String> = exclude_substrings.to_vec();
    let mut owned_data_records: Vec<OwnedDataDeclRecord> = Vec::new();
    for scan_dir in scan_dirs {
        let discovery = discover_owned_data_decls(corpus_roots, scan_dir, &excludes)?;
        owned_data_records.extend(discovery.records);
    }
    let (graph, indices) = resolve_workspace_entry(producer_roots, FLOOR_DISCOVERY_PRODUCER_ENTRY)
        .map_err(|e| format!("floor_discovery_producer resolve: {e}"))?;
    let ctx = make_eval_context(&graph, indices, v1_interpreter::ExecutionMode::Wet);
    let source_root_values: Vec<v1_interpreter::Value> =
        corpus_roots.iter().map(|s| str_value(s.clone())).collect();
    let exclude_values: Vec<v1_interpreter::Value> = exclude_substrings
        .iter()
        .map(|s| str_value(s.clone()))
        .collect();
    let owned_values: Vec<v1_interpreter::Value> = owned_data_records
        .iter()
        .map(|rec| owned_data_decl_record_to_value(rec, &ctx))
        .collect();
    let args = [
        (
            Some("source_roots".to_string()),
            list_value_from_vec(source_root_values),
        ),
        (
            Some("exclude_substrings".to_string()),
            list_value_from_vec(exclude_values),
        ),
        (
            Some("owned_data_records".to_string()),
            list_value_from_vec(owned_values),
        ),
    ];
    let result = v1_interpreter::run_in_context_with_args(
        &ctx,
        "discover_floor_corpus_rows_from_host_facts",
        &args,
        false,
    )
    .map_err(|e| format!("discover_floor_corpus_rows_from_host_facts: {e}"))?;
    parse_floor_discovery_producer_result(&ctx, &result)
}

pub(crate) fn apply_discovery_scope_dirs_filter(
    mut rows: Vec<DiscoveryRow>,
    discovery_scope_dirs: &[String],
) -> Vec<DiscoveryRow> {
    if discovery_scope_dirs.is_empty() {
        return rows;
    }
    rows.retain(|row| {
        discovery_scope_dirs
            .iter()
            .any(|d| row.entry.contains(d.as_str()))
    });
    rows
}

