#[cfg(test)]
mod discovery_summary_merge_tests {
    use super::{
        compute_histogram_data, finalize_discovery_summary, merge_discovery_summaries,
        project_witness_cost_receipt, repo_relative_dag_path, run_discovery_corpus_with_options,
        top_n_slowest_witnesses, witness_execution_leg_cache_put, ClaimOutcome,
        DiscoveryCorpusOptions, DiscoveryRow, DiscoverySummary, DiscoveryWidthPolicy,
        DiscoveryWitnessOutcome, EntryResolveReceipt, ResolveStageNanos,
    };
    use crate::v1_interpreter::{ExecutionMode, PerformanceReceipt};

    fn source_roots() -> Vec<String> {
        let workspace = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .ancestors()
            .nth(3)
            .expect("workspace root");
        vec![
            workspace.join("dag").to_string_lossy().into_owned(),
            workspace.join("src/v2").to_string_lossy().into_owned(),
        ]
    }

    fn sample_summary() -> DiscoverySummary {
        DiscoverySummary {
            total: 3,
            passed: 3,
            skipped: 0,
            deferred_rows: Vec::new(),
            divergences: Vec::new(),
            failures: Vec::new(),
            witness_outcomes: vec![
                DiscoveryWitnessOutcome {
                    entry: "a.dag".to_string(),
                    module_path: "a".to_string(),
                    function: "fast".to_string(),
                    outcome: ClaimOutcome::Pass,
                    execution_leg: "InterpretedLeg".to_string(),
                },
                DiscoveryWitnessOutcome {
                    entry: "b.dag".to_string(),
                    module_path: "b".to_string(),
                    function: "slow".to_string(),
                    outcome: ClaimOutcome::Pass,
                    execution_leg: "InterpretedLeg".to_string(),
                },
                DiscoveryWitnessOutcome {
                    entry: "a.dag".to_string(),
                    module_path: "a".to_string(),
                    function: "medium".to_string(),
                    outcome: ClaimOutcome::Pass,
                    execution_leg: "InterpretedLeg".to_string(),
                },
            ],
            entry_resolve_receipts: vec![
                EntryResolveReceipt {
                    entry: "a.dag".to_string(),
                    closure_subject: "subj-a".to_string(),
                    resolve_nanos: 100,
                    stage_nanos: ResolveStageNanos::default(),
                },
                EntryResolveReceipt {
                    entry: "b.dag".to_string(),
                    closure_subject: "subj-b".to_string(),
                    resolve_nanos: 200,
                    stage_nanos: ResolveStageNanos::default(),
                },
            ],
            total_resolve_nanos: 300,
            total_stage_nanos: ResolveStageNanos::default(),
            performance_receipts: vec![
                PerformanceReceipt {
                    subject_key: "subj-a".to_string(),
                    work_shape: "claim".to_string(),
                    wall_nanos: 1_000,
                    cpu_nanos: 1_000,
                    eval_self_nanos: 1_000,
                    sample_count: 1,
                },
                PerformanceReceipt {
                    subject_key: "subj-b".to_string(),
                    work_shape: "claim".to_string(),
                    wall_nanos: 50_000,
                    cpu_nanos: 50_000,
                    eval_self_nanos: 50_000,
                    sample_count: 1,
                },
                PerformanceReceipt {
                    subject_key: "subj-a".to_string(),
                    work_shape: "claim".to_string(),
                    wall_nanos: 5_000,
                    cpu_nanos: 5_000,
                    eval_self_nanos: 5_000,
                    sample_count: 1,
                },
            ],
            total_measured_nanos: 56_000,
            roster_closure_nodes: 42,
            total_entry_groups: 2,
            selected_entry_groups: 2,
        }
    }

    #[test]
    fn merge_discovery_summaries_takes_max_roster_closure() {
        // Per-shard closure is MAX-merged, not summed: parallel shards share the std/spec prefix, so
        // summing would double-count it; the heaviest single shard's closure is what the per-shard
        // memory peak is a function of. RED if a future edit sums the field (would be 101), drops the
        // merge line (would stay 0), or reverts the carrier.
        let mut a = sample_summary();
        a.roster_closure_nodes = 30;
        let mut b = sample_summary();
        b.roster_closure_nodes = 71;
        let merged = merge_discovery_summaries(vec![a, b]);
        assert_eq!(merged.roster_closure_nodes, 71);
    }

    #[test]
    fn production_witness_cost_projection_preserves_failed_and_refused() {
        let mut summary = sample_summary();
        summary.witness_outcomes.truncate(2);
        summary.performance_receipts.truncate(2);
        summary.entry_resolve_receipts.truncate(2);
        summary.witness_outcomes[0].outcome = ClaimOutcome::Fail;
        summary.witness_outcomes[1].outcome = ClaimOutcome::NotBool {
            got: "String".to_string(),
        };
        summary.performance_receipts[0].wall_nanos = 7_000_000;
        summary.performance_receipts[1].wall_nanos = 19_000_000;
        summary.entry_resolve_receipts[0].resolve_nanos = 100_000_000;
        summary.entry_resolve_receipts[1].resolve_nanos = 200_000_000;

        let rows =
            project_witness_cost_receipt(&source_roots(), &summary).expect("authored projection");
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0].eval_wall_nanos, 7_000_000);
        assert_eq!(rows[0].warm_nanos, 107_000_000);
        assert_eq!(rows[0].outcome, "Failed");
        assert_eq!(rows[0].detail, "returned Bool(false)");
        assert_eq!(rows[1].outcome, "Refused");
        assert_eq!(rows[1].detail, "returned `String`, not Bool");
    }

    #[test]
    fn production_witness_cost_projection_preserves_exact_nanoseconds_and_ordering() {
        let mut summary = sample_summary();
        for (outcome, function) in summary
            .witness_outcomes
            .iter_mut()
            .zip(["one_ns", "sub_ms", "one_ms"])
        {
            outcome.entry = "a.dag".to_string();
            outcome.module_path = "a".to_string();
            outcome.function = function.to_string();
        }
        summary.entry_resolve_receipts.truncate(1);
        summary.entry_resolve_receipts[0].resolve_nanos = 7;
        for (receipt, nanos) in summary
            .performance_receipts
            .iter_mut()
            .zip([1, 999_999, 1_000_000])
        {
            receipt.wall_nanos = nanos;
            receipt.eval_self_nanos = nanos;
        }

        let rows =
            project_witness_cost_receipt(&source_roots(), &summary).expect("authored projection");
        assert_eq!(rows.len(), 3);
        assert_eq!(rows[0].function, "one_ns");
        assert_eq!(rows[0].eval_wall_nanos, 1);
        assert_eq!(rows[0].resolve_nanos, 7);
        assert_eq!(rows[0].warm_nanos, 8);
        assert_eq!(rows[1].function, "sub_ms");
        assert_eq!(rows[1].eval_wall_nanos, 999_999);
        assert_eq!(rows[1].warm_nanos, 1_000_006);
        assert_eq!(rows[2].function, "one_ms");
        assert_eq!(rows[2].eval_wall_nanos, 1_000_000);
        assert_eq!(rows[2].warm_nanos, 1_000_007);

        let slowest = top_n_slowest_witnesses(&rows, rows.len());
        assert_eq!(
            slowest
                .iter()
                .map(|row| row.function.as_str())
                .collect::<Vec<_>>(),
            vec!["one_ms", "sub_ms", "one_ns"]
        );
        let histogram = compute_histogram_data(&rows);
        assert_eq!(histogram.eval.p50, 999_999);
        assert_eq!(histogram.eval.p100, 1_000_000);
    }

    #[test]
    fn production_witness_cost_projection_refuses_missing_and_duplicate_parent() {
        let mut summary = sample_summary();
        summary.witness_outcomes.truncate(1);
        summary.performance_receipts.truncate(1);
        summary.entry_resolve_receipts.clear();
        let missing = project_witness_cost_receipt(&source_roots(), &summary)
            .expect_err("authored projector must refuse missing parent");
        assert!(
            missing.contains("missing parent resolve-phase event"),
            "{missing}"
        );

        summary.entry_resolve_receipts = vec![
            EntryResolveReceipt {
                entry: "a.dag".to_string(),
                closure_subject: "subj-a".to_string(),
                resolve_nanos: 100_000_000,
                stage_nanos: ResolveStageNanos::default(),
            },
            EntryResolveReceipt {
                entry: "a.dag".to_string(),
                closure_subject: "subj-a-duplicate".to_string(),
                resolve_nanos: 200_000_000,
                stage_nanos: ResolveStageNanos::default(),
            },
        ];
        let duplicate = project_witness_cost_receipt(&source_roots(), &summary)
            .expect_err("authored projector must refuse duplicate parent");
        assert!(
            duplicate.contains("multiple parent resolve-phase events"),
            "{duplicate}"
        );
    }

    #[test]
    fn production_discovery_projects_one_real_witness() {
        let roots = source_roots();
        let entry = std::path::Path::new(&roots[0])
            .join("test/claim/witness_row_cost_projection_witness_test.dag")
            .to_string_lossy()
            .into_owned();
        let function = "witness_row_cost_projection_holds".to_string();
        // Execution-leg derivation has its own discriminating test and currently resolves a
        // workspace-relative authority against process CWD. Cargo runs unit tests from the
        // package directory, so prime the independently proven default for this fixture rather
        // than mutating process-wide CWD. The discovery, timing, event, and projection path below
        // remains the production path this test owns.
        witness_execution_leg_cache_put(&repo_relative_dag_path(&entry), "InterpretedLeg");
        let summary = run_discovery_corpus_with_options(
            &roots,
            &[],
            &[(entry.clone(), function.clone())],
            ExecutionMode::Hermetic,
            DiscoveryWidthPolicy::Serial,
            DiscoveryCorpusOptions {
                execution_authority_source_roots: roots.clone(),
                explicit_roster_only: true,
                exclude_substrings: Vec::new(),
                ..Default::default()
            },
        )
        .expect("one-row discovery must execute");
        assert_eq!(summary.total, 1);
        assert_eq!(summary.passed, 1);
        assert_eq!(summary.witness_outcomes.len(), 1);
        assert_eq!(summary.entry_resolve_receipts.len(), 1);

        let rows = project_witness_cost_receipt(&roots, &summary)
            .expect("real discovery summary must pass the authored projector");
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].entry, entry);
        assert_eq!(rows[0].function, function);
        assert_eq!(rows[0].outcome, "Done");
        assert_eq!(rows[0].detail, "");
    }
}

pub struct LayerImportFactRaw {
    pub layer: &'static str,
    pub path: String,
    pub import_module: String,
}

const LAYER_STD: &str = "LayerPrefixStd";
const LAYER_EXTDEPS: &str = "LayerPrefixExtdeps";
const LAYER_COMPILER: &str = "LayerPrefixCompiler";
const LAYER_WORKFLOW: &str = "LayerPrefixWorkflow";

// SCAFFOLD (§7 HAND-RUST — authority: `v2.std.cross_tree.resolution.layer_prefix_from_dotted_qualified_name`).
// Host `layer_import_facts` must stamp `LayerImportFact.layer` on every emitted row; the builtin
// seam cannot call the `.dag` classifier without an interpreter round-trip per file. This mirror
// is byte-synced to that authority and carries an explicit dissolution trigger — not a second
// permanent taxonomy.
// 🟡 dissolve-on: `layer_import_facts` host builtin routes `layer` through interpreter eval of
// `layer_prefix_from_dotted_qualified_name` (or a shared host projection registered beside
// `reference_resolution_facts`), deleting this Rust copy when namespace terminal step Phase 3 lands.
pub(crate) const CLI_RUN_LAYER_PREFIX_FROM_DOTTED_MODULE_SCAFFOLD_MARKER: &str =
    "cli_run_layer_prefix_from_dotted_module_scaffold";

/// Rust mirror of `v2.std.cross_tree.resolution.layer_prefix_from_dotted_qualified_name`.
/// See `CLI_RUN_LAYER_PREFIX_FROM_DOTTED_MODULE_SCAFFOLD_MARKER`.
fn layer_prefix_from_dotted_module(module: &str) -> &'static str {
    let parts: Vec<&str> = module.split('.').filter(|p| !p.is_empty()).collect();
    if parts.is_empty() {
        return LAYER_STD;
    }
    match parts[0] {
        "v2" => match parts.get(1) {
            None => LAYER_STD,
            Some(&"std") => LAYER_STD,
            Some(&"extdeps") => LAYER_EXTDEPS,
            Some(&"compiler") => LAYER_COMPILER,
            Some(&"workflow") => LAYER_WORKFLOW,
            Some(&"lens") | Some(&"test") => LAYER_COMPILER,
            Some(_) => LAYER_COMPILER,
        },
        "extdeps" => LAYER_EXTDEPS,
        "std" => LAYER_STD,
        "compiler" | "lens" | "test" => LAYER_COMPILER,
        "workflow" | "gunbc" | "tools" => LAYER_WORKFLOW,
        _ => LAYER_STD,
    }
}

fn rel_path_for_layer_import(path: &Path) -> String {
    if path.is_relative() {
        return path.to_string_lossy().replace('\\', "/");
    }
    repo_relative_path_normalized(path)
}

fn pool_roots_abs(pool_roots: &[String]) -> Vec<String> {
    pool_roots.iter().map(|r| anchor_source_root(r)).collect()
}

fn collect_layer_import_scoped_paths(roots: &[String]) -> HashSet<String> {
    let mut scoped = HashSet::new();
    for root in roots {
        let Some(abs_root) = try_anchor_source_root(root) else {
            continue;
        };
        let root_path = Path::new(&abs_root);
        if !root_path.is_dir() {
            continue;
        }
        let mut dag_files: Vec<PathBuf> = Vec::new();
        collect_dag_files_tolerant(root_path, &mut dag_files);
        for file in dag_files {
            scoped.insert(rel_path_for_layer_import(&file));
        }
    }
    scoped
}

/// Cheap preflight: the reference arm parses the witness-layer pool and is reserved for
/// import-less files only (transitional producer §3.1). When every scoped file still carries
/// `import` lines, import-syntax facts are complete and the reference pass is skipped.
fn importer_roots_have_importless_dag_files(roots: &[String]) -> bool {
    for root in roots {
        let Some(abs_root) = try_anchor_source_root(root) else {
            continue;
        };
        let root_path = Path::new(&abs_root);
        if !root_path.is_dir() {
            continue;
        }
        let mut dag_files: Vec<PathBuf> = Vec::new();
        collect_dag_files_tolerant(root_path, &mut dag_files);
        for file in dag_files {
            let content = match std::fs::read_to_string(&file) {
                Ok(c) => c,
                Err(_) => continue,
            };
            if extract_module_path(&content).is_some() && extract_import_paths(&content).is_empty()
            {
                return true;
            }
        }
    }
    false
}

fn project_layer_import_syntax_facts(
    root: &str,
    out: &mut Vec<LayerImportFactRaw>,
    seen: &mut HashSet<(String, String)>,
) {
    let Some(abs_root) = try_anchor_source_root(root) else {
        eprintln!(
            "[layer-import] declared root {root} absent on disk — skipped, no import-syntax facts projected"
        );
        return;
    };
    let root_path = Path::new(&abs_root);
    if !root_path.is_dir() {
        return;
    }
    let mut dag_files: Vec<PathBuf> = Vec::new();
    collect_dag_files_tolerant(root_path, &mut dag_files);
    dag_files.sort();
    for file in dag_files {
        let content = match std::fs::read_to_string(&file) {
            Ok(c) => c,
            Err(_) => continue,
        };
        if extract_import_paths(&content).is_empty() {
            continue;
        }
        let rel = rel_path_for_layer_import(&file);
        let importer = extract_module_path(&content).unwrap_or_default();
        let layer = layer_prefix_from_dotted_module(&importer);
        for import_module in extract_import_paths(&content) {
            if seen.insert((rel.clone(), import_module.clone())) {
                out.push(LayerImportFactRaw {
                    layer,
                    path: rel.clone(),
                    import_module,
                });
            }
        }
    }
}

/// Layer-scoped dependency edges for `v2.std.layer` (`LayerImportFact`) and sibling consumers.
///
/// Transitional producer (namespace terminal step, docs/plans/layering-imports-reference-repoint-design.md §3.1):
/// import-syntax facts for import-bearing files, plus `reference_edges_as_import_facts(..., strict=true)`
/// for import-less files in the scan roots. Import-syntax wins on `(path, target_module)` collision.
pub fn layer_import_facts(
    std_roots: &[String],
    extdeps_roots: &[String],
) -> Vec<LayerImportFactRaw> {
    let mut out = Vec::new();
    let mut seen: HashSet<(String, String)> = HashSet::new();
    for root in std_roots {
        project_layer_import_syntax_facts(root, &mut out, &mut seen);
    }
    for root in extdeps_roots {
        project_layer_import_syntax_facts(root, &mut out, &mut seen);
    }

    let importer_roots: Vec<String> = std_roots
        .iter()
        .chain(extdeps_roots.iter())
        .cloned()
        .collect();
    if importer_roots_have_importless_dag_files(&importer_roots) {
        // Qualified references (e.g. `v2.compiler.tokenize`) resolve against the full witness-layer
        // module census, not the std/extdeps scan roots alone — same pool/importer split as
        // `build_module_graph_facts_live` selection adjacency.
        let pool_roots = witness_layer_roots();
        let scoped_paths = collect_layer_import_scoped_paths(&importer_roots);
        for edge in reference_edges_as_import_facts(
            &reference_resolution_facts(&pool_roots, &importer_roots, &[]),
            true,
        ) {
            let rel = edge.path.replace('\\', "/");
            if !scoped_paths.contains(&rel) {
                continue;
            }
            if !seen.insert((rel.clone(), edge.import_module.clone())) {
                continue;
            }
            let importer = std::fs::read_to_string(workspace_root().join(&rel))
                .ok()
                .and_then(|content| extract_module_path(&content))
                .unwrap_or_default();
            let layer = layer_prefix_from_dotted_module(&importer);
            out.push(LayerImportFactRaw {
                layer,
                path: rel,
                import_module: edge.import_module,
            });
        }
    }
    out
}

// Host-fed fact extraction for `v2.lens.fact_cardinality` — the lens `.dag` table owns
// verdict logic; this bridge only projects top-level decl keys + content hashes from the
// witness-layer trees. DISSOLUTION: node-tree reader at gunbc#5364; until then one shared
// host seam (Chunk D).
const FACT_CARDINALITY_ITEM_KEYWORDS: [&str; 8] = [
    "data ",
    "fn ",
    "func ",
    "type ",
    "service ",
    "const ",
    "pattern ",
    "resource ",
];

pub struct FactCardinalityDeclFactRaw {
    pub rel_path_decl_key: String,
    pub tree: String,
    pub content_hash: String,
}

fn normalize_decl_body(source: &str) -> String {
    source
        .lines()
        .map(|line| line.split("//").next().unwrap_or(line).trim())
        .filter(|line| !line.is_empty())
        .collect::<Vec<_>>()
        .join("\n")
}

fn decl_body_hash(body: &str) -> String {
    crate::v1_rt::atom_identity_hash(normalize_decl_body(body))
}

/// Kind-agnostic top-level decl extraction (name, content-hash) for cross-tree cardinality.
pub fn extract_top_level_decls(content: &str) -> Vec<(String, String)> {
    let lines: Vec<&str> = content.lines().collect();
    let mut out = Vec::new();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        if line.starts_with("test ") {
            i += 1;
            continue;
        }
        let Some(kw) = FACT_CARDINALITY_ITEM_KEYWORDS
            .iter()
            .find(|kw| line.starts_with(*kw))
        else {
            i += 1;
            continue;
        };
        let rest = &line[kw.len()..];
        let name: String = rest
            .chars()
            .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
            .collect();
        if name.is_empty() {
            i += 1;
            continue;
        }
        let mut body = String::new();
        body.push_str(line);
        body.push('\n');
        i += 1;
        let mut depth = brace_delta(line);
        while i < lines.len() {
            let next = lines[i];
            if depth <= 0
                && FACT_CARDINALITY_ITEM_KEYWORDS
                    .iter()
                    .any(|kw| next.starts_with(kw))
                && !next.starts_with("test ")
            {
                break;
            }
            body.push_str(next);
            body.push('\n');
            depth += brace_delta(next);
            i += 1;
        }
        out.push((name, decl_body_hash(&body)));
    }
    out
}

fn rel_path_within_tree(top_root: &Path, path: &Path) -> String {
    path.strip_prefix(top_root)
        .unwrap_or_else(|_| {
            panic!(
                "fact_cardinality_decl_facts: path {} is not under tree root {}",
                path.display(),
                top_root.display()
            )
        })
        .to_string_lossy()
        .replace('\\', "/")
}

fn walk_fact_cardinality_tree_dir(
    top_root: &Path,
    dir: &Path,
    tree: &str,
    records: &mut Vec<FactCardinalityDeclFactRaw>,
) {
    let entries = std::fs::read_dir(dir).unwrap_or_else(|e| {
        panic!(
            "fact_cardinality_decl_facts: failed to read dir {}: {e}",
            dir.display()
        )
    });
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            walk_fact_cardinality_tree_dir(top_root, &path, tree, records);
            continue;
        }
        if path.extension().and_then(|e| e.to_str()) != Some("dag") {
            continue;
        }
        let rel = rel_path_within_tree(top_root, &path);
        let content = std::fs::read_to_string(&path).unwrap_or_else(|e| {
            panic!(
                "fact_cardinality_decl_facts: failed to read {}: {e}",
                path.display()
            )
        });
        for (name, hash) in extract_top_level_decls(&content) {
            records.push(FactCardinalityDeclFactRaw {
                rel_path_decl_key: format!("{rel}:{name}"),
                tree: tree.to_string(),
                content_hash: hash,
            });
        }
    }
}

fn walk_fact_cardinality_tree(
    top_root: &Path,
    tree: &str,
    records: &mut Vec<FactCardinalityDeclFactRaw>,
) {
    if !top_root.is_dir() {
        panic!(
            "fact_cardinality_decl_facts: tree root {} does not exist",
            top_root.display()
        );
    }
    walk_fact_cardinality_tree_dir(top_root, top_root, tree, records);
}

pub fn fact_cardinality_decl_facts() -> Vec<FactCardinalityDeclFactRaw> {
    let ws = workspace_root();
    let mut records = Vec::new();
    for root in witness_layer_roots() {
        let tree = Path::new(&root)
            .file_name()
            .expect("ci_layer_roots: each root must have a file_name component")
            .to_string_lossy()
            .into_owned();
        walk_fact_cardinality_tree(&ws.join(&root), &tree, &mut records);
    }
    records
}

#[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
pub struct ImportResolutionFactRaw {
    pub path: String,
    pub import_module: String,
    pub target_declared: bool,
}

#[derive(Clone, Debug, serde::Serialize, serde::Deserialize)]
pub struct ModuleDeclarationFactRaw {
    pub module: String,
    pub path: String,
}

fn is_excluded_import_path(rel: &str, exclude_substrings: &[String]) -> bool {
    exclude_substrings.iter().any(|s| rel.contains(s.as_str()))
}

// Per-call counters for the two host builtins the `.dag` interpreter actually invokes when a
// `.dag` fold reads `import_resolution_facts_live`/`module_declaration_facts_live` (e.g.
// `v2.lens.module_graph.import_closure_live`). Distinct from `MODULE_GRAPH_FACTS_BUILD_COUNT`
// above, which counts the separate Rust-side `build_module_graph_facts_live` batching path used
// by `current_entry_closure_files` — the two paths are not the same call site, so a cost receipt
// comparing them needs its own counter (module-grain affected-set equivalence receipt).
#[cfg(test)]
static IMPORT_RESOLUTION_FACTS_CALL_COUNT: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);
#[cfg(test)]
static MODULE_DECLARATION_FACTS_CALL_COUNT: std::sync::atomic::AtomicUsize =
    std::sync::atomic::AtomicUsize::new(0);

#[cfg(test)]
pub(crate) fn reset_import_resolution_facts_call_counts_for_test() {
    IMPORT_RESOLUTION_FACTS_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
    MODULE_DECLARATION_FACTS_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
}

#[cfg(test)]
pub(crate) fn import_resolution_facts_call_count_for_test() -> usize {
    IMPORT_RESOLUTION_FACTS_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
}

#[cfg(test)]
pub(crate) fn module_declaration_facts_call_count_for_test() -> usize {
    MODULE_DECLARATION_FACTS_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
}

/// The import-facts walk plus what it OBSERVED: every in-scope `.dag` path the walk
/// saw on disk, and every path whose content read refused. The skip arm on an
/// unreadable file used to be silent (`Err(_) => continue`), which made a vanished
/// module indistinguishable from an absent one — the fail-open undercount the facts
/// consumers must refuse on (operator review 2026-07-28, PR #7384). One walk,
/// projected two ways: `import_resolution_facts` stays the thin fact projection.
pub(crate) struct ImportResolutionObservation {
    pub(crate) facts: Vec<ImportResolutionFactRaw>,
    /// Workspace-relative `.dag` paths seen by the importer walk (post-exclusion),
    /// whether or not their content produced facts.
    pub(crate) observed_paths: HashSet<String>,
    /// (path, error) for every observed file whose content read refused — sorted by
    /// walk order (deterministic: the walk sorts per root).
    pub(crate) read_refusals: Vec<(String, String)>,
}

pub(crate) fn import_resolution_facts_with_observation(
    pool_roots: &[String],
    importer_roots: &[String],
    exclude_substrings: &[String],
) -> ImportResolutionObservation {
    #[cfg(test)]
    IMPORT_RESOLUTION_FACTS_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let abs_pool_roots = pool_roots_abs(pool_roots);
    let abs_importer_roots = pool_roots_abs(importer_roots);
    let declared: HashSet<String> = build_module_path_index(&abs_pool_roots)
        .into_iter()
        .map(|(k, _)| k)
        .collect();
    let mut out = Vec::new();
    let mut observed_paths: HashSet<String> = HashSet::new();
    let mut read_refusals: Vec<(String, String)> = Vec::new();
    for root in &abs_importer_roots {
        let root_path = Path::new(root);
        if !root_path.is_dir() {
            continue;
        }
        let mut dag_files: Vec<PathBuf> = Vec::new();
        collect_dag_files_tolerant(root_path, &mut dag_files);
        dag_files.sort();
        for file in dag_files {
            let rel = rel_path_for_layer_import(&file);
            if is_excluded_import_path(&rel, exclude_substrings) {
                continue;
            }
            observed_paths.insert(workspace_relative_repo_path(&rel));
            let content = match std::fs::read_to_string(&file) {
                Ok(c) => c,
                Err(e) => {
                    read_refusals.push((workspace_relative_repo_path(&rel), e.to_string()));
                    continue;
                }
            };
            for import_module in extract_import_paths(&content) {
                let target_declared = declared.contains(&import_module);
                out.push(ImportResolutionFactRaw {
                    path: rel.clone(),
                    import_module,
                    target_declared,
                });
            }
        }
    }
    ImportResolutionObservation {
        facts: out,
        observed_paths,
        read_refusals,
    }
}

pub fn import_resolution_facts(
    pool_roots: &[String],
    importer_roots: &[String],
    exclude_substrings: &[String],
) -> Vec<ImportResolutionFactRaw> {
    import_resolution_facts_with_observation(pool_roots, importer_roots, exclude_substrings).facts
}

/// The native realization of `v2.lens.module_graph` `dependency_resolution_facts_live`: both
/// leaves, unioned reference-first through the one dedup authority below, projected to the
/// dependency-edge triple. `target_module` is the fact's `import_module` — the same renaming the
/// `.dag` `import_fact_to_dependency_edge` performs, and the reason this returns the raw fact rows
/// rather than a second edge struct is that the projection is a rename, not a transformation.
pub fn dependency_resolution_facts(
    pool_roots: &[String],
    importer_roots: &[String],
    exclude_substrings: &[String],
) -> Vec<ImportResolutionFactRaw> {
    let reference_edges = reference_edges_as_import_facts(
        &reference_resolution_facts(pool_roots, importer_roots, exclude_substrings),
        /* strict */ true,
    );
    let import_edges = import_resolution_facts(pool_roots, importer_roots, exclude_substrings);
    union_dedup_import_facts_reference_first(reference_edges, import_edges)
}

/// THE UNION, ONCE. Reference-first exact dedup over `{path, import_module, target_declared}`,
/// keeping first occurrence and therefore a stable order.
///
/// This is the single authority for a union that had two independent spellings: the `.dag`
/// `union_import_resolution_fact_lists` (reference-first, exact dedup, interpreted) and the host
/// selection-graph twin's `selection_edges` (import-first, dedup deferred to adjacency
/// construction). Two spellings of one concept is the §3 fork; one helper consumed by both is the
/// repair, and it is what lets the interpreted composition be retired without the native producer
/// answering a different question.
///
/// WHY IT IS NATIVE. Measured on the live corpus in one process: the two host leaves cost 146ms
/// and 5ms, while the interpreted union+dedup over the ~18.5k unioned facts cost 104,943ms — the
/// whole of `dependency_resolution_facts_live`'s 112,261ms, and effectively the whole of the
/// partition-closure census that consumes it. The cost is the interpreted composition, not the
/// corpus scan, so caching the leaves recovers 151ms of 112,000ms and the fold has to go.
///
/// EXACTNESS IS THE CONTRACT, not a nicety: the partition-closure census judges unresolved targets,
/// so `target_declared: false` rows must survive, and equality is the same three-field identity the
/// `.dag` `import_resolution_fact_eq` decides. Nothing here may collapse to a coarser adjacency.
pub(crate) fn union_dedup_import_facts_reference_first(
    reference_edges: Vec<ImportResolutionFactRaw>,
    import_edges: Vec<ImportResolutionFactRaw>,
) -> Vec<ImportResolutionFactRaw> {
    let mut seen: HashSet<(String, String, bool)> =
        HashSet::with_capacity(reference_edges.len() + import_edges.len());
    let mut out: Vec<ImportResolutionFactRaw> =
        Vec::with_capacity(reference_edges.len() + import_edges.len());
    for fact in reference_edges.into_iter().chain(import_edges.into_iter()) {
        let key = (
            fact.path.clone(),
            fact.import_module.clone(),
            fact.target_declared,
        );
        if seen.insert(key) {
            out.push(fact);
        }
    }
    out
}

pub fn module_declaration_facts(pool_roots: &[String]) -> Vec<ModuleDeclarationFactRaw> {
    #[cfg(test)]
    MODULE_DECLARATION_FACTS_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let abs_pool_roots = pool_roots_abs(pool_roots);
    let mut out: Vec<ModuleDeclarationFactRaw> = build_module_path_index(&abs_pool_roots)
        .into_iter()
        .map(|(module, path)| ModuleDeclarationFactRaw { module, path })
        .collect();
    out.sort_by(|a, b| a.module.cmp(&b.module));
    out
}

// ── Reference-derived module edges (namespace terminal step, DESIGN "deps via container.member") ──
//
// SCAFFOLD (DESIGN §7). Replaces the import-parse module graph (`extract_import_paths` /
// `import_resolution_facts`) with edges derived from where a module's body/type REFERENCES resolve,
// so the module graph survives corpus-wide `import` deletion (namespace-only resolution, operator-
// signed 2026-07-06; the reference is the sole representation of usage, Rule 1). One O(corpus) parse
// pass over the pool (reusing the real front-end `tokenize` + `parse` — no substring scan), cached.
// Consumers (`build_module_graph_facts_live`, affected-set selection) union these edges onto the import
// edges during the transition; when the import grammar is deleted (parent's terminal step) the import
// term is empty and the module graph is reference-only, the `src/v2/lens/module_graph.dag`
// single-swap-point end state. Every closure/loader/lens consumer is edge-source-agnostic (reads edge
// rows as data, never import syntax).
//
// Confidence tag (parent ruling, 2026-07-14; DESIGN §5): the LOADER closure and affected-set read
// ALL edges (over-load is safe — a superset only compiles extra modules). SELECTION reads
// Qualified + UniqueBare only (dropping AmbiguousBare), so an over-connected graph cannot silently
// widen the selection tier. (The inert-lens reach was the other reader of that tier until gunbc#8141
// deleted it.) AmbiguousBare is a bare identifier declared in >1
// module; under namespace-only that is a Rule-2 ambiguity the source should qualify.
//
// Dissolve-on: `symbol_index_fill` (SymbolIndex lane) projects exact, scope-aware reference edges from
// the filled containment tree; when that lands, this parse-and-index approximation (which is liberal
// on bare-name reference collection — a local binder that shadows a globally-unique declared name
// yields a spurious UniqueBare edge, safe for the loader, tolerated at the selection grain) deletes.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum RefEdgeResolution {
    Qualified,
    UniqueBare,
    AmbiguousBare,
}

impl RefEdgeResolution {
    fn rank(self) -> u8 {
        match self {
            RefEdgeResolution::Qualified => 2,
            RefEdgeResolution::UniqueBare => 1,
            RefEdgeResolution::AmbiguousBare => 0,
        }
    }
}

#[derive(Clone)]
pub struct ReferenceEdgeRaw {
    pub path: String,
    pub target_module: String,
    pub resolution: RefEdgeResolution,
}

/// Project reference edges into the `ImportResolutionFactRaw` channel the module-graph adjacency and
/// closure consumers already read (the `module_graph.dag` single-swap-point contract — downstream is
/// edge-source-agnostic). `strict` drops `AmbiguousBare` edges.
///
/// The tier is per-CONSUMER and the two are not interchangeable:
///   - `false` (keep AmbiguousBare) for the LOADER — over-connection is harmless there, since a
///     superset only compiles extra modules.
///   - `true` for SELECTION — over-connection is not a safety problem
///     here, it is what destroys the answer. Measured: at `false` an entry's median closure is
///     1136 of 2240 modules (homonyms fan every referrer across the pool); at `true` it is 96,
///     the same order as the import-only baseline's 54.
/// Grouping these two under one tier is what made the 2026-07-14 selection repoint look
/// impossible — see `build_module_graph_facts_live_uncached`.
pub fn reference_edges_as_import_facts(
    edges: &[ReferenceEdgeRaw],
    strict: bool,
) -> Vec<ImportResolutionFactRaw> {
    edges
        .iter()
        .filter(|e| !strict || e.resolution != RefEdgeResolution::AmbiguousBare)
        .map(|e| ImportResolutionFactRaw {
            path: e.path.clone(),
            import_module: e.target_module.clone(),
            target_declared: true,
        })
        .collect()
}

/// Parse a `.dag` module's source text through the real front-end. Returns the module node, or
/// `None` on a parse error (the whole-tree compile reports such errors loudly; the module graph
/// simply omits its edges, and the corpus stays green because a syntax-broken file never resolves).
fn parse_module_node_tolerant(rel: &str, content: &str) -> Option<Rc<crate::v1_std_core::Node>> {
    let filename = rel.to_string();
    let tokens = crate::v1_compiler_tokenize::tokenize(content.to_string(), filename.clone());
    let source_index =
        crate::v1_std_core::build_newline_index(filename.clone(), content.to_string());
    let mut source_indices = HashMap::new();
    source_indices.insert(filename.clone(), source_index);
    let result = crate::v1_compiler_parse::parse(tokens, std::rc::Rc::new(source_indices));
    if result.error.is_some() {
        return None;
    }
    result.module.clone()
}

/// The names a module EXPORTS (what an `import M { X }` could once have listed): every top-level
/// item name, plus coproduct variant constructors (not record field labels — those are not
/// importable symbols and poison the name→module index when record literals use them as labels).
/// Precise by construction — fn-body locals and params are never descended into — so the
/// name→module index is not poisoned by incidental identifiers.
fn collect_module_decl_names(module: &Rc<crate::v1_std_core::Node>) -> Vec<String> {
    use crate::v1_compiler_emit_core_support::is_type_def_item;
    use crate::v1_std_core::Connective;
    let mut names = Vec::new();
    for item in module.children.iter() {
        if !item.name.is_empty() {
            names.push(item.name.clone());
        }
        if is_type_def_item(item.clone()) && item.connective == Connective::Disj {
            for variant in item.children.iter() {
                if !variant.name.is_empty() {
                    names.push(variant.name.clone());
                }
            }
        }
    }
    names
}

/// Reconstruct a qualified-name segment list from a `FieldAccess` chain (`A.B.c` → `[A, B, c]`).
/// `None` when the base is not a plain identifier (e.g. a call result `f(x).field` — that is a
/// value field access, not a module-qualified name).
fn ref_field_chain(node: &Rc<crate::v1_std_core::Node>) -> Option<Vec<String>> {
    use crate::v1_std_core::ExprData;
    let mut segs: Vec<String> = vec![node.name.clone()];
    let mut cur = node.children.get(0).cloned()?;
    loop {
        match &*cur.expr_data {
            ExprData::ExprFieldAccess { .. } => {
                segs.push(cur.name.clone());
                cur = cur.children.get(0).cloned()?;
            }
            ExprData::ExprVar { .. } => {
                segs.push(cur.name.clone());
                break;
            }
            _ => return None,
        }
    }
    segs.reverse();
    if segs.iter().any(|s| s.is_empty()) {
        return None;
    }
    Some(segs)
}

/// Walk a type subtree collecting identifier names at type positions (type constructors, type
/// parameters referenced in signatures). Used for import-less reference edges; over-collects local
/// type-param binders, which is safe for the loader and tolerated at the strict selection tier.
fn collect_type_ref_names(
    node: &Rc<crate::v1_std_core::Node>,
    bare: &mut std::collections::HashSet<String>,
) {
    if !node.name.is_empty() {
        bare.insert(node.name.clone());
    }
    for c in node.children.iter() {
        collect_type_ref_names(c, bare);
    }
    for p in node.params.iter() {
        collect_type_ref_names(p, bare);
    }
    if let Some(t) = &node.type_annotation {
        collect_type_ref_names(t, bare);
    }
}

/// Walk a declaration subtree collecting cross-module reference use sites: value calls/vars,
/// variant constructors, qualified-name chains, and type-annotation identifiers. Binders (params,
/// `let` bindings, lambda parameters, match-pattern fields, record-literal labels) are excluded,
/// because the liberal `node.name` scan this replaced was attributing local names like `items`
/// and `r` to unrelated extdeps modules.
///
/// EXCLUDING BINDERS BY BINDING KIND WAS THE DEFECT, AND IT FAILED SILENTLY FOR THE LIFETIME OF
/// THE FUNCTION. The previous form kept an `ExprVar` only when its `binding_kind` was
/// `Some(FunctionValueBinding)`, which reads as "keep the references, drop the locals" and does
/// nothing at all: `binding_kind` is stamped by `infer_var_binding_kind` on inference's own
/// representation and is `None` on every node of the PREPARED tree this walk reads. Measured on
/// the prepared corpus: 205,609 `ExprVar` nodes, 205,609 of them unstamped, zero of any other
/// kind. So the predicate matched nothing, no bare variable reference ever produced a reference
/// edge, and every edge this index has ever carried came from `ExprCall`, `ExprRecordLit`, field
/// chains and type annotations.
///
/// THE FAILURE DIRECTION IS WHAT MADE IT INVISIBLE. A predicate matching on a field its input
/// never populates is indistinguishable from a correct one by reading, by typecheck and by grep;
/// it does not refuse, it returns an empty set. The consumer gets a smaller closure and the
/// damage surfaces as a runtime throw somewhere else entirely — measured on floor run
/// 32621117917, 170 enrolled claims that threw `no such function: <a data row in another module>`
/// instead of reaching a verdict.
///
/// SO THE SEPARATION IS STRUCTURAL, because the stamp carries no information here. `bound` holds
/// the names an enclosing binder introduced and a name in it is never a reference. The remaining
/// failure directions are deliberately asymmetric: over-binding drops an edge and silently
/// reproduces exactly the defect above, while under-binding admits a local name and merely widens
/// the scope — which is observable as `PreparedClaimScope::module_count` and as
/// `ambiguous_bare_names`. The design whose failure mode is measurable is the correct trade.
fn collect_node_refs(
    node: &Rc<crate::v1_std_core::Node>,
    bare: &mut std::collections::HashSet<String>,
    chains: &mut Vec<Vec<String>>,
    source_indices: &Rc<HashMap<String, Rc<NewlineIndex>>>,
    classify: &mut ExprVarClassification<'_>,
) {
    let mut bound: Vec<(String, ExprVarClass)> = Vec::new();
    collect_node_refs_inner(
        node,
        bare,
        chains,
        false,
        false,
        &mut bound,
        source_indices,
        classify,
    );
}

/// WHERE EVERY `ExprVar` GOES, AS A CLOSED SET RATHER THAN A RESIDUE.
///
/// The defect this replaces classified by subtraction: keep the ones whose binding kind is
/// `Some(FunctionValueBinding)`, and whatever is left is not a reference. A residue cannot be
/// audited — a name that fits none of the author's cases lands on one side or the other with
/// nothing announcing it, which is how an arm that matched NOTHING went unnoticed for the
/// lifetime of the function. Here every occurrence reaches exactly one member, the reference set
/// is the members that ARE references by construction, and the member for "fits nothing" exists
/// so that it can be counted rather than assumed away.
///
/// WHAT THIS DOES AND DOES NOT GUARANTEE, at the grain the honest claim allows: it is total over
/// ONE node kind (`ExprData::ExprVar`) under ONE classification. It is NOT a claim that arm
/// reachability is decidable in general — "can this match arm ever be taken" is not a property
/// worth a general wall, and nothing here promises one. What is decidable, and all that is
/// claimed, is that this particular syntactic classification covers this particular node kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum ExprVarClass {
    /// Bound by an enclosing declaration's or lambda's parameter.
    BoundByParameter,
    /// Bound by a `let` earlier in the same block.
    BoundByLet,
    /// Bound by an enclosing match pattern.
    BoundByMatchPattern,
    /// Not bound here, and this module declares it — resolves locally, no cross-module edge.
    DeclaredInThisModule,
    /// Not bound here, and some other module declares it — the cross-module reference edge that
    /// the previous form could never record.
    DeclaredElsewhere,
    /// The innermost receiver of a dotted chain (`extdeps` in `extdeps.browser.chromium`). The
    /// chain is recorded WHOLE by the dotted scan at the field-access node above, so the head is
    /// already accounted for; classifying it again as a bare name would ask the wrong question of
    /// it — a chain head names a module path segment, not a declaration this module could hold.
    QualifiedChainHead,
    /// Not bound, not a chain head, and declared by no module in the subject. Kept as a member so
    /// the population is observable; it is the arm whose silence produced this defect.
    NamesNothingKnown,
}

/// Classification state for one module's walk. Carries the corpus-wide declaration index, which
/// is why the index build runs declarations first and classification second.
struct ExprVarClassification<'a> {
    /// EXACT RECONCILIATION, PUBLISHED. Every traversed occurrence lands in exactly one of
    /// `free_reference_edges`, `bound_occurrences_suppressed`, `chain_head_occurrences` or
    /// `NamesNothingKnown`, with an unsupported binder refusing outright, and
    /// the identity is asserted before the index is published. A counter set that does not add
    /// up means an occurrence vanished, which is the failure this whole change exists to make
    /// unrepresentable — so it refuses rather than reporting a plausible smaller closure.
    occurrences: usize,
    free_reference_edges: usize,
    bound_occurrences_suppressed: usize,
    chain_head_occurrences: usize,
    refusals: Vec<String>,
    /// `None` where the caller has no declaration index — see `reference_resolution_facts`,
    /// which runs before any subject is prepared. Absent is spelled as absent rather than as an
    /// empty map, because an empty map would answer "no module declares this name" to every
    /// question and silently collect nothing: ⊥-as-answer standing in for ⊥-as-ignorance.
    decl_index: Option<&'a HashMap<String, std::collections::BTreeSet<String>>>,
    tally: &'a mut BTreeMap<ExprVarClass, usize>,
    unclassified: &'a mut Vec<String>,
    /// The module currently being walked. ONE classification spans the whole index build so the
    /// reconciliation identity is over the same population as the tally; walking per-module with
    /// per-module counters against a shared tally would compare two different denominators.
    module: String,
}

impl ExprVarClassification<'_> {
    /// Assign one occurrence and answer whether it is a reference edge. Total: every input
    /// reaches exactly one `ExprVarClass`.
    /// A BINDER FORM THIS COLLECTOR CANNOT NAME IS A TYPED REFUSAL, NOT A GUESS IN EITHER
    /// DIRECTION. Assuming bound silently reproduces the under-approximation being removed;
    /// assuming free builds an inflated scope for every claim before anything complains. The
    /// construct is reported and the run stops before any scope is built.
    fn refuse_binder(&mut self, construct: &str, detail: &str) {
        self.refusals.push(format!(
            "{}: unsupported binder syntax {construct} ({detail})",
            self.module
        ));
    }

    fn classify(&mut self, name: &str, bound_as: Option<ExprVarClass>, chain_head: bool) -> bool {
        self.occurrences += 1;
        // THE CHAIN HEAD ARM IS ORDERED LAST, AND THE ORDER IS THE WHOLE CORRECTNESS ARGUMENT.
        // A binder answers first: `fn f(cron: Tab) { cron.List }` reads the parameter. A
        // DECLARATION answers second, because the dotted scan owns only chains whose prefix is a
        // MODULE PATH — `some_data_row.field` is an ordinary value reference that merely looks
        // like one, and suppressing it here DELETES A REAL EDGE. Only a head that is neither
        // bound nor declared anywhere is the module-path segment this member is for.
        let head_is_undeclared = chain_head
            && bound_as.is_none()
            && self
                .decl_index
                .map(|index| !index.contains_key(name))
                .unwrap_or(false);
        if head_is_undeclared {
            *self
                .tally
                .entry(ExprVarClass::QualifiedChainHead)
                .or_insert(0) += 1;
            self.chain_head_occurrences += 1;
            return false;
        }
        let Some(decl_index) = self.decl_index else {
            // No index: this caller cannot decide the unbound cases, so an unbound name keeps
            // this producer's own prior contract of "treat it as a reference and let resolution
            // decide". Counted under the member it would otherwise have to guess at.
            let class = bound_as.unwrap_or(ExprVarClass::DeclaredElsewhere);
            *self.tally.entry(class).or_insert(0) += 1;
            if bound_as.is_none() {
                self.free_reference_edges += 1;
                return true;
            }
            self.bound_occurrences_suppressed += 1;
            return false;
        };
        let class = match bound_as {
            Some(bound) => bound,
            None => match decl_index.get(name) {
                Some(mods) if mods.contains(&self.module) => ExprVarClass::DeclaredInThisModule,
                Some(_) => ExprVarClass::DeclaredElsewhere,
                None => {
                    self.unclassified.push(format!("{}::{name}", self.module));
                    ExprVarClass::NamesNothingKnown
                }
            },
        };
        *self.tally.entry(class).or_insert(0) += 1;
        // Only a name some module declares is an edge. A bound name is not, and a name nothing
        // declares has no target to reach — recording it would invent an edge, not find one.
        let is_edge = matches!(
            class,
            ExprVarClass::DeclaredInThisModule | ExprVarClass::DeclaredElsewhere
        );
        match class {
            ExprVarClass::BoundByParameter
            | ExprVarClass::BoundByLet
            | ExprVarClass::BoundByMatchPattern => self.bound_occurrences_suppressed += 1,
            ExprVarClass::DeclaredInThisModule | ExprVarClass::DeclaredElsewhere => {
                self.free_reference_edges += 1
            }
            // Counted as neither an edge nor a suppression: it is its own member, and the
            // reconciliation below adds it in explicitly rather than letting it hide in one.
            ExprVarClass::NamesNothingKnown => {}
            // Unreachable from here: a chain head returns above, before the declaration index is
            // consulted at all. Named rather than wildcarded so a future member cannot inherit
            // this arm's silence.
            ExprVarClass::QualifiedChainHead => {}
        }
        is_edge
    }

    /// all traversed occurrences == free + bound-suppressed + names-nothing-known.
    fn reconciles(&self) -> bool {
        let names_nothing_known = self
            .tally
            .get(&ExprVarClass::NamesNothingKnown)
            .copied()
            .unwrap_or(0);
        self.occurrences
            == self.free_reference_edges
                + self.bound_occurrences_suppressed
                + self.chain_head_occurrences
                + names_nothing_known
    }
}

/// The names one node's own binder introduces, in the shapes the prepared tree uses: a
/// declaration's or lambda's parameters, and a match arm's pattern bindings. A `let` is NOT here
/// — it binds over its later SIBLINGS rather than over its own subtree, so it is handled where
/// the child list is walked.
fn binder_names_of(
    node: &Rc<crate::v1_std_core::Node>,
    source_indices: &Rc<HashMap<String, Rc<NewlineIndex>>>,
    classify: &mut ExprVarClassification<'_>,
) -> Vec<(String, ExprVarClass)> {
    use crate::v1_std_core::{ExprData, MatchPattern};
    let mut out: Vec<(String, ExprVarClass)> = Vec::new();
    for p in node.params.iter() {
        if p.name.is_empty() {
            classify.refuse_binder("parameter", "declared parameter carries no name");
            continue;
        }
        out.push((p.name.clone(), ExprVarClass::BoundByParameter));
    }
    // A LAMBDA'S PARAMETERS ARE ITS CHILDREN, NOT ITS `params`. `lambda_param_names_at` reads
    // them as children[1..] with the body at child 0, and recovers each name from its authored
    // span — so the same producer the compiler uses answers here rather than a second reading of
    // the shape.
    if matches!(&*node.expr_data, ExprData::ExprLambda) {
        for n in node.children.iter().skip(1) {
            let name = authored_name_at(source_indices.clone(), n.clone());
            if name.is_empty() {
                classify.refuse_binder(
                    "lambda parameter",
                    "no authored name recoverable from its span",
                );
                continue;
            }
            out.push((name, ExprVarClass::BoundByParameter));
        }
    }
    if let Some(mp) = &node.match_pattern {
        pattern_binder_names(mp.clone(), classify, &mut out);
    }
    out
}

/// A match pattern binds names at every depth, so the binder walk is a recursion over the
/// pattern tree rather than a single level of it. A `VariantPattern`'s `field_bindings` carry
/// the FIELD name on the node and the actual binder in that node's own `match_pattern` — for
/// `Present { value: v }` the node is named `value` and its nested pattern is `Bind { v }`, and
/// for the shorthand `Present { value }` the parser synthesises `Bind { value }`. Reading the
/// field name as the binder therefore binds the wrong name in the general case and misses the
/// real one; nested patterns of any depth are handled by the same recursion. A field binding
/// with no nested pattern at all is not a shape this walk understands, so it refuses.
fn pattern_binder_names(
    pattern: Rc<MatchPattern>,
    classify: &mut ExprVarClassification<'_>,
    out: &mut Vec<(String, ExprVarClass)>,
) {
    match &*pattern {
        MatchPattern::Bind { declaration } => {
            if declaration.name.is_empty() {
                classify.refuse_binder("match binding pattern", "binding carries no name");
            } else {
                out.push((declaration.name.clone(), ExprVarClass::BoundByMatchPattern));
            }
        }
        MatchPattern::VariantPattern { field_bindings, .. } => {
            for fb in field_bindings.iter() {
                match &fb.match_pattern {
                    Some(nested) => pattern_binder_names(nested.clone(), classify, out),
                    None => classify.refuse_binder(
                        "variant field binding",
                        "field binding node carries no nested pattern",
                    ),
                }
            }
        }
        MatchPattern::LitPattern { .. } | MatchPattern::Wildcard => {}
    }
}

#[allow(clippy::too_many_arguments)]
fn collect_node_refs_inner(
    node: &Rc<crate::v1_std_core::Node>,
    bare: &mut std::collections::HashSet<String>,
    chains: &mut Vec<Vec<String>>,
    skip_bare_name: bool,
    // `chain_receiver`: true when this node is the receiver position of an enclosing dotted
    // chain that the scan above already recorded WHOLE. It propagates down the receiver spine
    // only, so the head `ExprVar` it terminates at is classified as the chain head it is rather
    // than as a bare name the module fails to declare.
    chain_receiver: bool,
    bound: &mut Vec<(String, ExprVarClass)>,
    source_indices: &Rc<HashMap<String, Rc<NewlineIndex>>>,
    classify: &mut ExprVarClassification<'_>,
) {
    use crate::v1_std_core::{ExprData, MatchPattern};
    let mut receiver_spine = false;
    if let ExprData::ExprFieldAccess { .. } = &*node.expr_data {
        if let Some(chain) = ref_field_chain(node) {
            chains.push(chain);
            receiver_spine = true;
        }
    }
    // This node's own binder — parameters and match-pattern bindings — is in scope for
    // everything below it and is popped on the way out.
    let introduced = binder_names_of(node, source_indices, classify);
    let restore_to = bound.len();
    bound.extend(introduced);
    if !skip_bare_name {
        match &*node.expr_data {
            ExprData::ExprVar { .. } => {
                if !node.name.is_empty() {
                    // EVERY occurrence is assigned, and the assignment decides the edge. An
                    // enclosing binder answers first because a bound name shadows any
                    // declaration sharing its spelling; otherwise the declaration index decides,
                    // and a name it does not hold reaches the counted `NamesNothingKnown` member
                    // rather than falling into either side unremarked.
                    let bound_as = bound
                        .iter()
                        .rev()
                        .find(|(n, _)| n == &node.name)
                        .map(|(_, class)| *class);
                    if classify.classify(&node.name, bound_as, chain_receiver) {
                        bare.insert(node.name.clone());
                    }
                }
            }
            ExprData::ExprCall { .. } => {
                if !node.name.is_empty() {
                    bare.insert(node.name.clone());
                }
            }
            ExprData::ExprRecordLit { .. } => {
                if !node.name.is_empty() {
                    bare.insert(node.name.clone());
                }
                for c in node.children.iter() {
                    collect_node_refs_inner(
                        c,
                        bare,
                        chains,
                        true,
                        false,
                        bound,
                        source_indices,
                        classify,
                    );
                }
                for pr in node.properties.iter() {
                    collect_node_refs_inner(
                        pr,
                        bare,
                        chains,
                        true,
                        false,
                        bound,
                        source_indices,
                        classify,
                    );
                }
                bound.truncate(restore_to);
                return;
            }
            _ => {}
        }
        if let Some(mp) = &node.match_pattern {
            if let MatchPattern::VariantPattern { name, .. } = &**mp {
                if !name.is_empty() {
                    bare.insert(name.clone());
                }
            }
        }
    }
    // A `let` BINDS OVER ITS LATER SIBLINGS, WHICH IS WHY THIS LOOP IS NOT A PLAIN `for`.
    // On the prepared tree a block is a child list and a `let` is one of its members, carrying
    // its bound name on the node and its VALUE as its only child. So the value is walked in the
    // scope that precedes the binding — `let x = x` reads the outer `x`, as it must — and the
    // name enters scope for the members that follow it.
    let siblings_restore_to = bound.len();
    for (idx, c) in node.children.iter().enumerate() {
        let child_is_receiver = receiver_spine && idx == 0;
        collect_node_refs_inner(
            c,
            bare,
            chains,
            false,
            child_is_receiver,
            bound,
            source_indices,
            classify,
        );
        if matches!(&*c.expr_data, ExprData::ExprLet) {
            if c.name.is_empty() {
                classify.refuse_binder("let binding", "binding carries no name");
            } else {
                bound.push((c.name.clone(), ExprVarClass::BoundByLet));
            }
        }
    }
    bound.truncate(siblings_restore_to);
    for p in node.params.iter() {
        if let Some(t) = &p.type_annotation {
            collect_type_ref_names(t, bare);
        }
    }
    if let Some(b) = &node.body {
        collect_node_refs_inner(
            b,
            bare,
            chains,
            false,
            false,
            bound,
            source_indices,
            classify,
        );
    }
    if let Some(t) = &node.type_annotation {
        collect_type_ref_names(t, bare);
    }
    for u in node.uses.iter() {
        collect_node_refs_inner(
            u,
            bare,
            chains,
            false,
            false,
            bound,
            source_indices,
            classify,
        );
    }
    for pr in node.properties.iter() {
        collect_node_refs_inner(
            pr,
            bare,
            chains,
            false,
            false,
            bound,
            source_indices,
            classify,
        );
    }
    if let Some(tr) = &node.transport {
        collect_node_refs_inner(
            tr,
            bare,
            chains,
            false,
            false,
            bound,
            source_indices,
            classify,
        );
    }
    bound.truncate(restore_to);
}

/// Count of shared leading dot-separated segments between two module paths (containment proximity).
fn module_prefix_shared_len(a: &str, b: &str) -> usize {
    a.split('.')
        .zip(b.split('.'))
        .take_while(|(x, y)| x == y)
        .count()
}

/// Longest module-path prefix of a qualified chain that names a declared module.
fn longest_declared_module_prefix(
    chain: &[String],
    module_names: &std::collections::HashSet<String>,
) -> Option<String> {
    let mut k = chain.len();
    while k >= 1 {
        let candidate = chain[..k].join(".");
        if module_names.contains(&candidate) {
            return Some(candidate);
        }
        k -= 1;
    }
    None
}

thread_local! {
    static REFERENCE_EDGE_CACHE: RefCell<HashMap<String, Vec<ReferenceEdgeRaw>>> =
        RefCell::new(HashMap::new());
    /// Import-less files the reference producer could NOT account for. Keyed identically to
    /// `REFERENCE_EDGE_CACHE` and populated in the same pass.
    ///
    /// This set is what separates the two states an empty adjacency used to conflate
    /// (DESIGN §5, ⊤-as-answer vs ⊤-as-ignorance). An import-less file the producer PARSED and
    /// found no outgoing references in genuinely has no dependencies — its closure is `{self}`
    /// and "affected iff my own file is touched" is a precise answer, not a gap. An import-less
    /// file that failed to read/parse is a gap: the producer never got to ask. Only the second
    /// may refuse, and because it is a list rather than a boolean it is typed, located, and
    /// countable.
    static REFERENCE_UNACCOUNTED_CACHE: RefCell<HashMap<String, Vec<ReferenceAccountingRefusal>>> =
        RefCell::new(HashMap::new());
}

/// An import-less file the reference-edge producer could not answer for, with the located cause.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReferenceAccountingRefusal {
    pub path: String,
    pub cause: &'static str,
}

/// Reference-derived analogue of `import_resolution_facts`: emit one edge per (file, referenced
/// module). Same row shape channel as import facts, plus a `resolution` confidence tag. Cached by
/// (pool_roots, importer_roots, excludes).
pub fn reference_resolution_facts(
    pool_roots: &[String],
    importer_roots: &[String],
    exclude_substrings: &[String],
) -> Vec<ReferenceEdgeRaw> {
    let abs_pool_roots = pool_roots_abs(pool_roots);
    let abs_importer_roots = pool_roots_abs(importer_roots);
    let cache_key = format!(
        "{}\u{1f}{}\u{1f}{}",
        abs_pool_roots.join("\u{1e}"),
        abs_importer_roots.join("\u{1e}"),
        exclude_substrings.join("\u{1e}")
    );
    if let Some(cached) = REFERENCE_EDGE_CACHE.with(|c| c.borrow().get(&cache_key).cloned()) {
        shared_fill::record_hit("reference_edges", &cache_key);
        return cached;
    }
    // THE WHOLE-POOL PARSE PASS BELOW IS THE FLOOR'S LARGEST SHARED FILL. Timed and attributed
    // from here so the claim that happens to reach it first is not read as the claim that costs
    // it; see `shared_fill` for why the per-row number alone cannot answer that.
    shared_fill::begin_fill();
    let reference_edges_fill_start = std::time::Instant::now();
    let mut unaccounted: Vec<ReferenceAccountingRefusal> = Vec::new();

    // ── Pass 1: parse the pool once. Build the exported-name→module index (precedence: first root
    // wins, mirroring `build_module_path_index`) and the declared-module-name set. Keep each file's
    // parsed tree so edge emission does not re-parse.
    let mut decl_index: HashMap<String, std::collections::BTreeSet<String>> = HashMap::new();
    let mut module_names: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut seen_modules: std::collections::HashSet<String> = std::collections::HashSet::new();
    // `has_imports` decides per-file whether reference edges are emitted at all: a file that still
    // carries `import` lines is covered EXACTLY by `import_resolution_facts` (no regression, no
    // over-connection). Only an import-less (stripped) file falls back to reference edges. So on the
    // un-stripped tree this producer emits nothing and the module graph is byte-identical to before.
    let mut pool_trees: HashMap<String, (String, Rc<crate::v1_std_core::Node>, bool)> =
        HashMap::new();
    for root in &abs_pool_roots {
        let root_path = Path::new(root);
        if !root_path.is_dir() {
            continue;
        }
        let mut files: Vec<PathBuf> = Vec::new();
        collect_dag_files_tolerant(root_path, &mut files);
        files.sort();
        for file in files {
            let rel = rel_path_for_layer_import(&file);
            let content = match std::fs::read_to_string(&file) {
                Ok(c) => c,
                Err(_) => continue,
            };
            let module_name = match extract_module_path(&content) {
                Some(m) => m,
                None => continue,
            };
            let tree = match parse_module_node_tolerant(&rel, &content) {
                Some(t) => t,
                None => continue,
            };
            let has_imports = !extract_import_paths(&content).is_empty();
            // Precedence: a module name already claimed by an earlier root does not re-contribute
            // exported names (first-root-wins, as `build_module_path_index`).
            if seen_modules.insert(module_name.clone()) {
                module_names.insert(module_name.clone());
                for name in collect_module_decl_names(&tree) {
                    decl_index
                        .entry(name)
                        .or_default()
                        .insert(module_name.clone());
                }
            }
            pool_trees
                .entry(rel)
                .or_insert((module_name, tree, has_imports));
        }
    }

    // ── Pass 2: for each importer file, collect its reference use sites and resolve them to modules.
    let mut edges: Vec<ReferenceEdgeRaw> = Vec::new();
    for root in &abs_importer_roots {
        let root_path = Path::new(root);
        if !root_path.is_dir() {
            continue;
        }
        let mut files: Vec<PathBuf> = Vec::new();
        collect_dag_files_tolerant(root_path, &mut files);
        files.sort();
        for file in files {
            let rel = rel_path_for_layer_import(&file);
            if is_excluded_import_path(&rel, exclude_substrings) {
                continue;
            }
            let (self_module, tree) = match pool_trees.get(&rel) {
                // A file that still carries imports is covered exactly by `import_resolution_facts`;
                // emitting reference edges for it would only over-connect. Skip — reference edges are
                // for import-less (stripped) files.
                Some((_, _, true)) => continue,
                Some((m, t, false)) => (m.clone(), t.clone()),
                // Absent from pass 1 means pass 1 skipped it: unreadable, no module line, or a
                // parse failure. Each is the producer being UNABLE TO ASK what this file depends
                // on — ignorance, not an answer — so each is recorded as a located refusal rather
                // than silently yielding an edgeless file that downstream reads as "no
                // dependencies" (DESIGN §5: a failure arm must refuse, never widen).
                None => {
                    let content = match std::fs::read_to_string(&file) {
                        Ok(c) => c,
                        Err(_) => {
                            unaccounted.push(ReferenceAccountingRefusal {
                                path: rel.clone(),
                                cause: "unreadable",
                            });
                            continue;
                        }
                    };
                    // Import-bearing: accounted EXACTLY by `import_resolution_facts`, so this is
                    // not a refusal — the other producer owns this file's edges.
                    if !extract_import_paths(&content).is_empty() {
                        continue;
                    }
                    let module_name = match extract_module_path(&content) {
                        Some(m) => m,
                        None => {
                            unaccounted.push(ReferenceAccountingRefusal {
                                path: rel.clone(),
                                cause: "no-module-line",
                            });
                            continue;
                        }
                    };
                    match parse_module_node_tolerant(&rel, &content) {
                        Some(t) => (module_name, t),
                        None => {
                            unaccounted.push(ReferenceAccountingRefusal {
                                path: rel.clone(),
                                cause: "parse-failed",
                            });
                            continue;
                        }
                    }
                }
            };
            let mut bare: std::collections::HashSet<String> = std::collections::HashSet::new();
            let mut chains: Vec<Vec<String>> = Vec::new();
            // THE INDEX IS BUILT FROM THE BYTES THIS PRODUCER ALREADY READ, not fetched from a
            // prepared subject that does not exist at this point: `collect_node_refs` recovers a
            // lambda parameter's name from its authored span, and a missing index would leave
            // those names unbound and let them resolve as references.
            let mut file_indices: HashMap<String, Rc<NewlineIndex>> = HashMap::new();
            if let Ok(content) = std::fs::read_to_string(&file) {
                file_indices.insert(
                    rel.clone(),
                    crate::v1_std_core::build_newline_index(rel.clone(), content),
                );
            }
            let file_indices = Rc::new(file_indices);
            // THIS PRODUCER ANSWERS A CORPUS-WIDE QUESTION BEFORE ANY SUBJECT IS PREPARED, so it
            // has no declaration index to classify against and cannot decide
            // DeclaredElsewhere / NamesNothingKnown. It supplies an EMPTY index, under which
            // every unbound name classifies as a reference — the behaviour this producer already
            // had, preserved deliberately rather than by omission. The totality guarantee is
            // therefore scoped to the floor's index build, which is the consumer that has the
            // declarations; this one keeps its own looser contract and its own counters.
            let mut scratch_tally: BTreeMap<ExprVarClass, usize> = BTreeMap::new();
            let mut scratch_unclassified: Vec<String> = Vec::new();
            let mut classify = ExprVarClassification {
                decl_index: None,
                tally: &mut scratch_tally,
                unclassified: &mut scratch_unclassified,
                module: self_module.clone(),
                occurrences: 0,
                free_reference_edges: 0,
                bound_occurrences_suppressed: 0,
                chain_head_occurrences: 0,
                refusals: Vec::new(),
            };
            for item in tree.children.iter() {
                collect_node_refs(item, &mut bare, &mut chains, &file_indices, &mut classify);
            }
            // THE SECOND CONSUMER ENFORCES THE SAME REFUSAL THE FIRST ONE DOES. `classify` reports
            // two failure states and neither is survivable for a graph that is about to be
            // published: an unsupported binder form means the binder set is incomplete, so a name
            // that IS bound can be recorded as a free reference (or the reverse); a reconciliation
            // miss means the occurrences do not add up, which is the same statement arrived at by
            // counting. Reading them and proceeding anyway would publish an under-bound, possibly
            // widened graph while the refusal sat unread in a field — the fail-open this
            // classification exists to remove, one consumer away from the floor path that checks
            // it correctly (review 55667).
            //
            // TWO CAUSES, NOT ONE, because they have different remedies: a binder refusal names a
            // syntax the collector must learn, and a reconciliation miss names an accounting
            // defect in the collector itself. Collapsing them would send both to whichever
            // remedy the shared symbol happened to suggest.
            //
            // The file is SKIPPED rather than published, matching this producer's three existing
            // refusal arms above (`unreadable`, `no-module-line`, `parse-failed`), which also skip
            // and record. The narrowing is therefore typed, located and countable through
            // `reference_accounting_refusals`, not silent — a skipped file is visible in that
            // channel, which is what separates it from the empty-observation narrow.
            if !classify.refusals.is_empty() {
                unaccounted.push(ReferenceAccountingRefusal {
                    path: rel.clone(),
                    cause: "binder-refusal",
                });
                continue;
            }
            if !classify.reconciles() {
                unaccounted.push(ReferenceAccountingRefusal {
                    path: rel.clone(),
                    cause: "occurrence-accounting-mismatch",
                });
                continue;
            }
            // Resolve to per-file (target_module → strongest confidence).
            let mut file_edges: std::collections::BTreeMap<String, RefEdgeResolution> =
                std::collections::BTreeMap::new();
            let mut upgrade = |m: String, res: RefEdgeResolution| {
                let entry = file_edges.entry(m).or_insert(res);
                if res.rank() > entry.rank() {
                    *entry = res;
                }
            };
            for chain in &chains {
                if let Some(m) = longest_declared_module_prefix(chain, &module_names) {
                    if m != self_module {
                        upgrade(m, RefEdgeResolution::Qualified);
                    }
                }
            }
            for name in &bare {
                if let Some(mods) = decl_index.get(name) {
                    // Same-module declaration wins by lexical scope (namespace-only): a bare name the
                    // referencing file itself declares resolves LOCALLY — no cross-module edge. This
                    // is what keeps a ubiquitous fixture `data` (e.g. `live_tree_disposition`,
                    // declared top-level in ~670 test files) from fanning every referrer out to every
                    // declarer.
                    if mods.contains(&self_module) {
                        continue;
                    }
                    // Proximity disambiguation (namespace-only "nearest in the containment tree"):
                    // among declarers, prefer the one sharing the longest module-path prefix with the
                    // referencing module. A single nearest → UniqueBare; a tie at the nearest depth →
                    // AmbiguousBare (a genuine homonym the source must qualify — the bright-cat lane).
                    let mut best_len = 0usize;
                    let mut winners: Vec<&String> = Vec::new();
                    for m in mods.iter() {
                        let shared = module_prefix_shared_len(&self_module, m);
                        if winners.is_empty() || shared > best_len {
                            best_len = shared;
                            winners.clear();
                            winners.push(m);
                        } else if shared == best_len {
                            winners.push(m);
                        }
                    }
                    match winners.len() {
                        0 => {}
                        1 => upgrade(winners[0].clone(), RefEdgeResolution::UniqueBare),
                        _ => {
                            // Homonym-qualification worklist dump (bright-cat lane (c) seed): each
                            // AmbiguousBare is a bare ref, in a file that does not declare it, whose
                            // nearest declarers tie — the definitive "needs qualification" site.
                            if std::env::var("REFAMBIG_DUMP").is_ok() {
                                let is_witness =
                                    rel.contains("/test/") || rel.ends_with("_test.dag");
                                let cands: Vec<String> =
                                    winners.iter().map(|s| (*s).clone()).collect();
                                eprintln!(
                                    "REFAMBIG\t{}\t{}\t{}\t{}",
                                    if is_witness { "witness" } else { "compile" },
                                    rel,
                                    name,
                                    cands.join(",")
                                );
                            }
                            for t in winners {
                                upgrade(t.clone(), RefEdgeResolution::AmbiguousBare);
                            }
                        }
                    }
                }
            }
            for (m, res) in file_edges {
                edges.push(ReferenceEdgeRaw {
                    path: rel.clone(),
                    target_module: m,
                    resolution: res,
                });
            }
        }
    }

    unaccounted.sort_by(|a, b| a.path.cmp(&b.path));
    shared_fill::record_fill(
        "reference_edges",
        &cache_key,
        reference_edges_fill_start.elapsed().as_nanos() as u64,
    );
    REFERENCE_UNACCOUNTED_CACHE.with(|c| c.borrow_mut().insert(cache_key.clone(), unaccounted));
    REFERENCE_EDGE_CACHE.with(|c| c.borrow_mut().insert(cache_key, edges.clone()));
    edges
}

/// Import-less files `reference_resolution_facts` could not account for, with located causes.
/// Shares the producer's cache key, so calling this after the producer is free.
pub fn reference_accounting_refusals(
    pool_roots: &[String],
    importer_roots: &[String],
    exclude_substrings: &[String],
) -> Vec<ReferenceAccountingRefusal> {
    let cache_key = format!(
        "{}\u{1f}{}\u{1f}{}",
        pool_roots_abs(pool_roots).join("\u{1e}"),
        pool_roots_abs(importer_roots).join("\u{1e}"),
        exclude_substrings.join("\u{1e}")
    );
    if let Some(cached) = REFERENCE_UNACCOUNTED_CACHE.with(|c| c.borrow().get(&cache_key).cloned())
    {
        return cached;
    }
    // Cold: run the producer, which populates both caches in one pass.
    let _ = reference_resolution_facts(pool_roots, importer_roots, exclude_substrings);
    REFERENCE_UNACCOUNTED_CACHE.with(|c| c.borrow().get(&cache_key).cloned().unwrap_or_default())
}

/// Reachability stats for bare references to one declared export name (namespace homonym triage).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct BareRefReachability {
    /// Nearest-wins ties among declarers (AmbiguousBare — needs qualification).
    pub ambiguous_sites: usize,
    /// Unique nearest declarer shares zero module-path prefix with the referrer (disjoint subtree).
    pub cross_subtree_unique_sites: usize,
}

#[cfg(test)]
mod reference_edge_producer_tests {
    use super::reference_resolution_facts;

    fn fixture_root(tag: &str) -> std::path::PathBuf {
        // Under the workspace `target/` (gitignored): `rel_path_for_layer_import` fail-closes on
        // paths outside the workspace root, and `target/` keeps the fixture out of version control.
        super::process_workspace_root()
            .join("target")
            .join(format!("gunbc-refedge-{tag}-{}", std::process::id()))
    }

    fn write(root: &std::path::Path, rel: &str, content: &str) {
        let p = root.join(rel);
        std::fs::create_dir_all(p.parent().unwrap()).expect("mkdir");
        std::fs::write(&p, content).expect("write dag");
    }

    // Green-by-execution + discriminating RED: the producer must derive a cross-module edge from a
    // bare reference in an import-LESS file (the stripped case), resolve a same-module name LOCALLY
    // (no edge — the live_tree_disposition fan-out guard), and emit NOTHING for an import-bearing
    // file (import-covered). A reader that ignored the parsed references would fail the first assert.
    #[test]
    fn reference_edges_derived_from_bare_refs_local_and_import_aware() {
        let root = fixture_root("core");
        let _ = std::fs::remove_dir_all(&root);
        // Declares the shared name.
        write(
            &root,
            "decl.dag",
            "module test.decl\n\nfn shared_fn() -> Bool {\n  true\n}\n",
        );
        // Import-LESS file that references it → edge to test.decl.
        write(
            &root,
            "refless.dag",
            "module test.refless\n\nfn use_it() -> Bool {\n  shared_fn()\n}\n",
        );
        // Declares its OWN shared_fn and references it → resolves locally, NO edge.
        write(
            &root,
            "reflocal.dag",
            "module test.reflocal\n\nfn shared_fn() -> Bool {\n  true\n}\n\nfn use_it() -> Bool {\n  shared_fn()\n}\n",
        );
        // Import-bearing file → covered by import facts, producer emits nothing for it.
        write(
            &root,
            "imported.dag",
            "module test.imported\n\nimport test.decl { shared_fn }\n\nfn use_it() -> Bool {\n  shared_fn()\n}\n",
        );

        let roots = vec![root.to_string_lossy().into_owned()];
        let edges = reference_resolution_facts(&roots, &roots, &[]);
        let has_edge = |from_sub: &str, to_mod: &str| {
            edges
                .iter()
                .any(|e| e.path.contains(from_sub) && e.target_module == to_mod)
        };
        let emits_any = |from_sub: &str| edges.iter().any(|e| e.path.contains(from_sub));

        assert!(
            has_edge("refless.dag", "test.decl"),
            "import-less file referencing shared_fn must yield an edge to its declaring module"
        );
        assert!(
            !emits_any("reflocal.dag"),
            "a same-module declaration resolves locally — no cross-module edge"
        );
        assert!(
            !emits_any("imported.dag"),
            "an import-bearing file is import-covered — the reference producer skips it"
        );
        let _ = std::fs::remove_dir_all(&root);
    }

    fn str_list_value(items: &[String]) -> crate::v1_interpreter::Value {
        super::list_value_from_vec(
            items
                .iter()
                .map(|s| crate::v1_interpreter::str_value(s.clone()))
                .collect(),
        )
    }

    fn edge_from_record(
        ctx: &crate::v1_interpreter::InterpContext,
        value: &crate::v1_interpreter::Value,
    ) -> (String, String) {
        let crate::v1_interpreter::Value::Record { fields, .. } = value else {
            panic!("expected ModuleDependencyEdge record, got {value}");
        };
        let path = match ctx.field(fields, "path") {
            Some(crate::v1_interpreter::Value::Str(s)) => s.to_string(),
            other => panic!("path field: {other:?}"),
        };
        let target = match ctx.field(fields, "target_module") {
            Some(crate::v1_interpreter::Value::Str(s)) => s.to_string(),
            other => panic!("target_module field: {other:?}"),
        };
        (path, target)
    }

    fn dependency_edges_from_free_monoid(
        ctx: &crate::v1_interpreter::InterpContext,
        value: &crate::v1_interpreter::Value,
    ) -> Vec<(String, String)> {
        match value {
            crate::v1_interpreter::Value::Variant {
                variant_name,
                fields,
                ..
            } if ctx.sym_eq(*variant_name, "Empty") => Vec::new(),
            crate::v1_interpreter::Value::Variant {
                variant_name,
                fields,
                ..
            } if ctx.sym_eq(*variant_name, "Cons") => {
                let head = ctx
                    .field(fields, "head")
                    .expect("Cons.head must be present");
                let tail = ctx
                    .field(fields, "tail")
                    .expect("Cons.tail must be present");
                let mut edges = vec![edge_from_record(ctx, head)];
                edges.extend(dependency_edges_from_free_monoid(ctx, tail));
                edges
            }
            other => panic!("expected FreeMonoid Cons/Empty, got {other}"),
        }
    }

    // Divergence control for the §3 producer fork dissolved in #6935: an import-less file that
    // references another module by bare name is invisible to import_resolution_facts but visible to
    // reference_resolution_facts (strict tier). Before the builtin registration the .dag lens
    // under-selected; after, dependency_resolution_facts_live and the host agree.
    #[test]
    fn reference_edge_dag_host_producer_divergence_control() {
        use super::{
            build_multi_entry_index, import_resolution_facts, make_eval_context,
            reference_edges_as_import_facts, reference_resolution_facts,
            resolve_entry_with_index_for_discovery_corpus, workspace_root,
        };
        use crate::v1_interpreter::{self, ExecutionMode};

        let root = fixture_root("divergence");
        let _ = std::fs::remove_dir_all(&root);
        write(
            &root,
            "decl.dag",
            "module test.decl\n\nfn shared_fn() -> Bool {\n  true\n}\n",
        );
        write(
            &root,
            "refless.dag",
            "module test.refless\n\nfn use_it() -> Bool {\n  shared_fn()\n}\n",
        );

        let pool = vec![root.to_string_lossy().into_owned()];
        let has_import_edge = |from_sub: &str, to_mod: &str| {
            import_resolution_facts(&pool, &pool, &[])
                .iter()
                .any(|e| e.path.contains(from_sub) && e.import_module == to_mod)
        };
        let has_host_ref_edge = |from_sub: &str, to_mod: &str| {
            reference_edges_as_import_facts(&reference_resolution_facts(&pool, &pool, &[]), true)
                .iter()
                .any(|e| e.path.contains(from_sub) && e.import_module == to_mod)
        };

        // RED control: import-only producer cannot see a reference-only dependency.
        assert!(
            !has_import_edge("refless.dag", "test.decl"),
            "import_resolution_facts must miss a reference-only edge — otherwise this test is not discriminating"
        );
        // Host selection-tier producer finds it (the fork surface we are dissolving).
        assert!(
            has_host_ref_edge("refless.dag", "test.decl"),
            "host reference_resolution_facts (strict) must find the reference-only edge"
        );

        let ws = workspace_root();
        std::env::set_current_dir(&ws).expect("chdir workspace");
        let module_graph_entry = ws
            .join("src/v2/lens/module_graph.dag")
            .to_string_lossy()
            .into_owned();
        let index_roots = vec![
            ws.join("dag").to_string_lossy().into_owned(),
            ws.join("src/v2").to_string_lossy().into_owned(),
            pool[0].clone(),
        ];
        let index = build_multi_entry_index(&index_roots);
        let (graph, indices) =
            resolve_entry_with_index_for_discovery_corpus(&index, &module_graph_entry)
                .expect("module_graph.dag resolves");
        let ctx = make_eval_context(&graph, indices, ExecutionMode::Wet);
        let args = [
            (Some("pool_roots".to_string()), str_list_value(&pool)),
            (Some("importer_roots".to_string()), str_list_value(&pool)),
            (
                Some("exclude_substrings".to_string()),
                str_list_value(&[] as &[String]),
            ),
        ];
        let dag_edges = dependency_edges_from_free_monoid(
            &ctx,
            &v1_interpreter::run_in_context_with_args(
                &ctx,
                "dependency_resolution_facts_live",
                &args,
                false,
            )
            .expect("dependency_resolution_facts_live eval"),
        );
        assert!(
            dag_edges
                .iter()
                .any(|(path, target)| path.contains("refless.dag") && target == "test.decl"),
            ".dag dependency_resolution_facts_live must find the reference-only edge after builtin registration"
        );

        let _ = std::fs::remove_dir_all(&root);
    }

    /// Discriminating witness for layering-imports reference repoint (Phase 1,
    /// docs/plans/layering-imports-reference-repoint-design.md §4.5): an import-less
    /// std-layer file with a qualified `v2.compiler.*` reference must surface a layering violation.
    #[test]
    fn layer_import_facts_reference_only_violation_control() {
        use super::{extract_import_paths, layer_import_facts};

        let root = fixture_root("layering_ref_only");
        let _ = std::fs::remove_dir_all(&root);
        write(
            &root,
            "plant.dag",
            "module v2.std.ref_only_plant\n\nfn leak_probe() -> Bool {\n  v2.compiler.tokenize.eq(a: \"a\", b: \"b\")\n}\n",
        );

        let std_roots = vec![root.to_string_lossy().into_owned()];
        let content = std::fs::read_to_string(root.join("plant.dag")).expect("read plant");
        assert!(
            extract_import_paths(&content).is_empty(),
            "fixture must be import-less — otherwise this test is not discriminating"
        );
        let facts = layer_import_facts(&std_roots, &[]);
        assert!(
            facts.iter().any(|f| {
                f.path.contains("plant.dag")
                    && f.import_module.starts_with("v2.compiler")
                    && f.layer == "LayerPrefixStd"
            }),
            "layer_import_facts must emit a reference-derived compiler edge for import-less std file"
        );

        let _ = std::fs::remove_dir_all(&root);
    }

    /// A cross-layer edge out of a std file must be *grounded in that file's own text* —
    /// either a real `import`, or a real reference occurrence (the reference-derived
    /// edge the sibling control above proves is emitted). An edge naming a module the
    /// file never mentions is fabricated by the producer, which is the actual
    /// "prelude bare name" defect class this test was built for.
    ///
    /// It used to assert the strictly stronger `no std -> extdeps/compiler edge at all`,
    /// which DESIGN §3 deleted on 2026-07-24: the layer DAG
    /// `std <- extdeps <- compiler <- workflow` was "convention standing where no
    /// necessity stood, and it blocked correct grounding — a std surface citing the
    /// extdeps rows that ground it". Under that deleted rule every such edge was false
    /// by definition; today the 9 in-corpus edges are exactly those sanctioned
    /// citations (`std.measure` -> `extdeps.units.*` and `std.process` ->
    /// `extdeps.process.*` from #7268, `std.claim_evidence` and
    /// `v2.std.compilers.target_model` -> `extdeps.external_authority`), so the old
    /// assertion reported grounding as a violation. Acyclicity is the only structural
    /// law; folders are browsing conventions.
    #[test]
    fn layer_import_facts_cross_layer_edges_are_grounded_in_file_text() {
        use super::{extract_import_paths, layer_import_facts, LayerImportFactRaw};

        /// `layer_import_facts` has TWO fact provenances by construction: a scan of real
        /// `import` lines, and — only when the importer roots contain import-less `.dag`
        /// files — reference-derived edges from `reference_resolution_facts`. So grounding
        /// is the disjunction, and each arm is checked against the surface that provenance
        /// actually uses:
        ///
        /// - **import-backed** — the module appears in the parsed import surface
        ///   (`extract_import_paths`). This is the strong arm and the common case.
        /// - **reference-backed** — the module appears in the file's *code* text. The
        ///   sibling `..._reference_only_violation_control` proves the producer emits such
        ///   an edge for an import-less std file with a qualified reference, so demanding
        ///   an `import` for it would encode an invariant the project is actively
        ///   dissolving (DESIGN's namespace-only lane ends with `import` as a *parse
        ///   error*, deps derived from `container.member` references). Requiring one here
        ///   would red on a legitimate reference (review 44710).
        ///
        /// The reference arm is *code* containment, not text containment: string literals
        /// are stripped first. `.dag` has no comment syntax, so a prose
        /// `data ..._note: String = "…"` row is the only non-code text — and those rows
        /// legitimately name module paths (this PR adds two), which is exactly the
        /// laundering vector review 44626 rejected `contains` for. Stripping literals
        /// keeps that closed while admitting the real reference.
        ///
        /// Three SEPARATE buckets out, never folded together (DESIGN §5 state-space
        /// conflation): "I could not read the file" is not "the edge is fabricated", and
        /// "grounded by a reference" is not "grounded by an import" — the second
        /// distinction is what keeps the reference arm from silently becoming the whole
        /// oracle. `path` is a repo-relative key, so it is anchored at the workspace root
        /// exactly as the producer anchors it; reading it raw only works when cwd happens
        /// to be that root, which under `cargo test` (cwd = package root) it is not.
        fn ungrounded(facts: &[LayerImportFactRaw]) -> (Vec<String>, Vec<String>, Vec<String>) {
            /// Drops `"…"` string-literal content, keeping everything else. A `\` escapes
            /// the next character, so `\"` does not close a literal.
            fn code_text_only(content: &str) -> String {
                let mut out = String::with_capacity(content.len());
                let mut in_string = false;
                let mut escaped = false;
                for c in content.chars() {
                    if escaped {
                        escaped = false;
                        continue;
                    }
                    match c {
                        '\\' if in_string => escaped = true,
                        '"' => in_string = !in_string,
                        _ if in_string => {}
                        _ => out.push(c),
                    }
                }
                out
            }

            let ws = super::workspace_root();
            let mut fabricated = Vec::new();
            let mut reference_backed = Vec::new();
            let mut unreadable = Vec::new();
            for f in facts.iter().filter(|f| {
                f.layer == "LayerPrefixStd"
                    && (f.import_module.starts_with("extdeps.")
                        || f.import_module.starts_with("v2.compiler"))
            }) {
                let Ok(content) = std::fs::read_to_string(ws.join(&f.path)) else {
                    unreadable.push(f.path.clone());
                    continue;
                };
                let edge = format!("{} -> {}", f.path, f.import_module);
                if extract_import_paths(&content)
                    .iter()
                    .any(|m| m == &f.import_module)
                {
                    continue;
                }
                if code_text_only(&content).contains(&f.import_module) {
                    reference_backed.push(edge);
                } else {
                    fabricated.push(edge);
                }
            }
            (fabricated, reference_backed, unreadable)
        }

        let std_roots = vec!["src/v2/std".to_string(), "dag/std".to_string()];
        let extdeps_roots = vec!["src/v2/extdeps".to_string(), "dag/extdeps".to_string()];
        let facts = layer_import_facts(&std_roots, &extdeps_roots);
        assert!(
            !facts.is_empty(),
            "producer emitted no layer facts at all — the corpus read is broken, so an \
             empty violation set below would be vacuous"
        );
        let (fabricated, reference_backed, unreadable) = ungrounded(&facts);
        assert!(
            unreadable.is_empty(),
            "every flagged std file must be readable at the workspace root — an unreadable \
             path means the oracle is broken, not that an edge is grounded: {unreadable:?}"
        );
        assert!(
            fabricated.is_empty(),
            "every cross-layer std edge must be grounded in its own file — a real parsed \
             import, or a real code reference; fabricated: {fabricated:?}"
        );
        // The reference-backed bucket is REPORTED, not asserted empty. Asserting it empty
        // is the import-only rule this oracle just stopped encoding; leaving it unsplit
        // would let the weaker arm silently absorb the stronger one. Zero in the corpus
        // today (all in-corpus cross-layer std edges are real `import` lines), and it is
        // the import-less std files the namespace lane produces that will land here.
        eprintln!(
            "cross-layer std edges: {} import-backed, {} reference-backed{}",
            facts
                .iter()
                .filter(|f| {
                    f.layer == "LayerPrefixStd"
                        && (f.import_module.starts_with("extdeps.")
                            || f.import_module.starts_with("v2.compiler"))
                })
                .count()
                - reference_backed.len(),
            reference_backed.len(),
            if reference_backed.is_empty() {
                String::new()
            } else {
                format!(" {reference_backed:?}")
            }
        );

        // RED controls, each planting a fact against a REAL, READABLE file and asserting
        // `unreadable` is empty first — otherwise a path-anchoring bug would satisfy them
        // for the wrong reason.
        let red = |path: &str, import_module: &str| {
            let planted = vec![LayerImportFactRaw {
                layer: "LayerPrefixStd",
                path: path.to_string(),
                import_module: import_module.to_string(),
            }];
            let (fab, refd, unread) = ungrounded(&planted);
            assert!(
                unread.is_empty(),
                "RED control fixture must be readable, else it fires for the wrong reason"
            );
            (fab.len(), refd.len())
        };

        // (1) a module the file neither imports nor mentions anywhere.
        assert_eq!(
            red(
                "dag/std/measure.dag",
                "extdeps.units.no_such_module_mentioned_anywhere"
            ),
            (1, 0),
            "an edge with no import and no reference behind it must be flagged fabricated"
        );

        // (2) a near-miss sibling: `std.measure` imports `extdeps.units.iec_80000_13`, and
        // `..._14` does not occur in the file in any form. Guards the arm against matching
        // on a prefix of a real module name.
        let measure = std::fs::read_to_string(super::workspace_root().join("dag/std/measure.dag"))
            .expect("read measure.dag");
        let near_miss = "extdeps.units.iec_80000_14";
        assert!(
            !extract_import_paths(&measure)
                .iter()
                .any(|m| m == near_miss)
                && measure.contains("extdeps.units.iec_80000_13"),
            "control precondition: {near_miss} is not imported, while its sibling _13 is"
        );
        assert_eq!(
            red("dag/std/measure.dag", near_miss),
            (1, 0),
            "a sibling module absent from the file must not be grounded by the prefix of \
             the one that is present"
        );

        // (3) + (4) the two arms of the reference case, on authored fixtures because the
        // live corpus has no import-less std file to exercise them. The pair is what makes
        // the reference arm discriminating rather than a rubber stamp: same shape, same
        // module name, differing only in whether the occurrence is code or prose.
        let fixture = super::process_workspace_root()
            .join("target")
            .join(format!("gunbc-layer-grounding-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&fixture);
        std::fs::create_dir_all(&fixture).expect("mkdir fixture");
        let referenced = "v2.compiler.tokenize";

        // (3) import-less, module named ONLY inside a prose `String` literal — the
        // laundering vector review 44626 rejected `contains` for. Must stay fabricated.
        let prose = fixture.join("prose.dag");
        std::fs::write(
            &prose,
            "module v2.std.prose_plant\n\ndata note: String = \"grounding is decided against \
             v2.compiler.tokenize, which this file does not reference\"\n",
        )
        .expect("write prose fixture");
        assert_eq!(
            red(&prose.to_string_lossy(), referenced),
            (1, 0),
            "a module named only inside a string literal must stay fabricated — stripping \
             literals is what keeps prose from laundering an edge"
        );

        // (4) import-less, same module in a real code position — the legitimate
        // reference-derived edge the sibling control proves the producer emits. Must be
        // grounded, and grounded by the REFERENCE arm specifically.
        let code = fixture.join("code.dag");
        std::fs::write(
            &code,
            "module v2.std.code_plant\n\nfn leak_probe() -> Bool {\n  \
             v2.compiler.tokenize.eq(a: \"a\", b: \"b\")\n}\n",
        )
        .expect("write code fixture");
        assert!(
            extract_import_paths(&std::fs::read_to_string(&code).expect("read code fixture"))
                .is_empty(),
            "fixture must be import-less, else it exercises the import arm instead"
        );
        assert_eq!(
            red(&code.to_string_lossy(), referenced),
            (0, 1),
            "a real qualified reference in an import-less file must ground the edge via the \
             reference arm — requiring an `import` here is the invariant DESIGN dissolved"
        );

        let _ = std::fs::remove_dir_all(&fixture);
    }
}

#[cfg(test)]
mod pool_heads_oracle_tests {
    use super::*;
    use std::collections::BTreeSet;

    /// Local oracle for #6956: dump reference_resolution_facts + pool qualified-fill
    /// SymbolIndex digests (run with `--nocapture`, compare branch vs main).
    #[test]
    fn pool_heads_materialization_oracle_dump() {
        let roots = vec![
            workspace_root()
                .join("src/v2")
                .to_string_lossy()
                .into_owned(),
            workspace_root().join("dag").to_string_lossy().into_owned(),
        ];
        let ref_edges = reference_resolution_facts(&roots, &roots, &[]);
        let mut ref_rows: Vec<String> = ref_edges
            .iter()
            .map(|e| format!("{}|{}|{:?}", e.path, e.target_module, e.resolution))
            .collect();
        ref_rows.sort();
        let ref_digest = v1_rt::bytes_identity_hash(ref_rows.join("\n").as_bytes());

        let index = build_multi_entry_index(&roots);
        let fill = pool_qualified_fill(&index).expect("qualified fill");
        let qkeys: BTreeSet<String> = fill.entries.keys().cloned().collect();
        let bare_keys: BTreeSet<String> = fill.global_bare.keys().cloned().collect();
        let svc_keys: BTreeSet<String> = fill.services.keys().cloned().collect();
        let sym_digest = v1_rt::bytes_identity_hash(
            format!(
                "entries={}\n{}\nbare={}\n{}\nservices={}\n{}",
                qkeys.len(),
                qkeys.into_iter().collect::<Vec<_>>().join("\n"),
                bare_keys.len(),
                bare_keys.into_iter().collect::<Vec<_>>().join("\n"),
                svc_keys.len(),
                svc_keys.into_iter().collect::<Vec<_>>().join("\n"),
            )
            .as_bytes(),
        );

        println!(
            "POOL_HEADS_ORACLE reference_edge_count={} reference_digest={} symbol_index_digest={} qualified_entries={} global_bare={} services={}",
            ref_edges.len(),
            ref_digest,
            sym_digest,
            fill.entries.len(),
            fill.global_bare.len(),
            fill.services.len(),
        );
    }
}

// ── CommitWitnessClaim roster resolvability (PR-time detector) ─────────────────────────────────
//
// Every explicit `CommitWitnessClaim` row on the GithubActionsCiJob surface must resolve its
// entry module and name every `check_fn` — the #7060 class (witness moved, roster row stale →
// `no main function found` on every main CI run until #7079). Host-fed; dissolve-on: the
// `.dag` authority evaluates `project_ci_floor_witness_entries` without this re-parse once
// fn-body reflection can read the roster at compile time.

const COMMIT_WORKFLOW_ENTRY: &str = "dag/gunbc/commit_workflow.dag";
const CI_FLOOR_COMMIT_WITNESS_SCHEDULE_FN: &str = "ci_floor_commit_witness_claim_schedule";

fn schedule_witness_pairs_from_value(
    ctx: &v1_interpreter::InterpContext,
    val: &v1_interpreter::Value,
) -> Result<Vec<(String, String)>, String> {
    let v1_interpreter::Value::List(items) = val else {
        return Err(format!(
            "{CI_FLOOR_COMMIT_WITNESS_SCHEDULE_FN} did not return a List: {val:?}"
        ));
    };
    let mut pairs = Vec::new();
    for item in items.iter() {
        let v1_interpreter::Value::Record { fields, .. } = item else {
            return Err(format!(
                "{CI_FLOOR_COMMIT_WITNESS_SCHEDULE_FN} element is not a Record: {item:?}"
            ));
        };
        let entry = commit_witness_field_str(ctx, fields, "entry")?;
        let function = commit_witness_field_str(ctx, fields, "function")?;
        pairs.push((entry, function));
    }
    Ok(pairs)
}

fn commit_witness_field_str(
    ctx: &v1_interpreter::InterpContext,
    fields: &[(v1_interpreter::Symbol, v1_interpreter::Value)],
    name: &str,
) -> Result<String, String> {
    match ctx.field(fields, name) {
        Some(Value::Str(s)) => Ok(s.to_string()),
        other => Err(format!("{name} not a String: {other:?}")),
    }
}

fn ci_floor_commit_witness_claim_pairs() -> Result<Vec<(String, String)>, String> {
    let roots = witness_layer_roots();
    let index = process_shared_index(&roots);
    let (graph, source_indices) = resolve_entry_with_index(&index, COMMIT_WORKFLOW_ENTRY)?;
    let ctx = make_eval_context(
        &graph,
        source_indices,
        v1_interpreter::ExecutionMode::Hermetic,
    );
    let val = v1_interpreter::run_in_context(&ctx, CI_FLOOR_COMMIT_WITNESS_SCHEDULE_FN, true)
        .map_err(|e| format!("{CI_FLOOR_COMMIT_WITNESS_SCHEDULE_FN}: {e}"))?;
    schedule_witness_pairs_from_value(&ctx, &val)
}

pub fn commit_witness_claim_pair_resolvable(entry: &str, function: &str) -> bool {
    let roots = witness_layer_roots();
    let index = process_shared_index(&roots);
    let mut entry_cache = std::collections::HashMap::new();
    matches!(
        commit_witness_claim_pair_resolvability_with_index(
            &index,
            &roots,
            entry,
            function,
            &mut entry_cache,
        ),
        CommitWitnessClaimPairResolvability::Resolvable
    )
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum CommitWitnessClaimPairResolvability {
    Resolvable,
    EntryMissing { detail: String },
    EntryResolveFailed { detail: String },
    FunctionNotFound,
}

#[derive(Debug, Clone)]
enum RosterEntryRegistryCache {
    EntryMissing { detail: String },
    EntryResolveFailed { detail: String },
    Functions(std::collections::HashSet<String>),
}

fn roster_entry_registry_cache(
    index: &MultiEntryIndex,
    roots: &[String],
    entry: &str,
) -> RosterEntryRegistryCache {
    let entry_path = match resolve_entry_file_under_roots(roots, entry) {
        Ok(p) => p,
        Err(detail) => {
            return RosterEntryRegistryCache::EntryMissing { detail };
        }
    };
    let (graph, source_indices) = match resolve_entry_with_index(index, &entry_path) {
        Ok(r) => r,
        Err(detail) => {
            return RosterEntryRegistryCache::EntryResolveFailed { detail };
        }
    };
    let ctx = make_eval_context(
        &graph,
        source_indices,
        v1_interpreter::ExecutionMode::Hermetic,
    );
    RosterEntryRegistryCache::Functions(ctx.item_registry.keys().cloned().collect())
}

fn commit_witness_claim_pair_resolvability_with_index(
    index: &MultiEntryIndex,
    roots: &[String],
    entry: &str,
    function: &str,
    entry_cache: &mut std::collections::HashMap<String, RosterEntryRegistryCache>,
) -> CommitWitnessClaimPairResolvability {
    let cached = entry_cache
        .entry(entry.to_string())
        .or_insert_with(|| roster_entry_registry_cache(index, roots, entry));
    match cached {
        RosterEntryRegistryCache::EntryMissing { detail } => {
            CommitWitnessClaimPairResolvability::EntryMissing {
                detail: detail.clone(),
            }
        }
        RosterEntryRegistryCache::EntryResolveFailed { detail } => {
            CommitWitnessClaimPairResolvability::EntryResolveFailed {
                detail: detail.clone(),
            }
        }
        RosterEntryRegistryCache::Functions(names) => {
            if names.contains(function) {
                CommitWitnessClaimPairResolvability::Resolvable
            } else {
                CommitWitnessClaimPairResolvability::FunctionNotFound
            }
        }
    }
}

pub fn commit_witness_claim_roster_defects() -> Vec<(String, String, String)> {
    let Ok(pairs) = ci_floor_commit_witness_claim_pairs() else {
        return vec![(
            "dag/gunbc/commit_workflow.dag".to_string(),
            CI_FLOOR_COMMIT_WITNESS_SCHEDULE_FN.to_string(),
            "schedule_projection_failed".to_string(),
        )];
    };
    let roots = witness_layer_roots();
    let index = process_shared_index(&roots);
    let mut entry_cache = std::collections::HashMap::new();
    let mut defects = Vec::new();
    for (entry, function) in pairs {
        let cause = match commit_witness_claim_pair_resolvability_with_index(
            &index,
            &roots,
            &entry,
            &function,
            &mut entry_cache,
        ) {
            CommitWitnessClaimPairResolvability::Resolvable => continue,
            CommitWitnessClaimPairResolvability::EntryMissing { detail } => {
                format!("entry_missing:{detail}")
            }
            CommitWitnessClaimPairResolvability::EntryResolveFailed { detail } => {
                format!("entry_resolve_failed:{detail}")
            }
            CommitWitnessClaimPairResolvability::FunctionNotFound => {
                "function_not_found".to_string()
            }
        };
        defects.push((entry, function, cause));
    }
    defects
}

pub fn commit_witness_claim_roster_unresolvable_count() -> i64 {
    let defects = commit_witness_claim_roster_defects();
    for (entry, function, cause) in &defects {
        eprintln!(
            "COMMIT_WITNESS_CLAIM_ROSTER_REFUSAL count={} entry={entry} function={function} cause={cause}",
            defects.len()
        );
    }
    defects.len() as i64
}

pub fn non_fold_residue_wildcard_red_fixture_holds() -> bool {
    let fixture = vec![(
        "m.dag".to_string(),
        "module m\ntype Mode = A | B | C\nfn f(x: Mode) -> Bool {\n  match x {\n    A => true\n    _ => false\n  }\n}\n"
            .to_string(),
    )];
    nfr_residue_sites(&fixture).contains(&"m.dag::f".to_string())
}

pub fn non_fold_residue_total_fold_green_fixture_holds() -> bool {
    let fixture = vec![(
        "m.dag".to_string(),
        "module m\ntype Mode = A | B | C\nfn f(x: Mode) -> Bool {\n  match x {\n    A => true\n    B => false\n    C => false\n  }\n}\n"
            .to_string(),
    )];
    !nfr_residue_sites(&fixture).contains(&"m.dag::f".to_string())
}

pub fn non_fold_residue_roster_red_fixture_holds() -> bool {
    !non_fold_residue_site_is_rostered("synthetic/unrostered_site.dag::would_fail")
}

pub fn non_fold_residue_synthetic_unrostered_red_holds() -> bool {
    let fixture = vec![(
        "synthetic_red_fixture.dag".to_string(),
        "module synthetic_red_fixture\ntype Mode = A | B | C\nfn f(x: Mode) -> Bool {\n  match x {\n    A => true\n    _ => false\n  }\n}\n"
            .to_string(),
    )];
    let sites = nfr_residue_sites(&fixture);
    let site = "synthetic_red_fixture.dag::f";
    sites.contains(&site.to_string()) && !non_fold_residue_site_is_rostered(site)
}

